INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-1','naver-2093701183','naver','가로수길에서 분위기 좋은 카페 찾다가 방문한 공원스크립트 ☕️🌿 시그니처 티라미수 세트랑 샌드위치 주문했는데 둘 다 만족스러웠어요! 티라미수는 부드럽고 촉촉하면서 커피 향이 은은하게 느껴져서 왜 시그니처인지 알 것 같더라고요. 달기만 한 스타일이 아니라 커피랑 같이 먹기 좋았어요 :) 샌드위치도 재료가 잘 어우러지고 든든해서 브런치로 먹기 좋았고, 티라미수까지 곁들이니 조합이 딱이었어요. 매장 분위기도 감각적이고 여유로운 느낌이라 가로수길 데이트나 친구랑 카페 찾을 때 방문하기 좋은 곳! 다음에는 다른 디저트도 먹어보고 싶어요 😊','2026-10-12T00:00:00.000Z'),
('nr-2','naver-2093701183','naver','가구업체에서 운영하는 카페라 그런지 가구들도 다 넘 멋있고 공간도 넓은데다 청음실이 너무 멋져서 가로수길 느좋카페 찾으시는 분께 강추드려용 ㅎㅎ 분위기가 넘 좋아서 데이트 하기에 딱이더라구요 ㅎ 시그니처인 티라미수도 넘 촉촉하고 휘낭시에도 겉바속촉이어서 디저트 맛집이라고도 할만해여 🫶 디저트들이 아아랑 잘어울리네요!! 시그니처 음료인 헤이즈도 달달하니 맛있어요~','2026-10-12T00:00:00.000Z'),
('nr-3','naver-2093701183','naver','신사역 데이트하러 왔는데 분위기가 진짜 좋아요! 매장도 대형카페라 건물 전체가 카페인데, 청음실도 있어서 노래 들을 때 와도 좋고 커피부터 샌드위치, 티라미수까지 디저트도 다양해서 조용하게 대화하기 좋았습니다💚💚 층마다 다른 분위기라 신사역 가로수길 올 때 무조건 추천이에요!!','2026-10-12T00:00:00.000Z'),
('nr-4','naver-2093701183','naver','고기동 공원스크립트를 자주갔었는데 가로수길점은 고기동과 다른 느낌으로 좋네요. 분위기도 좋고, 쇼파 테이블도 많아서 쉬기좋습니다. 또 커피랑 오렌지루이보스 그리고 피스타치오 티라미수, 휘낭시에 맛이 훌륭합니다! 신사 자주오는데 다음에 재방문의사 있습니다!','2026-10-12T00:00:00.000Z'),
('nr-5','naver-2093701183','naver','카페 분위기도 아늑하고 인테리어도 예뻐서 편하게 쉬다 가기 좋았어요! 음료도 맛있고 디저트도 만족스러웠습니다. 직원분들도 친절하시고 전체적으로 인테리어도 이쁘고 깔끔해서 기분 좋게 시간 보내고 왔어요. 다음에 근처 오면 또 방문하고 싶어요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-6','naver-2093701183','naver','늦게까지 하는 카페 중에 가장 미감이 좋은 카페였어요! 노래도 좋고 3층이어서 다양한 취향대로 좌석을 고를 수 있어서 좋았어요! 조명도 예뻐보이는 조명이라 완전 약속장소로도 자주 올 것 같아요. 공부나 데이트 상관없이 저 진심 단골예정입니다..','2026-10-12T00:00:00.000Z'),
('nr-7','naver-2093701183','naver','가로수길 카페 느좋 💙 바로 여기 추천 새벽 1시까지 영업해서 늦은 시간가기에도 좋아요 제가 갔을때는 평일 밤 10시 쯤이였는데 사람도 많고 노래도 좋음. 망고빙수도 진한 우유얼음에 망고 배부를 정도로 한가득 올라가있어요 지하1층 부터 3층까지 분위기도 다 달라서 올때마다 다른 카페 온 느낌 :)','2026-10-12T00:00:00.000Z'),
('nr-8','naver-2093701183','naver','지하부터 3층까지 카페인데 분위기가 각각 다 달라서 다양한 분위기를 즐길 수 이써요 그리고 피스타치오 티라미수 너무 마싯습니다…. 직원분들도 너무너무 친절해요…🫰🏻🫰🏻🫰🏻🫰🏻','2026-10-12T00:00:00.000Z'),
('nr-9','naver-2093701183','naver','고기리 유명 감성 청음카페의 가로수길점. 지하1층부터 3층까지 대형카페. 어마어마한 스피커와 음향시설의 청음카페지만 마치 가구 편집샾에 온 듯한 편안하고 멋진 소파와 테이블. 인테리어가 감각적이면서 고급스러움. 좌석이 여유롭게 배치되어 여유로움. 데이트나 혼자 작업이나 독서하기에 좋음. 지하 1층 청음실은 꼭 가보시길. 아메리카노는 구수하고 깔끔. 촉촉한 티라미수 강추.','2026-10-12T00:00:00.000Z'),
('nr-10','naver-2093701183','naver','음악도 좋고 인테리어도 널찍하고 여유있어서 편안하게 시간보내기 좋습니다☺️카페 넘 잘 찾아온 것 같아요','2026-10-12T00:00:00.000Z'),
('nr-11','naver-13093133','naver','프랑스식 빵과 프리미엄 디저트가 다양한 기욤 디카페인 커피 한잔씩 하며 잠시 쉼의 시간을 가졌어요. 인테리어도 예쁘고 감상있는 공간으로 인기있는 카페네요. 오랜만에 나간 청담동 핑크빛 입구부터 눈길을 끄는곳^^','2026-10-12T00:00:00.000Z'),
('nr-12','naver-13093133','naver','청담동 언덕애 있는 베이커리 카페입니다. 마카롱, 케익 전문점 같은데 커피도 맛납니다. 실내 공간이 넓고 독특한 인테리어로 꾸며 놓았습니다. 아이들이 무척 좋아할 공간입니다. 맛나게 마셨습니다. 사업 번창하세요.','2026-10-12T00:00:00.000Z'),
('nr-13','naver-13093133','naver','1년만에 다시 방문. 처음 만날때 선물했던 곳이라 좋은 기억이 있는곳. 1.매장 청결 2.직원분들 무척 친절 3.마카롱뿐만 아니라 에끌레르등 디저트 모두 맛있어보임 4.내부에서 다저트나 커피 즐기고 가기 좋을듯 5.기욤의 선물포장은 1년만에 봐도 예쁨 감사합니다! :)) 오늘 오랜만에 방문했는데, 1년전처럼 좋은 기억 :))','2026-10-12T00:00:00.000Z'),
('nr-14','naver-13093133','naver','아이스아메리카노 8000원 말차오레 13500원','2026-10-12T00:00:00.000Z'),
('nr-15','naver-13093133','naver','핑크핑크한 분위기도 너무 예쁘고 빵도 맛있어요🩵','2026-10-12T00:00:00.000Z'),
('nr-16','naver-13093133','naver','마카롱 최고!!! 🩷🩷🩷🩷','2026-10-12T00:00:00.000Z'),
('nr-17','naver-13093133','naver','자주 방문 하는 곳 인데 👀 리뷰를 처음 남기네요 ㅋㅋㅋ; 여전히 러블리한 기욤청담입니다 맛있고 분위기 러블리한 기욤 ~','2026-10-12T00:00:00.000Z'),
('nr-18','naver-13093133','naver','아메리카노도 맛있고 에끌레어에 카라멜크림 진짜 진하고 고급스러운맛!!','2026-10-12T00:00:00.000Z'),
('nr-19','naver-13093133','naver','디저트가 너무 맛있어요 저는 루시 케이크 골랐는데 쇼콜라도 맛있어보입니다!','2026-10-12T00:00:00.000Z'),
('nr-20','naver-13093133','naver','프랑스 디저트의 자부심이 느껴졌던 기욤카페에서 차와 까눌레, 비스켓을 즐겨봤어요. 인터넷에서 검색하다 가보게 되었는데 핑크컨셉이 새로웠고 베이커리와 디저트 모두 맛과 멋이 담겨있었네요.','2026-10-12T00:00:00.000Z'),
('nr-21','naver-1497634414','naver','케이크로 유명한 곳이라 해서 포장해왔습니다. 무화과 케이크와 몽블랑 케이크를 먹었고, 또 먹고 싶을만큼 맛있습니다. 개인적인 취향은 몽블랑보다는 무화과 케이크가 적당히 달달하면서 약간의 상큼한 과일향과 케이크가 잘 어우러진 것 같습니다. 다음 번엔 커피와 꼭 같이 먹어보고 싶습니다. 두 조각 포장하니 포장상자 사이즈도 딱 맞고, 보냉팩도 튼튼해서 돈주고 구매해도 후회 없습니다.','2026-10-12T00:00:00.000Z'),
('nr-22','naver-1497634414','naver','무화과를 좋아해서 시즌되면 찾아다니는 편인데, 까치화방에서도 오픈했길래 찾아왔어요. 평소에도 예쁜케이크가 많이 나오기도해서 눈여겨보다 왔는데 인테리어가 생각보다 넓게 잘 되어있네요👍 디저트는 무화과 생크림으로 시켰는데 무화과가 신선해서 좋네요! 다음번엔 무화과크럼블도 한번 먹어보면 좋을것같아요😊','2026-10-12T00:00:00.000Z'),
('nr-23','naver-1497634414','naver','커피 마시러 들렀는데 자리도 너무 편안하고 음악도 좋고 커피도 적당히 진하고 맛있어요. 대화하기도 좋습니다! 퐁신퐁신 수플레 카푸치노도 진짜 포근하고 따뜻하고 고소해요🐾 가을제철 무화과 디저트들도 넘 예쁘네요 배불러서 못했지만 베이커리류 다 먹어보고 싶어요🥹 무조건 재방문각입니당 !!','2026-10-12T00:00:00.000Z'),
('nr-24','naver-1497634414','naver','친구가 커피가 맛있다구 꼭 가보라고 추천해서 방문했어요. 커피 맛이 넘 좋고 넘 분위기있네요🥹 신논현에 카페 여러곳 돌아다녔었는데 앞으로 자주 올 것 같아요. 다음에는 무화과 케이크 먹으러 올게요','2026-10-12T00:00:00.000Z'),
('nr-25','naver-1497634414','naver','카페 너무 이쁘고 분위기 좋아요 1층은 햇볕 은은하게 들면서 짙은 녹색 느낌에 고급스러워요 2층은 좀 더 프라이빗한 느낌으로 바에 온거같은 느낌이에요 케이크는 강남에서 먹은곳중 최고에요 뭐하나 튀지않고 부드럽게 어우러지는 맛이에요','2026-10-12T00:00:00.000Z'),
('nr-26','naver-1497634414','naver','전체적으로 깔끔하고 편안한 분위기의 카페였어요. 매장도 쾌적하고 커피도 무난하게 맛있었습니다. 직원분들도 친절해서 편하게 이용할 수 있었고, 잠깐 쉬거나 이야기 나누기 좋은 곳이에요. 근처에 오게 되면 다시 방문할 것 같습니다 :)','2026-10-12T00:00:00.000Z'),
('nr-27','naver-1497634414','naver','강남 올때마다 자주 애용하는데 베이커리랑 케이크가 맛있어요. 과일 케이크 조각도있고 작은사이즈 아파트사이즈 있는데 가격도 괜찮고 다 맛있습니다. 예뻐서 선물용으로도 추천해요 커피도 맛있습니다 ❤️','2026-10-12T00:00:00.000Z'),
('nr-28','naver-1497634414','naver','분위기가 너무 좋고 초코 바게트는 처음인데 질겨서 잘 안썰리긴하지만 따근하고 좋아요...무화과 케이크도 커피도 좋어용 🥰👍🏻 화병도 살 수 있고 여러모로 이쁜곳~~','2026-10-12T00:00:00.000Z'),
('nr-29','naver-1497634414','naver','무화과철에 무화과 케이크 먹고싶어서 왔는데 인테리어도 너무 예쁘고 분위기가 너무 좋네요~~ 케이크도 맛잇어서 담에 다른 제철과일 케이크 또 먹으러 오려고용','2026-10-12T00:00:00.000Z'),
('nr-30','naver-1497634414','naver','까치화방 ◾ 말차 피치 5,900원 ◾ 평일 점심 방문 ◾ 1~3층으로 구성된 대형카페 작년에 케이크를 구매하러 방문했던 기억이 있어 이번에는 말차 피치가 궁금해 다시 들러봤어요. 말차의 은은한 향과 복숭아의 달콤하고 상큼한 맛이 잘 어우러진 음료였습니다. 층이 나뉜 색감도 예뻐서 보기에도 좋았고, 마실 때는 깔끔하게 넘어가 부담 없이 즐길 수 있었어요. 평일 점심시간에 방문했는데 좌석에 여유가 있어 조용하게 쉬다 가기 좋았습니다. 1층부터 3층까지 공간이 넓어 원하는 분위기에 맞춰 자리 잡기 편했고, 전체적으로 어둡고 고급스러운 인테리어가 인상적이었어요. 잠시 휴식이 필요하거나 분위기 좋은 대형카페를 찾는다면 방문해볼 만한 곳입니다🙂','2026-10-12T00:00:00.000Z'),
('nr-31','naver-32269733','naver','다시 재방문한 노아 베이커리. 압구정에 일이 있어 카페 방문했는데 다시 재방문했어요. 갓 구운 빵과 맛있는 커피가 정말 맛있어 재방문했어요...저는 모카빵을 좋아해서 1번으로 선택했어요. 재방문 의사 및 지인 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-32','naver-32269733','naver','압구정 현대아파트 앞에 있는 빵집.. 여러가지 빵이 많이 진열되었고 식사대용으로 먹을 수 있는 빵과 커피를 파는 곳.. 맛은 평범한데 매장이 깔끔하고 공간이 널찍해서 이야기나누다 가기 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-33','naver-32269733','naver','압구정에 올 일이 있어서 왔다가 들렸는데 빵도 맛있어보이고 음료도 맛있더라두요! 매장에서 먹엇는데 집 갈 때 빵듀 사갈라두요 ㅎㅎ 조용하고 만족해요👍👍👍','2026-10-12T00:00:00.000Z'),
('nr-34','naver-32269733','naver','공간이 크고 깔끔합니다. 빵도 여기서 직접 제조하시는데 성수동지가를 생각해봤을때 1층 공간에서 직접 빵제조해서 판다는게 참 멋지십니다.','2026-10-12T00:00:00.000Z'),
('nr-35','naver-32269733','naver','🥖빵 생각날 때 종종 방문하는 곳인데 올 때마다 만족도가 높은 베이커리예요. 이번에는 크랜베리 바질 마카다미아 치즈빵을 먹어봤는데 재료 조합이 정말 좋네요. 크랜베리의 은은한 달콤함과 바질 향, 고소한 마카다미아에 치즈 풍미까지 더해져 질리지 않고 맛있게 먹었습니다. 먹기 편하게 커팅도 해주셔서 좋았고 빵 종류가 다양해서 고르는 재미도 있어요. 카페 공간도 아늑하고 편안한 분위기라 잠깐 쉬어가기에도 잘 어울리는 곳입니다.','2026-10-12T00:00:00.000Z'),
('nr-36','naver-32269733','naver','압구정역 근처 카페 찾다가 들어갔는데 좌석 넓고 좋네요. 조용하게 얘기하고 싶을 때 추천드려요 ㅎ','2026-10-12T00:00:00.000Z'),
('nr-37','naver-32269733','naver','압구정 병원 방문하다 발견한베이케리 카페입니다. 요즘 건강빵에 관심이 많아 주로 건강빵 위주로 먹고 있는데 빵도 다양하고 맛있어요. 커피도 향도 좋고 빵이랑 함께 먹으니 좋네요. 압구정 방문하면 재방문 의사있어요. 적극 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-38','naver-32269733','naver','압구정역 근처에 있는 맛난 빵집입니다. 간식용으로 빵 몇개 포장했는데 맛나네요. 이 자리에 꽤나 오래 있었던 것으로 기억합니다. 승승장구하세요.','2026-10-12T00:00:00.000Z'),
('nr-39','naver-32269733','naver','와이프랑 압구정 데이트 오랜만에 왔어요! 갬성 카페 찾아보니 베이커리도 맛있다고 해서 왔네요! 33곡 미숫가루라테랑 뱅오쇼콜라 너무 맛있네요^^ 음악도 좋고 분위기도 좋네요😄','2026-10-12T00:00:00.000Z'),
('nr-40','naver-32269733','naver','성수 나들이… 지쳐가던 중 오아시스 발견!!!! 레몬에이드랑 아메리카노, 복슝아 케잌으로 당 충전!! 공원뷰도 이쁘고~ 커피숍도 쾌적!!!','2026-10-12T00:00:00.000Z'),
('nr-41','naver-2040815061','naver','도성초교사거리에서 선릉역 사이 대치동 골목 안에 숨어 있는 위스키바 분위기가 나는 카페. 데일리 아메리카노 4,900원에 테이크아웃 완료. 일반 아아를 주문했는데 은은하게 달지 않으면서 고소한 헤이즐넛 향이 나는 게 매력이다. 이 집 커피 괜찮았음.','2026-10-12T00:00:00.000Z'),
('nr-42','naver-2040815061','naver','선릉에 이런 멋진 카페가 있는 줄 몰랐어요•• 인테리어도 깔끔하니 테라스석도 낭만 있고 무엇보다 커피, 디저트가 정말정말 맛있어요 ♡ 프렌치토스트 강강강추 드립니다 !!!! 재방문 592010 할 의사 있는 선릉 최고 카페에요 -','2026-10-12T00:00:00.000Z'),
('nr-43','naver-2040815061','naver','커피 마시러 종종 들르던 커피바 선릉, 이번에는 지인들과 저녁에 와인 한잔하러 갔어요. 익숙한 곳인데 저녁에 오니 또 새롭더라고요. 선선한 가을바람을 느낄 수 있는 데크 자리도 있어 반가웠어요. 직원분이 와인에 대해 친절하게 설명해주시고 직접 오픈해주셔서 기분 좋게 시작했어요. 안주로 주문한 샤퀴테리칩, 피치 컨트리 브레드, 피치 소르베도 모두 맛있어서 와인 한잔 곁들이며 즐겁게 먹었네요. 좋은 사람들과 맛있는 음식 앞에 두고 이런저런 이야기를 나누다 보니 시간이 금방 지나갔어요. 앞으로는 커피도, 와인도 생각날 때 들르게 될 것 같아요','2026-10-12T00:00:00.000Z'),
('nr-44','naver-2040815061','naver','조용하고 차분한 분위기 덕분에 대화하기 좋은 카페!! 음료가 달달하고 맛있어서 카이막도 추가했는데... 넘 맛있어요.... 매장에서 직접 만드는 수제 카이막이라던데 맛이 진하고 빵하고도 찰떡인 것!! 아지트 삼아 종종 와야겠어요!!','2026-10-12T00:00:00.000Z'),
('nr-45','naver-2040815061','naver','완전 대박적 원두 맛… 과일향 산미 가득한 드립 아아랑 꾸덕한 크림에 달콤한 복숭아 산도 선릉이 아니고 어디 핫플에 있을 법한 곳','2026-10-12T00:00:00.000Z'),
('nr-46','naver-2040815061','naver','카이막도 커피도 맛있어요 동생이 동네에 엄청 괜찮은커피집 생겼다고해서 와봤는데 너무 쾌적하고 좋아요! 카이막도 너무 진하고 맛있어요 커피바라 와인이랑 위스키도 파는데 사퀴테리칩도 맛있을 거 같아서 다음번에 한번 저녁에도 와 보고 싶어요~','2026-10-12T00:00:00.000Z'),
('nr-47','naver-2040815061','naver','처음생겼을때부터 다녔던 커피숍. 여기 커피 말로 표현 못해요. 진짜 맛있어요. 아파서 입맛없을때도 여기커피는 생각날정도. 회사에는 여기 드립백 사놓고 타마셔요. 일하는 분들도 친절하시고 좋아요','2026-10-12T00:00:00.000Z'),
('nr-48','naver-2040815061','naver','삼성동에서 밥 먹고 노크 커피바에 방문했어요! 일단 주차 어려운 동네에서 무료 주차 가능한 카페라 너무 좋구요! 사장님,직원분들 모두 너무 친절하고 상냥하세요♡ 에어리카노가 궁금했는데 스벅의 나이트로 커피랑 비슷해요. 씁쓸함은 줄이고 부드러움만 남긴 커피맛이에요! 간만에 마시는 질소커피라 맛있게 마셨고 바치케도 직접 만드시는 것 같은데 맛있었 어요! 너무 달거나 산미 강하지 않으면서 적당히 꾸덕해서 식감이 딱 좋았습니다. 마지막에 주문한 말차빙수(18000원)는 아이스크림 한 스쿱 같은 양으로 적은 양이지만 제일 맛있었어요!! 시럽 뿌리지 않고 그냥 먹었는데 달지 않으면서 사각한 얼음이라 몹시 맛있게 먹었답니다♡','2026-10-12T00:00:00.000Z'),
('nr-49','naver-2040815061','naver','에스프레소 토닉!!!! 새콤하게 토~ 달콤하게 닉~ 청량한 맛 아메리카노는 초콜릿 향 은은한게 대박적 커피를 살기 위해 먹는 게 아니고 즐기려고 오는 곳 상호 바꾸고 더 잘되는 것 같아서 좋아요 이 일대 젊은 분들 엄청 많이 오심 메뉴 하나하나가 새롭고 원두가 초초초대박 쿠키 감사합니다 ❤️','2026-10-12T00:00:00.000Z'),
('nr-50','naver-2040815061','naver','비가 엄청 내리던 평일 점심에 커피랑 디저트 먹으러 방문한 노크 커피바 선릉! 매장 인테리어가 블랙이라 묵직하게 멋졌고 수제카이막, 후르츠산도, 얼그레이 밀크티, 카페라떼와 아아 주문했는데 모두 순삭했습니다♡ 특히 카이막이 맛있었어요!ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-51','naver-1102745487','naver','800일 기념일 케이크로 다크그림 신논현역점에서 테디소파 케이크 예약해서 픽업했어요💙 평소 레터링 케이크는 크림치즈 베이스가 많아서 디자인만 예쁘고 끝까지 다 못 먹는 경우가 많았는데, 여기 소파 부분은 입안에서 사르르 녹는 부드러운 우유 생크림이라 느끼함 없이 정말 맛있게 먹었어요! 안쪽 시트도 달달하고 진한 브라우니라 생크림과의 조합이 완벽하고, 아메리카노랑 같이 먹으니 극락입니다 ☕️ 신논현역 3번 출구 바로 앞이라 픽업 동선도 최고고, 매장도 무채색 블랙 힙한 인테리어라 분위기 너무 좋네요. 비주얼도 맛도 다 잡은 케이크 찾으시면 무조건 추천합니다! 🧸✨','2026-10-12T00:00:00.000Z'),
('nr-52','naver-1102745487','naver','강남 신논현역 근처에서 분위기 좋은 카페를 찾다가 다크그림을 방문했습니다. 모던한 블랙톤 인테리어에 은은한 조명이 더해져 세련되면서도 차분한 분위기가 인상적이었고, 무엇보다 매장이 넓고 쾌적해 여유롭게 머물기 좋았습니다. 도심 속에서 발견한 보석 같은 공간이라는 표현이 잘 어울리는 곳입니다. 이날 주문한 메뉴는 라테, 아메리카노, 브라우니 아이스크림입니다. 라테는 부드럽고 고소한 우유 풍미와 은은한 커피 향이 좋았고, 아메리카노는 깔끔하면서도 깊은 커피 풍미가 느껴졌습니다. 브라우니 아이스크림은 진하고 꾸덕한 브라우니에 부드러운 아이스크림이 더해져 달콤함이 배가됐습니다. 따뜻하고 쫀득한 브라우니와 시원하고 부드러운 아이스크림의 식감 대비도 매력적이었습니다. 신논현역에서 편안히쉬어가기 좋은 카페로 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-53','naver-1102745487','naver','엄마랑 신논현 근처 데이트하다가 방문한 다크그림! 강남 신논현 카페 중에서도 매장 바로 앞에 주차 가능해서 편하게 들어갔어요. 네이버 플레이스 메뉴랑 현장 메뉴판 주문 가능 여부가 조금 다르니 참고하세요!! 제가 주문한 시그니처 메뉴인 테디크림라떼와 테디아인슈페너는 곰돌이 얼음이 올라가서 귀엽고 크림도 정말 고소 하더라고요.❤️. 귀여운 곰돌이 모양의 초코브라우니 아이스크림 세트는 쫀득쫀득 달달하고 아이스크림이랑 합이 너무 좋아서 저희.엄마가 더 맛나게 드셨어요 ㅋ인테리어도 감성 넘치고 사진 잘 나오니 강남 신논현 디저트 맛집 찾는 분들께 추천해요!','2026-10-12T00:00:00.000Z'),
('nr-54','naver-1102745487','naver','카페 분위기가 너무 좋아서 여유롭게 시간 보내기 딱 좋았어요. ㅎㅎ ☕ 분위기 좋은 공간에서 커피 한잔하니 제대로 힐링하는 느낌이었어요! 테디 브라우니도 달달하면서 부드러워서 맛있었고 아이스크림까지 같이 먹으니 조합은 말해 모해.... 🍨 주문 케이크도 있었는데 디자인이 너무 귀여워서 눈길이 가더라구요! 다음에는 주문 케이크도 꼭 한번 먹어보고 싶어요. ㅎㅎ 🎂','2026-10-12T00:00:00.000Z'),
('nr-55','naver-1102745487','naver','친구 생일케이크 검색하다가 너무 귀여운 곳을 발견했어요 곰돌이 의자도 고를 수 있고 레터링 케이크로 너무 좋은 것 같아요🐻','2026-10-12T00:00:00.000Z'),
('nr-56','naver-1102745487','naver','귀엽게 초도 바꿨더니 훨씬 퀄리티가 좋아져서 너무너무 남편이 좋아했어요! ~! 유부남된 기념과 생일기념으로 해줬는데 케익이 맛도있구 이뿌구 담에 또 이용할거같아영','2026-10-12T00:00:00.000Z'),
('nr-57','naver-1102745487','naver','신논현역 곰돌이 케이크가 너무 귀여운 다크그림 케이크로 케이크 사러 방문했어요 :) 들어가자마자 진한 초코향이 브라우니 맛이 너무 기대되더라구요!! 친구 생일로 구매했는데 친구도 완전 귀엽다고 맘에 들어했어요🫶','2026-10-12T00:00:00.000Z'),
('nr-58','naver-1102745487','naver','카페는 전체적으로 블랙톤 인테리어라 분위기가 세련되고 미감 높은데, 귀여운 테디베어 모양의 아이스크림과 베이커리가 반전 매력이에요! 특히 넘모 귀여운 테디베어 아이스크림 세트는 꼭 추천하고 싶어요!!🥺 그리고 시그니처 테디베어 아인슈패너 아이스도 사진이 예쁘게 나와 강력 추천합니다👍 친구와 방문했는데 귀여운 비주얼에 반해 계속 사진을 찍을 정도였어요ㅜㅜ 달콤한 디저트를 좋아하시는 분들께 꼭 추천하며, 디카페인 있어서 밤늦게 가기에도 좋아여! 기념일이 있으면 다음에도 꼭 다시 찾아가고 싶은 멋진 카페예요 🧸🖤','2026-10-12T00:00:00.000Z'),
('nr-59','naver-1102745487','naver','선물하기 너무 좋구, 다음에 또 올 것 같아요! 추천해요!!!!','2026-10-12T00:00:00.000Z'),
('nr-60','naver-1102745487','naver','곰돌이가너무귀여워요 커피도너무맛잇어요 또올게요','2026-10-12T00:00:00.000Z'),
('nr-61','naver-13574087','naver','한강 피크닉 가면서 듀자미에서 케이크 포장했어요🍰🤍 케이크 종류가 다양하고 하나같이 비주얼이 예뻐서 고르는 순간부터 행복한 고민ㅎㅎ 무엇보다 케이크가 너무 달기만 하지 않고 크림은 부드럽고 촉촉해서 맛있었어요! 재료 맛도 잘 느껴지고 전체적인 맛의 밸런스가 좋아서 한 조각도 부담 없이 순삭✨ 역시 케이크 맛집이라는 생각이 들더라고요. 예쁜 케이크 포장해서 한강에서 먹으니 피크닉 분위기도 제대로🌿🤍 다음 피크닉 때도 케이크 생각나면 또 들를 것 같아요!','2026-10-12T00:00:00.000Z'),
('nr-62','naver-13574087','naver','간만에 디저트 맛집을 갔더니 좋았어요. 커피는 필터는 없지만 3종류가 참 맛나네요 베리류맛 아주 좋았습니다. (풍미있슴) 디저트는 시그니처 솔트 카라멜 케이크 너무 맛나네여! 다 먹어보겠어요 💙','2026-10-12T00:00:00.000Z'),
('nr-63','naver-13574087','naver','오랜만에 방문한 듀자미. 맛은 그대로다. 금액은 이렇게 비쌌었나ㄷㄷ 딸기케잌으로 유명한 듀자미 맛은 그대로 좋다. 구름둥둥은 처음 먹어봤는데 피스타치오랑 딸기 조합이 좋았다.','2026-10-12T00:00:00.000Z'),
('nr-64','naver-13574087','naver','여긴 부르면 가져가는 시스템이에요 주문번호 불렀는데 제가 그렇게 늦게 간것도 아니고 테라스에 있어서 1분만에 갔는데 알바생들끼리 부르면 알아서 가져가야한다 어쩌고저쩌고 자기들끼리 얘기하는게 제가 가져가는데 다들려서 좀 불쾌했어요. 블루리본은 엄청 많은데 직원교육좀 잘 시키세요. 케익 맛보기도전에 기분 별로에요','2026-10-12T00:00:00.000Z'),
('nr-65','naver-13574087','naver','여자친구 선물용으로 케익 샀는데 얼마나 좋아할지 기대가 되네요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-66','naver-13574087','naver','수박쥬스&소르베/ 애플셔벗티/ 딸기생크림케잌/ 구름둥둥/+밀푀유프랄리네/ 배부른 상태로 먹었음에도 너무 맛있었다는 점이 포인트! 딸생케는 무난할 수있지만, 이 곳에선 우유크림의 부드러운맛과 딸기와 시트자체가 다 잘 어울려서 맛있었어요~ 딸기타르트도 있지만, 타르트보단 케잌을 선호해서 케잌으로 먹었어요ㅎ 구름둥둥은 겉은 크림이지만 속에 피스타치오 시트와 산딸기크림이 있어서 일행이 단맛도 적당하고 맛있어서 좋아했어요~ 추가로 시킨 밀푀유는 고소한 맛이 가득했어요~ 일행은 너무 달다고 했지만, 제 입맛에 단맛은 딱 적당했어요~ (일행이 느낀 단맛은 밀푀유의 밑부분이 였던것같아요ㅎ) 딸생케를 추천받아서 온 곳인데 다양한 종류의 케잌도 있어서 너무 좋았고 직원들도 너무 친절해서 좋았어요~ 다른 케잌도 먹고 싶어요~','2026-10-12T00:00:00.000Z'),
('nr-67','naver-13574087','naver','가로수길에 오면 반드시 들러야 할 케이크 맛집이 있다. 그중에서도 특히 애정하는 듀자미는 매장 통창을 채운 블루리본 개수부터 압도적이다. 이곳 생크림케익은 여느 디저트 카페와는 차원이 다른 부드러운 식감과 고소함을 자랑해 꼭 맛봐야하는 메뉴! 빵 시트 역시 무너지지 않을 만큼 탄탄하면서도 은근하게 촉촉해, 시트 사이 듬뿍 들어간 달콤한 딸기와 완벽한 조화를 이룬다. 추천 메뉴는 시그니처인 ‘구름둥둥’과 올해로 17주년을 맞이한 ‘딸기 생크림 케이크’다. 누구에게 추천해도 실패 없을 맛! 특히 카페 내 취식 시 1인 1메뉴(디저트 포함)만 주문하면 음료를 강제하지 않아, 가로수길에서 꽤 합리적으로 디저트를 즐길 수 있다는 것도 큰 장점. 커피 없이 케이크만 먹어도 전혀 느끼하지 않은, 제대로 된 디저트 맛집🍰','2026-10-12T00:00:00.000Z'),
('nr-68','naver-13574087','naver','듀자미 구름둥둥 포장했어요- 귀염귀염합니다! 친구 생일여서 귀요미에 초 꽂았어요. 케이크 종류도 많고 친절하셔서 재방문 무조건 합니다! 케이스 안에 포장도 꼼꼼하게 신경써서 해주셨어요 흔들릴까봐 걱정했는데 걱정 안해도 될거처럼 잘 해주셨습니다! 포장도 맛도 친절하고 좋아요! 추천합니다!','2026-10-12T00:00:00.000Z'),
('nr-69','naver-13574087','naver','딸기 케이크 맛있어요 특별한 맛은 아니지만 맛있는 케이크 디저트도 많고 매장은 예쁜데 직원분이 친절한 편은 아닌 듯 합니다','2026-10-12T00:00:00.000Z'),
('nr-70','naver-13574087','naver','워낙 유명한 카페라 타이밍 맞춰 방문했습니다. 마침 마지막 하나 남아있던 밀푀유 말차를 주문했는데, 진한 녹차크림과 파삭한 밀푀유 식감의 조화가 좋았습니다. 과하지 않은 달콤함이라 커피와 차 모두 잘 어울렸고 디저트 완성도가 느껴졌어요. 원두도 선택 가능하고, 디저트 종류도 다양해 선택 폭이 넓고, 2층까지 좌석이 있어 여유 있게 머물기 좋은 카페입니다. ☺️','2026-10-12T00:00:00.000Z'),
('nr-71','naver-1560351161','naver','신사 쪽에서 파이와 음료를 함께 즐기고 싶다면 따우전드 신사 강추 ㅎㅎ저는 아이스 아메리카노와 아이스 밀크티, 치즈 블루베리 파이, 피그레이 파이를 주문 완! 야장 좌석과 애견동반 가능 여부, 배터리 충전까지 다 가능 ㄷㄷ 신사역카페를 찾거나 가로수길카페에서 디저트를 즐기고 싶은 분, 파이맛집을 찾는 분들 바로 여기 ㄱㄱ가로수길디저트가 당기는 날 방문해 보거나 신사핫플 코스에 넣어도 좋을듯??? 가로수길디저트포장으로 파이를 가져가기 가능 저도 포장함','2026-10-12T00:00:00.000Z'),
('nr-72','naver-1560351161','naver','신사에서 파이 먹고 싶어서 들른 따우전드 신사점! 바닐라크림파이랑 펌킨파이 먹었는데 둘 다 너무 달기만 하지 않고 맛있었어엽🥹🫶 바닐라크림파이는 기대한대로 바나나향과같이 너무 부드럽고 맛있구요.. 펌킨파이는 호박 특유의 은은한 단맛이 잘 느껴져서 취향이었어요❣️ 신사역 근처에서 디저트 찾는다면 또 방문하고 싶은 곳이에요!','2026-10-12T00:00:00.000Z'),
('nr-73','naver-1560351161','naver','가로수길 갔다가 따우전드 신사에서 파이 포장해왔어요. 바나나 크림 파이는 바나나가 넉넉하게 들어 있고 생각보다 단맛이 세지 않아서 계속 손이 가는 맛이었어요ㅎㅎ 특히 타르트지가 바삭해서 식감이 좋았습니다','2026-10-12T00:00:00.000Z'),
('nr-74','naver-1560351161','naver','커피와 파이를 같이 먹고 싶은 날 들르기 좋았어요 :) 따우전드 신사점에서 주문한 아메리카노는 진했고, 오트바닐라라떼는 담백해서 두 음료의 느낌이 달랐어요. 스무스한 맛을 좋아한다면 오트라떼 쪽이 잘 맞을 것 같아요. 파이는 무화과가 올라간 피그레이와 치즈블루베리로 골랐어요. 얼그레이와 신선하고 달달한 무화과 조합도 좋았지만, 블루베리 크림이 과하게 달거나 느끼하지 않은 점도 마음에 들었어요.','2026-10-12T00:00:00.000Z'),
('nr-75','naver-1560351161','naver','커피도 진하고 파이가 진짜 진짜 맛있네요. 무화과 들어간 파이는 얼그레이 맛이 나는데 무화과도 신선하고 많이 안달아서 좋았고, 치즈 블루베리는 적당히 달달하고 상큼해요. 유럽 분위기나는 인테리어도 멋있어요. 야외 테이블에 앉았는데 정말 좋은 시간을 보냈어요.','2026-10-12T00:00:00.000Z'),
('nr-76','naver-1560351161','naver','신사에서 카페 찾다가 들어갔는데 분위기가 생각보다 너무 좋았어요. 노란 조명이랑 벽에 큰 거울이 있어서 공간이 넓어 보이고 팝송이 나와서 약간 미국 카페 같은 느낌도 났어요!! 유자파인파이랑 피칸파이 먹었는데 유자파인파이가 진짜 너무 맛있었어요….♥️ 새콤상콤해서 레몬케이크 같은 느낌이고, 피칸파이는 고소하고 달달한 맛! 둘이 맛이 확 달라서 번갈아 먹기 좋았어요. 파이 종류가 꽤 다양해 보여서 다른 것도 먹어보고 싶더라고요. 밖에 테이블이랑 화분도 예쁘게 되어 있어서 날씨 선선할 때 야외에 앉아 있으면 분위기 좋을 것 같아요. 사진도 잘 나오는 카페라 신사 쪽 갈 일 있으면 또 들를 것 같아요 :)','2026-10-12T00:00:00.000Z'),
('nr-77','naver-1560351161','naver','친구 생일기념으로 찾아보고 방문하였는데 컨셉도 너무 좋고 분위기와 음악도 무드있게 좋습니다 :) 사장님도 친절하시고 다음에 신사에 올때 또 한번 들려서 그때는 직접 먹어보고 가야겠어요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-78','naver-1560351161','naver','#협찬 너무 예뻐서 와보고 싶던 카페예요 외관부터 내부까지 빈티지한 모습으로 꾸며져 있어서 완전 취향저격 당했어요💘 혈당 폭발할 각오 하고 갔는데 파이다 생각보다 많이 달지 않아서 오히려 좋았어요! (다음에 또 많이 먹어도 된다는 소리😋)','2026-10-12T00:00:00.000Z'),
('nr-79','naver-1560351161','naver','아메리칸 파이가 이렇게 맛있는 줄 처음 알았어요 파이가 딱딱하지 않고 부드러워요~ 술술 넘어가요 진짜 맛있어요 커피와도 잘 어울려요 파이 종류가 다양해요 시즌마다 나오는 메뉴도 달라요 주차는 불가능해요','2026-10-12T00:00:00.000Z'),
('nr-80','naver-1560351161','naver','워낙 유명한곳이고 성수나 다른지점도 방문한 맛집이에요 분위기도 좋고 파이도 맛있어요 따우전드는 늘 사랑입니다','2026-10-12T00:00:00.000Z'),
('nr-81','naver-2081934943','naver','라비르에서 고구마브륄레, 휘낭시에, 쇼콜라 디아망, 무화과 타르트에 쵸코라떼랑 아메리카노까지 먹어봤어요 ☕️🍠🍫 고구마브륄레는 위에 바삭하게 올라간 부분이 포인트라 식감도 좋고 고구마의 달달한 맛이 잘 어울렸어요. 휘낭시에는 겉은 살짝 바삭하고 안은 촉촉해서 커피랑 같이 먹기 좋았고, 쇼콜라 디아망은 초코 풍미가 진해서 달달한 거 좋아하는 분들께 잘 맞을 것 같아요. 무화과 타르트도 무화과가 올라가 있어서 상큼하면서 달콤하게 먹기 좋았고, 쵸코라떼는 부드럽고 진한 초코맛이라 디저트랑 찰떡이었어요ㅋㅋ 아메리카노까지 같이 주문하니 달달한 디저트 먹으면서 커피가 딱이네요 ㅋㅋ','2026-10-12T00:00:00.000Z'),
('nr-82','naver-2081934943','naver','첫인상은 그저 깔끔한 인테리어구만 이게 전부였습니다. 근데 따뜻한 아메리카노를 한 모금 마시는 순간 와 이집 커피는 묵직하구나 그리고 에그타르트 장난이 1도 없는 집이구나를 느낄 수 있었습니다. 그 작고 작은 귀여운 동그라미 안에 모든 진심를 꾹꾹 눌러 담은 무화과 크림치즈 휘낭시에도 와 정말 개눈 감추듯이 뱃속으로 들어갔습니다. 정말 마싯는 디져트 집을 발견한 날이네요. 문앞에 붙은 "빠티쓰히" 라는 단어가 진심으로 느껴졌습니다. 담에 또 가서 다른 것도 먹어보렵니다.','2026-10-12T00:00:00.000Z'),
('nr-83','naver-2081934943','naver','아메리카노는 살짝 산미가 있고, 옥수수 쁘띠갸또르가 제일 맛있었어요! 옥수수크림이 고소하고 맛있어요. 초코 휘낭시에와 마들렌은 무난했고, 라떼아트도 예뻐서 좋았어요 🤎 양재역 근처에서 깔끔한 카페 찾는다면 추천!','2026-10-12T00:00:00.000Z'),
('nr-84','naver-2081934943','naver','구움과자 좋아해서 이것저것 많이 먹어봤는데 라비르는 전체적으로 많이 달지 않고 재료 맛이 잘 느껴져서 좋았어요. 특히 대추케이크는 처음 먹어봤는데 생각보다 훨씬 맛있었어요. 대추 특유의 은은한 단맛과 향이 나면서도 너무 무겁거나 텁텁하지 않고, 촉촉해서 커피랑 같이 먹기 딱 좋았어요. 구움과자들도 버터 향이 고소하게 나고 식감도 좋아서 하나씩 먹다 보니 금방 없어지더라고요. 포장도 깔끔해서 선물용으로도 괜찮을 것 같아요. 대추 디저트는 왠지 어른들 입맛일 것 같다는 생각이 있었는데 전혀 아니었고, 오히려 흔하지 않은 맛이라 더 기억에 남았어요. 다음에는 다른 종류도 같이 먹어보고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-85','naver-2081934943','naver','양재역 근처에서 디저트 맛집 찾다가 방문했는데 정말 만족스러웠어요. 버터스카치라떼, 럼 바닐라 마들렌, 휘낭시에, 쇼콜라 디아망, 플뢰르 드 시트롱까지 다양하게 맛봤는데 하나같이 완성도가 높았습니다. 특히 마들렌이랑 휘낭시에는 겉바속촉이 확실해서 수제로 만든 티가 딱 나더라고요. 매장 분위기도 차분하고 조용해서 커피 한 잔 하기 좋았어요. 디저트 위주로 판매하는 곳이라 메뉴 구성도 특별하고, 재료 퀄리티가 좋다는 게 먹으면서 바로 느껴졌습니다. 양재역 근처 카페 찾으시는 분들께 추천드려요!','2026-10-12T00:00:00.000Z'),
('nr-86','naver-2081934943','naver','양재역쪽에 올 일있어서 들렸다가 에그타르트가 있어서 들렸어요!! 다음에 오면 무화과타르트를 꼭 먹어보고 싶습니당😆 사장님이 디저트에 진심이신 것 같아용','2026-10-12T00:00:00.000Z'),
('nr-87','naver-2081934943','naver','점심시간에 혼자 왔는데 조용하고 맛있어서 힐링하고 가요!! 또 올거같아요!! ☘️','2026-10-12T00:00:00.000Z'),
('nr-88','naver-2081934943','naver','양재역 근처에 이런 느좋 카페가 있다니.. 동네사람이면 진짜 자주 올 것 같아요 타르트가 품절이라 아쉽지만 다른 디저트들도 맛잇어요','2026-10-12T00:00:00.000Z'),
('nr-89','naver-2081934943','naver','골목길에 한적하게 자리 잡고 있는 예쁜 카페네요 검색으로 케이크가 너무 맛있어 보여서 왔어요🩵 일반 카페에서 보기 드문 케이크가 있어요 예쁘기도 하고 맛도 특별해 보여서 기대됩니다🥰!','2026-10-12T00:00:00.000Z'),
('nr-90','naver-2081934943','naver','동네에 생긴 이쁜 카페에 왔어요.차도 맛있고 과자도맛있어요.그리고 미니케이크도 넘넘 이쁘네요.👏🏻👏🏻👏🏻일요일날 열어서 좋아요😄','2026-10-12T00:00:00.000Z'),
('nr-91','naver-1317157725','naver','강남에 에타, 스콘맛집이라고 해서 왔어요!! 스콘도 맛있지만 에그타르트가 진짜진짜 맛있어요. 겉에 적당히 바삭하면서 에그필링은 촉촉하고 버터향도 나면서 완전 고소해요! 제가 먹은 에타 탑3안에 들어여 스콘도 짱마싯고 너무 뻑뻑하지 않고 바삭해서좋아요. 스콘 맛집 진짜 인정합니다,,, 그냥 잼 안발려져 있는 스콘도 맛있어요ㅠㅠㅠ 평일인데도 사람많고 직장인들이 많이 오시는 것 같아요. 강남에 유명하고 사람많은 웬만한 카페 디저트보다 여기가 진짜 맛있는 것 같아요. 또올거에여 귯','2026-10-12T00:00:00.000Z'),
('nr-92','naver-1317157725','naver','공간이 넓어서 왔는데 장소 자체가 쾌적하고 너무 예뻐요!! 디저트 종류도 많아서 눈이 돌아가게 되는...🤩🤩 사진도 잘 나오고 대화하기에도 좋고 디저트와 커피까지 맛있고!!! 아주 좋은 장소를 찾은 것 같아 기분이 좋아요🩷🩷','2026-10-12T00:00:00.000Z'),
('nr-93','naver-1317157725','naver','아이스 카페라떼, 스콘 먹었는데 맛있어요. 스콘에 버터 맛이 많이 나서 좋네요. 인테리어도 예쁘고 식기류가 너무 고급스럽고 예쁘네요!','2026-10-12T00:00:00.000Z'),
('nr-94','naver-1317157725','naver','근처 베이커리 찾다가 에그타르트 찾다가 왔는데 다른 스콘들도 너무 맛있었어요! 커피도 맛있고 분위기도 넘 좋아요 ㅎㅎ 다음에도 근처에 오면 또 들르고 싶어요. 따뜻하게 데워주시기도 하셔서 더 맛있게 먹었습니다 :)','2026-10-12T00:00:00.000Z'),
('nr-95','naver-1317157725','naver','언제와도 너무 맛있는 스콘과 에그타르트!! 쇼케이스 여는 순간 버터향이 가득!! 너무나무 맛있어요!!','2026-10-12T00:00:00.000Z'),
('nr-96','naver-1317157725','naver','분위기 좋은 카페☕️✨️ 밀크티 은은하게 맛있네요~ 근데 비엔나커피랑 밀크티 위에 크림만..좀..어떻게.. 솔트크림인지 많이 짜더라구요🥲','2026-10-12T00:00:00.000Z'),
('nr-97','naver-1317157725','naver','우연히 주변 병원방문으로~~~띠라리 점심시간이라 웨이팅ㅠㅠ 다시 재도전!!! 우와~~~~^^ 고급스런 버터.나이프가 취향저격🌈🌈🌈 커피듀 맛나요👍👍👍 스콘듀 쵝오👍 다시 재방문~~~~ 더운날씨🤗🤗🤗건강조심하세용','2026-10-12T00:00:00.000Z'),
('nr-98','naver-1317157725','naver','근처에 일이 있어 왔다가 시간이 조금 남아 들렸어요 강남역 카페 주차 라고 검새하고 주차 30분 무료라서 아무생각없이 왔는데 넓은 카페에 맛있는 베이커리 디카프 커피도 넘 맛있고 운이 좋았네요ㅎ 잠시나마 여유부리고 갑니다🩵🙏','2026-10-12T00:00:00.000Z'),
('nr-99','naver-1317157725','naver','스콘 에그타르트 맛집이네여 에그타르트 존맛탱입니다 와서 먹구 잔뜩 포장해가요 배달주문도 엄청 많더라구요 선물하기도 좋을 것 같구 단골될 예정입니당 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-100','naver-1317157725','naver','에그스콘에 이끌려 왔는데 너무 강남강남 한 곳에서 커피 한 잔 했어요~ 분위기도 좋고! 직원분들도 친절하셔서 기분좋게 쉬다 갔네요~','2026-10-12T00:00:00.000Z'),
('nr-101','naver-1257167808','naver','주기적으로 먹어줘야 하는 레이지요거트 어쩜 베흐싱글만 먹게 되는지..! 근데 날이 너무 좋아서 가을 기념 마롱이 당겨서 맛보기로 마롱 먹었는데 여러분 마롱 완전 추천드려요 다음은 네흐나 다른 메뉴 도전! 🌰','2026-10-12T00:00:00.000Z'),
('nr-102','naver-1257167808','naver','오늘 넘넘 맛있게 먹구 가용ㅎㅎㅎㅎ 요거트가 상큼하고 꾸덕하이 딱 제스타일이더라구용ㅎㅎㅎ 친구랑 같이 힐링 제대로 하고 가용❤️❤️ 과일도 신선하고 재료도 푸짐하게 쌓아 올려 주셔서 넘 맛나용ㅎㅎㅎ 직원분도 친절하셔서 덕분에 좋은 식사 자리였어용ㅎㅎ 간편하게 쉽게 먹을 수 있어 딱이에요','2026-10-12T00:00:00.000Z'),
('nr-103','naver-1257167808','naver','코코넛청크를 좋아해서 셰리제 먹어봤는데 너무 맛있었어요! 서비스 요거트와 추가한 요거트까지 세스쿱 먹으니까 엄청 든든하더라고요 ~!! 강남역에서 너무 가성비좋게 먹은 거 같아요 다음에 또 방문하고 싶어요~','2026-10-12T00:00:00.000Z'),
('nr-104','naver-1257167808','naver','점심은 건강하게 그릭 요거트 먹고 싶어서 방문했어요!! 사장님도 너무 예쁘시고 친절 하시네요^^ 그래니 더블이랑 마롱 싱글을 먹었는데 넘 맛있네요~ 그릭요거트는 밤이랑 두유랑 플레인 섞어서 먹었는데 제 입맛에는 달달한 밤이 제일 맛있었어요!! 견과류도 많이 들어가 있고 블루베리, 바나나도 신선하니 맛있네요!!💕','2026-10-12T00:00:00.000Z'),
('nr-105','naver-1257167808','naver','저의최애 힐링요거트 맛집 아지트에요♡♡ 처음으로 베흐 더블해보았는데 과일도 상큼하고 피스타치오요거트도 고소하고 블루베리요거트도 달콤해요 넘넘맛있고 적당한꾸덕한식감에 넘맛있어요 또 올게요!!!','2026-10-12T00:00:00.000Z'),
('nr-106','naver-1257167808','naver','애견동반 되서 찾아왔어요! 사장님이 강아지도 친절하게 맞아주셔서 감사했어요! 가방이 없어서 주저했는데 괜찮았어요! 손님들이 특이하게 거의다 외국인이였어요 ㅎㅎ 레몬요거트 먹었는데 너무 맛있게 먹었어요!! 상큼한 레몬맛 강추합니다!','2026-10-12T00:00:00.000Z'),
('nr-107','naver-1257167808','naver','베흐 싱글 즐겨먹는데 계절 과일이 바뀌니까 새로운 메뉴 먹는 느낌이에요ㅎㅎ 제철과일 무화과 넘 좋네요!!','2026-10-12T00:00:00.000Z'),
('nr-108','naver-1257167808','naver','꾸덕한 그릭요거트 먹고 싶을 때 오는 레이지요거트 계절과일이 시즌에 맞춰 바뀌니 계절별로 오는 재미가 있어요ㅎㅎ 베흐는 꿀이 같이 나와서 달달하게 즐길 수 있답니가 싱글로 먹어도 은근 배불러서 간식이나 간단한 한끼로 좋아요 :)','2026-10-12T00:00:00.000Z'),
('nr-109','naver-1257167808','naver','강남역 그릭요거트맛집 레이지요거트 :) 그릭요거트 자체 플레이버도 많고, 맛 선택도 다양해서 좋아요! 싱글 or 더블로 선택해서 먹는 것도 좋아서 앞으로 자주 방문할 것 같아요~~! 그릭요거트 엄청 꾸덕꾸덕 녹진하고 진하고 맛있어요ㅠㅠ❤ 그래놀라도 같이 샀는데 완전 꼬숩고 최고에요~ㅎㅎ 리뷰이벤트로 받은 블루베리요거트도 상콤하니 맛나요🫐💜 담엔 매장에서 직접 먹어보려구요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-110','naver-1257167808','naver','평소에 혼자 자주 먹으러 오는 곳이에요! 이번에 계절과일로 무화가가 나왔다고해서 먹으러왔는데 평소랑 똑같이 넘 맛있어요 ღ 밤 요거트랑 잘 어울려요!','2026-10-12T00:00:00.000Z'),
('nr-111','naver-1643374390','naver','학동로 골목에서 우연히 발견한 보석 같은 베이커리 ''레자미오네뜨''에서 맘모스빵을 구매했습니다. 매장에 들어서는 순간부터 고소하고 달콤한 빵 냄새가 발길을 사로잡더니, 역시 기대를 저버리지 않는 맛이네요! 묵직한 두께만큼이나 속이 알차게 채워져 있어 한 끼 식사나 든든한 간식으로 제격입니다. 달콤하면서도 부드러운 크림과 팥, 소보로의 조화가 완벽해서 끝까지 질리지 않고 맛있게 즐겼습니다. 특히 사장님께서 리뷰 서비스로 챙겨주신 덕분에 더욱 기분 좋은 방문이 되었어요. 빵 좋아하시는 분들이라면 꼭 한번 들러보시길 추천합니다. 재방문 의사 200%입니다!','2026-10-12T00:00:00.000Z'),
('nr-112','naver-1643374390','naver','예전부터 저장해놓은 곳인데 드디어 왔네요! 인테리어도 너무 예쁘고 맛있는 빵도 한가득입니다🥖🍞🥪🥯🥐🥨사고싶은 빵이 너무 많아서 행복한 고민의 시간이었네요 날이 선선해지만 크림베이글이랑 화이트리 사러 또 올께요❤️❤️','2026-10-12T00:00:00.000Z'),
('nr-113','naver-1643374390','naver','크루아상 붕어빵이 먹고싶어서 방문했어요! 저번에 생일때 방문 했을때 넘 맛있게 먹은 기억이 있어서 또 방문 했네요:) 모든 메뉴 다 있고 처음 방문 이시라면 꼭꼭 바닐라 크림 붕어빵 추천 드려요!! 정말 바닐라 크림이 말도 안되게 맛있답니다!! 다음에 또 방문 할게요😍💗','2026-10-12T00:00:00.000Z'),
('nr-114','naver-1643374390','naver','어머니가 이곳의 쌀 시금치치아바타를 좋아해서 벌써 네번째방문이네요! 앞 손님이 붕어빵을 사가기에 이번엔 붕어빵도 추가해보았습니다 ㅎㅎ 소금빵이나 타르트도 다 맛있고 재료도 풍부해서 즐겨찾는 곳이에요! 특히 쌀시금치 치아바타는 쫄깃최고입니당 ㅎㅎ다음엔 크림들어간 디저트도 먹어보고싶네요~!','2026-10-12T00:00:00.000Z'),
('nr-115','naver-1643374390','naver','명란 바게트랑 붕어빵 먹고 싶어서 방문했어요!! 둘다 진짜 맛있는데 여기 빵은 뭘 먹던 실패 없는 맛입니다ㅎㅎ😊 종종 배달로도 시켜 먹고 있어용','2026-10-12T00:00:00.000Z'),
('nr-116','naver-1643374390','naver','친구가 강추한 곳이라 항상 와보고 싶었는데 근처 올 일이 있어서 들렸어요! 바닐라 크림 붕어빵부터 베이글, 소금빵까지 아주 다양한 메뉴들이 있어 고민했지만 제일 시그니처인 붕어빵을 샀습니다! 너무 기대되네요 분위기도 넘 좋았습니다ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-117','naver-1643374390','naver','빵순이가 픽한 빵 담는 접시부터 유럽 느낌이 가득가득😘 종류도 다양하고 요즘 핫한 빵들 여기 다 모여있어요!! 다양한 크림 붕어빵들과 과일산도까지 논현에 오신다면 레자미오네뜨 꼭 들렀다 빵 쇼핑 하고 가세요~!👀💛','2026-10-12T00:00:00.000Z'),
('nr-118','naver-1643374390','naver','딸기 요거트 붕어빵, 대파크림치즈 베이글, 두바이피쵸 샌드베이글 먹어봤어요! 메뉴 조합부터 흔하지 않아서 고르는 재미가 있었는데, 먹어보니 맛도 정말 신기하고 신선하네요ㅎㅎ 특히 각각 재료의 조합이 생각보다 너무 잘 어울려서 놀랐어요. 비주얼도 예쁘고 평소 먹던 베이글이랑은 확실히 다른 느낌! 색다른 디저트 좋아하시는 분들께 추천하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-119','naver-1643374390','naver','논현역 근처에서 붕어빵 하면 일등인 베이커리 찾으신다면 여기로 오세요 매장 너무 예쁘고 직원분들 친절 합니다 특히 다양한 붕어빵 종류들이 눈을 즐겁게 하고 소금빵 명란 바게트. 등 다양한 메뉴들 모두 입을 즐겁게 해주는 곳이라서 논현역 오시면 한번 들러보세요','2026-10-12T00:00:00.000Z'),
('nr-120','naver-1643374390','naver','분위기부터 너무 예뻐서 들어가자마자 기분 좋아지는 곳이에요! 음식도 정갈하게 나오고 맛도 만족스러워서 즐겁게 식사했어요. 매장 분위기가 편안하고 아늑해서 여유롭게 이야기하기 좋았습니다. 직원분들도 친절하게 응대해주셔서 더욱 기분 좋은 방문이었어요. 다음에도 다시 방문하고 싶은 곳이라 추천합니다 :)','2026-10-12T00:00:00.000Z'),
('nr-121','naver-1235425429','naver','선릉 건강빵 맛집 제일 좋아하는 곳인데 담백하고 좋아요. 여기 초코오랑쥬 바게트가 너무 달지 않고 특색있어서 좋아요. 빵이 금방 품절되서 오전 방문 추천..','2026-10-12T00:00:00.000Z'),
('nr-122','naver-1235425429','naver','선정릉을 바라보며 사워도우 새느위치를 먹을 수 있어요! 다만, 평일 점심시간 이후에 가면 새느위치가 텅- 인기빵들도 텅- 입니다!😭 가격대는 좀 있는 편이지만, 빵이 맛있고, 사워도우 잘하는 집 잘 없으니까 온김에 냉동실에 든든하게 쟁일려고 사워도우랑 통밀빵이랑 왕창 사가요. 커피도 꽤 괜츈합니다!!👍🏻','2026-10-12T00:00:00.000Z'),
('nr-123','naver-1235425429','naver','단호박치아바타 사러 자주오는데 오늘은 뺑스위스도 사봤어용!! 가격에 비해 빵도 큼직큼직한데 담백하니 맛있어요 !! 맛있고 건강까지 챙길수 있는 빵 찾는다면 여기에욧~~','2026-10-12T00:00:00.000Z'),
('nr-124','naver-1235425429','naver','호두바게트와 초코바게트가 너무 맛있어요. 다른빵들도 맛있어서 자주 오네요. 날씨가 추워지니 스프 메뉴가 나왔던데 다음에 먹어보려구요.','2026-10-12T00:00:00.000Z'),
('nr-125','naver-1235425429','naver','커피도 맛있고 빵도 다 맛있어요! 직접 구워 바로 나와서 더 맛있는거같아요😊','2026-10-12T00:00:00.000Z'),
('nr-126','naver-1235425429','naver','여기 자주 오는데 올때마다 분위기도 좋고 빵도 맛있어요! 빵 종류도 많고 좋아요','2026-10-12T00:00:00.000Z'),
('nr-127','naver-1235425429','naver','빵도 맛있고 커피도 넘 맛있어요. 야외테이블도 좋고 온김에 선정릉 산책하고 갑니다','2026-10-12T00:00:00.000Z'),
('nr-128','naver-1235425429','naver','쌀쌀한 아침에 프렌치어니언 스프가 너무 맛있어요! 바게뜨와 커피 한잔까지 완벽!','2026-10-12T00:00:00.000Z'),
('nr-129','naver-1235425429','naver','추천받아 왔어요. 일부러 공휴일 10시 맞춰 왔는데 감자꽈리 소금빵은 매진이네요. 명불허전 정말 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-130','naver-1235425429','naver','n번째 방문 중인 빵집입니다! 샌위치 맛나용','2026-10-12T00:00:00.000Z'),
('nr-131','naver-1374995918','naver','예전엔 커피만 먹고 가서 몰랐는데 여기 생레몬케이크가 엄청 맛있어요. 가끔 아주 배고프지 않을 땐 회사 점심시간에 걸어와서 사갑니다. 제가 지금까지 먹은 레몬 구움과자 중 최고에요👍👍👍👍🍋🍋💗','2026-10-12T00:00:00.000Z'),
('nr-132','naver-1374995918','naver','논현역쪽에 약속이 있는데 시간이 좀 떠서 방문했습니다 들어오자마자 이곳은 디저트에 진심인 곳이구나 하는 생각이 들어서 설렜고요…. 제가 진짜 레몬들어간 빵들을 좋아하는데 먹자마자 이거다 싶었네요ㅠㅠㅠ 가격도 합리적이고요….. 디저트 도장깨기 하면 넘 좋을듯요!!!!!!👍👍👍','2026-10-12T00:00:00.000Z'),
('nr-133','naver-1374995918','naver','평소에 보기만하던 카페를 왔는데 디저트종류도 너무많고 커피도 짱 맛있어요!!!!! 내부도 넓고 분위기도좋아서 지인이랑 수다떨기 딱인 카페입니다. 주변에 2차로 먹을곳이랑 역이랑도 가까워서 자주올것같아요!!!!','2026-10-12T00:00:00.000Z'),
('nr-134','naver-1374995918','naver','에그타르트부터 디저트랑 음료 종류가 다양해서 메뉴 고르는 재미가 있었어요ㅎㅎ 에그타르트는 겉은 바삭하고 안쪽은 촉촉해서 커피랑 같이 먹기 딱 좋더라구요. 자두에이드는 상큼하고 달달해서 더운 날 마시기 좋은 맛이었어요🍑 콜드브루는 깔끔하고 진해서 디저트랑 곁들이기 좋았습니다. 뉴욕치즈케이크스무디는 꾸덕하고 달달한 맛이라 디저트 먹는 느낌 제대로였어요. 각자 다른 메뉴를 주문했는데 음료마다 개성이 있어서 골고루 맛보기 좋았어요! 카페 분위기도 편안해서 여유롭게 이야기 나누며 쉬기 좋았습니다. 디저트랑 음료 맛있게 먹고 기분 좋게 쉬다 온 카페라 다음에도 또 방문하고 싶어요🤍','2026-10-12T00:00:00.000Z'),
('nr-135','naver-1374995918','naver','베이커리 종류가 진짜 많아서 뭐 먹을지 행복한 고민하게 되는 곳이에요!! 교토의 새벽(말차 티라미슈)이랑 딥쇼콜라 스콘, 동경시오빵 먹었는데 완전 취향저격이었어요ㅠㅠ 다음엔 다른 메뉴도 도장깨기 하러 갈게요 🍫','2026-10-12T00:00:00.000Z'),
('nr-136','naver-1374995918','naver','지나가다 우연히 방문했어요 디저트 종류가 많아서 고민하다가 에그타르트 주문했는데 시나몬 파우더도 뿌려주시고 정성스럽게 포장해주셨어요 시나몬은 처음 뿌려먹는데 꽤 잘어울려요 바닐라향이 진하고 타르트지도 바삭해서 맛있게 잘먹었어요 다음엔 다른 디저트도 먹으러 갈게요🩷','2026-10-12T00:00:00.000Z'),
('nr-137','naver-1374995918','naver','논현역 근처에서 소금빵 맛집 찾다가 방문한 마르케입니다~ 갓 구운 강남소금빵이 정말 맛있었어요. 매장도 깔끔한 베이커리카페 분위기라 커피랑 함께 여유롭게 즐기기 좋았고, 직원분들도 친절해서 기분 좋게 이용했습니다. 논현역에서 소금빵 맛집으로 추천합니다!','2026-10-12T00:00:00.000Z'),
('nr-138','naver-1374995918','naver','혼자편하게 즐기기 좋은곳이었어요... 미숫가루라떼한잔 ..ㅎ 달달하니 마음까지 달달해지네요','2026-10-12T00:00:00.000Z'),
('nr-139','naver-1374995918','naver','소금빵 너무 맛있어요ㅜㅜㅠ 커피도 진하네요! 여기 모든 메뉴들이 포장되어있어서 엄청 청결합니다👍🏻','2026-10-12T00:00:00.000Z'),
('nr-140','naver-1374995918','naver','두 번째 방문 하는 마르케! 남자 친구랑 가서 디저트 많이 뿌시고 왔어요ㅎㅎ 소금 빵 이 정말 맛있어요. 여기는 소금 빵을 데워서 줘서 바삭하고 따뜻하게 맛있게 먹을 수 있었어요.비오는데도 손님들이 꽉찬 거 보니 디저트 맛집으로 정말 유명한 거 같아요. 배달도 됩니다.','2026-10-12T00:00:00.000Z'),
('nr-141','naver-1610724435','naver','물론! 너무 광고 같은 느낌 말고 **실제로 다녀온 사람이 쓴 것처럼**, 두 가지 말투로 바꿔볼게요. **① 자연스럽고 편한 말투** 미니말레 분위기가 생각보다 너무 좋았어요. 인테리어가 모던하고 깔끔해서 들어가자마자 마음에 들었고, 전체적으로 차분한 느낌이라 편하게 커피 마시기 좋았어요. 저는 산미가 살짝 있는 커피로 주문했는데 은은하게 산미가 느껴지면서 깔끔해서 맛있게 마셨습니다. 근처에 있어서 왔는데 모던한 느낌의 카페 찾다가 방문했는데 인테리어가 깔끔하고 예뻐서 좋았어요! 너무 꾸며진 느낌보다는 차분하고 세련된 분위기라 앉아있기 편했어요. 커피는 산미가 조금 있는 메뉴로 시켰는데 생각보다 맛이 괜찮았고 깔끔하게 마무리되는 느낌이었어요.','2026-10-12T00:00:00.000Z'),
('nr-142','naver-1610724435','naver','아이스 카페라떼와 핫 카페라떼를 마셨어요. 역삼역 근처 카페고 몇몇 테이블은 테라스 감성 좌석도 있어요. 선물할거 사기도 좋을거 같아요. 선물포장도 된대요 아이스는 시원하고 부드러웠고, 핫 라떼는 따뜻하고 고소한 맛이 좋았습니다. 두 메뉴 모두 커피와 우유의 조화가 좋아 부담 없이 맛있게 마시기 좋았어요. 원두를 고소한거 산미 있는거로 선택해써 고를 수 있어요. 편하게 커피 한잔하기 좋은 곳이라 만족했습니다. 아. 일하시는 분들 친절하세요.','2026-10-12T00:00:00.000Z'),
('nr-143','naver-1610724435','naver','역삼역카페 찾다가 예전에 미니말레 팝업때 먹었던게 생각나서 강남파이낸스센터 근처온김에 왔는데 여전히 맛있어요! 헬싱키라떼가 시그니처라 무조건 드시는거 추천!! 테라스감성도 너무 좋고 분위기가 좋아서 데이트하기도 좋고 친구들 가족들이랑 오기에도 좋아요~~','2026-10-12T00:00:00.000Z'),
('nr-144','naver-1610724435','naver','블랙&화이트 톤의 모던하고 깔끔한 분위기이며, 테라스가 유리로 둘러싸여 계절에 관계없이 즐길 수 있는 공간이 감성을 더해주는 카페입니다. 커피류, 밀크티, 에이드 등 다양한 음료와 간단한 디저트까지 메뉴 선택지가 다양했고, 로스팅 원두, 드립백, 쿠키 세트는 선물용으로 좋을 것 같았습니다. 키오스크가 있어 편하게 주문할 수 있고, 커피 주문 시 원두 선택할 수 있으며 커피 맛집답게 향도 좋고 맛도 좋았습니다. ☕️ 아메리카노 3,600원/라떼 4,300원/아인슈페너 4,800원 대체적으로 가격이 착한 편인데 테이크아웃 할인까지 있어 자주 애용할 것 같습니다.😋','2026-10-12T00:00:00.000Z'),
('nr-145','naver-1610724435','naver','역삼역카페 중에서 제일 좋아하는 카페예요! 강남파이낸스센터에서 걸어갈 수 있는데, 인생라떼를 만난 곳입니다🤍🩶 테라스감성도 좋고 야간분위기도 멋져요~ 헬싱키라떼는 특히 꼭 드셔보세요! 쿠키랑 디저트 선물포장하기도 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-146','naver-1610724435','naver','밥 먹고 커피한잔하러 역삼역카페 찾아왔는데 저녁까지해서 야간분위기 진짜 좋고 원두도 다양하고 메뉴가 진짜 다양해서 골라먹는 맛이 있어요!! 고소한 원두 라떼종류로 먹으니까 진하고 엄청 맛있네요ㅎㅎ 테라스감성 즐기기에 딱 !!','2026-10-12T00:00:00.000Z'),
('nr-147','naver-1610724435','naver','역삼역 근처 카페입니당.무더위에 피해들어왔다가 원두향이 넘 진해서 따뜻한 라떼 먹어보았습니다 ㅎㅎ 커피향 진한곳만 가면 온전히 라떼 맛을 보고싶어져서 따뜻한 걸 마시게.되는데요. 모던한 공간에 맞는 세련되도 깊은 맛이 맘에 쏙 들었어요. 오늘 콜레스테롤 수치듣고 놀라지만 않았더라면 너무 맛있어보이는 쿠키와 케익도 먹었을텐데..아쉽습니다...관리를 좀 하고 다시 도전해보고싶은 메뉴가 많네요 ㅎㅎ 야간분위기는 더 좋을텐뎅 묵직한 느낌에 고소한 라떼 원하신다면 추천합니창밖에 살짝 보이는 테라스감성도 맘에 들어용','2026-10-12T00:00:00.000Z'),
('nr-148','naver-1610724435','naver','역삼역카페 찾다가 들어온 카페인데 밖에는 테라스 감성도 느낄 수 있어서 요즘 같은 날씨에 낮에는 바깥에 앉으면 너무 좋을 거 같아요. 평일 저녁에 방문해서 한적하니 집중하기 좋았는데 커피가 정말 맛있더라고요! 헬싱키라떼 엄청 찐하고 꼬숩한데 은은한 단맛이 있어서 회사 주변이면 자주 올 거 같아요.. ㅠㅠ 브리티쉬아인슈페너도 위에 생크림이 쫀득하니 달달하더라고요 ㅎㅎ 산미있는 원두도 맛있었어요 그래서 드립백도 팔길래 나오는길래 드립백도 선물포장으로 몇 개 샀어요~~ 커피 좋아하시면 추천드려요😊','2026-10-12T00:00:00.000Z'),
('nr-149','naver-1610724435','naver','강남파이낸스센터 근처에 역삼역카페, 강남역카페 에서 가장 분위기도 좋고 커피가 정말정말 맛있어요!!!! (야간 분위기도 좋대요)특히 헬싱키라떼가 너무 맛있고 좋은거 같아요! 선물포장 쿠키도 추석에 선물하면 좋을거 같고 테라스감성 도 너무 좋았습니다🔥❤️','2026-10-12T00:00:00.000Z'),
('nr-150','naver-1610724435','naver','역삼역 근처에서 커피 마시러 들렀는데 헬싱키 라떼 완전 제 스타일이었어요! 너무 달지 않으면서 고소하고 부드러워서 계속 손이 가더라고요. 시즌 메뉴 버즈 샷은 오렌지의 상큼함과 커피 조합이 산뜻해서 색다르게 즐기기 좋았어요. 수제 뉴욕쿠키도 도톰하고 꾸덕해서 커피랑 잘 어울렸습니다.','2026-10-12T00:00:00.000Z'),
('nr-151','naver-37362104','naver','천장이 높아서 개방감이 좋았던 카페예요! 저장해두었던 곳인데 근처에 왔다가 생각나서 방문했어요. 바나나푸딩이 남아 있을까 싶어 미리 전화드렸는데 응대도 정말 친절하셨고, 예상치 못하게 좌석 예약까지 도와주셔서 도착하자마자 편하게 이용할 수 있었어요. 정말 감사합니다 🙇🏻‍♀️ 기대했던 바나나푸딩도 맛있게 잘 먹었어요! 투 고 바나나푸딩까지 한 번에 주문했는데, 나갈 때 챙겨드리겠다고 먼저 말씀해주시는 사장님의 센스와 친절함이 정말 인상적이었어요. 맛도 좋고, 서비스도 따뜻해서 기분 좋게 머물다 왔습니다 :)','2026-10-12T00:00:00.000Z'),
('nr-152','naver-37362104','naver','판교에 있을때부터 가보고 싶었는데, 당시엔 기회가 없었어요. 우연히 종로에서 발견해서 와봤는데 역시 명불허전이네요. 샌드위치는 아주 먹음직스럽게 플레이팅 되어어요. 짜지않고 맛있어요. 바게트는 보통의 바게트보다 단단한 편입니다. 맛은 시우어도우에 좀 더 가까운 것 같고요. 평소에 먹던 바게트에 비해 특색있는 집이에요.','2026-10-12T00:00:00.000Z'),
('nr-153','naver-37362104','naver','바게트 샌드위치 맛있어요🥰 바나나 푸딩도 폭신폭신 달달하니 별미네요 전 치아가 약해서 바게트가 좀 딱딱했지만😂 충분히 바삭하고 씹을수록 고소해요~ 직원분들도 친절하십니다.','2026-10-12T00:00:00.000Z'),
('nr-154','naver-37362104','naver','역삼에서 근무를 하면서 근처에 있어서 자주 가는데 강남근처에서 바게트는 역시 여기가 최고인거 같습니다. 어떻게 만들어도 정말 맛있습니다. 특히 당일 산 바게트로 집에서 샌드위치 해먹으면 여기는 바로 프랑스 어디쯤인거 같습니다^^ - 스티브잡식 부부 다녀갑니다 -','2026-10-12T00:00:00.000Z'),
('nr-155','naver-37362104','naver','무화과브리샌드위치, 햄치즈샌드위치, 바나나푸딩세트, 바나나푸딩 포장했어요. 바게트 전문점답게 맛납니다. 가격이 조금 있네요. 승승장구하세요.','2026-10-12T00:00:00.000Z'),
('nr-156','naver-37362104','naver','천안 시골쥐🐀입니다. 근처 출장으로 들렸다가, 조식을 위해 방문하였습니다. 바게트와 샌드위치 둘 다 진짜 어어어어어어엄청 맛있습니다. 햄치즈샌드위치 살사소스, 루꼴라가 엄청난 킥!입니다. 직원 불친절하다는 얘기가 있던데, 화요일 오전 8시경 방문 기준으로 전혀 그런느낌 없구, 친절하셨습니다!!!! 빵 사고 나오는데, 뒤로 3분이나 서계시던 엄청난 맛집입니다. 지방 시골쥐분들, 혹여나 낯설은 환경때문이 망설이신다면 자신있게 추천드립니다.','2026-10-12T00:00:00.000Z'),
('nr-157','naver-37362104','naver','콜드브루랑 뺑오쇼콜라 너무 맛있게 먹었습니다. 분위기도 너무 감각적이고 예뻤어요!','2026-10-12T00:00:00.000Z'),
('nr-158','naver-37362104','naver','넘넘 맛있더라구요 ~ 바나나푸딩에 찍어먹어도 토마토수프에 찍어먹어도 진짜 맛났어요 엄마는 건포도 바게트 넘 맛있대요 감사합니다 번창하세요','2026-10-12T00:00:00.000Z'),
('nr-159','naver-37362104','naver','제과점에 있는 수많은 빵들 중에 전문점을 만들기 적합한 빵은 화려한 빵이 아니라 데일리 빵입니다. 질리지 않고 매일 먹을 수 있는 빵이어야 전문점이 될만 하다는 건데요. 그래서 ''식빵 전문점'', ''소금빵 전문점''이 있는 겁니다. 그런 면에서 바게트도 전문점을 하기 적합한 빵인데요. 너무 달거나 짜지 않고, 질리지 않아서 전문점을 만들기에 적합합니다. 그런데 생각보다 바게트 전문점은 거의 눈에 띄지 않는데요. 바게트 중에 여러가지 바게트를 만들기가 어려울 뿐더러 ''맛있는 바게트''를 만들기 역시 쉽지 않아서 입니다. 서론이 길었네요. 바게트케이는 다양한 바게트를 건강하고 맛있게 만드는데 특화된 매장입니다. 다양하게 맛보고 싶어서 여러 종류를 샀는데 모두 맛있네요. 추천하고 싶은 베이커리입니다.','2026-10-12T00:00:00.000Z'),
('nr-160','naver-37362104','naver','꽤 맛있고 선택지도 다양합니다. 바게트는 무난했습니다. 바삭하다가 씹을수록 쫀득해지는 타입의 라이트한 바게트는 아니었습니다.','2026-10-12T00:00:00.000Z'),
('nr-161','naver-1201043555','naver','쿤달 베이커리 앤 커피🥐☕ 아이스 카페라떼 마시고 갑니다.😄💕 카페 내부도 잘 꾸며져있고 카페라떼 음료랑 아쿠아 민트 KUNDAL Scent My Life 시향지도 주셔서 상큼하게 향 잘 맡고 갑니다.🤗👍🏻✨ 감사합니다.😉🩷💕 압구정로데오역에서 연인이나 인테리어 예쁘고 트렌디한 카페 쿤달 압구정로데오역점 추천합니다.😃👍🏻 #쿤달 #KUNDAL #압구정로데오역카페 #베이커리앤커피 #아쿠아민트 #AQUAMINT #강남구베이커리앤커피 #강남구카페 #☕ #🥐 #😍 #😋 #👍🏻 #내돈내산 #감성카페','2026-10-12T00:00:00.000Z'),
('nr-162','naver-1201043555','naver','주말에 남편이랑 같이 압구정 카페 가려고 놀러왔다가 쿤달 카페로 들어왔어요! 야외 뚫려있는 좌석에 앉으니 너무 좋아요 날씨도 딱이고! 커피도 맛있고 분위기도 넘 좋으니 기분이 좋네요 카페 향도 너무 좋아요','2026-10-12T00:00:00.000Z'),
('nr-163','naver-1201043555','naver','날씨가 좋은데 시원한 바람을 창을 열고 즐길 수 있는것이 제일 만족입니다 ~~ 청결하고 직원분들도 너무 친절 하세요 ~~~ 빵도 너무 이뻐서 먹기 아깝네용 ~ 추천 합니다 ~','2026-10-12T00:00:00.000Z'),
('nr-164','naver-1201043555','naver','압구정 카페로 베이커리 쿤달 적극 추천드려요! 음료도 맛있고 카페 분위기도 넘 좋아요^^','2026-10-12T00:00:00.000Z'),
('nr-165','naver-1201043555','naver','생딸기라떼, 핑크레몬에이드, 자몽허니블랙티 마셨어요. 음료도 맛있고 공간 넓어서 대화하기 좋아요','2026-10-12T00:00:00.000Z'),
('nr-166','naver-1201043555','naver','매장이 넓고 인테리어가 예뻐서 사진찍으니 예쁘네요 커피도 맛있고 초코릿도 맛있어요 다음에 또 올게요','2026-10-12T00:00:00.000Z'),
('nr-167','naver-1201043555','naver','넓은공간 오픈형이라 바깥공기 쐬면서 편하게 이야기하기에 좋았습니다 음료도 괜찮구요','2026-10-12T00:00:00.000Z'),
('nr-168','naver-1201043555','naver','오랜만에 다시 왔어요!!!!압구정 카페중에 여전히 빵이랑 커피는 최고네요!!!👍👍👍','2026-10-12T00:00:00.000Z'),
('nr-169','naver-1201043555','naver','압구정카페찾다가 방문한 쿤달 베이커리카페:) 베이커리맛집느낌 낭낭💕','2026-10-12T00:00:00.000Z'),
('nr-170','naver-1201043555','naver','압구정 예쁜 베이커리카페 쿤달입니다 아인슈페너 맛나고 아아도 원두 고를수 있어 좋네요 쿤달의 이달의향 책갈피도 주셨네요','2026-10-12T00:00:00.000Z'),
('nr-171','naver-1659730937','naver','강남역에 왔다가 맛있는 빵 먹고싶어서 왔어요.여기 건물자체가 매장이여서 b1층2층3층 좌석 넓고 맛있는 빵 많아요.저번에 강남샌드먹어보고 맛있어서 아이들줄려고 세트로 구입했어요.소금크림커피의 크림진짜 부드러워요.','2026-10-12T00:00:00.000Z'),
('nr-172','naver-1659730937','naver','베이커스트 브라운에 디저트를 맛보러 식사를 모두 마친 뒤에 다녀왔어요 다양하고 먹음직스러운 빵이 진열되어 시그니처로 유명한 강남샌드를 고를까 먹기 전까지 아주 잠시 고민했습니다 하지만 워낙 소금빵을 좋아하는 편이라 오리지널 소금빵과 달콤한 메론 소금빵 상큼한 자몽 에이드를 함께 주문했어요 매장은 지상 삼층까지 넓게 운영되어 바깥 풍경을 감상하며 머무르기 좋았고 다양한 테이블이 있어 앉기 편했습니다 오리지널 소금빵은 씹을수록 쫀득쫀득한 식감이 매력적이었고 메론 소금빵 겉은 소보로처럼 바삭한 식감으로 구워졌어요 크게 한입 베어 물었을 때 부드러운 메론 크림이 달지 않게 입에 감기면서 특유의 향긋함이 맴돌아 맛있었습니다 디저트와 함께 마신 자몽 에이드 역시 과육이 신선하고 청량감이 훌륭했어요','2026-10-12T00:00:00.000Z'),
('nr-173','naver-1659730937','naver','엄마랑 오랜만에 카페 데이트하러 베이커스트 브라운에 다녀왔어요. 붉은 벽돌 건물 외관부터 빈티지한 분위기가 마음에 들었고, 내부 공간도 쾌적해서 편하게 수다 떨기 좋았어요. 강남역 베이커리 소금빵으로 소문난 곳답게 소금빵 속이 버터 풍미로 가득 차서 고소하고 겉은 바삭했어요. 시그니처 흑임자 라떼는 크림이 정말 고소하고 부드러워서 엄마도 맛있다며 잘 드셨어요. 패키지가 예쁜 강남 샌드 세트도 구매했는데 선물용으로도 딱 좋아 보여요. 남은 빵이랑 음료는 친절하게 포장해 주셔서 집에 가져와서도 맛있게 먹었어요. 재방문 의사 100%입니다!','2026-10-12T00:00:00.000Z'),
('nr-174','naver-1659730937','naver','주말에 업무 볼만한 카페 찾다가 빵 맛집이라길래 방문했어요. 큰 기대 없이 주문했는데 페스츄리 대맛집이네요,, 소금빵 맛집으로 유명하던데 왁뿌 소금빵도 있고 확실히 종류가 다양해요. 강남샌드도 한 개 먹고 맛있어서 기절.. 진심 빵 맛집 카페 인정이에요..!!!!! 참고로 콘센트는 많이 없습니다.','2026-10-12T00:00:00.000Z'),
('nr-175','naver-1659730937','naver','강남에서 친구들과 편하게 이야기 나누며 커피와 디저트를 즐기기 좋은 대형 베이커리 카페, 베이커스트 브라운. 붉은 벽돌 외관부터 유럽풍의 빈티지한 분위기가 느껴져 들어가기 전부터 분위기가 좋았고, 입구 야외 테이블도 예뻤어요. 지하 1층부터 지상 3층까지 공간이 넓어 층마다 분위기가 조금씩 달랐는데, 2층은 쇼파 좌석이 있어 친구들과 이야기 나누기 좋았고 3층은 자연광이 들어와 여유로운 느낌이었어요. 빵 종류도 다양해서 구경하는 재미가 있어요. 저희는 아이스·따뜻한 아메리카노, 소금크림커피와 무화과 퀸아망, 강남샌드를 주문했어요. 특히 무화과 퀸아망은 비주얼부터 예쁘고 바삭한 페이스트리와 달콤한 무화과가 정말 잘 어울렸어요. 강남샌드는 8가지 맛이라 선물용으로도 좋았고 맛도 넘 좋았어요!!','2026-10-12T00:00:00.000Z'),
('nr-176','naver-1659730937','naver','무화과 시즌 과일로 예쁜 디저트가 참많아요. 아이들 요구로 왔는데 시간되면 커피도 먹고가고싶은 곳이에요 장소가 이쁘거든요.^^ 마들렌 소금빵 에그타르트 냄새가 참좋네요.','2026-10-12T00:00:00.000Z'),
('nr-177','naver-1659730937','naver','강남역에 이렇게 좋은 카페가 있는지 몰랐어요~ 매장 넓고 빵 종류 많아요! 저녁에 가서 커피 안마시고 티 마셨는데 맛있었습니다👍❤️','2026-10-12T00:00:00.000Z'),
('nr-178','naver-1659730937','naver','매장이 크고 넓어서 단체 모임하시 좋고, 디저트도 있어서 커피랑 곁들이기 좋아요! 다양한 메뉴가 있어 선택 폭이 넓어 다인원의 취향에 맞게 주문하기 수월했습니다. 분위기도 좋으니 연인 혹은 친구들과 함께 방문하면 더 좋을 거 같아요. 사진도 잘 나옵니당!','2026-10-12T00:00:00.000Z'),
('nr-179','naver-1659730937','naver','카페 분위기 좋아요. 좌석도 많구요. 고급진 샌드와 부드러운 소금크림커피 맛있어요.','2026-10-12T00:00:00.000Z'),
('nr-180','naver-1659730937','naver','초당케이크 크림이 완전맘에들어요 음료도 흑임자 진하고 고소해요','2026-10-12T00:00:00.000Z'),
('nr-181','naver-1275470400','naver','오후에 외부손님방문이 있어서 간식으로 먹을겸~선릉의 자랑!!^^유명하고 유명한 소금빵맛집 베통에 갔어요~~!!!줄안서도 살수 있었던건 좋았는데ㅎㅎ 빵이 나오는 시간이 아니여서 거의 남아있는 빵이 없었지만~일단 남아있는것만이라도 사왔어요!!^^언제 먹어도 버터버터하고 짠짠고소한 베통소금빵~조금 가격대가 있지만 가끔 손님접대용..그리고 선물용등..으로 활용좋아요~😁가게 내부도 넓어서 커피한잔과 소금빵한개의 여유를 즐기기도 좋은 베통역삼점☆','2026-10-12T00:00:00.000Z'),
('nr-182','naver-1275470400','naver','넘 기대가 컸나 엄청난 맛은 못느꼈어요. 제 입맛엔 플레인보다는 솔티초코가 더 맛있었어요 매장 넓고 분위기 좋아요','2026-10-12T00:00:00.000Z'),
('nr-183','naver-1275470400','naver','소금빵+베이글 느낌. 베이글생지로 만든 소금빵? 담백하면서 버터향 좋고 좁은부분은 바삭바삭! 통통한부분은 폭신해서 식감도 좋다. 커피랑 같이 먹으니까 든든하네요','2026-10-12T00:00:00.000Z'),
('nr-184','naver-1275470400','naver','여기 소금빵 맛집이에요!! 평일 아침에 오픈하자마자 방문했는데 사람들이 이미 줄서있더라구요?! 깜짝 놀랐습니다ㅎㅎ 저는 매장에 앉아서 먹을 생각이었는데 빵 여러개 테이크아웃 해서 가시는 분들 많았어요! 한시간 가량 매장에 있었는데 빵이 매대에 있을때면 줄은 계속 있었어요~ 포인트 적립도 되는 듯해서 해달라고 하려다가 손님이 끊기지 않아 타이밍 놓쳐서 말 못하고 나왔슴니다아..ㅠ 담에 또 방문하려구요!! 소금빵 특색있고, 맛도 정말 있어요. 왜 유명한지 알겠더라구요! 추천추천 👍🏻','2026-10-12T00:00:00.000Z'),
('nr-185','naver-1275470400','naver','베통은 진짜 ㅋㅋㅋㅋ 그렇게 웨이팅 도중 빡침이 있어도 직원님들 친절함에 완전 무장해제 되어버려요 빵이야 뭐 맨날 맛있구요 (그러니 기다리죠ㅠㅠ)','2026-10-12T00:00:00.000Z'),
('nr-186','naver-1275470400','naver','소금빵은 역시 베통 오전에 일찍 갔는데도 웨이팅... 그래도 잘 사고 나왔네요! 직원들도 친절 가끔갑니다.','2026-10-12T00:00:00.000Z'),
('nr-187','naver-1275470400','naver','- 트러플 소금빵, 솔티 초코 소금빵 1시간 웨이팅.. 한사람 당 10개 이상은 사가시는 거 같아서 1차로 소금빵 종류별로 다 나와도 다 사가셔서 또 기다려야 돼요. 2차로 더 나올 때는 샌드위치 종류는 안나오고 다른 소금빵들만 채워졌어요. 사람대비 소금빵 채워지는 속도가 못 따라오는 거 같아서 많이 기다려야 됩니다. 베통 소금빵은 비싼 편이지만 소금빵 안에 초코나 트러플 크림? 같은 내용물이 들어있어서 더 맛있게 먹었어요👍🏻 저는 초코보다 트러플이 맛있었습니다😋','2026-10-12T00:00:00.000Z'),
('nr-188','naver-1275470400','naver','신세계백화점에 줄서있는거 보다가 역삼점 생겨서 친구들과 다녀왔어요. 여기도 정말 인기 많은데 우와! 소금빵 맛이 최고에요! 일반 소금빵과 전혀 다른 맛...! 라떼도 맛있고요. 또 갈거에요!!','2026-10-12T00:00:00.000Z'),
('nr-189','naver-1275470400','naver','아침 8시에 오픈했는데 몇 명이 줄을 서 있었어요.빵 종류에 따라 구워지는 시간이 달라집니다.그 시간보다 앞서 줄이 생기니, 사고 싶은 빵 제공 시간보다 약 15분 일찍 도착해야 합니다.또한 일본어에 능통한 여성 직원이 있어 매우 친절하고 큰 도움이 되었습니다.감사합니다. 정말 큰 도움이 되었습니다.음료도 빵도 맛있었습니다.아주 멋진 아침 식사가 되었습니다.','2026-10-12T00:00:00.000Z'),
('nr-190','naver-1275470400','naver','초코소금 젤맛남','2026-10-12T00:00:00.000Z'),
('nr-191','naver-2092813866','naver','너무 귀여운 인테리어 가득이에요 >< 3층까지 있어서 좌석도 많고, 인테리어 보는 재미도 있네요!!!! 커피도 고소하니 맛있고 빵들이 진짜 넘 맛있어요..... 최에 카페가 될 것 같아용 직원분들도 친절하셔서 좋습니다-!','2026-10-12T00:00:00.000Z'),
('nr-192','naver-2092813866','naver','빵 엄청 많고 다양해요 !!! 소금빵도 종류별로 먹어봤는데 야끼소바랑 쪽파크림 진짜 맛있었어요 ㅠㅠㅠ 모찌도 쫀득하고 넘넘 추천해요 !!! 이번에 과일산도도 잔뜩 나왔던데 담에 먹어보려구요 ㅎㅎㅎ 직원분들도 친절하세영','2026-10-12T00:00:00.000Z'),
('nr-193','naver-2092813866','naver','대박 베이커리 진짜 너무 맛있어요-!!!! 빵 종류도 엄청 많고, 특히 저는 야끼소비 소금빵이랑 모찌 너무너무 추천드려요 !!! 3층까지 인테리어도 너무 예뻐서 사진찍기도 너무좋고, 테라스도 예쁘구요! 직원분들도 친절하셔서 기분좋게 머물다 갑니다 ㅎㅎ 또 오고 싶어요 !','2026-10-12T00:00:00.000Z'),
('nr-194','naver-2092813866','naver','더양한 메뉴도 먾구 직원분글도 친졸하시구 넓어요!꙼̈!꙼̈ 맛도 좋고 가격도 좋고 빵뷰터 과일까지 디저트 매니아 분들운 너무 좋아하실거 같어요오💕 카페처럼 음료도 다양하구 툭별헌 메뉴들도 머너요💕','2026-10-12T00:00:00.000Z'),
('nr-195','naver-2092813866','naver','도산공원 왔다가 우연히 보고 들어왔는데 감성감성~~♡ 소금빵이 여러종류가 있네요 맛난 커피와 빵먹으메 아들과 데이트잘하고 갑니다','2026-10-12T00:00:00.000Z'),
('nr-196','naver-2092813866','naver','부케드뺑 🥐🤎 빵 종류가 어쩜 이렇게 많은지… 들어가자마자 눈 돌아가서 하나씩 다 담고 싶었던 곳🫶🏻 비주얼부터 너무 예뻐서 고르는 시간마저 행복했던 곳이에요. 특히 복숭아 모찌랑 복숭아 에이드 조합🍑 진짜 너무 맛있었어요…💗 복숭아 모찌는 쫀득한 식감에 달콤하고 상큼한 복숭아가 가득해서 디저트로 딱이고, 복숭아 에이드는 달콤상큼해서 빵이랑 같이 먹으니 더 잘 어울렸어요🍑🫧 빵도 하나같이 맛있어 보여서 결국 이것저것 한가득😂 고소한 빵부터 달달한 디저트까지 종류가 다양해서 취향대로 골라 먹는 재미가 있는 곳! 예쁜 분위기에 맛있는 빵까지🤎 압구정에서 빵 좋아한다면 한 번쯤 들러볼 만한 부케드뺑✨ 강추요🥐🍑🤍','2026-10-12T00:00:00.000Z'),
('nr-197','naver-2092813866','naver','카페 들어오자마자 예쁘게 진열되어있는 빵들을 보고 이미 눈으로만 만족도 100%..🤭 크기가 작아보여서 자리가 없을까봐 걱정했는데 2,3층에 예쁜 좌석들이 여유있게 있어서 대화하기도 좋았어요 Best1인 화이트롤 소금빵 역시 맛있어서 다른 빵들의 맛도 궁금해졌어요!! 빵 도장깨기하러 또또 올 예정입니다😋🤎 원래도 가고 싶어서 저장해뒀던 곳인데 아이돌들이 자주 방문하는 곳이래서 방문하게 되었어요!!','2026-10-12T00:00:00.000Z'),
('nr-198','naver-2092813866','naver','멜론산도 크림 맛잇고 메론이 튼실해서 좋아요 ㅎ 가격도 합리적인거같고요 인테리어가 빈티지스러워서 매우 감성있고요, 직원분들도 매우 친절해요 라떼와 차도 마시기 좋고 맛있어요 다음에 여기 또 올것같아요 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-199','naver-2092813866','naver','친구랑 예전부터 와보고 싶어서 방문했는데 요즘 유행하는 모찌랑 왁뿌소금빵 먹으러 왔어요 ㅠㅠ 다행하게도 종류별로 다 있어서 고를수 있었는데 너무 좋았어요 다양한 디저트에 다음에 오면 과일 산도도 먹어보고 싶어요 !','2026-10-12T00:00:00.000Z'),
('nr-200','naver-2092813866','naver','엄마랑 데이트 나왔어요~~ 가게도 예쁘고 디저트도 맛집이고 음료도 좋아요!! 그리고 넘 친절하셔서 단골하고싶네요~~','2026-10-12T00:00:00.000Z'),
('nr-201','naver-2036833457','naver','저번에 잠봉뵈르 포장해서 먹었는데 바게트가 진짜 바삭해서 놀랬어요!! ㅠㅠ 찐 바게트 맛집! 넘 맛있어서 일주일만에 재방문했어여 ㅎㅎ 식사빵도 많고 달달한 빵도 있어서 자주 방문 할꺼같아용 최고!','2026-10-12T00:00:00.000Z'),
('nr-202','naver-2036833457','naver','모짜렐라 포카치아 샌드위치랑 카푸치노 먹었는데 담백하니 넘 맛있어요 :) 루꼴라도 많이 들어가있고 모짜렐라 치즈도 좋은 재료로 쓰시는지 느끼하지도 않고 맛있어용!! 카페 분위기도 힙해서 혼커하기 좋아요. 사장님도 친절하셔서 편안하게 먹고 가요😊','2026-10-12T00:00:00.000Z'),
('nr-203','naver-2036833457','naver','치아바타 햄치즈 샌드위치는 담백하고 에그마요 크로와상 샌드위치는 달달해서 맛있었어요~ 둘 다 맛있게 잘 먹었어요ㅎㅎ 카페 분위기도 좋고 사장님도 친절하셔서 좋았습니다 :)','2026-10-12T00:00:00.000Z'),
('nr-204','naver-2036833457','naver','이쁜박스에 선물하려고 방문했어요. 제빵사가 직접 만드는걸 볼수있어서 믿음이 가고 깨끗해요. 맛있는 빵 잘 선물할게요^^','2026-10-12T00:00:00.000Z'),
('nr-205','naver-2036833457','naver','매주 방문중! 빵 종류가 많아서 고르는 재미가 있어요. 샌드위치 크로와상 바삭하고 고소해서 맛있었고 에그마요랑도 잘 어울렸어요. 커피도 빵이랑 같이 먹기 좋았어요. 다른빵들도 몇 가지 포장해 왔는데 다 너무 맛있어요! ❤️','2026-10-12T00:00:00.000Z'),
('nr-206','naver-2036833457','naver','포카치아 샌드위치 넘 맛있고 건강한맛이에요 라떼도 맛있네요!! 빵냄새가 솔솔 다른빵도 맛나보여요','2026-10-12T00:00:00.000Z'),
('nr-207','naver-2036833457','naver','지나가다 우연히 들어왔다 정말 만족했습니다!😃 일단 버터가 되게 향긋하고 맛있습니다. 그리고 빵 식감도 아주 폭폭하고 좋아요. 무엇보다 들어가면 실시간으로 빵을 굽고 계십니다🙏 아주 싱싱하게 빵 고르실 수 있어요!! 적극 추천드립니다!','2026-10-12T00:00:00.000Z'),
('nr-208','naver-2036833457','naver','가족이랑 점심 먹고 나들이 하다 방문했어요. 빵 냄새가 너무 좋아 들렸는데 정말 맛있었어요. 가게도 무척 청결하고 대화하기도 좋더라구요. 집 근처라 자주 올 것 같아요. 나중엔 샌드위치도 한 번 먹어보려해요.','2026-10-12T00:00:00.000Z'),
('nr-209','naver-2036833457','naver','청담동 주민입니다. 생긴지는 꽤되었지만, 가던 빵집이 있어서 안와보다가 몇칠전 먹어보고 맛있어서 계속 오고있어요. 잼뵈르가 특히 신선하고 맛있어요. 유럽식 빵 느낌이라 더욱 좋아요. 추천합니다.','2026-10-12T00:00:00.000Z'),
('nr-210','naver-2036833457','naver','예전 대로변 커피빈 뒷골목에 자리한 브라운브레드 브런치까페가 즐비한 이 골목에 다양한 배이커리류를 판매하면서 샌드위치 다수를 맛볼수있는 몇 안되는 동네 주민들의 맛집으로 소개받아 방문해봄 오전 8시반부터 오후1시까지 30분단위로 빵들을만들어내고있어 매장안은 버터의 향긋한 냄새가 가득 라떼는 원두의 풍미와 부드러운 크림이 느껴져서 합격점 치아바타는 다수의 올리브가 들어가 아이들도 잘먹는 메뉴 인근 들릴일 생길때 들러볼만한곳 :)','2026-10-12T00:00:00.000Z'),
('nr-211','naver-1881502126','naver','나의 최애 스콘가게!!!! 너어무 맛있어요 일단 포장부터 잔뜩했구요 매장 들른길에 커피랑 먹고갑니다 커피도 참 맛있는데요 스콘의 단짠과 어울리는 커피에요!!! 주차는 평일엔 1시간 무료에요 주말에는 2시간인데... 구매금액 상관없이 동일한 주차시간 제공합니다 스콘을 7만원어치나 샀는데 주차가 한시간뿐이라 빨리먹고 포장하고 집에왔어요 그거 조금 아쉬웠다면 아쉬웠던 점이네요','2026-10-12T00:00:00.000Z'),
('nr-212','naver-1881502126','naver','도곡동에 있는 브라이언스 커피 도곡점 입니다 날씨가 시원해서 그런지 완전 개방형 카페네요. 롱블랙 주문했고 커피 맛있습니다. 지하 1층에 베이커리 카페도 있다고 하네요. 커피 즐기기엔 딱 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-213','naver-1881502126','naver','스콘 맛집이라해서 방문해 봤어요. 포장으로 이용을 해봤는데 스콘 종류도 너무나 다양했고 맛있습니다! 베이커리류가 있는 아래 층은 차분한 분위기여서 조용히 시간 보내기 좋을 거 같아요.','2026-10-12T00:00:00.000Z'),
('nr-214','naver-1881502126','naver','가격대는 있지만 스콘 종류가 다양하고 맛납니다. 네이버에는 운영시간이 오전 7 시부터라고 공지 되어있어, 7시 20분경 방문하니 명업은 7시30분부터라고 하시던데, 네이버에도 실제 운영시간으로 공지하시는 것이 소비자와의 오해를 줄일 수 있을 것 같습니다.','2026-10-12T00:00:00.000Z'),
('nr-215','naver-1881502126','naver','* 매봉 본점보다 강한 베이커리라인을 가진 ''브라이언스커피 도곡'' 지하1층은 베이커리와 외부 공간, 지상1층은 커피바로 구성되어있다. 지하1층 베이커리엔 브라이언스의 시그니처인 다양한 스콘외에 적지않은 종류의 케익라인을 볼 수 있다. 지하1층의 외부는 봄가을 정원에서 커피를 마시는 느낌을 받을 수 있는 넓은 공간이 있어서 공간을 정말 잘 활용하고있다는 느낌을 받는다. 1층의 커피는 왠지 매봉 본점보다 살짝 약한 느낌이다 ~','2026-10-12T00:00:00.000Z'),
('nr-216','naver-1881502126','naver','추석을 맞이하여 부모님댁 방문. 동생부부와 양재천 아침 러닝을 마치고 커피 한 잔 하러왔어요. 올케가 브라이언스커피 꼭 와보고 싶었다며😊 커피와 휘낭시에, 스콘 먹었는데 정말 맛있네요.','2026-10-12T00:00:00.000Z'),
('nr-217','naver-1881502126','naver','스콘 맛집! 가격이 좀 사악하긴 하지만~ 맛있어요. 커피는 1층에서 결제, 스콘은 지하에서 결제해야해서 좀 번거롭지만 그래도 맛은 최고입니다','2026-10-12T00:00:00.000Z'),
('nr-218','naver-1881502126','naver','올해 마지막 쿠폰을 채우고 있어요 커피 훌륭해여','2026-10-12T00:00:00.000Z'),
('nr-219','naver-1881502126','naver','시그니처 몰라떼 쓰지도 않고 달지도 않고 딱 균형있어 좋아요! 커피 맛집입니다','2026-10-12T00:00:00.000Z'),
('nr-220','naver-1881502126','naver','가격대가 좀 있지만 플랫화이트 맛있고 아메리카노도 인근 카페중엔 젤 괜찮아요','2026-10-12T00:00:00.000Z'),
('nr-221','naver-34259240','naver','양재천 주변 브라이언스 커피 본점입니다. 원래도 사람이 많은데 요즘 양재천 인기가 높아서 사람이 더 많아진 것 같습니다. 1. 스콘이 맛있습니다. 빵 나오는 시간에 가면 따듯한 스콘을 먹을 수 있습니다. 속은 부드럽고 겉은 바삭한 스콘이고 위에는 설탕이 뿌려진 것처럼 달콤합니다. 2. 스콘이 맛있지만 당연히 커피도 맛있습니다. 예전에는 원두를 고를 수 있었는데 이제는 일반 원두와 디카페인만 있습니다. 3. 1층에는 좌석이 많진 않고 2층에 좌석이 많습니다. 4. 주차도 가능하긴 한데 그냥 걸어오는게 마음 편합니다. 5. 혹시 꼭 가고 싶으시면 멀지 않은 타워펠리스에 다른 지점이 있습니다. 스콘과 커피가 맛있는 브라이언스 커피입니다. 양재천에서 식사하고 가기 좋습니다. #브라이언스커피#양재천카페추천','2026-10-12T00:00:00.000Z'),
('nr-222','naver-34259240','naver','스콘 맛집🥹 커피 맛집🥹🫶 인테리어 맛집🥹🫶👍 브라이언스커피 왕짱 쵝오😭😭🫶 더 자세한 후기는 제 블로그로 놀러오세요☺️ https://m.blog.naver.com/hadaeng_12/224420689161','2026-10-12T00:00:00.000Z'),
('nr-223','naver-34259240','naver','예전에 이 근처 살 때 부모님이 원두 사 오시던 추억의 카페인데, 남자친구가 저랑 가고 싶다고 기억해 뒀다 데려가 줘서 점심 먹고 방문했어요! 매봉역이랑 가깝고 주차는 불가하지만 바로 옆 유료주차장이 있어서 이용하기 편했습니다. 산미 없는 아메리카노 클래식 원두는 견과류와 초콜릿 풍미가 묵직하고 고소해서 맛있고, 에티오피아 고로 필터커피는 향긋한 꽃향기에 고급스러운 베리류 산미라 완전 제 취향이었어요☕️ 베이커리는 유명한 스콘이나 휘낭시에 종류로 추천해요! 새로 도전해 본 버터떡은 버터 맛도 안 나고 고무 같은 식감이라 조금 아쉬웠습니다 ㅠㅠ 디저트 도전은 아쉬웠지만 커피 퀄리티와 분위기가 워낙 훌륭해서 데이트 코스로 강추합니다! 😊','2026-10-12T00:00:00.000Z'),
('nr-224','naver-34259240','naver','브라이언스 커피 본점입니다. 1. 주변에 발렛파킹하셔야 합니다. 2. 스콘도 맛있고 커피도 맛있습니다. 3. 양재천 주변이라 산책하고 커피마시기 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-225','naver-34259240','naver','일요일의 양채천이라 차도 많고 사람도 많아서 커피는 다른 곳에서 먹고 브라이언스에서는 원두만 사왔어요! 카페지만 빵집만큼 화려한 디저트들이 잔뜩 있고요! 특히 스콘 맛집답게 스콘이 어마어마한 바구니에 한가득 있어요. ㅎㅎ 원두 라인업이 다양한 편은 아니고 디카페인 원두는 콜롬비아였어요. 제가 먹는 게 아니라 드립용 분쇄 요청했는데 원두 겉봉투에 커피가루도 많이 묻어 있고 따로 담아주지는 않으셔서 포장 상태가 살짝 아쉬웠습니당.','2026-10-12T00:00:00.000Z'),
('nr-226','naver-34259240','naver','공간이 넓은데 아늑합니다 커피도 맛있어요. 저는 산미있는거 골랐는데 산미 제대로네요.','2026-10-12T00:00:00.000Z'),
('nr-227','naver-34259240','naver','강남에서 점심 먹고 찾아서 방문했어요!! 구움과자 전문점답게 다양한 재료를 사용하여 종류별로~ 까눌레/스콘/휘낭시에/갈레트브루통/에그타르트/ 소금빵/크로와상/피칸파이/쿠키/버터떡 등 많이 진열되어 눈길을 사로잡았어요!! 음료가 다양하지는 않아서 몰라떼로 통일해서 먹었는데요 아인슈페너 느낌의 맛이었습니다!! 구움과자는 부드럽거나 쫀득한 느낌의 맛이었는데요 일부는 적당히 달았고 어떤건 많이 달달했습니다!! 디저트 가격이 높은편이었고 주차공간이 없어요!! 앞에 다른 카페에 있는 유료주차장에 발렛 맡기고 시간당 5천원 드리고 왔습니다!! 맛있게 잘 먹고 왔습니다!!~😋 쑤기바옹의 블로그에 오시면 더 자세한 리뷰 보실 수 있어요!!😘','2026-10-12T00:00:00.000Z'),
('nr-228','naver-34259240','naver','분위기 좋고 커피 맛있어요~','2026-10-12T00:00:00.000Z'),
('nr-229','naver-34259240','naver','다 좋은데 가격이 비싸서 내가 살 수 잇는 건 저 버터 스콘 한 조각이다 4500원 잼 발라잇는 건 600원 더 받는다 옆의 여자는 부자인가 빵을 3개 아니 샌드위치까지 4개를 덥석덥석 집었다 그래도 진짜 극락의 맛 특히 웜스콘 나올때 먹엇는데 먹으면서 울뻔했다 다른 빵들도 도곡동 답게 마포동보다 1500원에서 2000원씩 거의 1.5배가까이 까눌레는 거의 2배 수준이고 돼지고기보다 다 비싸다','2026-10-12T00:00:00.000Z'),
('nr-230','naver-34259240','naver','소파 의자 너무 편해요. 채광이 들고 조용하며 자연친화적인 인테리어로 책 읽기도 좋습니다! 디카페인 마셨는데 맛있었어요. 비닐 포장이나 덮개가 없어서 베이커리류를 먹진 않았어요.','2026-10-12T00:00:00.000Z'),
('nr-231','naver-2077061316','naver','어제 평냉먹고 비가 주적주적 내리는 금요일 음악들으면서 책 좀 보려 최근에 강남 일대에서 꽤 뜨고 있는 브라이언스커피 포스코사거리점을 방문했습니다 여가 소금빵이 맛있다고 해서 궁금했는데 늦은 오후에 방문해서 그런지 매진되서 베리치즈케이크랑 바리스타가 추천한 소셜클럽 원두의 카페라떼를 먹었는데 괜찮았습니다 여기 터주대감이 바로 길건너 테라로사인데 아주 괜찮은 커피맛집을 알게되서 기분이 좋네요 잘 먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-232','naver-2077061316','naver','커피 향이 너무 좋아요~ 커피도 커피지만 빵이 생각나서 또다시 찾게 되는 집! 오늘은 드뎌 소금빵 먹어 보았습니다. 빵잘알못이지만소금빵은 기본 재료가 충실해야 더 맛있는데 버터, 소금, 설탕, 밀가루 재료에 진심인 것 같아요~ 맛있게 잘 먹었습니다. 끝에 살짝 맴도는 단맛이 너무 좋아요. 버터는 빵 바닥안에 잘 녹아 살아있는 느낌이에요. 대신 바닥이 과자처럼 바사삭하는 느낌은 약합니다. 오늘은 소금빵, 에그타르트, 초코스콘 먹었는데 또 먹어도 맛있네요*^^*','2026-10-12T00:00:00.000Z'),
('nr-233','naver-2077061316','naver','아침7시부터 운영해서 간단히 아침요기하기 좋습니다. 베이커리류도 다양하고 맛납니다.','2026-10-12T00:00:00.000Z'),
('nr-234','naver-2077061316','naver','* 강남구 로컬카페(?) 브라이언스커피 포스코사거리점 브라이언스커피는 매봉에 본점에 있는데 압구정점까지 강남에만 5개 매장이 있는 강남구로컬 베이커리카페. 필터커피를 정말 맛있게 내려주는데 시그니처인 스콘과 함께 먹으면 조합이 제대로임. 다양한 스콘들이 있는데 가격은 약간 하는편. 포스코사거리점은 넓고 천장고가 매우 높아서 개방감이 그만. 바깥쪽과 건물안쪽에 출입문이 있는데 건물안쪽에도 쉴수있는 감각적인 좌석을 두었다','2026-10-12T00:00:00.000Z'),
('nr-235','naver-2077061316','naver','오픈하고 30분지나서 갔는데 매장에 사람 엄청 많아요 진짜 머선일이구? 👀 일요일 오전 8시30분에 왜 다들 카페에서 모임하는건데여? 덕분에 제가 테이크아웃 했짜나여 🤣 다음번엔 나도 아침 8시에 와야겠다👉👈','2026-10-12T00:00:00.000Z'),
('nr-236','naver-2077061316','naver','대략 한달만에 방문입니다 여전히 분위기 좋고 커피도 맛있고 빵도 맛있는데 오후시간이어서 빵이 별로 없네요ㅠ 브라이언스 커피에서 비지니스 미팅은 늘 성공적','2026-10-12T00:00:00.000Z'),
('nr-237','naver-2077061316','naver','따뜻한 우드톤의 유니크한 천정 인테리어가 특징 층고가 높고 실링팬이 있어 시원한 개방감을 주며 넓고 테이블도 많음 (창가에 바테이블이 없고 단순한 테이블 배치로 구내식당처럼 간격이 좁은건 아쉬움) 매장에서 직접 로스팅한 원두 선택 할수 있고 간편하게 키오스크로도 주문가능! 인기 많은 클래식 에스프레소를 선택했는데, 라떼가 진하고 풍미가 깊어 고소한 원두를 좋아하는 분들은 만족할 만한 맛입니다.☕️ 스콘 맛집답게 다양한 스콘, 휘낭시에, 마들렌, 까눌레 등 구움 과자 위주로 있었고 제가 방문한 시간대가 일러 빵종류가 적었는데 다양한 베이커리를 원하시면 11시 이후 방문을 추천합니다.🥨 커피와 베이커리 둘다 맛있는 브라이언스커피 👍','2026-10-12T00:00:00.000Z'),
('nr-238','naver-2077061316','naver','블루베리 스콘 & 블루치즈 스콘 아이스 플랫화이트 매장 뒤편 지상주차는 무료, 지하주차는 평일 1시간 무료라 편하네요','2026-10-12T00:00:00.000Z'),
('nr-239','naver-2077061316','naver','매장도 널찍하고 디저트 종류도 다양한데, 기본 버터밀크 스콘을 선택! 겉은 바삭, 안은 촉촉한 스콘 👍 아메리카노도 고소하고 진해서 스콘이랑 딱었어요! (커피도 너무 맛있음 >_<~)','2026-10-12T00:00:00.000Z'),
('nr-240','naver-2077061316','naver','🤩🤩🤩🤩 여기는 원래 증권사 지점이 있던 자리인데 어느새 커피샾으로 바뀌었다. 브라이언스커피는 매봉역쪽에 본점이 있는데 여기가 첫번째 지점인거 같다. 여기 해성빌딩이 임대료가 전국 탑텐에 꼽히는 곳인데 대형브랜드 커피숖도 아닌 개인 브랜드가 용기있는 도전이다. 브라이언스커피는 스콘 맛집으로 유명한만큼 열가지 이상의 스콘을 구비하고 있고 요즘 핫한 버터떡도 맛있다. 최상의 재료로 최고의 레시피를 선보인다는 모토에 맞게 커피도 좋은 원두를 사용한다. 주말에는 해성빌딩 입주사들이 출근안하는 틈을 타 3시간 무료주차를 내걸었다. 여기 주차 후 인근 코엑스와 현대백화점 그리고 한강공원까지 가족나들이를 겨냥한 타겟팅이 훌륭한 포인트이다.','2026-10-12T00:00:00.000Z'),
('nr-241','naver-1414148461','naver','양재천 카페거리에 있는 베이커리 카페로 1층, 2층, 야외 테이블석으로 구성되어 있으며, 특히 2층 테라스석은 초록 나무를 가까이에서 볼 수 있어 뷰가 정말 좋아요! 😀 커피와 음료, 빵 종류가 다양하고 매장 내 베이킹룸이 있는 것을 보니 직접 빵을 생산하는 것 같았습니다. 스콘, 뺑오쇼콜라, 바게트 먹었는데, 스콘은 딱딱하지 않아 좋았고 뺑오쇼콜라는 촉촉하면서 부드러웠으며 바게트는 담백하니 대체적으로 빵들이 맛있었습니다. 👍','2026-10-12T00:00:00.000Z'),
('nr-242','naver-1414148461','naver','양재천 빵맛집 브래드앤워크~♡ 너무맛나요 신선한 빵들 갓구운 맛있는빵들과 고소한커피. 런닝하고 산책하머 들르기좋은~~ 카페요~^^','2026-10-12T00:00:00.000Z'),
('nr-243','naver-1414148461','naver','겉바속촉 빵과 따뜻한 커피, 완벽했던 베이커리 카페 방문기♡ 통창으로 햇살이 쏟아지는 여유로운 공간에서 정말 만족스러운 빵과 커피를 즐기고 왔어요. 매장 인테리어도 깔끔하고 좌석도 편안해서 분위기부터 이미 합격점이었습니다. 바삭하게 결이 살아있는 페스츄리 도우 위에 통통하고 뽀득한 소세지가 올려져 있어요. 한 입 베어 물면 짭조름하면서도 고소한 풍미가 입안 가득 퍼지는, 페스츄리소시지빵은 식사 대용으로도 전혀 부족함 없는 베스트 메뉴예요. 담백하고 쫄깃한 치아바타 샌드위치는 신선한 루꼴라와 재료 속이 꽉 차 있어 든든했어요~ 통창 뷰를 바라보며 맛있는 샌드위치와 디저트로 여유로운 시간을 보내고 싶으신 분들께 강력 추천합니다. 빵 좋아하시는 분들이라면 꼭 한번 방문해 보세요!','2026-10-12T00:00:00.000Z'),
('nr-244','naver-1414148461','naver','호밀빵 (발효종) 소화도 잘되고 맛있구요!! 솔드아웃 금방됨!(오픈런 성공) 오전8시 오픈인데도 양재천 운동하고 오시는분들 산책하다 들리시는분 많네요 1~2층으로 되어있어 2층은 양재천뷰!!너무 힐링됩니다 n번째 방문이에요 🤗🥐🍞🥖☕️','2026-10-12T00:00:00.000Z'),
('nr-245','naver-1414148461','naver','양재천에서 정말 애정하는 곳입니다. 저는 이곳 파니니를 정말 좋아해서 쿠팡이츠로도 주문해 먹곤하는데😍, 오늘도 이곳에 오면서 치킨파니니를 먹을까 머쉬룸파니니를 먹을까 줄거운 상상을 하며 왔는데 치킨파니니만 남고 품절되었네요.. 선택의 고민을 덜어줘서 치킨파니니를 더욱 맛있게 먹고 갑니다 ㅋㅋ 빵과 내용물의 조화가 이보다 완벽할 수 있을까 싶네요. 테라스에 앉아 이 뷰를 즐기며 이 맛있는 파니니를 먹을 수 있음에 오늘 하루 충만하게 감사했습니다^^','2026-10-12T00:00:00.000Z'),
('nr-246','naver-1414148461','naver','도곡동 양재천 카페거리에 있는 단골 카페. 베이커리 메뉴도 다양하고 2층 규모로 돼 있는데 매장 1층 야외 테이블도 잘 돼 있다. 매장 분위기도 좋은 편. by 블라초블로그','2026-10-12T00:00:00.000Z'),
('nr-247','naver-1414148461','naver','샌드위치 크기가 크고, 먹음직스러워요. 직접 빵 만드는 곳이라 믿음이 가요. 보통 베이커리 카페 커피는 영 아닌 경우 많은데 괜찮아요. 양재천 초록초롣한 뷰가 편안함을 주네요. 샌드위치에 컬리플라워 들어간 것은 처음인데 좋아요. 컬리플라워와 새우 들어가 있어요 잠봉베르 궁금했는데 다 나가서 버섯 샌드위치도 시켜보았어요. 정확한 명칭은 파니니가 붙어요. 주문하면 따뜻하게 파니니 스타일로 주니 더 좋아요. 따뜻함이 주는 맛도 더 있죠. 아침 일찍 8시에 여는 것도 너무 좋아요.','2026-10-12T00:00:00.000Z'),
('nr-248','naver-1414148461','naver','여기 빵 종류도 많고 너무 맛있어요. 단백한 식사빵종류부터 달콤한 디져트류 빵까지 커피도 너무 맛있습니다. 매일매일 오고싶은 곳이에요. 사장님께서도 친절히 빵도 다시 데워주시고 컷팅도 해주시고 최고입니다.','2026-10-12T00:00:00.000Z'),
('nr-249','naver-1414148461','naver','샌드위치 종류가 많고 다 맛있어요 2층자리에서 양재천이 더 잘보여요 양재천걷다가 빵도 먹고 차 마시기 좋은 양재천뷰 맛집 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-250','naver-1414148461','naver','빵 맛집이란 소문듣고 왔어요^^ 강아지들도 많이 오네요~ 스콘이 진짜 너무너무 맛있구요 다른 빵도 다 맛있는데 트러플 버터 지인짜 맛있습니다 ~ 양재천 초록초록한 뷰를 보며 티타임하기 좋아요💚','2026-10-12T00:00:00.000Z'),
('nr-251','naver-38232590','naver','역삼베이커리카페 블리스라운드역삼점 매장의 위치도 좋아요 강남역도보7분, 역삼역도보5분거리 블리스라운드는 매일 신선하게 만드는 치아바타와 식빵, 카스테라, 파운드케이크, 샌드위치, 호두정과 등 빵천국이에요 빵지순례에 딱이에요','2026-10-12T00:00:00.000Z'),
('nr-252','naver-38232590','naver','초코바게트 좋아하는 분은 무조건 추천드려요. 과하게 달지 않으면서도 깔끔한 초코가 듬뿍 들어가서 먹다보니 저도 모르게 앉은 자리에서 하나 다 먹어서 내일 또 사러 가려고요. 아이는 마라롱을 먹었는데 꼬끄가 쫀득하면서 달콤한데 블루베리 크림의 상큼함과 만나니 조화롭다며 칭찬하네요^^','2026-10-12T00:00:00.000Z'),
('nr-253','naver-38232590','naver','역삼역이랑 가까운 곳에 있어서 찾아가기도 너무 쉽고, 매장이 커서 정말 좋아하는 빵집 겸 커피 맛집이에요. 사장님도 정말 친절하시고 빵 진열대도 청결하게 놓여있어서 마음 놓고 빵 고르는 재미가 있는 듯..ㅎㅎ 그리고 여기서 무슨 빵을 먹어도 맛있어요..!','2026-10-12T00:00:00.000Z'),
('nr-254','naver-38232590','naver','커피맛있고 르방 시키면 올리브유랑 같이 주는거 넘 좋아요 분위기도 좋고 빵종류도 많은데 빵들이 가격대비 다른곳에 비해 사이즈가 작은편인거같아요 역삼 시세인가..','2026-10-12T00:00:00.000Z'),
('nr-255','naver-38232590','naver','역삼역인근 베이커리 규모도 크고 음료랑 빵종류많아요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-256','naver-38232590','naver','직장 근처라 자주 들린 카페에요. 한 20번은 온 것같은데 최애 메뉴는 밤 파운드에요. ( 스트레스 날리기에 최고) 스콘도 맛있어요. 초코바게트, 치아바타 대체로 다 맛있음 다만 쿠키는 제 취향이 아니었어요ㅎㅎ 그것을 제외한 모든 빵 그리고 음료가 맛있으니 한번씩 꼭 드셔보세요! 적극 추천 합니다.','2026-10-12T00:00:00.000Z'),
('nr-257','naver-38232590','naver','치아바타랑 샌드위치가 정말 맛있네요👍👍 식사빵류 좋아해서 집어왔는데 역대급으로 맛있어서 남친 안 주고 혼자 흡입했어요 다음엔 치아바타 종류별로 집어오려구요!!','2026-10-12T00:00:00.000Z'),
('nr-258','naver-38232590','naver','메론케이크 맛있다고 소문나서 샀어요 ㅎㅎㅎ 가격도 합리적이고 다른 처음보는 디저트들도 기대돼서 같이 샀습니다. 한시적으로 일정금액 이상시 노트 증정하고 았오서 완전 향복한 소비였습니다. 감사합니다.','2026-10-12T00:00:00.000Z'),
('nr-259','naver-38232590','naver','쿠키 비주얼부터 장난 아니에오...🩷 그리고 꼭 상하목장 아이스크림 먹으세용!!!! 다른 곳에서도 팔지만 블리스라운드가 유독 꾸덕 고소함이 강한 거 같아용( σ̴̶̷̤ .̫ σ̴̶̷̤ )♡ 코코넛스무디를 정말 많이 먹어봤는데 커피 맛집이라 그런가 진짜 고급스러운 맛 나용 ㅠㅠ🚰·̫🚰','2026-10-12T00:00:00.000Z'),
('nr-260','naver-38232590','naver','블리스라운드에서 홍차파운드 사와봤는데, 왜 동네에서 맛있기로 소문난 곳인지 바로 알겠더라고요!!평소 홍차 디저트를 좋아해서 기대하고 먹어봤는데, 향이 은은하게 퍼지면서 너무 달지 않아서 딱 제 취향이었어요ㅎㅎ부담스럽지 않은 단맛이라 커피나 차랑 같이 먹기 정말 좋았고, 먹다 보니 또 생각나는 맛이더라고요. 매장도 넓고 깔끔해서 들어가자마자 기분이 좋았어요. 특히 요즘 베이커리 카페 가면 빵이 그냥 노출돼 있거나 보관이 아쉬운 곳도 많은데 요기는 전부 안쪽에 보관되거나 개별 포장되어 있어서 위생적인 부분에서 정말 만족스러웠어요~그런 세심한 부분 덕분에 더 믿고 고르게 되더라고요. 맛도 좋고 매장 관리도 깔끔해서 전체적인 만족도가 높았어요ㅎㅎ홍차파운드가 특히 맛있어서 다음에도 또 이거 사러 방문해볼까해욧 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-261','naver-2035747537','naver','근처 피부과에서 시술을 하는 친구를 기다리다가 배가 고파서 방문했어요~ 가게가 크지 않은데 생각보다 빵이 되게 맛있어요!! 특히 명란마요 소금빵이 느끼하지 않고 고소해요! 먹고 나서 또 사고 싶은데 몇분동안 다 팔렸어요 ㅠㅠㅠㅠ 다음에 또 올게요','2026-10-12T00:00:00.000Z'),
('nr-262','naver-2035747537','naver','항상 여자 직원 분도 친절하시고 비밀샌드위치 진짜 넘 맛있어요! 가성비도 좋고 강추에요!! 초코 치아바타 나왔다고 시식 주셨는데 이거도 맛있네요 추천해요!','2026-10-12T00:00:00.000Z'),
('nr-263','naver-2035747537','naver','샌드위치 좋아해서 지나가다 입간판 보고 들어왔어요 ㅎㅎ 너무 맛있네요 치아바타 기공이 제대로입니다!! 치폴레 샌듸치 매콤하니 맛나용 왕추천!!','2026-10-12T00:00:00.000Z'),
('nr-264','naver-2035747537','naver','동네언냐랑 비밀베이커리에 왔는데요. 매주 치아바타 정기적으로 구매하신다며 여기 어떻게 알았어? 라고 하시는 맛집입니다. 샌드위치 맛있고 커피 맛있고 짱입니다.','2026-10-12T00:00:00.000Z'),
('nr-265','naver-2035747537','naver','건강한 맛의 샌드위치집입니다. 학원 간식으류 나눠먹으려고 종종 사가요. 항상 변함없이 깔끔하고 신선해요 . 새로생긴 초코 치아바타 시식해봤는데 정말 맛있네요. 다음에 사야겠어요','2026-10-12T00:00:00.000Z'),
('nr-266','naver-2035747537','naver','먹음직스러운게 너무 많아요 ㅠㅠ 그리고 사장님 너무 친절하세여ㅎㅎ 새로운 메뉴들이 엄청 많은데 진짜 눈이 너무 즐겁고 행복합니다 친절한 서비스 감사합니다❤️','2026-10-12T00:00:00.000Z'),
('nr-267','naver-2035747537','naver','샌드위치 진짜 맛있게 잘 먹었어요🥪💛 빵은 부드럽고 속재료가 알차게 들어 있어서 한입 먹을 때마다 재료 맛이 잘 느껴져요~특히 채소도 신선하고 전체적으로 간이 과하지 않아서 부담 없이 먹기 좋았어요! 생각보다 양도 꽤 든든해서 간단한 점심이나 아침 식사로 딱 좋을 것 같아요😊 재료도 푸짐하고 맛도 좋아서 다음에 또 먹고 싶은 샌드위치였어요👍 재구매 의사 100%! 맛있게 잘 먹었습니다🥪💕','2026-10-12T00:00:00.000Z'),
('nr-268','naver-2035747537','naver','비밀베이커리 진짜 가성비도 좋고 넘 맛있어요 >.< 강추입니다. 야채 듬뿍 든 비밀샌드위치 건강에도 좋고 넘 맛나요! 직원분들도 친절하시고 추천합니다.','2026-10-12T00:00:00.000Z'),
('nr-269','naver-2035747537','naver','샐러드부터 샌드위치, 다양한 빵 종류까지 메뉴가 다양하게 있어서 좋네요. 간단하게 식사하기에도 좋고, 빵 구매 시 음료도 할인해주셔서 부담 없이 이용하기 좋았어요.','2026-10-12T00:00:00.000Z'),
('nr-270','naver-2035747537','naver','진짜 제가 애정하는 곳이에요! 건강식이고 맛있고 가격도 최고! 강추합니다😊❤️❤️','2026-10-12T00:00:00.000Z'),
('nr-271','naver-19866400','naver','친구랑 양재천 산책하고 유명한 샌디치가게 왔는데 분위기가 넘 좋아서 1차 반했습니다☺️ 빵 냄새두 너무 좋구 외국 놀러온 것처럼 좋았어요ㅎㅎ 치킨샌드위치,사과브리샌디치,스프 종루별로 시켰는데 넘 마싰을 것 같아요🥰 잘먹고 가겠습니다🥪♥️🌱','2026-10-12T00:00:00.000Z'),
('nr-272','naver-19866400','naver','한가로운 가을 주말을 더 행복하게 해주는 곳이예요🤎 친절은 덤이구요. 넘넘 맛나서 자꾸 먹게 되는 핫샌드위치와 옥수수스프 그리고 뺑오쇼콜라. 저희 가족 최애조합입니다.','2026-10-12T00:00:00.000Z'),
('nr-273','naver-19866400','naver','역시나 실망시키지 않은 비플레이트…🤎 빵도 너무 맛있는데 샌드위치도 너무 맛잇어요. 요즘 샌드위치 기본 만원 대인데 내용물이 아쉬운데 여기는 진짜 버터 잠봉뵈르양 완전 많구 바게트도 너무 맛남 ㅠㅠㅠ 콰트로 치즈는 진짜 어디 치즈 쓰는지 치즈양 대박 ㅠㅠ 너무 맛있어요…♥️','2026-10-12T00:00:00.000Z'),
('nr-274','naver-19866400','naver','빵들이 너무 먹음직스럽게 생겼어요! 식빵이랑 샌드위치 포장했는데 빨리 먹고싶네요 :) 다음에는 매장에 와서 커피랑 스프랑 샌드위치 먹어보려구요 직원분들도 친절하시고 너무 좋은 경험이었습니다😍🥰','2026-10-12T00:00:00.000Z'),
('nr-275','naver-19866400','naver','5,6년 전 이동네 살 때 알게 된 동네 빵집이었는 데 그 때도 웨이팅이 밖에 있는 맛집이었지만요 ^^ 근처로 이전하며 확장하시고, 샌드위치 메뉴+ 음료가 많아지고 종류가 다양해져서 좋더라고요! :9 지난 번에 양재천 나들이 와선 어머니랑 왔을 때 포카치아 샌디치 맛있게 먹었어요. 다음엔 느즈막히 와서 호밀바게트도 사고, 오후 한정 샌드위치로 브런치를 여유롭게 즐겨보려고요 ☘️🥖','2026-10-12T00:00:00.000Z'),
('nr-276','naver-19866400','naver','주말 양재천산책나왔다가 우연히 들러 브런치 먹었는데 샐러드도 넘맛있고 샌드위치도 넘넘 맛있었어요👍분위기도 좋고 커피도 맛있어요 메뉴도 다양해서 고르는게 한참 걸렸네요^^다음에 또 와서 다른메뉴도 먹어보고 싶어요❤️','2026-10-12T00:00:00.000Z'),
('nr-277','naver-19866400','naver','양재천에서 유명한 베이커리라 예전부터 가보고 싶었는데 드디어 방문! 시그니처 치킨샌드위치와 허브빵 포장했는데 샌드위치 포장 시 할인도 되어서 좋았습니다. 집 근처였으면 자주 왔을텐데 아쉽네요. 재방문 의사 있습니다.','2026-10-12T00:00:00.000Z'),
('nr-278','naver-19866400','naver','오늘은 신메뉴 Quattro Grilled Chesse Sandwich 도전했는데 역시 실망시키지 않네요!👍✨ 풍부한 치즈와 느끼함 잡아주는 할라피뇨, 그리고 단짠을 완성하는 꿀이 신의 한수 같아요! 늘 먹을 때마다 느끼지만 좋은 재료가 정말 아낌없는 비플레이트!😍','2026-10-12T00:00:00.000Z'),
('nr-279','naver-19866400','naver','오랜만에 방문해본 비플레이트 예전 맛있는 일리원두의 고소함을 살리지못해 커피맛이 아쉬웠던 기억이 나서 오늘의 커피맛은 어떨지 궁금 놀랍도록 부드러웠던 치아바타 햄치즈샌드위치는 역시나 오늘도 대성공 지난번 원두맛의 이상함이 디게싱이슈여서 조절했다셔서 맛을보니 오늘은 풍미도 가득하고 만족스러운 맛이었음 다만 실내 들어서니 계속 목이 칼칼해 이유가 뭘까 둘러보니 내부 공기순환/에어컨 먼지관리가 좀 되면 좋을듯싶음 재방문의사 있음','2026-10-12T00:00:00.000Z'),
('nr-280','naver-19866400','naver','항상 들리는 곳이예요 분위기도 편안하고 베이커리 샌드위치도 너무 맛있어요! 실패없는 맛집입니다','2026-10-12T00:00:00.000Z'),
('nr-281','naver-1614953667','naver','압구정로데오 카페 찾다가 급하게 찾아간 곳인데 카페도 넓고 내부 인테리어도 예뻤어요! 사진 찍기도 좋고 대화 나누기도 좋습니다~ 빵이랑 케이크도 비주얼 좋고 맛있어요! 이번에 저녁에 가서 품절된 빵이 있었는데 다음에는 일찍 가서 다른 빵도 먹어보고 싶네요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-282','naver-1614953667','naver','압구정에서 유명한 카페를 다녀왔습니다. 입구부터 이색적인 분위기와 함께 아름다움이 느껴지는 카페였고 안에 들어서니 유럽에 있는 기분이 드는 카페였어요. 빵과 커피도 맛있고 특히 빵 디자인이 정말 아름다워요 ㅎㅎ 내부에 포토뷰가 정말 많아서 데이트나 혼자 올때도 정말 좋네요. 크기가 큰데도 에어컨도 빵빵해서 어디에 앉든지 시원해요. 정말 아름다운 카페네요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-283','naver-1614953667','naver','내돈내산 100% 찐리뷰!! 🥐🤎 빵 종류가 정말 다양해서 들어가자마자 뭐부터 골라야 할지 한참 고민했어요! 무엇보다 더운 여름에 시원하고 매장도 엄청 넓고 쾌적해서 편하게 먹기 좋았고, 직원분들도 너무 친절하셔서 기분 좋게 이용했어요☺️ 특히 페스츄리가 진짜 감동적으로 맛있어요…🥹💕 바삭하면서도 고소하고 풍미가 제대로라 먹고 나서도 계속 생각나는 맛! 빵 좋아하시는 분들은 꼭 한번 가보세요. 저도 다음에 또 방문할 예정이에요🫶🏻','2026-10-12T00:00:00.000Z'),
('nr-284','naver-1614953667','naver','카페 너무 이쁘고 디저트도 다양해서 뭘 먹어야 할지 모르겠어여! 주말 오후쯤에 가서 많이 없긴했지만 그래도 올만한 카페였습니당 :)','2026-10-12T00:00:00.000Z'),
('nr-285','naver-1614953667','naver','압구정에 볼일이 있어서 왔다가 역근처 카페 방문하였는데 매장 인테리어도 예쁘고 커피도 맛있고 딸기청과 함께 딸기 아이스크림도 맛있고 빵도 맛있어요!','2026-10-12T00:00:00.000Z'),
('nr-286','naver-1614953667','naver','여기는 사진 찍으면 너무 이쁘게 잘 나오는 카페예요ㆍ♡ 여기 유명 리본빵 크림 들어 맛있고, 커피 맛도 괜찮아요ㆍ크리스마스때 장식 정말 이뻐요ㆍ','2026-10-12T00:00:00.000Z'),
('nr-287','naver-1614953667','naver','외국인 친구에게 한국 예쁜 카페 소개하려고 찾다가 잘견하고 갔는데 대만족이에요! 빵 맛있고, 특히 리본빵 처음 먹어봤는데 예쁘고 진짜 맛있어요! 야외 예쁘니깐 사진 꼭 찍으세용!!💝😝','2026-10-12T00:00:00.000Z'),
('nr-288','naver-1614953667','naver','압구정에서 보기 드문 대형 카페예요 굉장히 빈티지스러운 인테리어 컨셉으로 4층은 야외테라스로 꾸며 있어요 옆좌석과 붙어있지 않아 대화 나누기도 좋아요 커피 베이커리 다 기본이상이었어요','2026-10-12T00:00:00.000Z'),
('nr-289','naver-1614953667','naver','압구정에 찾기힘든 대형카페! 인테리어가 너무 이쁘고 케이크도 너무 맛나요~','2026-10-12T00:00:00.000Z'),
('nr-290','naver-1614953667','naver','2번째방문이에요.여긴 제가 좋아하는 카페 중 하나에요.베이커리도 예뻐서 인스타감성 찍기좋고 매잠 분위기도 층마다 달라서 포토존많아요. 여기는 무조건가세요. 한번도안가본사람은있어도 한번만 가본사람은 없을~','2026-10-12T00:00:00.000Z'),
('nr-291','naver-1776798877','naver','셀렉티드닉스는 탁 트인 루프탑 뷰가 매력적인 카페예요 ☀️ 도심 건물들과 파란 하늘이 한눈에 들어와서 사진 찍기에도 좋더라고요. 커다란 노란색 NICK’S 조형물도 포토존으로 딱이에요 💛 디저트는 세 가지를 나란히 담아주셔서 비주얼부터 눈길이 갔어요! 크럼블과 코코아 가루, 초콜릿 토핑까지 각각 다르게 올라가 있어서 하나씩 즐기는 재미가 있어요. 음료와 디저트를 앞에 두고 도심 풍경을 바라보니 여유로운 카페 시간이 완성되는 느낌이에요. 날씨 좋은 날 데이트하거나 친구랑 사진 찍으러 가기 좋은 곳이에요 :)','2026-10-12T00:00:00.000Z'),
('nr-292','naver-1776798877','naver','강남역 인근에 이렇게 큰 규모의 티라미수 카페가 있다는 걸 최근에 알게 되었습니다. 지하 1층부터 루프탑까지 총 5개 층을 사용하고 있어서 처음 방문하시는 분들은 규모에 놀라실 것 같습니다. 이날은 얼그레이라떼와 밀크티, 티라미수 3종 플래터를 주문했는데, 클래식·바나나·초코바나나 세 가지 맛을 한 번에 맛볼 수 있어 처음 방문이라면 추천드리고 싶습니다. 루프탑 좌석에서는 강남 스카이라인이 한눈에 들어와 사진 찍기에도 좋았습니다. 공간대여도 가능하다고 하니, 소모임이나 스터디 장소를 찾으시는 분들께도 추천드립니다.','2026-10-12T00:00:00.000Z'),
('nr-293','naver-1776798877','naver','와 강남 한복판에 이렇게 멋진 시티뷰의 카페가 있다니! 티라미슈와 커피도 너무 맛있고 층마다 다른 느낌의 카페라서 구경하는 재미가 가득하네요. 루프탑에서 전망보며 시원한 아아와 바나나티라미슈 먹으니 그냥 모든 근심들이 사라지는 느낌이에요.','2026-10-12T00:00:00.000Z'),
('nr-294','naver-1776798877','naver','음료도 디저트도 넘나 맛있는 <셀렉티드닉스> 아메리카노 비타민비트음료 라즈베리티라미수, 초코 크런치미들렌, 무화과 휘낭시에 루프탑 8f 스터디룸 . . 3f / 2f / 1f 층마다 특색이 있는 공간이 마음에 들어요 님편이랑 휴일날 데이트 제대로 했어요 😋🫰❤️','2026-10-12T00:00:00.000Z'),
('nr-295','naver-1776798877','naver','디저트와 함께 곁들인 딸기라떼는 신선한 딸기 과육이 듬뿍 들어가 있어 우유의 부드러움과 딸기의 상콤달콤함이 완벽한 밸런스를 이루었습니다. 인위적인 시럽 맛이 아닌 생생한 과육 식감이 씹혀 마시는 내내 즐거움을 더해주더라고요. 함께 주문한 비타민유자는 따뜻하고 상큼한 유자 향이 은은하게 퍼지며 지친 일상에 산뜻한 활력을 불어넣어 주었습니다. 달콤한 디저트와 상큼한 음료의 조화가 훌륭하여 머무는 내내 완벽한 당 충전과 힐링을 누릴 수 있었습니다.','2026-10-12T00:00:00.000Z'),
('nr-296','naver-1776798877','naver','일단 커피랑 디저트가 너무 맛있구요... 특히 티라미수가 격이 다른게 한입 먹자마자 느껴졌었습니다. 공간 자체도 너무 멋있고 강남 한복판에서 이런 보석같은 대형카페를 찾을 수 있다는게 감사할따름이네요. 자주 방문하는거 예약하겠습니다 ~','2026-10-12T00:00:00.000Z'),
('nr-297','naver-1776798877','naver','3종 플래터에 비타민 음료, 커피까지 여유롭게 즐기고 왔어요-! 무엇보다 오늘처럼 날씨 좋은 날에는 루프탑 분위기가 정말 좋더라고요. 탁 트인 공간에서 바람도 선선하게 불고, 햇살까지 좋아서 앉아 있는 것만으로도 기분이 좋아졌어요. 3종 플래터는 여러 가지를 한 번에 맛볼 수 있어서 좋았고, 비타민 음료도 상큼해서 음식과 잘 어울렸어요. 커피까지 마시면서 여유롭게 시간 보내기 딱 좋았던 곳! 날씨 좋은 날 루프탑에서 분위기 즐기고 싶을 때 다시 방문하고 싶은 곳이에요 :)','2026-10-12T00:00:00.000Z'),
('nr-298','naver-1776798877','naver','두쫀쿠 먹고싶어서 우연히 찾게된 디저트 카페 💚🤎 오랜만에 먹은 두쫀쿠라 그런가 더 맛있어땅 ㅎㅎ 아이스아메리카노랑 세투로~~ 여기 시그니처가 티라미수던데 넘 맛있어보여서 특이한 딸기티라미수 시켰는데 그냥 딸기케이크임..!! 스펀지에 딸기크림.. ㅎㅎ 클래식을 먹었어야했나 ㅎㅎ 좀 아쉽당..!','2026-10-12T00:00:00.000Z'),
('nr-299','naver-1776798877','naver','강남역 ''셀렉티드닉스''는 갤러리에 온 듯한 모던한 분위기가 매력적인 공간입니다. 과육이 가득한 상큼한 망고쥬스, 아트가 예쁜 말차라떼와 카페라떼 모두 눈과 입이 즐거운 훌륭한 맛이었어요! 좌석 간격도 넓어서 일행과 쾌적하게 대화하기 정말 좋았습니다. 강남 분위기 맛집으로 추천해요!','2026-10-12T00:00:00.000Z'),
('nr-300','naver-1776798877','naver','셀렉티드닉스에 두 번째 방문했는데, 매장 내부와 외부 분위기가 깔끔하고 아늑해서 데이트하기 정말 좋은 곳이에요. 진저 레몬 에이드와 초코 라떼, 그리고 달콤새콤한 라즈베리 티라미수를 주문했는데 비주얼도 예쁘고 맛도 훌륭해서 기분 좋은 시간을 보냈습니다. 가격대도 합리적이고 전체적으로 만족스러워서 다음에도 또 방문하고 싶네요.','2026-10-12T00:00:00.000Z'),
('nr-301','naver-1689410898','naver','친구들과 특별한 날을 보내려고 브릴뤠에 왔어요 :) 음식 나오자마자 비주얼부터 너무 맛있어 보여서 기대됐어요!! 분위기도 좋아서 친구들이랑 기분 내면서 식사하기 딱 좋은 것 같아요. 특별한 날 맛있는 음식 먹으면서 좋은 시간 보내고 갑니다 💛','2026-10-12T00:00:00.000Z'),
('nr-302','naver-1689410898','naver','푸딩은 부드럽게 부서지는 느낌보단 탱글만 식감이고, 개인적으로 밀크티가 제일 유명한것 같은데 제 입엔 꽤 달게 느껴졌어요!커스터드가 역시 기본에 적정한 단맛이였어요 팬케이크는 지금까지 먹은 수플레 중 제일 맛있었고 입 안에 들어가는 순간 사르르르르르르 녹아요!!! 아아 필수!!!!!','2026-10-12T00:00:00.000Z'),
('nr-303','naver-1689410898','naver','수플레가 넘 퐁신퐁신하구 맛있어요!! 종류도 너무 다양해서 고르기 힘들었는데 크림브륄레로 시켜서 달달하니 너무 좋더라구용🥹 다음번에 올 때는 초코나 딸기로도 시켜보려구요!! 직원 분들도 너무 친절하셔서 더욱 더 기분 좋게 먹었어요💓 감사합니다🫶🏻','2026-10-12T00:00:00.000Z'),
('nr-304','naver-1689410898','naver','좌석은 생각보다 많은데 사람이 꽉차면 좀 소란스러운 느낌이긴 해요. 청포도 에이드가 맛있고 양이 많아요. 커스타드 푸딩이 진하고 식감이 부드러워서 만족스러웠어요. 음료가 빨리나오고 좌석이 편해요. 리뷰이벤트 밀크푸딩도 양이 많고 우유 맛이 진해서 매력있어요.','2026-10-12T00:00:00.000Z'),
('nr-305','naver-1689410898','naver','소과당 강남본점 다녀왔는데 팬케이크가 정말 맛있었어요! 🥞 쌀가루로 주문했는데 폭신폭신하고 담백해서 부담 없이 먹기 좋았고, 아메리카노랑도 정말 잘 어울렸어요. 비주얼도 예쁘고 맛도 좋아서 강남역에서 디저트 생각날 때 또 방문하고 싶은 곳이에요 😊☕️','2026-10-12T00:00:00.000Z'),
('nr-306','naver-1689410898','naver','소과당 수플레가 제일 맛있어요. 여름엨 빙수, 가을엔 수플레! 그리고 4계절 내내 맛있게 먹는 우유푸딩까지😁😁 강남역 근처에서 가성비 좋은 브런치 집이라 종종 방문하고 있어요! 물론 커피도 맛있어요~','2026-10-12T00:00:00.000Z'),
('nr-307','naver-1689410898','naver','수플레케이크를 원한다면 강남에서 선택지가 많지 않지만 그 많지 않은 선택지가 대부분 다행히 정답의 맛을 제공하는 거 같아요 소과당은 정답 이상! 맛있는 디저트, 환한 분위기. 매장이 조금 더 넓으면 좋겠지만 그럼 웨이팅이 더 있겠죠? 복숭아 수플레 먹었는데 쌀 반죽 최고!','2026-10-12T00:00:00.000Z'),
('nr-308','naver-1689410898','naver','친구들과 간만에 만나서 카페 어디가지 할까 하다가 발견한 곳! 아는 언니는 이미 알고 있는데 맛있다그러더라구요~ 디저트 종류 다양하고 수플레팬케이크도 쌀가루 밀가루 고를 수 있어서 너무 좋은데요?! 넘 맛나요:)','2026-10-12T00:00:00.000Z'),
('nr-309','naver-1689410898','naver','푸딩 먹고 싶어서 찾아왔는데 종류가 정말 다양해서 고르는 재미가 있어요 🍮 푸딩이 탱글탱글하면서도 부드럽고 많이 달지 않아서 맛있게 먹었습니다! 분위기도 깔끔하고 강남역에서 가까워서 디저트 먹으러 오기 좋네요. 다음에는 수플레도 먹어보고 싶어요 :) 푸딩 좋아하시는 분들께 강추합니다! 가로수길 르사이트나 더현대 포동푸딩보다 만족도가 높았음. 푸딩매니아인 아이도 좋아하네요','2026-10-12T00:00:00.000Z'),
('nr-310','naver-1689410898','naver','특별한 날에 사랑스런 지인분과 소과당 방문했어요!! 직원분 예쁘시고 친절하시고 음식도 맛있어요~🥰 쌀가루 플레인 팬케이크, 코코넛스무디, 애플시나몬티 주문했는데 달달한 저녁보내고 갑니당💕','2026-10-12T00:00:00.000Z'),
('nr-311','naver-32636994','naver','소나에 오신다면 샴페인 슈가볼 꼭 드셔보세요!! 디저트의 새로운 경험과 식감, 향을 느끼실 수 있어요. 남자친구 와서 행복한 경험을 하고 갑니당. 저는 단 음식을 별로 안 좋아하는데 소나는 디저트들이 과하게 달지도 않고 정말 맛있어용 눈과 입이 행복한 데이트였습니당💜','2026-10-12T00:00:00.000Z'),
('nr-312','naver-32636994','naver','디저트 맛집 찾아다니는데, 오늘 친구 생일이라 회사에서 가까운 곳의 특별한 메뉴가 있는 곳으로 찾았음. 슈가볼을 깨트려서 라벤더/라즈베리시럽을 부어서 먹는 메뉴는 샴페인폼에 라벤더향이 꽤 강하게 들어가있고, 밑에 깔려있는 치즈가 녹진한 느낌을 냄. 바슈랭은 머랭안의 라즈베리소르베와 바닐라아이스크림이 조화롭게 상큼함을 주고 딜플라워가 독특한 느낌을 줌. 맛있다!','2026-10-12T00:00:00.000Z'),
('nr-313','naver-32636994','naver','체리자두쥬스,소나카 고르곤졸라, 하비스트(추수)주문했습니다. 바질향나는 아이스크림에 바삭해서 과자같은 모나카에 장미맛나고 특이했어요 체리자두쥬스는 설탕들어가지않은 신선하고 건강한 체리와자두주스라서 넘 개운하고맛있어요','2026-10-12T00:00:00.000Z'),
('nr-314','naver-32636994','naver','압구정에서 분위기 좋은 디저트 레스토랑 찾다가 방문했는데 생각보다 훨씬 만족스러웠어요. 전체적으로 공간이 아늑하면서도 고급스럽고, 디저트 하나하나 플레이팅도 예뻐서 보는 재미가 있었어요. 단순히 달기만 한 디저트가 아니라 맛의 조합이나 식감이 다양해서 코스로 먹어도 질리지 않았고, 특히 디저트가 너무 달지 않아서 좋았어요. 직원분들도 친절하고 응대가 편안해서 분위기까지 좋았어요. 특별한 날이나 데이트할 때 방문하기 좋은 곳 같아요. 가격대가 조금 있는 편이지만, 일반적인 카페 디저트와는 확실히 다른 경험이라 한 번쯤 가볼 만한 곳이라고 생각해요. 압구정에서 예쁘고 분위기 좋은 디저트 코스 찾으시는 분들께 추천하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-315','naver-32636994','naver','맛있는데 예쁜 디저트가 돝보였던 곳 같아용!! 개인적으로는 식용 꽃이 좀 써서 샴페인 볼보다는 초콜릿 크렘 브륄레가 더 맛있었는데 둘 다 사실 특색 있어서 좋았어요! 과일과 포슬포슬한 치즈케이크의 조화도 특이한데 맛있었구 초콜릿 무스 같은 크렘 브륄레도 좋았어요! 인테리어도 예쁘구 직원 분도 친절합니당','2026-10-12T00:00:00.000Z'),
('nr-316','naver-32636994','naver','신사역 근처에서 분위기 좋은 카페 발견 ☕️🤍 특히 다른 카페에서는 쉽게 볼 수 없는 특별한 디저트 메뉴들이 많아서 좋았어요! 디저트 구경하는 재미도 있고 분위기도 좋아서 신사역 근처 오면 또 방문하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-317','naver-32636994','naver','세가지 시켰는데 워낙 초코를 좋아해서 제 원픽은 다크초콜릿 크렘브륄레 이지만, 고르기가 힘들게 셋 다 다른 매력의 느낌이라 다 맛있어요!! :)','2026-10-12T00:00:00.000Z'),
('nr-318','naver-32636994','naver','분위기 좋고 평소 경험해보지 못했던 색다른 디저트와 음료를 경험해 볼 수 있어서 좋아요☺️💓 메뉴들도 다 맛있고 직원분들도 친절하셔서 추천합니다🫶','2026-10-12T00:00:00.000Z'),
('nr-319','naver-32636994','naver','머랭이 부드러우면 상큼달콤한 맛이 조화로웠어요 머랭을 이렇게 기술적으로 잘 만들긴 쉽지않은데 입안에서 바삭하면서 크림과 섞여서 입에서 살살 녹네요 라즈베리 소르베가 킥이닷! 이라고 지인이 감탄했네요! 느므느므 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-320','naver-32636994','naver','독특한 디저트가 있다고 해서 방문했습니다 !! 카페 시그니처 디저트인 슈가볼을 주문했는데 점원 분이 디저트에 대해 꼼꼼히 소개해주셨어요! 덕분에 처음보는 디저트임에도 불구하고 잘 즐겼습니다~♡♡ 블루베리와 라벤더 향이 향긋하고 생화도 신선해서 오래도록 기억에 남는 맛이었습니다!','2026-10-12T00:00:00.000Z'),
('nr-321','naver-1331575749','naver','까눌레맛집 같아 간곳인데 까눌레보다는 치즈케익이 생각납니다 꾸덕한게 아닌 부드러운치즈케익.. 생각나네요 커피도 맛있습니다','2026-10-12T00:00:00.000Z'),
('nr-322','naver-1331575749','naver','까눌레에 커피 조합이 미쳤어요 바치케 넘 맛있어요 개인적으로 바치케 중심부가 부드러운걸 좋아하는데 이 집이 딱 그 맛입니다. 넘 맛나서 좋아요. 의자도 편하고 공간이 대화하기도 편해서 마음에 듭니다. 디카페인 드립 마셨는디 향긋하고 넘 좋네요. 굿굿','2026-10-12T00:00:00.000Z'),
('nr-323','naver-1331575749','naver','저장만 해두고 궁금했던 카페인데 오늘 기회가 되어 드디어 방문했어요! 분위기도 좋고 커피도 맛있어서 만족했습니다 다음에 또 방문하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-324','naver-1331575749','naver','까눌레를 좋아해서 찾아보다가 와봤는데, 분위기도 좋고.. 무엇보다 음악이 너무 좋아서🫰🏻🫰🏻 강남 오면 꼭 다시 와야겠아염// 귯뜨!!','2026-10-12T00:00:00.000Z'),
('nr-325','naver-1331575749','naver','강남에 이렇게 조용하고 분위기있는 곳 찾기가 힘든데! 너무 아늑하고 커피도 디저트도 맛있었어요!! 친구들과 오순도순 대화하기 너무 좋아요','2026-10-12T00:00:00.000Z'),
('nr-326','naver-1331575749','naver','까눌레는 겉은 바삭하고 속은 촉촉하면서 쫀득해요 단맛도 과하지 않아 커피와 잘 어울립니다. 아이스 아메리카노도 고소한맛, 산미있는 맛 선택할 수있고 디저트와 함께 즐기기 좋았습니다. 매장 분위기도 차분하고 깔끔해요. 까눌레 좋아하시는 분이라면 한 번쯤 방문해 볼 만한 카페입니다.','2026-10-12T00:00:00.000Z'),
('nr-327','naver-1331575749','naver','커피잔도 너무 이쁘구 디저트도 너무 맛있어용! 인테리어랑 음악 선곡도 넘넘 조아요 ㅠ','2026-10-12T00:00:00.000Z'),
('nr-328','naver-1331575749','naver','친구가 휘낭시에 좋아해서 같이 따라와봤는데 늦게 왔는데도 재고가 남아있어서 좋았고 맛있을거같아요 가게 안에 인테리어도 예뻐서 낮에 오면 좋을거가타요','2026-10-12T00:00:00.000Z'),
('nr-329','naver-1331575749','naver','디저트 맛집 찾다가 왔는데 너무 맛있고 얼그레이 밀크티도 제가 먹어본 것 중에 제일 맛있었어요ㅠㅠㅠ 분위기도 너무 좋아요🤤','2026-10-12T00:00:00.000Z'),
('nr-330','naver-1331575749','naver','친구랑 강남에서 밥 먹고 디저트 먹으러 왔어요 너무너무 맛있어요 까눌레 맛있는 곳 드문데 여기 담백하니 맛있습니다🫶','2026-10-12T00:00:00.000Z'),
('nr-331','naver-1207231213','naver','베이커리 카페 <Standard Bread> 도산점. 지점이 여러 군데가 있네요. 테라스가 좋아서 방문했는데 루프탑 야외 공간은 더 멋져요! 한 번 더 오려고요~ 😍 총 4층까지 있는 매우 넓은 곳이에요. 😘 아이스 카페라떼(6,300원) 주문했는데 커피 맛은 보통이에요. 그래도 양이 많아서 좋아요. ☕️ 직원 분들도 모두 친절하세요. 🥰 멋진 테라스에서 좋은 시간 보내고 갑니다~ 루프탑 즐기러 한 번 더 올 거예요! ❤️','2026-10-12T00:00:00.000Z'),
('nr-332','naver-1207231213','naver','무화과 계절이왔어요!! 그럼 뭐다? 무화과 베이글 먹어야죠 막 구워낸 따끈한 식빵을 먹을수있는곳 스탠다드 브레드 요기 원래 소금식빵 완전 추천하는 집인데 이 시즌엔 무조건 무화과 베이글입니다 무화과향기 은은하게 풍기고 쫄깃한 베이글에 바작바작 씹히는 무화과 맛있어요 1층에서 빵고르고 2층에서 음료 주문 인테리어 아주 독특하고 직원분들도 친절 그리고 테이블도 많아요! 근데 사람도 많음','2026-10-12T00:00:00.000Z'),
('nr-333','naver-1207231213','naver','빵이 갓 나온 시간이라 그런지 매장 안에 고소한 빵 냄새가 가득하고 종류도 다양해 구경하는 재미가 있다. 공간도 감각적이고 진열도 정갈해서 빵 하나 고르는 시간까지 즐거웠던 곳. 이른 아침부터 기분 좋은 빵 구경. #스탠다드브레드 #스탠다드브레드도산 #신사동빵집 #신사동베이커리 #강남빵집 #빵지순례 #베이커리투어 #내돈내산','2026-10-12T00:00:00.000Z'),
('nr-334','naver-1207231213','naver','감각적인 공간과 메뉴 구성 덕분에 외국인들도 많이 찾을 것 같은 카페였습니다. 백화점에 입점해도 잘 어울릴 만큼 브랜드의 완성도가 느껴졌고, 편안하게 머물며 커피를 즐기기 좋은 공간이었습니다. 아주 가끔씩 오는곳 압구정로데오 가볼만한카페 4층정원도 깔끔','2026-10-12T00:00:00.000Z'),
('nr-335','naver-1207231213','naver','빵, 음료, 빙수 메뉴가 알차게 구성되어 있어서 방문해봤어요. 1층은 베이커리, 2층은 음료로 나뉘어져있어서 신기했어요. 공간이 넓고 앉을 자리가 많고 다양해요. 디카페인 롱블랙으로 주문했고 컵 사이즈에 비해 밍밍하지만 먹을만해요. 빙수도 아는 맛이에요! 빵이 맛있는 곳인 것 같아요! 재방문의사 있습니다.','2026-10-12T00:00:00.000Z'),
('nr-336','naver-1207231213','naver','생식빵 정말 정말 맛있어요!!!!!! 버터향 가득하고 쫀득한 갓 나온 식빵 뜯어먹는 맛이 최고네요!!! 커피랑 같이 먹으니 두배로 더 맛잇네요~ 허니버터 갈릭 토스트 갈릭향과 달콤함의 조합에 끝네주네요. 아침 일찍 열어 자주 방문할 듯 해요.','2026-10-12T00:00:00.000Z'),
('nr-337','naver-1207231213','naver','에그인헬 19,000원 (5점♡) 플레인 치즈찰빵 2,000원 (4점) 아이스 카페라떼 디카페인 6,800원 (2점) 에그인헬에 빵이 포함되어 있지 않습니다. 대신 통통한 고기완자 6개와 계란 2개가 있어서 든든합니다. 정말 맛있어요♡ 양은 여자 혼자 먹기 딱 좋은 양이예요. 사진으로는 양이 많아 보이는데 그릇이 작아요 (스푼도 작아서 불편ㅜㅜ) 두 번째 사진은 다른 브런치카페 에그인헬인데 (빵포함 가격 17,200), 이것도 맛있지만 스탠다드 브레드에 비하면 확실히 허전합니다. 치즈찰빵도 쫀득하니 맛있네요. 다만, 커피는 풍미 없이 쓰기만 해서 중간 이하예요. 가격이 비싸서 다음엔 안온다고 생각했는데, 에그인헬이 넘나 제 스타일이라서 종종 올듯 합니다.','2026-10-12T00:00:00.000Z'),
('nr-338','naver-1207231213','naver','카페가 한건물 다쓰고 4층까지 있어 매장이 넓고 그리고 분위기도 유럽 중세시대때 빵집에 온 느낌의 인테리어에 여기는 식빵이 시그니처메뉴이고 다른 빵들과 디저트 음료도 맛있고 대화하기 좋고 주문과 결제는 1층에서 하고 음료는 2층에서 받으시고 브런치 메뉴도 있고 테라스도 있어서 좋습니다. 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-339','naver-1207231213','naver','점심시간에 콧바람 쏘이러 마실나오기 좋은 카페에요 기본 식빵 메뉴부터 디저트와 브런치 메뉴까지 전체적으로 구성도 알차서 점심 식사하기에도 딱이에요. 빵맛은 당연히 맛있고 특히 브리오슈 너무 맛있어요 완전 추천이에요!!','2026-10-12T00:00:00.000Z'),
('nr-340','naver-1207231213','naver','여동생이랑 간단하게 한 끼 하러 방문했어요 갓 구운 빵들이라 고소하고 맛있었고 매장 분위기 너무 좋네요 마치 중세로 떨어진 거 같은 느낌이에요 좋은 시간 보내고 갑니다😊','2026-10-12T00:00:00.000Z'),
('nr-341','naver-1689752307','naver','강남역 근처에 위치한 이색카페에요. 귀여운 동물들도 많고 사장님도친절하셔요! 매장도 넓고 깨끗해서 단순히 동물친구들 뿐만아니라 커피마시며 책읽기에도, 대화, 모임하기에도 좋아요!! 강남역 커피 맛집이에요!','2026-10-12T00:00:00.000Z'),
('nr-342','naver-1689752307','naver','슬로우커피 ◾ 귀여운 거북이 빵을 만날 수 있는 이색 카페 ◾ 수족관 속 거북이와 다양한 물고기, 이구아나까지 볼 수 있는 공간 ◾ 커피와 함께 여유를 즐기기 좋은 강남 카페 강남 카페투어를 하다가 슬로우커피에 방문했어요. 가장 먼저 눈에 들어온 건 귀여운 거북이 모양의 빵이었는데, 보기만 해도 기분이 좋아지는 비주얼이라 사진을 남기기에도 좋았습니다. 매장 중앙에는 수족관이 마련되어 있어 거북이와 다양한 물고기를 구경할 수 있었고, 이구아나까지 만나볼 수 있어 일반 카페와는 또 다른 재미가 있었어요. 커피를 마시며 동물들을 천천히 구경할 수 있어 여유로운 시간을 보내기 좋았고, 색다른 분위기의 강남 카페를 찾는다면 한 번 방문해 보시길 추천드립니다. 🙂','2026-10-12T00:00:00.000Z'),
('nr-343','naver-1689752307','naver','항상 지나가다 봐 온 곳이었는데 늘 가고싶다만 생각하다 오늘 와봤어요! 시그니처 메뉴도 정말 맛있고 매장이 넓고 거북이가 귀여워요 거북이 말고도 다양한 파충류들이 있어서 관찰하기도 좋았어요 다음에 또 오겠습니다!!','2026-10-12T00:00:00.000Z'),
('nr-344','naver-1689752307','naver','동물 좋아하는 친구랑 방문했어요!! 너무 귀여운 거북이들, 게코 도마뱀, 이구아나, 물고기들이 있고 매장도 쾌적해서 아이들이랑 방문하기도 좋아보여요!! 그리고 이런곳들 음료는 좀 별로인데 슬로우커피는 음료도 넘 맛있습니당','2026-10-12T00:00:00.000Z'),
('nr-345','naver-1689752307','naver','이색카페 추천합니다! 거북이랑 물고기, 파충류가 진짜 많고 음료 마시면서 동물 친구들 감상하기 좋아요!! 동물 좋아하시는 분 특히 파충류 좋아하시면 적극 추천합니당 매장도 깔끔하고 넓어서 여유롭게 커피 한 잔 하기 좋습니다👍','2026-10-12T00:00:00.000Z'),
('nr-346','naver-1689752307','naver','빵도 거북이모양이고 너무 이뻐요~~♡ 음료도 너무 맛있고 분위기가 최고에요~~♡ 다음에도 방문할께요~~♡♡','2026-10-12T00:00:00.000Z'),
('nr-347','naver-1689752307','naver','오랜만에 갔더니 예쁘고 귀여운 굿즈도 생기고 물고기들도 커지고 파충류들도 많아지고 좋네용!! 파충류랑 물고기 보며 디저트 먹기 좋아요~~>.< 7살 아들이 5살때부터 온곳 ㅋㅋㅋ 없어지지말고흥하기를 :)','2026-10-12T00:00:00.000Z'),
('nr-348','naver-1689752307','naver','슬로우커피에서 커플 세트 메뉴(슬로우 브런치, 애플브리치즈 샌드위치, 아이스 아메리카노, 아이스 바닐라라떼)를 먹었는데 커피와 디저트 모두 정말 맛있었어요! 수제 휘낭시에도 분위기 맞춰서 물고기모양!!! 센스 대박 감명받았습니다. 매장 안에 물고기 어항이랑 귀여운 파충류 마그넷들이 전시되어 있어서 구경하는 재미가 쏠쏠해요. 다사고싶어서 지갑털릴뻔... 한개만 사기로했어요 파충류샵 ''슬로우서울''도 구경이어지게 해둬서 같이 간 가족 친구 연인이랑 말 이어가기 좋아요! 이색적이고 볼거리가 많은 카페로 추천합니다!','2026-10-12T00:00:00.000Z'),
('nr-349','naver-1689752307','naver','샌드위치 든든하개 나와서 좋아요~ 친구랑 같이 수다떨면서 주말에 한끼 해결했습니당 내부에 수족관도 있는데 냄새도 안나고 깨끗하네요ㅎ','2026-10-12T00:00:00.000Z'),
('nr-350','naver-1689752307','naver','거북이랑 도마뱀이 귀엽고 음료가 맛있어여 파충류 좋아하면 꼭 가보세요!','2026-10-12T00:00:00.000Z'),
('nr-351','naver-1605676606','naver','친구 추천으로 와봤는데...들어서자마자 가게 분위기, 퍼지는 달콤고소한 향에 대만족했습니다 ㅠㅠ 동네에 있었으면 매일 왔을거 같아요 일원동 카페, 일원동 케이크 맛집으로 추천해요 그리고 테이블마다 생화있는거 넘 이뻐요 ㅠㅠ 사장님 정성이 느껴지는 카페입니다','2026-10-12T00:00:00.000Z'),
('nr-352','naver-1605676606','naver','개포에서 제일 좋아하는 케이크 집입니다! 🍰🌻학생때부터 놀던 마루공원이랑 대청공원 옆에 있어서 처음 생겼을때도 소꿉친구랑 왔었고,🤼‍♂️🤼‍♀️ 성당에 올때마다도 엄마,아빠한테 찡찡거려서👨‍👩‍👧 포장해갈 정도로 추억이 많은 곳입니다🥹 쑥케이크랑 녹차케이크가 진짜 레전드거든요🎂 밤케이크도 일본 특유의 몽블랑 느낌이 나구🤤 하지만 오늘은 안먹어본 맛들로만 사올거야! 라며 초당 옥수수케이키랑🌽 레몬케이크🍋 티라미수🍰 를 사왔습니다 🌽옥수수케이크 미쳤습니다🫢 안에 옥수수가 슈팅스타 터지듯이 톡톡 터지고..식감도 맛도 미쳤습니다;; 최고최고;; 그리고 티라미수.. 작년 리뷰에 티라미수 제발 만들어주에요 라고 울었는데 오랜만에 가보니 생겼..🥲 (원래 있었는데 품절되서 못 본 것일수도 있음 ㅎ) 티라미수도 존맛탱크리😋','2026-10-12T00:00:00.000Z'),
('nr-353','naver-1605676606','naver','자주오는 단골카페^^ 일찍 와서 커피만 시키고 기다렸다가 케익 한조각 더 시켰어요~~ 깔끔한모닝커피와 달콤한 케이크의 조화가 정말 좋아요 맛있는 커피와 디저트로 행복한 하루 시작합니다^^','2026-10-12T00:00:00.000Z'),
('nr-354','naver-1605676606','naver','신상 무화과 케이크 존맛🥭🥰오늘도 너무 맛있던 썬플라워의 케이크🌻🍰 가게 내부에도 항상 어여쁜 생화들이 있어서 들어가는 순간부터 기분이 좋아집니다🤭🌷 가을한정이라고 들었던것같은 밤케이크!🍁🍂 몽블랑은 아니지만 몽블랑같은 밤케이크와 고구마케이크를 포장해 보았는데, 🌰밤케이크 》 이 날 저희 아빠의 최애는 밤케이크였어요! 밤의 과하지않은 달달함과 폭신~한 크림의 조화감너무 끝내주고, 밤 특유의 고소함이 느껴져서 60대 아부지도 맛나게 드셨어요😋 🍠고구마 케이크 》 동양인들의 특권이라고 매번 느끼는 고구마케이크! 실패없는 맛이죠! 좌석이 적어서 먹고가는건 운세뽑기만큼 어렵지만, 그 작은 소소한 공간이 햇빛과 일원 특유의 아늑함과 평화로움이 느껴져서 포장을 위한 잠깐의 시간조차 기분이 좋아지게 하는것 같아요!','2026-10-12T00:00:00.000Z'),
('nr-355','naver-1605676606','naver','별점이 왜 5개 밖에 없을까요..(별점이 왜 4.5로 표시되는지 이상하네요.^^;;)포근한 느낌이 넘 좋아요! 통창이라 햇살 들어오는 것도 좋구요. 매장에서 모두 직접 만드셔서 그런지 매장에 달콤하고 따뜻한 기운, 냄새가 들어서자마자 기분 좋게 만들어요. 구움 디저트류 생김새도 예쁘고 사장님께서 매장도 아기자기 예쁘게 꾸며놓으셨어요.(쉐프복 입고 계시는거에서 전문성, 위생에 믿음이 갑니다) 그리고 테이블마다 생화 있는 카페는 첨이에요 ㅠㅠ 아침부터 배민기사님들 오시는거보니 맛집인정입니다. ㅎㅎ 이 근방 오신다면 일원동 카페 맛집, 일원동 케이크 맛집으로 추천드려요. 혼자든 둘이서든 언제든 만족하실겁니다! (진심으로요 ㅎㅎ)','2026-10-12T00:00:00.000Z'),
('nr-356','naver-1605676606','naver','지난번에 먹어보고 맛있어서 직접 구매하러 와봤어요~~ 골목에 위치한 일원동 카페맛집! 케이크 맛집!! 케잌 종류도 다양하고 좋네요! 매장도 아담하니 귀엽고 여유로울때 바깥보면서 커피한잔하면 좋을것같아요! 맛있게 먹겠습니다:)','2026-10-12T00:00:00.000Z'),
('nr-357','naver-1605676606','naver','화창한 토요일 오후 외출했다가 귀가하면서 들렸어요 원래 좋아하는 곳이라 주말에 시간날때 가끔 오는 곳이라 들렸는데 리뷰 이벤트 보고 처음 리뷰 올립니다. 저만 알고싶은 일원동 카페 맛집이지만 젊은 여성 사장님 흥하시길 바랍니다!!','2026-10-12T00:00:00.000Z'),
('nr-358','naver-1605676606','naver','일원동 카페맛집, 케이크맛집 찾으면 자주오는 썬플라워베이크샵입니다. 양재에서도 자주가고 사장님이 정말 베이킹 고수셔요. 안에 자리가 많지않아서 자주 만석이에요. 근처 주민들이 정말 애용하는 곳입니다.','2026-10-12T00:00:00.000Z'),
('nr-359','naver-1605676606','naver','사진에서도 바삭바삭함이 느껴지지않나요>_< 스콘 너무 맛있어요!!','2026-10-12T00:00:00.000Z'),
('nr-360','naver-1605676606','naver','스콘이 특히 맛있어요. 연중 무휴 아침 일찍 열어 모닝커피 자주 마시게 되네요^^','2026-10-12T00:00:00.000Z'),
('nr-361','naver-1081873068','naver','주말 점심에 방문했는데 사람엄청 많더라구요.그만큼 인기가많은 강남역카페 썸띵어바웃커피! 말차콜드브루 청귤에이드 맛있고 무화과생크림케이크 딸기버터스콘 넘 맛있어요. 여기 단골집으로 찜해요.','2026-10-12T00:00:00.000Z'),
('nr-362','naver-1081873068','naver','신논현 카페 찾다가 방문한 썸띵 어바웃 커피 ☕️ 말차 초코 라떼랑 무화과 생크림 케이크 주문했는데 조합이 너무 좋았어요! 말차 초코 라떼는 진한 말차의 쌉싸름함에 달달한 초코가 어우러져서 생각보다 많이 달지 않고 부드러웠어요 💚🍫 위에 올라간 초코까지 비주얼도 예뻐서 사진 찍기 좋았어요. 무화과 생크림 케이크는 무화과가 큼직하게 올라가 있고 생크림이 가볍고 부드러워서 부담 없이 먹기 좋았어요 🍰🤍 과일의 은은한 달콤함이 생크림이랑 잘 어울려서 라떼랑 같이 먹으니 딱! 매장 분위기도 밝고 감성적이라 신논현에서 데이트나 카페 타임 즐기기 좋은 곳이에요. 디저트 좋아하시는 분들께 추천하고 싶어요 :) ✨','2026-10-12T00:00:00.000Z'),
('nr-363','naver-1081873068','naver','요 근처 베이커리랑 커피 같이 하는 곳 중에서는 여기가 빵 제일 맛있는 듯.. 흠냐.. 무화과를 치즈케이크 안에까지 넣을 생각을 하시다니 맛잘알🤍 무화과 시즌 끝나기 전에 또 가고싶다,, 근데 다른 케이크들도 다 맛있어보임 ㅠㅠ 근데? 스콘이나 다른 구움과자도 먹어보고싶음 … 아 아른거린다','2026-10-12T00:00:00.000Z'),
('nr-364','naver-1081873068','naver','사람 없는 한가한 날 오면 세 배는 기분 좋은 카페 ❤️ 분위기 맛 비주얼 세 마리 토끼를 붙잡은 카페예요 무화과흑임자치즈케이크를 시켰는데 치즈케이크에 섞인 크런치한 식감, 건무화과의 풍미와 부드럽고 퐁신한 흑임자 크림, 무화과의 조화가 좋았어요','2026-10-12T00:00:00.000Z'),
('nr-365','naver-1081873068','naver','흑임자 무화과 치즈케이크랑 호지슈밀크티 주문해서 먹어봤어요ㅎㅎ 분위기도 좋고 디저트 맛도 좋아서 지인들이랑 같이 놀러오기 좋은 것 같아요 ㅎㅎ 주차는 주변 공용주차장에 주차했습니다. ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-366','naver-1081873068','naver','무화과를 많이 좋아해서 무화과 디저트 찾다가 오게 되었아요-! 무화과 타르트 케이크는 많이 봤는데 흑임자무화과케이크는 첨봐요~ 흑임자도 좋아해서 주문해서 먹어봤는데 조합 괜찮아요! 맛있어요~ 그리고 커피도 너무 맛있네요','2026-10-12T00:00:00.000Z'),
('nr-367','naver-1081873068','naver','오랜만에 조카랑 강남에서 만나 돌아다니다가 눈에 띄어 들어간 카페인데, 생각보다 인테리어가 너무 예뻐서 대만족하고 왔어요! 가게 들어서자마자 감각적인 조명이랑 미니멀하면서도 따뜻한 분위기의 인테리어가 인상적이었어요. 공간이 예쁘다 보니 조카랑 서로 사진 찍어주느라 시간 가는 줄 몰랐네요. 찍는 각도마다 분위기 있게 나와서 ''사진 맛집'' 인증입니다. 📸','2026-10-12T00:00:00.000Z'),
('nr-368','naver-1081873068','naver','공간이 너무 좋아요. 빈티지 엔틱 아늑! 적당한소음속에 작업하고책읽기좋아요 근데 케잌이 가격대비 맛이없었어요 무화과가싱싱한데 맛이없었다는 ㅠ 다음에는베이커리뉴를먹어봐야겠어요. 주말에는사람이많다고하니깐 좀 적을때, 평일이좋을것같아요~','2026-10-12T00:00:00.000Z'),
('nr-369','naver-1081873068','naver','디저트 하나하나가 어찌나 먹음직스럽고 예쁘던지 식사 후 방문햇는데 자리가 없어서 평일인데도 테라스 좌석에 앉아야할 정도로 인기가 많다는걸 실감하고왓네요 다행히 웨이팅은 피할수잇어서 만족스러웟어용 다음에 다른 신메뉴도 꼭 먹어보고싶네요!!','2026-10-12T00:00:00.000Z'),
('nr-370','naver-1081873068','naver','무화과 케익 먹고싶어서 검색해서 들렀어요 잘찾았네요 커피랑 조화도 좋고 아쥬 꿀맛 강남에 디저트가게많은데 여기 딱 정착하려구요 친구만나면 다음에 또 오겠슴다~!!!!','2026-10-12T00:00:00.000Z'),
('nr-371','naver-1041215062','naver','카페 분위기나, 직원분들의 친절함이나, 커피랑 베이커리 맛 모두 다 만족하는 카페입니다 ! 늘 갈 때 마다 기분 좋게 있다 가는 카페에요 정말,,,,, 오늘도 어반누크에서 행복한 시간 보내다 갑니당 ! 나중에 또 방문할게용 ^_^','2026-10-12T00:00:00.000Z'),
('nr-372','naver-1041215062','naver','빵도 다양하고, 우선 장소가 예뻐요. 일찍 오픈해서 화창한 아침햇실을 빋으먀 기분 좋게 갔네요~~ 요즘같은 시기에 더 화사하게 돋보이는 곳 같아요. 어딜 찍어도 어디서 찍어도 인생샷이 나오는 곳~~','2026-10-12T00:00:00.000Z'),
('nr-373','naver-1041215062','naver','매장이 쾌적해요. 커피도 맛있어요. 원두 고를 수 있어 좋아요. 베이커리 류도 다 맛있네요','2026-10-12T00:00:00.000Z'),
('nr-374','naver-1041215062','naver','압구정에서 이렇게 넓은 베이커리카페라뇨! 공간도 여유롭고 빵도 많아서 좋아요 모닝세트랑 샌드위치 먹었는데 맛있네요! 재료의 조화가 너무 좋아요 그리고 커피도 넘 맛있네요!! 다음엔 잠봉뵈르도 먹어보려구요 기대됩니다','2026-10-12T00:00:00.000Z'),
('nr-375','naver-1041215062','naver','빵종류도 많고 예쁜 카페 입니다 처음으로 샌드위치 먹어봤는데 맛있네요~ 가끔 점심에 빵땔길때 들어봐야겠습니다. 혼밥하기도 좋습니다','2026-10-12T00:00:00.000Z'),
('nr-376','naver-1041215062','naver','어반누크 신사점 드디어 왔어요ㅠㅜ 빵 너무 맛있고 매장 깔끔하고 무엇보다 커피가 너무 맛있어요ㅠㅜ쌀소금빵 쫀득해서 맛있어요ㅠ','2026-10-12T00:00:00.000Z'),
('nr-377','naver-1041215062','naver','신사동 분위기 좋은 카페 어반누크 신사점 다녀옴. 내부가 깔끔하면서도 감각적으로 꾸며져 있어 사진도 잘 나오고, 조용히 커피 마시며 쉬기 좋았음. 좌석도 편안한 편이라 대화하거나 잠깐 작업하기에도 괜찮았다. 커피 맛도 무난하게 좋았고 디저트와 함께 즐기니 더 만족스러웠음. 신사역·가로수길 근처에서 여유롭게 머물 카페 찾는다면 한 번 들러볼 만한 곳! #어반누크 #어반누크신사점 #신사동카페 #신사역카페 #가로수길카페 #신사카페 #강남카페 #서울카페 #카페추천 #데이트코스','2026-10-12T00:00:00.000Z'),
('nr-378','naver-1041215062','naver','오늘까지 일주년 이벤트로 소금빵 1+1 이벤트 하고 있어서 맛있는 소금빵을 저렴하게 구매했어요! 바삭하고 쫀득해서 계속 먹게되는 맛이고 맛도 다양해서 정말 좋았습니다. 다른빵들도 다 맛있어 보여서 재방문 의사 100%예요! 직원분들도 너무 친절해요!!!','2026-10-12T00:00:00.000Z'),
('nr-379','naver-1041215062','naver','퀄리티와 분위기가 훌륭합니다~♡','2026-10-12T00:00:00.000Z'),
('nr-380','naver-1041215062','naver','분위기가 너무 좋고 특히 야외 테라스 좌석은 가히 뉴욕에 있는 카페에 견주어도 순색이 없습니다. 직접 내린 착즙 주스도 맛있고 커피 맛 또한 일품입니다.','2026-10-12T00:00:00.000Z'),
('nr-381','naver-1067283876','naver','강남역 디저트 맛집 어퍼앤언더에 친한지인이랑 함께 점심식사를 먹고나서 디저트랑 음료를 먹으러 다녀왔는데 디저트도 다양하고 음료들도 다 너무 맛있었으며 매장 내부도 넓고 깨끗하고 좋은데 손님들도 엄청 많으며 가격도 합리적으로 괜찮아서 다음에 여자친구랑도 방문할려고합니다.','2026-10-12T00:00:00.000Z'),
('nr-382','naver-1067283876','naver','강남역 카페 어퍼앤언더에서 맛있는 음료랑 디저트 즐기고 왔어요! 아인슈페너는 크림이 진하고 쫀득해서 커피랑 합이 너무 좋았고, 쏠티카라멜은 위에 올라간 로투스 과자 찍어 먹으니 단짠 조합이 정말 완벽했어요. 기대했던 무화과 케이크는 푹신한 시트에 생크림이랑 제철 무화과가 듬뿍 올라가서 상큼 달콤하게 즐겼어요. 파이 결이 겹겹이 살아있는 크림브륄레 플랑도 바삭하고 고소해서 완전 취향저격이었어요. 디저트 종류도 다양하고 분위기도 좋아서 다음에도 또 방문하고 싶어요!','2026-10-12T00:00:00.000Z'),
('nr-383','naver-1067283876','naver','편안한분위기도 좋지만 디저트들이 진짜맛있어요.황치즈케이크 , 휘낭시에등등 맛있고 음료도 맛나고 여기 단골로 찜할래요~','2026-10-12T00:00:00.000Z'),
('nr-384','naver-1067283876','naver','매장이 크고 아늑해요 의자가 편하고 카공이나 노트북하기 좋아요 디저트가 다양해서 커피와 즐기기 좋아요 디카페인 커피 있음! 크림브륄레플랑과 아이스 아메리카노, 연하게 한 따뜻한 아메리카노 마셨어요 달달한 디저트랑 커피랑 잘 어울려요 커피는 산미가 적은 편이에요 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-385','naver-1067283876','naver','강남역 쪽에서 분위기 좋은 카페 찾다가 들른 어퍼앤언더. 건물부터 감성 있고 내부도 깔끔해서 사진 찍기 좋았어요. 특히 야외 테라스가 있어서 날씨 좋은 날 앉아 있기 딱 좋더라고요. 디저트도 예쁘게 나오고 음료랑 같이 먹기 좋았어요. 무화과 디저트도 비주얼이 좋고 전체적으로 여유롭게 쉬다 가기 좋은 곳이라 데이트나 친구랑 방문하기 추천해요','2026-10-12T00:00:00.000Z'),
('nr-386','naver-1067283876','naver','지나가다가 분위기가 좋아 보여서 우연히 방문했어요! 디저트도 너무 다양하고 좌석도 많고 3층으로 되어져 있어가지고 여러 명에서 방문하기에도 너무 좋을 것 같아요! 과일디저트랑 황치즈 디저트까지 종류별로 있어서 뭘 먹을지 고민되는 행복한 시간이었어요 🥹 분위기도 좋아서 강추해요!','2026-10-12T00:00:00.000Z'),
('nr-387','naver-1067283876','naver','강남에 이색디저트가 다양한 디저트카페예요! 일요일에 방문했더니 복작복작 자리도 겨우 잡았어요ㅠㅠ 휘낭시에, 까눌레, 마들렌, 바치케 진짜 다양하고 맛도 피스타치오, 옥수수, 소금초코처럼 이색적인 맛들이 많아서 신기했어용👀👀 디저트 좋아하시는 분들이라면 꼬옥 방문해보세용! 🧀황치즈바스크치즈케이크🧀 진짜 꾸덕하고 너무 맛있어요ㅠㅠ 황치즈 향과 맛이 강하고 꾸덕한거 좋아하시는 분들은 무조건 드셔보셔용 🍋레몬케이크🍋 상콤상콤 시트도 부드럽고 크림도 상콤 그자체예용 🍰다양한디저트를 만나보고 싶으시면 어퍼앤언더로 강추드리옵니다🤗','2026-10-12T00:00:00.000Z'),
('nr-388','naver-1067283876','naver','벌써 두번째 방문이에요!! 달달한 초코와 부드러운 바나나 조합이 정말 잘 어울리는 초코 바나나파이였어요 🍫🍌 파이는 바삭하고 속은 촉촉해서 식감도 좋았고, 초콜릿의 진한 맛에 바나나의 은은한 달콤함이 더해져서 부담스럽지 않게 맛있었어요. 커피랑 같이 먹으면 더 잘 어울릴 것 같아요! 디저트로 추천합니다 😊','2026-10-12T00:00:00.000Z'),
('nr-389','naver-1067283876','naver','커피 디저트가 맛있는 카페예요. 커피 가격대가 좀 비싼편이지만 맛있어서 자주 방문합니다. 피스타치오 들은 커피 맛있고, 케익들도 맛있어요. 치즈케익 늘 먹는거고 라스베리 크림 들은 것도 맛있어요. 추천해요.','2026-10-12T00:00:00.000Z'),
('nr-390','naver-1067283876','naver','5번째 방문~ 평일 낮에 방문하기 좋아서 지인들이랑 자주 옵니다 커피도 맛있고 디저트도 굿굿~ 이번엔 무화과 시즌이라 너무 이쁜 무화과 타르트도~ 휘낭시네랑 까눌레 맛집이라 픽! 강남역 오시면 들러보세요!','2026-10-12T00:00:00.000Z'),
('nr-391','naver-996334906','naver','신사역 디저트 맛집 에뚜왈에 맛있는 마들렌 사러 왔습니다. 정말 작은 디저트 가게 인데요. 프랑스 가게에 온것 같은 느낌입니다. 마들렌 상당히 크기가 있고, 가격도착하네요. 다른 인기 디저트 가게 처럼 재고가 금방 소진 되지 않코, 사장님이 열심히 디저트를 만들고 계시네요. 다음에 또 올께요!','2026-10-12T00:00:00.000Z'),
('nr-392','naver-996334906','naver','가로수길 지나가다 신사역 디저트 찾고 있었는데 손에 들고 먹으면서 갈만큼 여유롭고 달달항 기분을 선사해줘요 !! 파리 어느 골목을 지나는 느낌이라 여행 온 기분이에요 ㅎㅎ 디저트 전부 맛있고 마들렌 맛집이라 5개나 샀어요 💛','2026-10-12T00:00:00.000Z'),
('nr-393','naver-996334906','naver','가로수길 마들렌맛집으로 이미 너무 유명한 에뚜왈 ! 마들렌 종류도 다양하고 맛있었습니다. 마들렌이랑 휘낭시에, 퀸아망도 먹어봤는데 여기 빵들 다 맛있더라구요','2026-10-12T00:00:00.000Z'),
('nr-394','naver-996334906','naver','맛있음 마들렌이 두꺼움 인테리어도 예쁨','2026-10-12T00:00:00.000Z'),
('nr-395','naver-996334906','naver','📍가로수길 구움과자 맛집 에뚜왈 오픈때부터 다닌 오랜 ! 구움과자, 마들렌 맛집이예요💘 오랜만에 갔더니 마들렌 종류가 더 다양해졌네요 ! 예전에 레몬, 쇼콜라, 홍차 등을 자주 먹었고 , 이번엔 커피, 애플 시나몬 추가해서 구입했는데 역시 다 맛있네용⭐️⭐️ 배꼽이 통통하고 버터 맛이 진한 마들렌 찐맛집 찾으신다면 에뚜왈 추천합니다💖💖 ✔️~8/31 현백 무역센터점 팝업중','2026-10-12T00:00:00.000Z'),
('nr-396','naver-996334906','naver','역시 오래가는 디저트 맛집은 이유가 있는 것 같아요! 맛도 안변했고 재료도 안아끼고 오랜만에 마들렌 땡겨서 갔는데 정말 맛있어요 마들렌만 드셨던 분들은 마롱타르트 강추드려요 ㅠㅠ 고소하고 존맛임!!','2026-10-12T00:00:00.000Z'),
('nr-397','naver-996334906','naver','마들렌 맛집으로 이미 유명한 곳이라 주기적으로 한번씩 들르는 디저트집에오!🍋 늘 먹던 레몬글라쎄 쇼콜라에, 뺑오쇼콜라까지 같이 포장해서 주말에 집에서 행복한 디저트 파티해쌰오🥐💛','2026-10-12T00:00:00.000Z'),
('nr-398','naver-996334906','naver','에뚜왈 가로수길점🥐 오늘 중요한 약속이 있어서ㅋㅋㅋㅋㅋ 선물로 따끈따끈하게 마들렌 준비했습니닷 에뚜왈 오픈런(12:00)😆🤍 녹차맛이 없어서 아쉬웠지만-!! 나머지 친구들로 만족ㅋㅋㅋㅋㅋ 포장도 너무너무 고급스럽고, 맛도 보장되어있어서 자주 찾게 되네용🤍 늘 감사합니댜👩🏼‍❤️‍💋‍👨🏻 ps. 내돈내산 후기','2026-10-12T00:00:00.000Z'),
('nr-399','naver-996334906','naver','좁고 주차가 마땅치 않다는 어쩔 수 없는 아쉬움. 여성이 계신 곳에 방문할 때 사가면 이쁨받는 맛. 고정적으로 사가는 맛은 얼그레이, 초코 까다로우신 입맛들의 픽을 받은 맛들. 예전엔 재고 없을까봐 조마조마하며 갔는데 다니다보니 인기많은 제품은 그만큼 넉넉히 만들어주셔 큰 걱정없이 갈 수 있다 주말 오후엔 원하는 맛을 넉넉히 살 수 있음','2026-10-12T00:00:00.000Z'),
('nr-400','naver-996334906','naver','2019년부터 꾸준히 가로수길을 지키고 있는 마들렌 맛집.. 사람들이 계속 찾는 데는 이유가 있는 법이죠! 합리적인 가격의 디저트는 고급스러운 맛의 퀄리티는 정말 최고인 듯 👍👍 크로와상도 진짜 맛있으니 꼭 드셔보시고 쿠키류(개인적으로는 갈레트 브루통)도 맛있어요!!','2026-10-12T00:00:00.000Z'),
('nr-401','naver-2051720575','naver','🎄 에브리데이크리스마스 역삼점 ◾ 먹물크런치 4,200원 ◾ 아이스아메리카노 3,500원 층고가 높고 매장도 넓어서 전체적으로 탁 트인 느낌이 좋았고, 외부 좌석까지 마련되어 있어 날씨 좋은 날에는 야외에서 커피를 즐기기에도 좋아 보였어요. 먹물크런치와 아이스아메리카노를 주문했는데 단품 빵 가격도 비교적 저렴한 편이라 부담 없이 고르기 좋았습니다. 특히 빵 5개와 커피 1잔을 테이크아웃하면 9,900원인 레드백 상품도 판매하고 있어 가격적인 메리트가 꽤 크게 느껴졌어요. 방문 당시 사람이 적었는데도 커피 주문이 누락되어 말씀드린 뒤 받을 수 있었던 점은 조금 아쉬웠지만, 역삼 주변에서 넓고 가격 부담 적은 신상 베이커리 카페를 찾는다면 방문해보세요🙂','2026-10-12T00:00:00.000Z'),
('nr-402','naver-2051720575','naver','친구랑 역삼역 근처에 빵집 맛있는데 찾아서 왔어요! 소금빵, 깜빠뉴, 완두앙금빵, 튀김소보로 등등 메뉴가 다양하고 손님이 많아서 회전율 좋아서 늘 빵이 신선해요 ㅎㅎ 저도 자주 사먹고 레드백으로 9900원으로 빵 5개씩 잘 사고 있습니다!','2026-10-12T00:00:00.000Z'),
('nr-403','naver-2051720575','naver','매장은 넓고 밖에 테라스 있어서 시원한 바람 맞으면 대화하고 공부하기 좋을 것 같았어요. 레드뱃 9900원에 저렴하게 빵 5개 구입할 수 있고 커피대신 소금빵으로 변경가능합니다!! 새로 생긴 빵집이라 방문하였는데 다양한 빵 종류가 있어서 좋더라구여 . 맛있으면 앞으로 종종 방문할 계획입니당🤍','2026-10-12T00:00:00.000Z'),
('nr-404','naver-2051720575','naver','새로 생겼다해서 와봤어요 매장도 넓고 야외 테이블도 있고 분위기 너무 좋네요 화장실도 깔끔하니 자주 올 것 같아요 직장인들한테 아주 좋은 카페예요 리뷰이벤트까지 하고 있으니 모두들 오세요🩵🩵','2026-10-12T00:00:00.000Z'),
('nr-405','naver-2051720575','naver','언제나 기분좋은 빵 향기와 맛난 커피 다 좋아요~~ 진짜 매일 크리스마스 같아요~ 번창하세요. 갓 구운빵을 맛볼수 있어서 오늘은 더 행복한 하루가 될수 있을꺼 같아요. 4분 기다린 호두크림치즈빵 넘넘 좋아요~','2026-10-12T00:00:00.000Z'),
('nr-406','naver-2051720575','naver','역삼역 주변 쾌적한 대형 카페. 소금빵 맛집이네요! 매장이 아주 넓고 깔끔합니다. 테이블 간격이 여유있어서 더더욱 좋습니다. 오후 늦은 시간에는 빵이 벌써 다 떨어졌네요. 새로운 인기 장소가 될 것 같습니다.','2026-10-12T00:00:00.000Z'),
('nr-407','naver-2051720575','naver','소금빵 맛집입니다. 소금빵, 후추 소금빵, 명란 소금빵 등이 있어요. 식빵도 다양해요. 야끼모찌처럼 씹는 맛에 집중한 빵도 있고요. 매장이 넓습니다. 테이크아웃(빵 5개+아메리카노나 소금빵) 9,900원 레드백 행사(가오픈 기간 )도 좋고요.','2026-10-12T00:00:00.000Z'),
('nr-408','naver-2051720575','naver','빵들이 종류가 많고 다양해서 좋아요~ 식감도 딱 좋고 안에 필링도 알차게 차 있어서 맛있어요! 매일 오고 싶을 정도로 가성비와 맛을 다 챙겨 주셔서 행복해요ㅠㅠ 직원분들도 방문할 때마다 항상 친절하시고 깔끔하게 관리해 주셔서 좋으셔요! 항상 감사해용~~ 맛있는 빵 만들어 주셔서 덕분에 좋은 날 보내용','2026-10-12T00:00:00.000Z'),
('nr-409','naver-2051720575','naver','레디백 이벤트 (빵 5개+커피) 9,900원 프로모션 중에 이용해봤는데, 빵도 맛있고 가격도 너무 괜찮은 것 같아요! 💗 빵 종류가 다양하고 거의 다 먹어봤는데 맛있었어요ㅎㅎ💗 사실은 맛있어서 한 4번은 이미 방문했던 곳이에요ㅎㅎ 아쉽지만 주차지원은 안되는 것 같네요','2026-10-12T00:00:00.000Z'),
('nr-410','naver-2051720575','naver','역삼역 근처에 있어서 오기도 너무 편하고 매장도 넓어요! 빵 종류도 많아서 고르기 힘들더라구요ㅎㅎ직원분들 모두 친절하시고 레디백 이벤트 가성비 최고인 것 같아요👍 빵이 단순 저렴하기만 한 게 아니라 구매한 거 하나하나 다 맛있음','2026-10-12T00:00:00.000Z'),
('nr-411','naver-1192857924','naver','선정릉카페 중에 최고로 느좋카페 입니다~~ 옥수수크림라떼 미쳤네요 피스타치오도ㅎㅎ 여기 크림 엄청 잘하시네요~~♡ 크림라떼 먹은 곳 중 최고잉 케잌도 미쵸써요ㅜㅜㅜㅜ 여기 저장하구 자주올듯~~!!!','2026-10-12T00:00:00.000Z'),
('nr-412','naver-1192857924','naver','근처에 애견동반이 없어서 왓는데, 좋았어욤! 애견동반 가능한 것만이라도 너무 감사합니다🙏 얼그레이 밀크티도 먹엇는데 너무 맛잇어요-!! 오랜만에 고구마케익도 시켜서 먹엇는데 달달하니 힐링 햇어요🫶🏻 블루베리 베이글까지 완벽햇습니다!','2026-10-12T00:00:00.000Z'),
('nr-413','naver-1192857924','naver','밥먹고 배부른 상태였는데도 고구마 토르테 입안에서 살살녹고 크리미한 식감이 너무 맛있어서 폭풍흡입했어요 ! 시그니처 에이밤 커피도 맛있고, 저녁에 방문했는데 조명이나 인테리어가 너무 예쁘고 한적해서 여유롭게 잘즐기고 갔어요 ㅎㅎ 디저트 종류가 많아서 다음에 또 다른 조각케이크 먹으러 방문할 예정이에요 ~😗💛','2026-10-12T00:00:00.000Z'),
('nr-414','naver-1192857924','naver','얼그레이 밀크티 말차 초코롤 두개 주문했는데 완전 만족 스럽네요 노트북으로 작업 집중해서 하고 편하게 휴식하고 왔어요','2026-10-12T00:00:00.000Z'),
('nr-415','naver-1192857924','naver','와 여기 케이크 맛집이에요 !! 다음에 와서 또 먹어보고 싶은 종류들 한가득이에요 ㅎ.ㅎ 커피도 맛납니당 디카페인도 돼요~!!','2026-10-12T00:00:00.000Z'),
('nr-416','naver-1192857924','naver','크림라떼맛집 발견했어용☕️🤍 고구마케이쿠도 넘 취향저격🍠💛','2026-10-12T00:00:00.000Z'),
('nr-417','naver-1192857924','naver','감각적인 소품과 인테리어, 큰 창으로 들어오는 햇살로 감성 카페 느낌 물씬 나는 선정릉 카페예요! 북적이지 않아 조용하게 대화하기 편했고 시그니쳐 에이밤라떼와 아인슈페너가 고소한 커피 풍미로 정말 맛있어요~~ 얼그레이 케잌도 넘 달지 않아 커피와 잘 어울리더라구요! 사장님도 친절하셔서 감동,,🧡','2026-10-12T00:00:00.000Z'),
('nr-418','naver-1192857924','naver','주변에 일이 있어 왔다가 근처 카페를 찾아 우연히 들렀는데, 인테리어도 깔끔&세련되고 남편과 함께 대화하기 좋았어요 음료와 디저트도 굿! 담엔 솔드아웃된 맘모스빵 먹어보고 싶어요','2026-10-12T00:00:00.000Z'),
('nr-419','naver-1192857924','naver','에이밤커피와 녹차딸가라떼 번을 주문했는데 에이밤커피는 시그니처 커피답게 엄청 맛있엇구요 ㅎㅎ 녹차딸기라떼도 달달하니 취향저격이었어요 ㅎㅎ 번에는 크림 가득 들어있어서 커피와 너무 잘 어울렸어요 ㅎㅎ 너무 잘 먹고 갑니다!!','2026-10-12T00:00:00.000Z'),
('nr-420','naver-1192857924','naver','인테리어가 진짜 너무 좋아요 제가 사진을 잘 못찍는 편인데도 그냥 막 찍어도 이정도 진짜 인테리어에 신경 많이 쓰신 것 같고 카페가 조용하니 참 좋았어요 작은 카페이긴 한데 통창으로 개방감을 줘서 답답하지않아요 커피류도 달달하니 커피를 잘 못먹는 저에게도 너무 맛있었습니다 그리고 사장님이신지 직원분이신지 모르겠지만 너무 친절하고 너무 예뻐요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-421','naver-1040454016','naver','어머니가 매장에서 아모르 드시고 너무 맛있다를 여러번 연발하셨던게 기억나서 생신 케이크로 홀케이크 주문했어요. 미리 예쁘게 준비해주신 사장님 덕분에 행복하고 맛있는 기념일이었어요. 포장도 어찌나 꼼꼼하고 깔끔하게 해주시는지 매번 포장때마다 감탄해요! 그리고 워낙 휘낭시에 맛집이라 케이크 픽업갔다가 참지 못하고 제가 먹을 것도 포장해왔어요. 휘낭시에랑 티그레 추천합니다...❤️ 완전 완전 완전 추천이요! 초코 티그레 엄청 좋아했는데, 쑥 티그레 덜 단거 좋아하는 전 너무 맛있네요.','2026-10-12T00:00:00.000Z'),
('nr-422','naver-1040454016','naver','동생과 언니랑 오랜만에 만나서 저녁먹고 맛있는 디저트 카페 찾다가 후기 좋아서 왔는데 잘온 것 같아요 커피도 맛있고 디저트도 맛있고 친절하셔서 좋은시간 보냈어요','2026-10-12T00:00:00.000Z'),
('nr-423','naver-1040454016','naver','삼성서울병원 병문안 위해 케잌, 휘낭시에, 커피 구입하였습니다. 입원한 친구가 라떼가 아주 맛있대요~! 휘낭시에는 많이 안달고 바삭쫀득 맛있더라구요~! 전반적으로 디저트가 고급진 느낌이에요 병원내 카페가 한정적이어서 삼성서울병원 병문안시 바로앞이라 사들고가기 좋은거 같아요~!~! 포장도 깔끔히 잘해주시거든요🤓','2026-10-12T00:00:00.000Z'),
('nr-424','naver-1040454016','naver','디저트 졸아하는 딸아이가 부탁해서 사왔어요. 일원동 주택가에 클래식하게 있는 디저트 맛집입니다. 모양이 예쁘고 퀄리티가 남달라요. 재료도 좋은것 같아요. 크림도 텁텁함 없이 부드럽고 깔끔하고 말차케잌도 진한 말차맛이 인상깊어요. 휘낭시에도 찐든한게 맛있어요. 고급스러운 맛입니다. 특히 달지 않은게 너무 좋은데, 달지 않게 깊은 맛을 내고 재료가 밸런스가 좋아요. 추천해요','2026-10-12T00:00:00.000Z'),
('nr-425','naver-1040454016','naver','엔뚜디아♡ 언니네 동네 놀러오면 늘 꼭 들러서 밥보다 더먹고 가는 카페에요! 디저트는 다른데서 보지못한 예쁘고 맛있는!!! 디저트들이 너무 많아서 눈과 입이 호강해요😍😍 예술공간안에 카페가 있는 느낌으로 카페가 너무 고급스럽고 느낌있어요♡ 저는 여기오면 핫한성수동 부럽지 않아요😘 커피도 맛있어서 늦은시간인데도 우리 자매들은 카페인섭취 해버렸습니다! 오늘도 맛있는 커피와 디저트로 행복한 시간 보내다 옵니다♡','2026-10-12T00:00:00.000Z'),
('nr-426','naver-1040454016','naver','엄마랑 병원 왔다가 들렀는데 디저트 하나같이 다 예쁘고 음료도 맛있어요… 글고 휘낭시에 진짜 맛있으니까 꼭 드시길 ㅠㅠㅠ 공간도 깔끔해서 더 좋았어요 어른 입맛에도 맛있다고 보기에도 예쁘다고 하셔서 어른들 모시고 와도 좋을 듯용','2026-10-12T00:00:00.000Z'),
('nr-427','naver-1040454016','naver','일원동 디저트, 커피 맛집 카페 엔뚜디아. 조용한 분위기에서 맛있는 라떠와 휘낭시에로 힐링할 수 있는 곳이에요. 사장님도 친절하셔서 단골될 것 같아요.','2026-10-12T00:00:00.000Z'),
('nr-428','naver-1040454016','naver','일원동 최고의 디저트 카페예요. 집에서 제과제빵을 취미로하고있다보니 밖에서 케이크나 구움과자 사먹는게 아까운편인데 엔뚜디아는 차원이 다르게 맛있어서 자주 오게되는것같아요~ 바닐라와 사과의 조합이 이렇게 맛있는줄 몰랐어요...! 여러분 만자나 베르데 꼭 드셔보세요~ 두번드세요!!! 강추합니다🍎','2026-10-12T00:00:00.000Z'),
('nr-429','naver-1040454016','naver','디저트 좋아하시면 꼭 들러야할곳...! 한남동이나 성수 홍대까지 가지않아도 일원동에서 이런 고급스러운 디저트를 먹을수 있어서 행복해요~ 한달전에 들러서 포장해왔던 사진인데 리뷰쓰다보니 또 가고싶네요🥰','2026-10-12T00:00:00.000Z'),
('nr-430','naver-1040454016','naver','구석구석 예쁘고 아늑해요🫶🏻 그리고 유명한 카페 다녀봐도 너무 달기만 하거나 다 거기서 거기인 메뉴들이 지겨웠었는데 여기는 너무 달지 않으면서 새로운 메뉴들 도전해봐도 맛있어요. 동네에 이런 카페가 있다니 주민으로서 증말 만족','2026-10-12T00:00:00.000Z'),
('nr-431','naver-2058195307','naver','강남구청역 부근 핫한 카페가 있다고 해서 방문한 울루루 카페에요. 세련된 인테리어에 센스 넘치는 소품들로 가득했어요. 강남 한복판에서 나무와 수풀이 가득한 뷰로 커피를 마실 수 있는 공간이 있어서 편안하게 쉬었다 갔네요. 진하고 균형이 잘 잡힌 라떼에 달지 않고 마시면 건강해질 것 같은 딥그린 스무디도 너무 맛있었어요. 무엇보다 디저트를 매장에서 직접 만든다고 하는데 비주얼도 그렇고 맛있어서 하나씩 다 먹어보고 싶었습니다. 다음에 또 놀러올게요. 번창하세요!! ㅎ','2026-10-12T00:00:00.000Z'),
('nr-432','naver-2058195307','naver','지나가다가 들른 울루루~☺️✨ 이름이 너무 귀여워서 들르게 됐는데, 매장도 넘 이쁘고 사장님이 되게 감각적으로 꾸며놓으셨네요! 🌿🌿 날씨 좋은 날 바깥을 보면서 커피를 즐길 수 있구, 시그니처 커피도 넘넘 마싯어요! ㅎㅎ🤍 논현동 쪽 오시면 한번 들러보세요~ 🫶🏻🫶🏻','2026-10-12T00:00:00.000Z'),
('nr-433','naver-2058195307','naver','커피가 맛있고 장소도 넓고 너무 좋아요! 회사 점심시간에 가끔 오는데 항상 만족하고 돌아갑니다🤍 오늘은 브런치 먹었는데 브런치도 맛있네요💓 통창도 열려서 풍경도 볼 수 있고 넘 예뻐요!! 다음에 재방문 하겠습니다(내돈내산임!)','2026-10-12T00:00:00.000Z'),
('nr-434','naver-2058195307','naver','근처 운동 올 때마다 눈에 띄는 이곳이 궁금했는데, 드디어 오늘 와봤어요! 단백질 쉐이크 음료가 있어 운동 후 가벼운 점심으로 와서 먹기 좋고… 저는 오늘 베리 단쉑 시켰는데 너무 맛이 있는 게 대체당인지 진짜 당인지 물어봐야겠어요😂 다이어트 생각하고 왔는데 빵 냄새가 너무 좋아서 뭐 시켜 먹어야 하나 싶고, 혼자 와서 노트북 키고 업무하기도 매우 좋아요! 점심 시간 지나니 사람 다 빠지고 조용해서 좋습니다. 캘리포니아의 동네 카페에 온 기분이 들어요 :)','2026-10-12T00:00:00.000Z'),
('nr-435','naver-2058195307','naver','통창 너머로 초록초록한 뷰 보면서 여유 부리기 딱 좋은 곳이에요!🌿 우드 앤 콘크리트 인테리어도 너무 감각적이고, 차분한 음악 들으면서 커피랑 브런치 플레이트 먹으니 절로 힐링되네요. 혼자 노트북 하거나 책 읽으러 오기에도 정말 좋아요. 재방문 의사 100%입니다!✨','2026-10-12T00:00:00.000Z'),
('nr-436','naver-2058195307','naver','커피가 너무 맛있어요 ㅎㅎㅎㅎ 걷다가 분위기가 너무 좋아서 들어왔는데 커피도 맛있고 빵도 완전 맛있어요! 다음에 커피 생각나면 재방문 할게요~ 감사합니다 🙏','2026-10-12T00:00:00.000Z'),
('nr-437','naver-2058195307','naver','벌써 4~5번이나 방문한 카페예요.😊 통창 너머로 푸른 나무가 가득 보여 강남 한복판이라는 게 믿기지 않을 정도로 힐링되는 공간입니다. 마치 숲속에 와 있는 것 같은 분위기에서 커피 한잔하기 정말 좋아요. 커피도 맛있고 베이커리도 맛있어서 갈 때마다 함께 먹게 되네요. 조용히 쉬면서 여유를 즐기기 좋은 카페라 앞으로도 자주 방문할 것 같습니다.','2026-10-12T00:00:00.000Z'),
('nr-438','naver-2058195307','naver','창밖으로 펼쳐지는 뷰가 정말 예뻐서 들어가자마자 기분이 좋아졌어요ㅎㅎ 탁 트인 전망 덕분에 커피 마시면서 멍때리기 딱 좋았고, 공간도 여유롭고 분위기가 편안해서 오래 머물고 싶더라고요. 음료도 깔끔하고 맛있어서 뷰와 함께 제대로 힐링하고 왔습니다♡ 날씨 좋은 날 방문하면 더 예쁠 것 같아요 ⁽ ¨̮⁾⁽¨̮ ⁾*˚‧♡','2026-10-12T00:00:00.000Z'),
('nr-439','naver-2058195307','naver','공간이 차분하고 편안해서 조용히 힐링하기 딱 좋았습니다. 커피도 탄 맛이나 텁텁함 없이 깔끔하고 고소해서 맛있게 마셨어요. 디저트를 매장에서 직접 만드시는 것 같아서 같이 주문해 봤는데, 확실히 퀄리티가 좋고 커피랑 잘 어울립니다. 직원분들도 부담스럽지 않게 친절하게 응대해 주셔서 머무는 동안 편했습니다. 근처 오면 울루루 커피는 또 생각날 것 같아요. 잘 쉬다 갑니다!','2026-10-12T00:00:00.000Z'),
('nr-440','naver-2058195307','naver','왜 누를게 5개밖에 없는거에요 커피가 맛있어요 디저트가 맛있어요 음악이 좋아요 친절해요 주차하기 편해요 말고도 더 누르도 싶은데ㅠㅠㅠ 입장하기 전부터 빵냄새가 너무 고소해서 행복해요 커피도 너무 맛있고 주차도 소파도 편해요🤍🤍 시간이 붕떠서 우연히 온 곳에서 너무 친절하셔서 행복해요','2026-10-12T00:00:00.000Z'),
('nr-441','naver-1372135556','naver','아사이볼이 먹고싶은데 가성비 좋아보여서 일부러 찾아왔어요! 카톡친구 2천원 할인쿠폰도 있고 영수증리뷰 휘낭시에 증정도 있어서 넘 좋아요~~','2026-10-12T00:00:00.000Z'),
('nr-442','naver-1372135556','naver','친구들이랑 주말에 방문하였습니다. 조용하고 커피가 향도 좋고 맛있어요 디저트도 정말 맛있어요 좌석간격도 맘에들어요','2026-10-12T00:00:00.000Z'),
('nr-443','naver-1372135556','naver','후기가 좋아서 휘낭시에랑 쿠키 사러왔어용!💞 집근처라 좋으네요 히히 어제 미리 전화로 여쭤봤었는데 저녁에 여자분이 친절하게 알려주셔서 좋았고 오늘도 방문해서 포장까지 여자분이 또 친절하셨어용! 웨딩촬영용 간식으로 플래너님이랑 친구 줄건데 같이 맛나게 먹어볼게요✨🌷','2026-10-12T00:00:00.000Z'),
('nr-444','naver-1372135556','naver','원두도 집에서 내려먹었는데 맛있어요~💕 휘낭시에도 커피랑 잘어울림😍','2026-10-12T00:00:00.000Z'),
('nr-445','naver-1372135556','naver','코엑스 놀러왔다가 지인이랑 와봤어요 커피도 깔끔하고 분위기 너무 좋아요💕','2026-10-12T00:00:00.000Z'),
('nr-446','naver-1372135556','naver','우연히 들어온 카페인데 양도 많고 커피도 진짜 고소해요 산미잇는거안좋아해서 좋습니다 인테리어도 서윗','2026-10-12T00:00:00.000Z'),
('nr-447','naver-1372135556','naver','휘낭시에 빠쟉👍🏻👍🏻 다음엔 유기능 오트 우유 라떼 먹을거에요 ><','2026-10-12T00:00:00.000Z'),
('nr-448','naver-1372135556','naver','맛있고 카페도 넓고 좋아요! 회사 점심때 왔는데 또 오고싶은 카페입니다!!❤️','2026-10-12T00:00:00.000Z'),
('nr-449','naver-1372135556','naver','회사 직원 추천으로 와봤는데 카페 넓고 좋아용','2026-10-12T00:00:00.000Z'),
('nr-450','naver-1372135556','naver','조용하고 분위기 좋아요! 주변 너무 시끄러워서 힐링하러 왔어요! 커피도 맛있습니다!!','2026-10-12T00:00:00.000Z'),
('nr-451','naver-1840772401','naver','점심회식으로 삼계탕 먹고 후식으로 커피 마시려고 다녀 갑니다. 다행이 자리가 하나 남아서 겨우 앉았네요. 가성비 좋고 대화하기 좋아요. 오늘 대화 주제는 피서철 답게 부산 워터밤 다녀온 얘기랑 속초 휴가 다녀온 얘기, 그리고 피그마 상장 이야기가 주요 주제였는데 재미있게 대화할 수 있는 분위기라 좋네요.','2026-10-12T00:00:00.000Z'),
