INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-21001','naver-33586177','naver','일단 주문 후 음식을 받는데 1시간 가까이 걸렸습니다. 그리고 배달주문을 홀보다 우선시하는 모습이 보였는데 여기까진 그냥 넘어갔습니다. 그런데 밥이 다 떨어졌다고 하길래 음식을 먼저 먹고 30분을 기다린 후 밥을 받겠다고 배려했더니 알바생 분이 임의적으로 늦게 주문한 다른 테이블 먼저 밥을 주더군요 ㅎ 이런 상황이 어이가 없고 반복되지 않았으면 합니다. 리뷰에 직원이 친절하다는데 딱히 친절한 건 잘 모르겠고 알바생 교육 다시 하시길 바랍니다 음식은 맛있었습니다','2026-10-12T00:00:00.000Z'),
('nr-21002','naver-33586177','naver','와 씨 열라 짜증나네요 파추가 1000윈이래서 추가했더니 네가닥 강남이라 물가가 비싼가 한가닥만 더 달랬더니 직영점이라 본사에서 더달라면 안된다고 했다네 직영점 맞나? 절대 뭐 추가히지마세요 주는대로 잡수셔들','2026-10-12T00:00:00.000Z'),
('nr-21003','naver-33586177','naver','가끔 생각나는 중독적인 매운맛이에요! 오리지널은 정말 매운데도 자꾸 손이 가요. 매울수록 더 끌리는, 특유의 쫄깃한 떡과 마늘 진한 양념이 완벽한 조합이에요. 중독적인 맛','2026-10-12T00:00:00.000Z'),
('nr-21004','naver-33586177','naver','엽떡은 사회 스트레스를 날려주는 맛 👍🏻 맵찔이에겐 착한맛이 조아요 ☺️','2026-10-12T00:00:00.000Z'),
('nr-21005','naver-33586177','naver','불금이면 엽떡을 자주 떠올리는 아이가 밤에 학원 끝나고 야식으로 먹고 싶어해서 끝나는 시간에 맞춰 포장해왔어요~ 현충일이기도 해서 혹시 일찍 끝날까봐 미리 낮에 매장에 라스트 오더 시간 문의 드리고 다녀왔습니다! 최근에 기본 스타일만 먹다가 로제 분모자를 먹으니, 원래 맛도 있는데 더 맛있게 먹었어요! 친절하게 챙겨주시고 서비스로 쿨피스랑 단무지도 챙겨주셨어요! 정말 꿀맛으로 맛있는 음식 덕분에 스트레스도 싹 가시는 맛이였습니다!','2026-10-12T00:00:00.000Z'),
('nr-21006','naver-33586177','naver','엽기 닭볶음탕 착한맛 적당한 매콤한게 넘 맛있어요 일주에 한번씩 닭요리먹고 싶을때 꼭 건강식으로 강추합니다^^ 푹익은 감자와 떡볶이도 들어있고 약간 매콤한 닭 한마리 양도 많아서 굿 ^^ 자꾸 손가는맛 강추해요!!','2026-10-12T00:00:00.000Z'),
('nr-21007','naver-33586177','naver','사장님이 친절하시고 떡볶이도 맛있음','2026-10-12T00:00:00.000Z'),
('nr-21008','naver-33586177','naver','5명 모임에 닭볶음탕, 마라로제떡볶기 착한맛 넘 맛있게 먹었어요 매울때 계란찜 한입 먹으면서 배부르게 먹었어요 마지막에 디저트로 야채튀김을 끝으로 먹었어요 강추합니다','2026-10-12T00:00:00.000Z'),
('nr-21009','naver-33586177','naver','진짜 오랜만에 매장에서 엽떡에 소맥 먹었더니 행복 그 자체.. 압구정직영점 짱짱','2026-10-12T00:00:00.000Z'),
('nr-21010','naver-33586177','naver','마라엽떡에 짝궁은 꿔바로우 달달한 복숭아 쥬시쿨 얼음은 필수 매움을 가셔주는 단무지 일주일 노고를 덜어주는 맛 내가 이러려고 일을 하네 ☺️ 국물이 많아서 양배추 썰어서 먹으면 더 맛있어요.','2026-10-12T00:00:00.000Z'),
('nr-21011','naver-2073263172','naver','돼지, 순대국밥에 우동면이 들어간건 처음봤는데 넘 색다르고 맛있어요..💕 같이 나오는 밥도 셀프바에 밥통이 있어서 무한리필이라 엄청 배불렀어요!! 남자친구랑 2인세트로 먹었는데 수육도 같이 나와서 가성비 좋은거같아용 🫶 웨이팅 맛집이라는데 이른점심에 가도 사람 진짜 많더라고여 근데 매장이 워낙 넓고 단체석도 많아서 쾌적했어요!!','2026-10-12T00:00:00.000Z'),
('nr-21012','naver-2073263172','naver','국밥이 맛있었고 사이드와 곁들여 먹고 만족스러운 식사였어요 매장 분위기도 쾌적해서 다음번에 논현동 근처에 오면 다시 방문하고 싶은 의사 있어요 연중무휴여서 언제나 편하게 방문하기도 좋구요 사장님도 친절하게 대해주셔서 정말 감사했어요 부모님 모시고 오기도 좋을 것 같아요 합리적인 가격에 맛있는 국을 먹을수 있는 논현동 맛집 "동동국밥 논현점" 방문해 보시길 추천합니다.','2026-10-12T00:00:00.000Z'),
('nr-21013','naver-2073263172','naver','ღ''ᴗ''ღ 좋아요. 주변 볼일 있어 지나가다가 몇번 봤었던 동동국밥. 새로 오픈도 했고해서 방문 했어요. 우동돼지국밥 11,000 원 얼큰우동순대국밥 12,000 원 김치는 양배추김치인데 오.. 약간 매콤한데 맛있었어요. 국밥. 순대국 다 평소 먹어본 맛은 아니고 특이하면서 맛있었어요. 특히 우동 ! 우동이 잘 어울릴까 했는데 쫄깃하고 맛났어요. 고기에서 냄새도 안나고 깍두기도 너무 맛있었어요. AVEC EK.','2026-10-12T00:00:00.000Z'),
('nr-21014','naver-2073263172','naver','동동국밥 논현점에서 2인세트로 우동돼지국밥, 우동순대국밥, 수육까지 든든하게 맛봤다. 오픈한 매장이라 전체적으로 깔끔하고 밝은 분위기라 편안하게 식사하기 좋았고, 논현동에서 접근성 좋은 국밥집이라 혼밥은 물론 함께 식사하기에도 부담이 없었다. 특히 논현역에서 1~2분 거리! 영동시장, 자생한방병원 등의 근거리에 있어 뚝딱 한그릇 이용에 최고다! 부산에 안가도 동동국밥의 부드러운 돼지고기와 탱글탱글 쫄깃한 우동면을 맛볼수 있어 좋고, 인상적이었다. 우동돼지국밥은 담백하면서도 면을 함께 먹는 재미가 있었고, 우동순대국밥 역시 익숙한 순대국에 쫄깃한 우동면이 더해져 색다른 매력이 느껴졌다. 사이드로 주문한 수육도 부드러워 국밥과 잘 어울렸다. 논현동에서 색다른 국밥을 찾는다면 꼭 한번 들러볼 만한 곳이다🎵🎶','2026-10-12T00:00:00.000Z'),
('nr-21015','naver-2073263172','naver','칼국수도 국밥도 좋아하는 1인으로, 동동국밥 눈여겨 보고 있었는데 드디어 회사 근처 논현에 생겨서 퇴근길에 혼밥했는데 넘 깔끔하고 푸짐해요 !! 리뷰 작성하면 맛보기 순대 주는데 순대가 진짜 맛있어요 ㅠㅠㅠ 김치도 실비인지 매콤한데 아주 잘 어울리고 국밥은 약간칼칼 시원 해요 (생강?) 우동이 아주 키포인트 여기에 밥까지 말아먹으면 배터져요 ㅎㅎㅎ 혼밥 하기 편하게 바테이블도 있고 핸드폰 거치대도 있어서 유튜브보면서 혼밥 하기 편해요 !!!','2026-10-12T00:00:00.000Z'),
('nr-21016','naver-2073263172','naver','웨이팅이 있다고 들어서 오후1시에 방문햇습니다. 10분에서 15분정도 기다린거 같아요! 우동면도 맛잇고, 양도 적당하고, 밥은 무한리필이라 좋았습니다 재방문의사 100% 다음에 또 방문해서 얼큰으러 맛보아야겠습니다.','2026-10-12T00:00:00.000Z'),
('nr-21017','naver-2073263172','naver','동동국밥 논현점에서 매콤갈비찜에 우동사리를 추가해 둘이 먹었어요. 갈비 양이 은근 넉넉해서 둘이 먹기 좋았고, 우동면도 양념과 따로 놀지 않고 보들보들하게 어우러졌어요. 맵기는 평소 먹는 엽떡 초보맛보다 약간 더 맵게 느껴졌습니다. 밥은 무한 리필이라 남은 양념에 원하는 만큼 넣어 직접 볶아 먹었어요. 내부가 넓고 24시간 영업해서 늦은 시간 식사하기에도 좋겠어요. (업체로부터 식사권을 제공받아 직접 체험 후 작성한 리뷰입니다.)','2026-10-12T00:00:00.000Z'),
('nr-21018','naver-2073263172','naver','김치가 정말 맛있어요! 국밥도 깔끔하고 담백해서 부담 없이 먹기 좋았습니다. 우동면이 들어 있는 것도 색다르고 생각보다 잘 어울려서 인상적이었어요. 순대 꼭 드세요!! 새로 오픈한 매장이라 전체적으로 깔끔하고 분위기도 좋고, 직원분들도 친절해서 기분 좋게 식사하고 왔습니다. 다음에 또 방문하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-21019','naver-2073263172','naver','새로 생겨서 와보고 싶었는데 연휴 맞이로 가족이랑 이번에 방문했어요! 매장도 넓고 청결하고 쾌적해서 너무 좋네요 음식도 맛깔스럽고 우동면 들어간게 신기해요!김치도 너무 맛있어요ㅎㅎ 셀프빠 이용도 좋아요 !','2026-10-12T00:00:00.000Z'),
('nr-21020','naver-2073263172','naver','테이블 간격이 넓고 쾌적합니다. 날씨가 선선한데 문을 열어놓아 좋았습니다. 국밥집임에도 노래가 힙해 좋았습니다. 얼큰국밥의 경우, 첫맛이 꽤 맵다라고 느껴집니다. 전체적으로 맛은 깔끔합니다. 개인적으로 수육을 간장과 먹는 것을 좋아하는 데, 간장이 없어 아쉬웠습니다. 전체적으로 괜찮은 업장입니다. 감사합니다.','2026-10-12T00:00:00.000Z'),
('nr-21021','naver-1697208386','naver','삼성동 근처에서 아직도 여기를 모른채 그냥 지나치셨다면 정말 후회하실 겁니다. 강남 3대 방어 맛집으로 유명한 곳인데 집나간 며느리도 돌아온다는 가을별미자 고소하면서 오도독한 식감의 전어회, 촉촉하고 부드러운 속살의 전어구이, 새콤 달콤 매콤한 전어무침까지 맛볼 수 있습니다. 게다가 삼성동 인근에서 먹기 힘든 팔딱팔딱 싱싱한 생새우회가 먹기 좋게 손질되어 나오고 한 입 물면 톡 터지는 탱글한 식감의 생새우 소금구이로도 즐길 수 있으니깐 꼭 드셔보세요. 삼성동 근처에서 단체모임이나 데이트 장소로 방문하기 완전 딱 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-21022','naver-1697208386','naver','회도 신선하고 두툼해서 식감이 정말 좋았어요! 튀김도 바삭하고 종류가 다양해서 이것저것 먹는 재미가 있네요. 콘치즈랑 기본 반찬도 잘 나오고 전체적으로 음식이 깔끔해서 만족했습니다. 양도 푸짐해서 배부르게 잘 먹었어요 :) 다음에 또 방문하고 싶어요!','2026-10-12T00:00:00.000Z'),
('nr-21023','naver-1697208386','naver','가을맞이 전어 먹구 싶어서 예약하고 왔는데 너무 맛있어요 ~ 매장도 넓고 깔끔해서 데이트하기 좋아요 ! 사이드로 안키모김밥 있어서 주문해봤는데 잘 어울려용 🤤 삼성역 근처에서 횟집 찾으시면 추천드립니당','2026-10-12T00:00:00.000Z'),
('nr-21024','naver-1697208386','naver','고등어회 먹으러 제주도 가려다가 동어동락으로 왔습니다. 고소하고 맛있어요. 고등어회 못먹는 분들을 위해 모듬회와 새우튀김 주문하고 해물칼국수로 마무리 하였습니다. 사케가 가격이 좋아요. 맛있게 잘 먹었습니다.','2026-10-12T00:00:00.000Z'),
('nr-21025','naver-1697208386','naver','회가먹고싶어서 네이버에 찾아보니 리뷰가 좋아서 오게됬는데 웨이팅은한10분정도 한거같아요 회 잡내도 없고 스끼다시도 너무 잘나오고 맛있어서 오기잘한거같아요 진찌 손님 많아요ㅋㅋㅋㅋ 음식들이 너무맛있고 술도 다양해서 만족스럽게 먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-21026','naver-1697208386','naver','여기 회먹고싶을때마다 자주오는 곳인데 맛있어요 일욜 오니 평일보단 좀 한가해서 좋긴하네요 회 튀김 매운탕 다 맛있어요 강추해요','2026-10-12T00:00:00.000Z'),
('nr-21027','naver-1697208386','naver','순살전어가 있어요! 세꼬시 싫어하이거나 뼈때문에 전어 궁금해도 못드셨던분들 강추입니다! 꼬소하니 너무 맛있고 고등어도 비린맛제로! 신선 그자체! 매장이 넓고 쾌적합니다!','2026-10-12T00:00:00.000Z'),
('nr-21028','naver-1697208386','naver','고등어회도 비리지 않고 고소하니 너무 맛있고 튀김도 너무 맛있습니다!!! 회+튀김+매운탕 세트가 있어서 좋네요! 술 종류도 엄청 다양합니다~','2026-10-12T00:00:00.000Z'),
('nr-21029','naver-1697208386','naver','삼성역에서 이렇게 신선한 횟집을 만날 줄은 몰랐네요. 생새우회를 좋아해서 방문했는데 기대 이상이었습니다✨️✨️ 생새우회는 살이 오동통하고 달큰해서 전혀 비리지 않았고, 초장은 물론 김+묵은지+무순, 소금김밥+묵은지 등 다양한 조합으로 먹는 재미가 있었습니다. 머리구이까지 알차게 나와 만족! 가장 인상 깊었던 건 참어락세트였습니다. 참치, 단새우, 우니 등 하나하나 신선해서 여러 가지를 한 번에 즐기기 좋았어요. 특히 참다랑어는 기름진 부위가 잘 나와 정말 맛있게 먹었습니다. 묵은지소금김밥은 꼭 추가해서 같이 드셔보세요. 생새우 올려 먹으면 정말 최고의 조합입니다🫶🫶🫶 잘먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-21030','naver-1697208386','naver','회가 정말 신선하고 맛있었어요! 😊 전체적으로 음식도 깔끔하고 맛있어서 만족스러웠고, 직원분들도 친절하게 응대해주셔서 기분 좋게 먹고 왔습니다. 신선한 회 먹고 싶을 때 다시 방문하고 싶은 곳이에요! 👍','2026-10-12T00:00:00.000Z'),
('nr-21031','naver-1606942616','naver','생새우랑 전어 먹으러 왔어요. 저녁 6시 워킹으로는 못 오네요ㅎㅎ 예약해서 편하게 들어왔는데 이미 만석이라, 동어동락 인기에 한번 더 깜짝 놀랐답니다;; 꼬들꼬들 생새우 엄청 신선하구요, 가을 전어회도 진짜 맛있어요..... 저만의 시그니쳐(?)메뉴인 안키모 소금김밥으로 마무리하면 힐링끝이네요~! 완전 추천합니다!!!!','2026-10-12T00:00:00.000Z'),
('nr-21032','naver-1606942616','naver','강남 3대 방어 맛집으로 유명한 동어동락에서 역대급 신메뉴가 출시했습니다. 프리미엄 해산물들이 총집합한 참어락은 오도로, 단새우, 우니, 관자, 이꾸라, 샤인머스캣 구성으로 나오는데 감태에 다양한 조합으로 싸먹으면 해산물 파티 그 자체입니다. 그리고 삼성동 인근에서 아마 이곳에서만 먹을 수 있는 팔딱팔딱 생새우회도 꼭 주문해야할 메뉴입니다. 한 입 물면 톡 터지는 탱글한 식감의 생새우 소금구이로도 즐길 수 있으니깐 참고해주세요. 삼성동 근처에서 단체모임이나 데이트 장소로 방문하시면 센스있다는 소리 들으실 겁니다.','2026-10-12T00:00:00.000Z'),
('nr-21033','naver-1606942616','naver','가을이 왔어요~동어동락에서 오부장이랑 가을 전어회랑 새우소금구이 먹었어요. 전어가 아직 어려서 뼈도 안씹히고 연해서 먹기 좋았어요. 새우도 완전 싱싱 새우가 수족관 안에 있는 건 처음 봐요 살아있는 새우가 팔딱팔딱 아주 달달하고 맛있었어요. 동어동락은 언제나 매장이 만석이네요. 예약 필수예요','2026-10-12T00:00:00.000Z'),
('nr-21034','naver-1606942616','naver','가을 맞이 제철 해산물 달리러 예약하고 다녀왔어요! 🍂🐟 9월엔 무조건 전어회랑 깐 생새우회 먹어줘야 하는 거 아시죠? 전어회는 기름기 좔좔 흘러서 씹을수록 고소함 폭발하고, 생새우회는 살이 완전 탱글탱글 달달해요 🦐 버터에 바삭하게 구워 나온 새우 머리 튀김까지 진짜 꼬숩고 갓벽…✨ 신메뉴 안키모 소금김밥도 시켜봤는데, 담백짭짤 김밥에 녹진한 안키모랑 묵은지+와사비 얹어 먹으니 입안 가득 감칠맛 대잔치예요 🍣 상큼한 청귤사와랑 시원한 기린 생맥주 곁들이니까 술이 술술 들어가는 맛! 분위기도 너무 좋고 재료 신선도 최고라 데이트 코스로 완전 대만족이에요 🫧 조만간 또 방문할게요 💖','2026-10-12T00:00:00.000Z'),
('nr-21035','naver-1606942616','naver','삼성역맛집으로 유명한 <동어동락>에서 제철 생새우회를 제대로 즐기고 왔다. 수조에서 바로 잡은 싱싱한 새우를 깔끔하게 손질해 내어주니 껍질 벗길 필요 없이 편하게 먹을 수 있었고, 탱글한 식감에 씹을수록 은은한 단맛까지 제대로! 너무 맛있어서 결국 생새우회는 한 번 더 추가 주문했다. 함께 주문한 참어락set 역시 다양한 제철회를 푸짐하게 즐길 수 있었고, 감태에 싸 먹으니 또 다른 별미였다. 신선한 해산물에 맥주까지 곁들이니 완벽했던 곳으로, 강남에서 생새우회 맛집을 찾는다면 추천하고 싶은 동어동락 삼성본점.','2026-10-12T00:00:00.000Z'),
('nr-21036','naver-1606942616','naver','늦은시간까지 영업해 부담없이 즐길수 있는 장소입니다. 통영삼베체굴 하나만 먹어도 배부르네요. 토마토사와와 페어링하니 술이 쭉쭉 들어갑니다. 횟감이 신선하고 매운탕 안에 살이 넉넉해 발라 먹기 바빴습니다.','2026-10-12T00:00:00.000Z'),
('nr-21037','naver-1606942616','naver','생새우 좋아한다면 여기서는 몸통만 먹고 끝내면 섭섭해요 깐 생새우회는 탱글하면서 은근히 달았고 머리는 버터에 바삭하게 튀겨줘서 한 접시로 두 가지 메뉴를 먹는 기분이었어요 참어락SET은 참다랑어와 우니 단새우 관자 연어알을 감태에 내 마음대로 조합해 먹는 재미가 있었어요 샤인머스켓까지 올리니 짭짤 고소 달콤 조합도 꽤 잘 맞더라고요 산토리 생맥주는 새우 머리와 하이볼은 참어락SET과 찰떡 🍺 다음에는 활고등어회까지 노려봅니다 🦐😋','2026-10-12T00:00:00.000Z'),
('nr-21038','naver-1606942616','naver','퇴근 후 노동주에 전어회 먹었습니다!! 리뷰가 좋아서 방문했는데 진짜 신선해요. 친절하시구요. 다음에는 고등어회 먹으러 올게요!','2026-10-12T00:00:00.000Z'),
('nr-21039','naver-1606942616','naver','삼성역 전어맛집 🐟 일요일 오후 5:30분 미리 예약해서 방문했고 점차 손님들이 와서 자리가 찼습니다 회 빠르게 나오고 구성도 좋습니다 전어도 맛있지만 고등어도 짱 맛있습니다👍','2026-10-12T00:00:00.000Z'),
('nr-21040','naver-1606942616','naver','전어회 확실히 기름이 올라서 참 맛있어요 … 구이 회 무침 3개 세트로 나오는데 가성비가 너무 좋아용. 매운탕도 만원. .. 무조건 또 올게요','2026-10-12T00:00:00.000Z'),
('nr-21041','naver-1087970189','naver','여기는 정말 자주 방문하는 단골 맛집이에요! 😊 올 때마다 느끼지만 고기 질이 정말 좋아서 언제 먹어도 만족스럽고, 고기 본연의 맛도 훌륭해요. 반찬도 하나하나 정갈하게 잘 나와서 고기랑 곁들여 먹기 좋고, 사장님과 직원분들도 항상 친절하게 응대해 주셔서 기분 좋게 식사할 수 있어요. 무엇보다 고기를 맛있게 직접 구워주셔서 가장 맛있는 상태로 편하게 먹을 수 있다는 점이 정말 좋습니다! 고기부터 반찬, 서비스까지 어느 하나 아쉬운 점이 없는 곳이에요. 앞으로도 삼겹살 생각날 때마다 꾸준히 방문할 것 같아요. 맛있게 잘 먹었습니다! 👍','2026-10-12T00:00:00.000Z'),
('nr-21042','naver-1087970189','naver','너무너무 먹고 싶어서 큰맘먹고 왔어요. 웨이팅 시간 피해서 왔지만 우리뒤로 웨이팅 럭키비키 진짜 너무너무 맛있어요. 강남 삼겹살 넘버1티어 맛집 트러플 치즈복음밥도 꼭 필수 먹어야하는곳 재방문 의사 1000%','2026-10-12T00:00:00.000Z'),
('nr-21043','naver-1087970189','naver','전부터 와보고싶었는데 드디어 와보네요~~806은아쉽게품절이라 506이랑목살 육회먹었는데 다 넘맛있었어요~~고기다구워주시고 고기가두툼해서 식감도좋았어요~~왜 유명한지알겠네요~~^^','2026-10-12T00:00:00.000Z'),
('nr-21044','naver-1087970189','naver','첫방문. 고기 질도 좋고 반찬 깔끔하니 맛있어요~ 직접 구워주셔서 좋아요. 매장도 넓고 쾌적해서 더 만족했어요','2026-10-12T00:00:00.000Z'),
('nr-21045','naver-1087970189','naver','고기 질이 진짜 좋고 잡내 없이 깔끔해서 맛있게 먹었어요! 직원분이 고기도 잘 구워주셔서 편하게 먹을 수 있었고, 육즙도 살아있고 부드러워서 만족스러웠습니다ㅎㅎ 분위기도 깔끔하고 너무 시끄럽지 않아서 데이트나 모임으로 오기 좋을 것 같아요. 곁들여 먹는 메뉴들도 고기랑 잘 어울리고 전체적으로 음식 퀄리티가 좋아서 기분 좋게 식사했어요! 돼지고기 제대로 먹고 싶을 때 또 방문하고 싶은 곳입니다 :)','2026-10-12T00:00:00.000Z'),
('nr-21046','naver-1087970189','naver','진짜 고기질부터 반찬까지 맛도리 집입니다. 더군다나 너무 친절하고 매장도 청결해서 만족도 120프로입니다! 역삼오면 꼭 한번 들려보세요!!','2026-10-12T00:00:00.000Z'),
('nr-21047','naver-1087970189','naver','역삼역 맛집으로 유명한 돝고기 506! 506은 숙성시간을 말해주는건데 숙성을 오래 거쳐서 확실히 맛이 진하면서 독특한 유제품 같은 맛이 납니다. 근데 그게 전혀 거북스럽지않고 고기에 풍미를 더해줘서 좋았어요! 함께 나온 찬들이 정갈하고 밥과 함께 하기도 좋아서 마음에 들었습니다. 아이도 와서 즐길수 있는 파스타 샐러드 반찬이 좋았고 계란찜도 오코노미야키처럼 감칠맛 넘치는 가다랑어와 소스가 더해져서 맛있었어요!','2026-10-12T00:00:00.000Z'),
('nr-21048','naver-1087970189','naver','돝고기 506 기념일을 맞이하여 방문하였는데 고기의 육즙과 밑반찬들도 다 너무 맛있어요♡ 직접 다 구워주셔서 편하게 맛있게 먹을 수 있어요ㅎㅎ 참지 못하고 육회도 시켜버렸어요ㅎㅎ 기념일 혹은 특별한 모임시 강추예요!♡','2026-10-12T00:00:00.000Z'),
('nr-21049','naver-1087970189','naver','오늘은 가볍게 회식겸 룸으로 방문 했습니다 여전히 맛있었고 특히 크림볶음밥은 꼭 주문해 드세요!','2026-10-12T00:00:00.000Z'),
('nr-21050','naver-1087970189','naver','고기도 너무 맛있고 사이드도 맛있습니다 806이랑 트러플 볶음밥은 필수입니다!!','2026-10-12T00:00:00.000Z'),
('nr-21051','naver-1218830542','naver','세 명이서 저녁 먹으러 방문했어요! 고기가 두툼하고 상태도 좋아서 구웠을 때 육즙이 살아있고 맛있었어요. 삼겹살은 겉은 노릇하고 안은 촉촉해서 만족스러웠고 같이 곁들여 먹을 반찬들도 잘 나와서 느끼하지 않게 끝까지 맛있게 먹었습니다. 매장도 깔끔하고 직원분들도 친절해서 편하게 식사했어요. 세 명 모두 만족하면서 배부르게 먹었고 신논현에서 삼겹살 먹고 싶을 때 다시 방문할 것 같아요 특제소스가 참 맛있습니다','2026-10-12T00:00:00.000Z'),
('nr-21052','naver-1218830542','naver','신논현역 강남역 모임은 고민도 없이 돼봉 예약할거같아요 잡내 전혀 없고 구워주시고 너무 맛있습니다 여름시즌이라 묵사발도 서비스로 나오고 좋네요 야채 상태가 좋아요~','2026-10-12T00:00:00.000Z'),
('nr-21053','naver-1218830542','naver','아이들과 인근에 호캉스 왔다가 식사하러 들렀어요^^ 분위기도 시끌벅적해도 유쾌하게 좋아서 아이들도 불편함 없이 맛있게 즐겼답니다. 무엇보다 고기가 구워져 제공되서 가족들끼리 오기도 참 좋네요^^ 다음에도 또 방문할께요^^','2026-10-12T00:00:00.000Z'),
('nr-21054','naver-1218830542','naver','친구들이랑 방문했는데 고기 양도 많고 종류도 다양해서 너무 맛있게 먹었어요! 고기도 잡내 없이 부드럽고 같이 나온 김치랑 야채랑 먹으니까 조합이 좋았습니다 😋 양도 푸짐해서 친구들이랑 배부르게 먹었고 신논현에서 고기 먹을 때 또 방문하고 싶어요! 👍','2026-10-12T00:00:00.000Z'),
('nr-21055','naver-1218830542','naver','뭐먹을까 돌아다니다가 비가 갑자기 쏟아져서 그냥 들어왔는데 맛집이네요ㅎㅎㅎㅎ 고기 너무 맛았고 구워져서 나와서 너무 편했어요','2026-10-12T00:00:00.000Z'),
('nr-21056','naver-1218830542','naver','첨와봤는대 넘 맛있어요!! 첨앤 고기가 왤케 안나오지 했는데 다 구워서 나와서 편리하고, 모둠엔 구성이 좋아서 다양하게 잘 먹엇네여 모임하기 좋아요~~~!!','2026-10-12T00:00:00.000Z'),
('nr-21057','naver-1218830542','naver','올때마다 만족하고 가는 돼봉삼겹살 입니다! 늘 느끼는건데 양도 많고 맛은 당연히 너무 맛있어요! 직원분들도 친절하셔서 기분 좋은 식사 했습니다.','2026-10-12T00:00:00.000Z'),
('nr-21058','naver-1218830542','naver','정말 너무 맛있어요! 구워져서 나와서 너무 편하고 맛있습니당 저번에는 1층 자리가 없어서 지하로 방문했는데 1층은 문이 열려있어서 좋네요!! 직원분들도 너무 친절하십니다 또 방문할게요~','2026-10-12T00:00:00.000Z'),
('nr-21059','naver-1218830542','naver','삼겹살 먹고 싶어서 방문했는데 고기 질도 좋고 잡내 없이 너무 맛있었어요! 🥹 두툼한데 질기지 않고 육즙도 제대로라 오랜만에 삼겹살 진짜 맛있게 먹었네요ㅎㅎ 밑반찬도 깔끔하게 잘 나오고 고기랑 같이 먹을 게 많아서 좋았어요. 직원분들도 친절하시고 매장도 깔끔해서 기분 좋게 먹고 왔습니다 :) 삼겹살 생각날 때 또 방문할 것 같아요! 재방문 의사 있어요 👍🏻','2026-10-12T00:00:00.000Z'),
('nr-21060','naver-1218830542','naver','고기도 너무 맛있고 직원분들 너무 친절하시고좋아요!!! 메뉴도 다양하고 디저트까지 다양해서 이용하기 좋더라고요! 내부도 깔끔해서 자주 방문하게 될 것 같아요!','2026-10-12T00:00:00.000Z'),
('nr-21061','naver-619673845','naver','두꺼운고기가 윤기좔좔에 맛있게구워서 미나리까얹어먹으니 세상에 이런맛이...ㅎ 기본찬도 잘나오는데 맛깔스런 오징어젖갈부터 칼칼한된장까지 취향저격이라는...우렁된장에 쌈밥까지해먹으니 저세상행복이네요...매장이 너무 커서 놀랐는데 서비스까지 어찌나 친절하신지 다시가고싶은곳이네요~~~내장소저장','2026-10-12T00:00:00.000Z'),
('nr-21062','naver-619673845','naver','역삼역 인근에서 두툼하고 육즙 가득한 삼겹살을 찾는다면 두껍쌈 역삼직영점이 답입니다! 대표 메뉴인 숙성삼겹살은 두껍게 구워져 겉은 바삭하고 속은 육즙으로 가득 채워져 씹을 때마다 고소함이 제대로 터집니다. 전문 그릴러분이 적정 온도에서 딱 알맞게 구워주셔서 편하게 최상의 맛을 즐길 수 있어 만족스러웠습니다. 함께 주문한 계란찜은 폭신폭신한 부드러운 식감에 간이 딱 맞아 자칫 기름질 수 있는 고기 맛을 깔끔하게 잡아주는 최고의 사이드 메뉴였습니다. 매장 내부도 깔끔하고 테이블 간격이 넓어 쾌적한 환경에서 식사할 수 있었습니다. 친절한 서비스와 뛰어난 고기 질 덕분에 기분 좋게 식사를 마무리했습니다. 역삼동에서 실패 없는 삼겹살 맛집을 찾으시는 분들께 적극 추천합니다!','2026-10-12T00:00:00.000Z'),
('nr-21063','naver-619673845','naver','백미삼으로 먹었는데 고기질도 좋고 고기도 잘 구워주시고 무엇보다 정말 친절해요! 그리고 고기 환풍구도 불판에 있어서 ㅋㅋ상대방과 시야방해도 없고요 옷에 냄새배임도 적더라고 진짜신기 쾌적하고 굿굿 주말엔 콜키지프리도된다네요 강추강추','2026-10-12T00:00:00.000Z'),
('nr-21064','naver-619673845','naver','미나리 삼겹살 최고입니다 고기 진짜 부드럽고 너무 맛있어요 ^^ 사랑입니다 그라고 장소가 프라이빗하기 반 가림막이 있어서 편하게 식사 가능한것 같아요 회삭장소로도 추천입니다 ^^','2026-10-12T00:00:00.000Z'),
('nr-21065','naver-619673845','naver','인생삼겹살을 만나고 싶다면 강추합니다. 주차장 넓고 매장은 더 넓고 직원분이 구워주시고 잘라주시니 모임, 회식하기 좋고 일단 맛있습니다.','2026-10-12T00:00:00.000Z'),
('nr-21066','naver-619673845','naver','두껍삼 역삼직영점에서 맛있게 잘 먹고 왔어요🥰 고기도 두툼하고 육즙이 가득해서 정말 맛있었고 직원분들이 직접 구워주셔서 편하게 먹을 수 있어서 좋았어요! 특히 반찬들도 하나하나 너무 맛있어서 고기랑 같이 먹으니 더 맛있더라구요ㅎㅎ 전체적으로 음식도 깔끔하고 만족스러워서 역삼에서 고기 먹고 싶을 때 또 방문하고 싶은 곳이에요❤️ 감사합니다 :)','2026-10-12T00:00:00.000Z'),
('nr-21067','naver-619673845','naver','강남에 이정도 대형으로 고기먹기 좋은곳 , 냄새 안배는곳 찾기가 어려운데 나올때까지 상쾌하고 고기도 너무 맛있고 하나하나 손 댈 것 없이 다 잘라주셔서 너무 편하고 맛있게 먹고갑니다!🧡🤤🤍','2026-10-12T00:00:00.000Z'),
('nr-21068','naver-619673845','naver','처음 와봤는데 고기 넘넘 맛있고 직원분이 정말 친절하세요~~~중딩 아이들도 맛있다고 잘 먹네요. 매장 깔끔하고 테이블마다 무선충전기도 있어 완전 편리합니다~~~~^^','2026-10-12T00:00:00.000Z'),
('nr-21069','naver-619673845','naver','불판 온도까지 하나하나 체크하면서 고기 구워주는 곳은 처음이었네요 ㅎㅎ 덕분인지 숙성 삼겹살이 겉은 노릇하고 속은 촉촉해서 정말 맛있게 먹었습니다! 미나리랑 백김치를 같이 구워 먹으니까 생각보다 훨씬 잘 어울리더라고요. 조합이 진짜 좋았어요👍 내부 넓고 분위기도 좋구, 직접 구울 필요가 없어서 더 편하게 먹었습니다. 다음에는 가족들이랑 한 번 더 오고 싶네요!','2026-10-12T00:00:00.000Z'),
('nr-21070','naver-619673845','naver','회사 점심먹으러 가끔 오는데 점심메뉴도 좋지만 삼겹살 진짜 맛있어요!! 그리고 직원분들 친절합니다 .','2026-10-12T00:00:00.000Z'),
('nr-21071','naver-1581949803','naver','재료 신선하고 종류도 많고 튀김도 바삭하고 두끼 매장 중에서는 퀄리티 젤 좋은듯 직원분들도 친절하고 엄청 빠릿빠릿(?)하게 교육도 잘 받은 것 같음 여기는 올때마다 최고임','2026-10-12T00:00:00.000Z'),
('nr-21072','naver-1581949803','naver','강남역점이 제일 종류도 다양하고 퀄리티도 좋은것 같아요! 사람도 많이 와서 튀김도 자주 바뀌고 따뜻해서 좋았어요🩷','2026-10-12T00:00:00.000Z'),
('nr-21073','naver-1581949803','naver','매장이 넓고 깨끗합니다. 재료들의 퀄리티도 좋게 유지되고 있고 맛있습니다. 가성비 있게 여러 메뉴를 즐길 수 있어서 좋아요.','2026-10-12T00:00:00.000Z'),
('nr-21074','naver-1581949803','naver','떡볶이 좋아하면 최고의 식당입니다.ㅎㅎ 맛있는 떡볶이 양껏 다양한 맛대로 골라서 먹을 수 있어서 좋아요. 직원분들도 친절하셔서 행복한 식사시간 보냈습니다.','2026-10-12T00:00:00.000Z'),
('nr-21075','naver-1581949803','naver','매장이 잘 관리되어있고 맛있어요!','2026-10-12T00:00:00.000Z'),
('nr-21076','naver-1581949803','naver','방학이라 아이들이랑 방문했는데 아이들한테는 완전 천국이네요 👍🏻 평일 낮이라 쾌적하게 먹고 저는 마라로제 만들어 먹을 수 있어 행복하네요💕','2026-10-12T00:00:00.000Z'),
('nr-21077','naver-1581949803','naver','무한리필인데 가격도 저렴하고 맛있어요!! 밥도 맛있구 좋습니다! 부담없이 오기 좋고 매장도 넓어요ㅎㅎ 또 방문하고 싶네요','2026-10-12T00:00:00.000Z'),
('nr-21078','naver-1581949803','naver','제가 가본 두끼중에 제일 깔끔하게 관리되고 있는거 같아요~ 1인석 자리도 있고 아주 만족하고 갑니당🤤','2026-10-12T00:00:00.000Z'),
('nr-21079','naver-1581949803','naver','매장 깨끗하고 직원분들도 다 친절하세요! 다른지점보다 관리가 더 잘되어있는느낌이에요 다음에도 방문하겠습니다 😊','2026-10-12T00:00:00.000Z'),
('nr-21080','naver-1581949803','naver','매장이 넓고 재료들이 전부다 신선하고 깔끔하게 되어 있어요! 혼자 앉아서 먹을 자리가 있어서 다음에는 혼자 오려구요!','2026-10-12T00:00:00.000Z'),
('nr-21081','naver-1976639573','naver','강남역 고기집 찾다가 방문한 워낙 유명한 곳이길래 들렸어요 강남역에서 접근성도 좋아서 모임이나 회식 장소로 오기 괜찮았어요 땅코는 역시 목살이 유명한 이유가 있네요 두툼한 목살인데도 퍽퍽하지 않고 촉촉하면서 육즙이 살아있어서 정말 맛있었어요 삼겹살도 고소하고 참숯에 구워 먹으니 풍미가 확실히 좋았습니다 직원분이 고기를 직접 구워주셔서 굽는 정도 신경 쓰지 않고 편하게 먹을 수 있는 것도 장점이에요 같이 나오는 비지찌개도 고기 먹다가 곁들이기 좋고 조합이 잘 맞았어요 강남역 목살 맛집이나 강남역 삼겹살 맛집 찾는 분들, 친구들과 저녁 식사나 강남역 회식 장소 찾는 분들에게 추천하고 싶은 곳이에요 다음에 강남역에서 고기 먹을 때 또 방문하고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-21082','naver-1976639573','naver','고기 진짜 맛있게 먹고 왔어요!! 특히 목살이 진짜 맛있었어요🥹 두툼하게 나와서 기대했는데 먹어보니까 육즙도 많고 부드러워서 너무 맛있더라구요. 직원분이 고기도 직접 구워주셔서 편하게 먹을 수 있었어요! 굽기도 딱 맛있게 해주시고 먹기 좋게 잘라주셔서 저희는 그냥 맛있게 먹기만 하면 돼서 좋았어요ㅋㅋㅋ 목살은 소금에 찍어 먹어도 맛있고 쌈 싸서 먹어도 맛있어서 계속 손이 갔어요. 같이 구운 마늘이랑 먹으니까 더 맛있더라구요 🤤 그리고 전투라면도 같이 시켰는데 고기 먹으면서 얼큰하게 먹기 좋았어요! 서비스로 주신 비지찌개도 맛있어서 고기랑 같이 먹으니까 잘 어울렸어요ㅎㅎ 다만 화장실은 안가보시는게...','2026-10-12T00:00:00.000Z'),
('nr-21083','naver-1976639573','naver','고기가 두툼하고 큼직하게 나와서 먹음직스러웠어요. 🔥 숯불에 구우니까 겉은 노릇하게 익고 고기 식감도 좋았습니다. 먹기 좋게 잘라서 구워 먹으니 계속 손이 가더라고요. 마늘이랑 새송이버섯 같이 구워 먹는 것도 잘 어울리고, 뜨끈한 찌개까지 곁들이니 조합이 좋았어요. 고기 먹고 싶을 때 편하게 다시 방문하기 좋은 곳인 것 같습니다. 👍','2026-10-12T00:00:00.000Z'),
('nr-21084','naver-1976639573','naver','1인분에200그램 양도 많구요 직접구워주어 좋아요 기본찬이랑 비지찌개 나오구요 노포분위기로 즐기기좋은곳입니다~ 콩나물무침 데워서 먹는것도 좋았어요','2026-10-12T00:00:00.000Z'),
('nr-21085','naver-1976639573','naver','고기 진짜 맛있게 먹고 왔어요🥹 삼겹살은 고소하고 육즙도 좋았고, 목살은 퍽퍽하지 않고 부드러워서 특히 맛있었어요! 고기 자체가 맛있어서 소금에만 찍어 먹어도 맛있고, 김치랑 같이 구워 먹으니까 조합도 최고였어요. 사이드 메뉴까지 같이 먹으니까 배부르게 잘 먹고 왔습니다ㅎㅎ 삼겹살이나 목살 먹고 싶을 때 재방문하고 싶은 곳이에요👍','2026-10-12T00:00:00.000Z'),
('nr-21086','naver-1976639573','naver','대학 동기들이랑 모임하고 저녁 먹을 곳 찾다가 리뷰가 좋아서 바로 예약하고 방문했습니다! 삼겹살은 말해뭐해~ 목살도 부드러워서 맛있었습니다 갈메기살은 약간 꼬돌꼬돌한 맛이 좋았어요! 고기도 직원분들이 직접 구워주셔서 먹기 편했습니다! 아 그리고 저는 냉면을 먹었지만 라면을 시키면 반합에 끓여주더라구요? 다음에 방문하면 먹어봐야겠어요! 저녁 시간대에는 사람 많으니까 예약하는걸 추천!','2026-10-12T00:00:00.000Z'),
('nr-21087','naver-1976639573','naver','목살 맛집으로 유명한 땅코 !!! 다른 지점에서 먹어도 맛이 똑같아서 좋습니다 ! 목살이 퍽퍽하지 않고 부드러워서 아주 맛있어요 다 구워주시니 편리하니 좋습니다 👍👍','2026-10-12T00:00:00.000Z'),
('nr-21088','naver-1976639573','naver','고기맛남 ㅋ 강추 ㅋ 강남역에서 가본 고긱집 중에 상타치이다 그리고 돼지고기집인데도 구워주시는 서비스가 있다 와유 서비스로 주는 콩비지 찌게도 맛나다 고기구워주는 직원분도 친절하심 (숭실대 다니는 베트남분이라 하셨는데 귀엽고 친절하심 😍) 재방문 의사 있음 ㅋ 👍','2026-10-12T00:00:00.000Z'),
('nr-21089','naver-1976639573','naver','역시 너무 맛있어요 ! 특히 서비스로 나오는 찌개 너무 맛있어서 밥한공기 뚝딱햇어용 또올게요💗','2026-10-12T00:00:00.000Z'),
('nr-21090','naver-1976639573','naver','목살 진짜 맛있게 먹고 왔어요! 🥩 고기도 두툼하고 육즙이 살아 있어서 씹을수록 고소하고 맛있었어요. 잡내도 없고 고기 질이 좋아서 만족스러웠습니다. 같이 먹는 반찬이랑 곁들임도 잘 어울리고, 직원분들도 친절해서 기분 좋게 식사했어요. 목살 좋아하시는 분들은 한 번쯤 방문해보셔도 좋을 것 같아요! 다음에 또 방문하고 싶어요 😊','2026-10-12T00:00:00.000Z'),
