INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-26001','naver-1053426823','naver','작년 12월에 이사와서 주마다 한번씩 가고있어요. 맛나용.','2026-10-12T00:00:00.000Z'),
('nr-26002','naver-1053426823','naver','우리가 기대하는 중국요리의 정석. 그리고- 또 하나 패밀리 비지니스의 정석. 즐겨 다니는 식당. 그 이상의 반가움 한스쿱! 작은 요리 한그릇에 배불리 먹고도 포장까지 쌉 가능. 이러니 20여분 거리를 마다않고 걸어서 재방문..','2026-10-12T00:00:00.000Z'),
('nr-26003','naver-1053426823','naver','맛있어요','2026-10-12T00:00:00.000Z'),
('nr-26004','naver-2085617851','naver','동네 산책하다가 발견하고 방문했습니다 분위기도 아기자기하고 친절하신데 음식도 맛있습니다 향신료 잘 못드시는 분들도 잘 드실 거 같고 잘 드리는 분들이라면 고수뿌리 준비되어 있어서 넣어서 드리면 될 거 같아요 셀프바도 잘 되어있고 면,숙주도 무한리필이라 좋아요 :)','2026-10-12T00:00:00.000Z'),
('nr-26005','naver-2085617851','naver','쌀국수 전문 매장에서 처음먹어봐요! 너무 맛있네요 깔끔하고 저는 매운맛이 좋네요 :) 다음번에는 신메뉴 곱창 들은거 먹어보려구요 저희 아이들이 너무 좋아할 것 같아서 다섯가족 함께 방문할게요 :)','2026-10-12T00:00:00.000Z'),
('nr-26006','naver-2085617851','naver','아이들과 점심 먹으려고 나왔는데 예약없이 갔지만 바로 들어갔어요~어른2명과 초등1명,유아1명 4인가족입니다~소고기쌀국수1소곱창쌀국수1,우삼겹볶음밥1,반미1 시켰는데 양도 많고 너무 푸짐하더라고요~ 아이들도 너무 잘 먹고 사장님께서 큰애가( 코코넛음료 맛있겠다)하는 소리를 들으시고 서비스로 챙겨 주셨어요ㅠㅠ 너무 감사합니다^^아이도 잘 먹었습니다~ 다음에 또 오고 싶네요ㅎㅎ 리뷰 남겨주시면 저렇게 짜조랑 새우튀김도 주셔요!!!! 맛있어요^^다들 놀러오세요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-26007','naver-2085617851','naver','정말 든든하고 기분 좋은 식사를 하고 왔어요! 🥢 이번에 불고기 분짜와 매콤한 통통새우쌀국수를 주문해 봤어요. 불고기 분짜는 달짝지근한 불고기에 신선한 채소를 곁들여 새콤달콤한 소스와 함께 먹으니 입맛이 확 돌더라고요. 함께 시킨 매콤한 통통새우쌀국수는 이름 그대로 통통한 새우가 아낌없이 들어가 있고, 국물이 기분 좋게 얼큰해서 분짜와의 조합이 최고였어요. 🦐 무엇보다 두 메뉴 모두 그릇 가득 양이 정말 푸짐해서 깜짝 놀랐답니다. 맛도 훌륭한데 인심까지 넉넉해서 배부르게 싹싹 비우고 왔어요. 천호동에서 든든하고 맛있는 베트남 음식 찾으실 때 꼭 한번 방문해 보세요! 단골 맛집이 될 것 같아요.','2026-10-12T00:00:00.000Z'),
('nr-26008','naver-2085617851','naver','우연히 발견한 보석같은 곳입니다. 곱창 쌀국수 처음 먹어보는데 칼칼하고 매콤한 것이 한국인 입맛에 딱 맞고 같이 간 베트남 친구도 아주 맛있게 잘 먹었습니다. 고수 대신 미나리가 들어있어서 고수 싫어 하시는 분들도 잘 먹을 수 있고 고수도 따로 구비되어 있어서 고수러버들도 취향껏 넣어서 먹을 수 있는 선택의 폭이 넓은 곳입니다.','2026-10-12T00:00:00.000Z'),
('nr-26009','naver-2085617851','naver','천호왔다가: 쌀국수 맛집을. 찾던 중 오게되었어요 원체 쌀국수를 좋아하는 지라 기대하고 왔습니다 건물은 노후하나 내부는 청결하네요 리필코너도 정갈하구요 우선 가성비가 좋습니다 육수 고수 등 리필이 자유롭고 테이블 키오스크에서 리필 요청할 수 있도록 되어있네요 기본 소스들은 리필코너에서 가져올 수 있구요 맥주도 저렴하게 맛있게 먹었습니다 단 국물이 깔끔해서 진한맛은 나지않는 점이 아쉽습니다 매운 소스도 덜맵고요 ^^ 친절하고 잘 먹고갑니다','2026-10-12T00:00:00.000Z'),
('nr-26010','naver-2085617851','naver','새우쌀국수는 국물이 깔끔하면서도 매콤해서 좋았어요😊 분짜는 새콤달콤한 소스에 고기랑 면을 같이 먹으니까 좋더라구용! 야채도 신선했어요!!! 반미는 바삭한 빵에 속재료가 알차게 들어 있어요!! 개인적으로 빵이 진짜 취저🥹 직원분들도 친절하시고 매장도 깨끗해요!!','2026-10-12T00:00:00.000Z'),
('nr-26011','naver-2085617851','naver','천호역 5번출구 먹자골목에 위치 향신료 향이 강하지 않아서 쌀국수가 담백하고 맛있어요! 총총 썰은 미나리가 들어가서 국물에서 은은하게 미나리 향이 나요! 면, 숙주 리필 가능한데요. 드셔보고 하세요~ 양 진짜 많아요! 셀프바에서 소스, 청양고추, 양파절이 자유롭게 가져다 먹으니 편하고 좋아요','2026-10-12T00:00:00.000Z'),
('nr-26012','naver-2085617851','naver','소곱창 쌀국수를 진짜 좋아해서 여러군데서 시켜먹어봤는데 오늘 여기서 이 소곱창 쌀국수를 먹은 이후로 최애 쌀국수집이 바뀌었습니다 곱창이 작거나 곱이 별로 없는 쌀국수집들이 많았는데 여긴 곱창도 크고 안에 곱도 가득 차있어서 매콤한 국물이랑 먹으니까 그냥 너무 행복해지는 맛이었어요 진짜 너무너무 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-26013','naver-2085617851','naver','지나가다 들렀어요! 평점대로 너무 맛있고 깔끔하고 직원분도 친절하세요.. 요즘 고수 다 돈받고 찔끔주는데 여긴 고수 맘대로 먹을 수 있어서 너무너무 행복했아요.. 음식 퀄도 너무 좋고 또 생각날 것 같아요 다음에 또 올게요!','2026-10-12T00:00:00.000Z'),
('nr-26014','naver-1587144487','naver','성내동에 토종 닭으로 구워 먹는 숯불 닭구이 사계 숯불구이집!! 우연히 박세리 윤남노 방송으로 보게되었는데 실망하지는 않겠지란 마음으로 먹어보고 맛과 고기의 질에 깜짝 놀라서 후기 남겨요 닭안창살 새로운 맛이고 소금 간장 모두모두 맛있어요 골고루 드셔보시는거 추천합니다','2026-10-12T00:00:00.000Z'),
('nr-26015','naver-1587144487','naver','윤남노님 유튜브 보고 왔습니다! 근처 살지만 이런 맛집이 있는 줄 몰랐는데, 남노님 유튜브를 통해 알게되서 정말 기쁩니다💗 닭갈비는 말해뭐해 정말 맛있고, 공휴일 5시쯤 도착했는데, 웨이팅 없이 입장했습니다! 그리고 무엇보다 술이 술술 들어가요~!','2026-10-12T00:00:00.000Z'),
('nr-26016','naver-1587144487','naver','다이어트 중인데 닭고기는 몸에 좋다고 해서 찾아온 닭구이 전문점 입니다! 고기가 엄청 부드럽고 소금, 간장 하나씩 먹었는데 감칠맛이 좋아요…! 다른 고기 대비 지방 함량도 낮고, 고기도 부드러워서 자주 찾아올 것 같습니다! 🤍','2026-10-12T00:00:00.000Z'),
('nr-26017','naver-1587144487','naver','아주 담백하고 깔끔한 맛이예요! 갖은 반찬도 들큰하지 않고 맛깔지구요. 치킨집은 많아두 이렇게 숯불구이집 잘 없는데 좋은집 알아서 자주 올 것 같아요. 사장님 친절하셔서 더 기분좋게 먹었습니다!','2026-10-12T00:00:00.000Z'),
('nr-26018','naver-1587144487','naver','이번주 월요일에 처음 왔는데, 너무 맛있어서 수요일인 오늘 또 왔습니다! 진짜 진짜 맛있고, 계속 생각나요 ㅜㅜ 늦게 왔는데, 친절하게 맞이해주셔서 감동이였숩니다!','2026-10-12T00:00:00.000Z'),
('nr-26019','naver-1587144487','naver','엄청 기대하고 왔는데 오길 잘했어요 별점만점⭐️⭐️⭐️⭐️⭐️ 너무너무 맛있어서 또 올 것 같아요 ! 그리고 정말 친절하세요 😍','2026-10-12T00:00:00.000Z'),
('nr-26020','naver-1587144487','naver','여긴 말해모해죠.. 그냥 아..묻..따.. 닥목살 최고죠.. 늦게까지 하니까 퇴근하고 오기 넘 조아요!','2026-10-12T00:00:00.000Z'),
('nr-26021','naver-1587144487','naver','윤남노포 보고 왔는데 불 들어오는 것부터 맛집이구나 싶었어요!! 숯불 닭갈비 오랜만인데 넘 맛있게 먹고 갑니다!!','2026-10-12T00:00:00.000Z'),
('nr-26022','naver-1587144487','naver','너무 맛있어서 정신없이 먹다가 사진 찍었네요. 너무 맛있어요!! 감사합니다.','2026-10-12T00:00:00.000Z'),
('nr-26023','naver-1587144487','naver','엄마 모시고 왔는데 동네에 이런 맛집이 있을지 몰랐네요~ 종류별로 1인분씩 주문할 수 있어서 너무 좋아요 ❤️','2026-10-12T00:00:00.000Z'),
('nr-26024','naver-1154741968','naver','사시미 세트랑 구운 초밥 맛있게 잘 먹고 갑니다.😋👍🏻👍🏻 식후에 매실차도 주시고 사시미세트에 냉모밀 + 계란찜 + 튀김들🍤🍣 맛있게 골고루 잘 먹었습니다.🤗✨ 알찬 구성의 맛있는 상무초밥 감사합니다.😍🩷💕 #상무초밥 #상무초밥길동점 #사시미세트 #구운초밥 #냉모밀 #계란찜 #튀김 #길동초밥 #길동스시 #🍣 #내돈내산 #스시맛집 #강동구초밥 #강동구스시 #😋 #👍🏻','2026-10-12T00:00:00.000Z'),
('nr-26025','naver-1154741968','naver','매장이 깔끔하고 직원분들이 친절해서 기분 좋게 식사한 곳입니다. 특히 점심특선 구성(계란찜, 소바, 튀김, 초밥)이 알차서 가성비가 훌륭합니다. 회도 신선하고 밥 양과 간이 적당해 호불호 없이 즐기기 좋습니다. 정갈한 한 끼나 합리적인 가격의 초밥을 원하시는 분께 길동점 추천합니다.','2026-10-12T00:00:00.000Z'),
('nr-26026','naver-1154741968','naver','주말이나 공휴일도 런치특선이 가능해서 좋아요. 처음 9900원일때부터 다니기 시작했는데, 가격은 12900원이 되긴 했지만 자완무시도 있고 간장새우초밥도 추가가 되었어요. 매장 넓고 주차도 지원되고, 가성비 있고 맛있게 잘 먹고 갑니다.','2026-10-12T00:00:00.000Z'),
('nr-26027','naver-1154741968','naver','동네 맛집이라 자주 찾는 곳인데 올 때마다 너무 맛있게 잘 먹고 갑니다 :) 회도 신선하고 양도 푸짐해요! 점심 시간대에 방문하면 가성비 좋게 맛있는 식사할 수 있어요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-26028','naver-1154741968','naver','길동 맛집 상무초밥은 항상 밝고 활기찬 분위기여서 정말 좋아요. 상무 정성 세트는 구성이 알차고 스시도 다양하고 신선하고 차완무시는 부드럽고 마음을 편안하게 해주어서 정말 좋아요. 오늘도 친절하게 맞이해 주시고 정성을 다해 주셔서 정말 감사합니다^^','2026-10-12T00:00:00.000Z'),
('nr-26029','naver-1154741968','naver','저번에 중학생 아이들과 왔는게 좋아하더라구요 뭐랄까 대접받는 느낌이라고 할까? 넘 기분좋은 저녁입니다 주차도 되고 담에 또 올게요^^','2026-10-12T00:00:00.000Z'),
('nr-26030','naver-1154741968','naver','길동 맛집 상무초밥은 정성 가득한 스시 정식을 먹을 수 있는 정말 친근하고 최고의 장소예요. 상무 정성 세트는 스시도 신선하고 다양한 구성이어서 정말 좋아요. 오늘도 밝고 친절하게 맞이해 주셔서 정말 감사합니다^^','2026-10-12T00:00:00.000Z'),
('nr-26031','naver-1154741968','naver','매장이 깨끗하고 쾌적합니다. 음식이 신선하고 맛있고 가성비가 좋습니다. 대기는 있지만 그랄만한 가치가 있다고 생각합니다.','2026-10-12T00:00:00.000Z'),
('nr-26032','naver-1154741968','naver','결호기념일 맛난곳 초밥 아이들도 좋아하고 울가족모두 자주 이용합니다. 딱 양도 좋고 맛있어요. 번창하세요','2026-10-12T00:00:00.000Z'),
('nr-26033','naver-1154741968','naver','가성비 너무너무너무 좋아요 초밥 너무 사랑하는데 퀄리티도 좋아요 주차도 편해서 강력추천!!!','2026-10-12T00:00:00.000Z'),
('nr-26034','naver-1196392637','naver','생갈비살과 막창이 정말 맛있었던 곳이예요!ㅋㅋ. 생갈비살은 육즙이 풍부하고 부드러워 씹을수록 고소한 풍미가 느껴졌고, 막창은 잡내 없이 쫄깃한 식감이 일품이었습니다~~ 직원분들도 친절하고 매장도 깔끔해 기분 좋게 식사할 수 있었어요~ 다음에도 꼭 다시 방문하고 싶은 맛집이예요!','2026-10-12T00:00:00.000Z'),
('nr-26035','naver-1196392637','naver','상일동맛집 상일뚝방집에서 맛있는 갈비살과 생막창 먹고 왔어요! 일단, 원육이 정말 좋아서 생갈비살은 고소하고 육즙 촉촉하고 감칠맛도 좋아요 양념갈비살은 은은하게 달달한 양념이 완전 밥도둑이에요! 거기에 숙성된 상태라 더욱 부드러운 느낌? 거기에 쉽게 먹을 수 없는 생막창은 식감과 고소함이 매력적이라 술안주로 제격입니다! 식사로도 좋고 술안주로도 좋고 꼭 한 번 가보시길!','2026-10-12T00:00:00.000Z'),
('nr-26036','naver-1196392637','naver','고기를 직접 구워야하지만 고기질 좋고 맛있어요 아이들과 가끔 가는 고기집입니다 양념은 타서 생고기 먹었는데 양념이 세지않아서 양념이 더 맛있어요. 그리고 여기 라면이 아이들이 진짜 좋아하는 소고기라면이에요. 애들은 라면맛집이라며 ㅎㅎ 학교 다닐때 신촌기차길 옆 갈비살 먹던 생각이 나는 곳입니다. 매장에서 나오는 음악들으면 사장님이 저랑 같은 시대에 태어난것 같네요 ㅋㅋ','2026-10-12T00:00:00.000Z'),
