('nr-38496','naver-2037555555','naver','메뉴가 다양해서 너무 좋고 음식이 넘 맛있어요!! 친구가 엄청 추천해서 같이 왔는데 오길 넘 잘한것 같습니다 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-38497','naver-2037555555','naver','지인 추천으로 오늘 처음 방문했는데 계란토스트가 진짜 미쳤어요 너무 맛있고 곱도리탕도 술이 계속 들어가는 맛이에요🥹❤️무조건 재방문 할거 같습니다','2026-10-12T00:00:00.000Z'),
('nr-38498','naver-2037555555','naver','쭈꾸미와 계란말이 조합이 너무 좋아요!! 너무 잘먹고 갑니다 ㅎㅎ 날이 선선해서 창문도 다 열어두어 야장감성이라 좋았어요','2026-10-12T00:00:00.000Z'),
('nr-38499','naver-2037555555','naver','남자친구가 휴가 나와서 곱도리탕 먹으러 왔는데 너무 만족하면서 먹었습니다! 입맛이 워낙 까다로우신 분이라 걱정했는데 나중에 또 오자며 맛있다는 말만 연신 내뱉으며 갔네요 ㅎㅎ. 모임이든 데이트든 어떤 목적으로도 적합한 곳이니 다들 부담없이 방문하시면 맛있는 안주와 좋은 시간 보낼 수 있을 것 같습니다!','2026-10-12T00:00:00.000Z'),
('nr-38500','naver-2018843046','naver','네이버 검색하다가 우연히 예약해서 왔는데 고기 진짜 깔끔하고 인테리어 예쁘고 고깃집인데 시끄럽지도 않고 정말 좋았어요!! 자칭 목살러버인데 여기는 삼겹살도 살살 녹고 맛있어요ㅠㅠ 다음에 또 올게요','2026-10-12T00:00:00.000Z')
INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-38501','naver-2018843046','naver','남현동에 새로 생긴 삼겹살집인데 진짜 고기 질도 좋고 고기도 직접 구워주고 너무 맛있어요!!!! 사당역 5번출구에서 가깝고 장소도 넓어서 회식이나 단체 모임하기도 좋고 밑반찬 하나하나 다 맛있어서 입맛까다로운 사람데리고 와도 맛나다 할것같아요.','2026-10-12T00:00:00.000Z'),
('nr-38502','naver-2018843046','naver','추천받아서 왔는데 정말 맛있어요! 저는 똥손인데 잘생긴 청년들이 구워주셔서 더 맛있는 것 같습니다. 늘 고기 먹을 때마다 냄새 배는 걸 신경썼는데 굉장히 깔끔해서 그런 걱정도 전혀 없습니다. 무엇보다도 고기가 두툼해서 좋고 재래식 된장찌개도 완전 진국이라 강추합니다!!!','2026-10-12T00:00:00.000Z'),
('nr-38503','naver-2018843046','naver','부산사람인데 서울 여행와서 숙소 근처 맛집으로 찾아보니 유명하대서 예약하고 방문해봤어요!예약안했으면 하마터면 웨이팅으로 이어질 뻔 했는데 다행히 바로 입장가능했구요!와 고기 일단 질부터가 좋아보였는데 구워주시는 모자쓰신 여직원 분이 설명도 잘 해주시고 정말 맛있게 구워주셔서 목살이 삼겹살 처럼 부드러웠어요!!!!! 부산에 고기도 맛있는데 정말 맛있게 먹어서 일인분 추가 주문했네요 !!반찬들도 너무 맛있어서 다 비우고 온 것 같아요🫢🥹 그리고 된찌도 추천해주셔서 먹어봤는데 와.. 찰밥이랑 너무 찰떡이라 정말 바닥이 보일 정도로 비우고 왔네요 ㅎㅎ정말 맛도 맛있었지만, 여직원분의 친절하고 자세한 설명에 2배로 맛있게 먹고 온것같아요!다음에 서울여행오면 여긴 멀어도 또 올 것 같아요. 글자수로 인해. 한마디.짱!','2026-10-12T00:00:00.000Z'),
('nr-38504','naver-2018843046','naver','사당에 이렇게 맛있고 맘에 드는 고깃집은 처음봤어요! 사장님 왕친절하시고 너무 맛있게 구워주시고 고기 숙성정도도 너무좋고 곁들임 찬도 너무 깔끔하고 정갈하고!! 자주자주 가고싶어요!!! 아이스크림까지 먹을수있다니!! 걍 미쳤어요! 식당 고르고 있다면 요기로 가세요! 오래오래 장사해쥬세요!! 👍🏻👍🏻👍🏻','2026-10-12T00:00:00.000Z'),
('nr-38505','naver-2018843046','naver','삼굡살이 진짜 육즙가득팡팡터지구 맛있어요🥹 고기 맛나게 구워주셔서 수다떨면서 먹기 좋았어요 ㅎㅎ 친구 청모장소로 왔는데, 대만족..❤️‍🔥 김치찌개는 그냥 술 부르는 맛이니까 같이 시켜드세요😆','2026-10-12T00:00:00.000Z'),
('nr-38506','naver-2018843046','naver','삼겹살은 역시 남이 구워주는 게 제일 맛있음ㅋㅋㅋ 직원분이 처음부터 끝까지 딱 맛있게 구워주셔서 편하게 먹기만 하면 돼서 좋았어요! 고기도 두툼하고 육즙 살아있고, 겉은 노릇노릇하게 구워져서 진짜 맛있었어요. 직접 구우면 타이밍 놓치기 쉬운데 제일 맛있을 때 바로 먹을 수 있게 챙겨주시는 것도 👍 무엇보다 고기 굽느라 정신없지 않고 같이 간 사람이랑 얘기하면서 편하게 먹을 수 있다는 게 최고ㅎㅎ 삼겹살 생각날 때 또 갈 것 같아요. 재방문 의사 있음! 🥩💕','2026-10-12T00:00:00.000Z'),
('nr-38507','naver-2018843046','naver','동네에 있는 고깃집이라 가봐야지 하다가 드디어 가봤는데 고기 질도 너무 좋고 반찬으로 나온 톳이랑 샐러리 짱아찌도 넘 맛있었어요💛 서비스 된장국에도 고기가 가득 들어있구요!ㅎㅎ 오랜만에 맛있는 고기집을 찾은 것 같아 다음에 또 올 예정입니다','2026-10-12T00:00:00.000Z'),
('nr-38508','naver-2018843046','naver','사당역 근처 맛집 찾다가 방문한 한양 사당직영점! 숙성삼겹살이라 그런지 육즙도 풍부하고 고기가 정말 촉촉해서 끝도 없이 들어가더라고요. 폭신폭신한 왕계란찜과 구수한 재래식된장찌개에 찰공깃밥 곁들이니 조합이 완벽했습니다. 마무리로 시원한 물밀면까지 먹어주니 느끼함도 싹 내려가고 너무 깔끔했어요. 술 한잔 기울이기 딱 좋은 곳이라 조만간 또 방문할 예정입니다!','2026-10-12T00:00:00.000Z'),
('nr-38509','naver-2018843046','naver','퇴근하면서 고기가 너무 먹고싶어서 검색하다가 반려동물 가능 식당이라서 방문했어요! 부위별로 1인분씩 시킬 수 있고 직접 구워주셔서 편하게 먹을 수 있었어요! 직원분들 모두 너무 친절하시고 밑반찬 다 먹었을 때도 바로 더 필요하신지 물어보시고 새로 가져다주셔서 좋았어요! 특히 강아지랑 편하게 식사할 수 있게 자리 만들어주셔서 엄마가 좋아하셨어요. 덕분에 즐거운 식사시간이 되었습니다. 다음에 또 방문 하겠습니다!','2026-10-12T00:00:00.000Z'),
('nr-38510','naver-1010487663','naver','타임스퀘어건물에있어 주차 편하고 깔끔하게 먹기 괜츈 계란후라이 재밌었음 부대찌게맛은 아는맛 맛괜츈^^ 함당 쇼핑몰안에있으니 가볍게이용하기 좋은듯','2026-10-12T00:00:00.000Z'),
('nr-38511','naver-1010487663','naver','배고플때 저녁마다 와서 맛나게 먹어용 데이트하며 밥먹기 딱좋은 공간 밥집 ❤️든든하게 먹을수있어서 너무 좋고 좋아하는 돈까스도 먹으며 행복한 시간이에용🤩😁','2026-10-12T00:00:00.000Z'),
('nr-38512','naver-1010487663','naver','쇼핑하다 들렸는데 맛있어요. 육수통도 주셔서 국물 부족하면 부어가면서 먹을수 있어서 좋았구요 비빔만두, 감자전 맛있었어요~~','2026-10-12T00:00:00.000Z'),
('nr-38513','naver-1010487663','naver','부대찌개가 정말 맛있었어요! 국물도 진하고 햄이랑 소시지도 푸짐해서 든든하게 먹기 좋았습니다. 간도 자극적이지 않고 밥이랑 같이 먹으니 딱 좋았어요. 전체적으로 음식도 깔끔하고 맛있어서 다음에 또 방문하고 싶은 곳이에요. 😊','2026-10-12T00:00:00.000Z'),
('nr-38514','naver-1010487663','naver','부대찌개 땡길땐 무조건 해방촌 입니당👍 직원분들이 친절하셔서 기분좋게 밥먹을수 있는 좋은곳!! 당연히 부대찌개도 너무 너무 맛있어요🥰 리뷰 서비스 받은 야채튀김:)','2026-10-12T00:00:00.000Z'),
('nr-38515','naver-1010487663','naver','부대찌게 좋아해서 여러군데 가봤지만 여기는 참깔끔하네요^^. 맛도 물론 좋았어요 신림역 맛집이라더니~~ 역시네요. 납작만두 ㅋ 맛있어요. 20장은 먹을수있을거같아요 ㅋㅋ 담에 또 올께요~~~✌️','2026-10-12T00:00:00.000Z'),
('nr-38516','naver-1010487663','naver','직원분들 너무 친절하시고 부대찌개 정말 맛있어요ㅠㅠㅠ 해장하기 너무 좋습니다!!','2026-10-12T00:00:00.000Z'),
('nr-38517','naver-1010487663','naver','식당 내부도 깔끔하고 음식도 깔끔하고 반찬도 맛있었어요!! 또 올게요🍀👍🏻','2026-10-12T00:00:00.000Z'),
('nr-38518','naver-1010487663','naver','음식이 넘 맛있고 친절하세요! 계란후라이에 라면까지 포함되는데 가격도 합리적이에용 추천드립니다🤍🤍🤍👍👍','2026-10-12T00:00:00.000Z'),
('nr-38519','naver-1010487663','naver','아들과 영화보고, 점심으로 부대찌개 먹었어요. 매장 깨끗하고, 계란후라이 1인당 1개 셀프로 해서 먹을수 있어요. 밥 더 먹고싶으면 무료는 아니고 추가해야 된다는 아쉬움이 있었지만. 부대찌개 맛은 괜찮았어요. 잘 먹었습니다.','2026-10-12T00:00:00.000Z'),
('nr-38520','naver-1219615644','naver','항상 사람이 엄청 많은 곳 자리들이 너무 사람이 많아서 가끔 좀 덜치워졌을 때가 있지만 그래도 너무 바쁘니까~하고 이해할 수 있는 곳 시크하지만 친절한 직원분들과 횟집에서 가장 중요한 높은 회전율은 신림 횟집 중 가히 최고다 새우와 전어 맛있게 먹었따','2026-10-12T00:00:00.000Z'),
('nr-38521','naver-1219615644','naver','32000원의 행복 ㅎㅎ 신선하고 포장 빨라요👍','2026-10-12T00:00:00.000Z'),
('nr-38522','naver-1219615644','naver','이사와서 왔다갔다하면서 눈여겨봤다가 처음 왔는데 직원분들도 엄청 친절하시고 오징어통찜 대합탕 시켰는데 대합이 엄청크고 싱싱해서 놀랬어요!!😍😍 오징어통찜은 말할필요없이 녹진녹진 꾸덕꾸덕😋😋 담에는 회꼭먹으러 올께요😋😋','2026-10-12T00:00:00.000Z'),
('nr-38523','naver-1219615644','naver','가성비 최고, 해산물 최고, 분위기 최고,,, 신림 횟집 술집으로 강추합니다','2026-10-12T00:00:00.000Z'),
('nr-38524','naver-1219615644','naver','맛있고 친절해요','2026-10-12T00:00:00.000Z'),
('nr-38525','naver-1219615644','naver','언제 먹어도 신선하고 좋아용 ㅎㅎ 포장해가서 집에서 쏘주한잔 딱~~~ 최고입니다! 친절하셔서 좋아요 :)','2026-10-12T00:00:00.000Z'),
('nr-38526','naver-1219615644','naver','맛나고 친절해요','2026-10-12T00:00:00.000Z'),
('nr-38527','naver-1219615644','naver','ㅊㅈ','2026-10-12T00:00:00.000Z'),
('nr-38528','naver-1219615644','naver','윤기자르르 (❁´◡`❁) 너무 맛있는 횟집!! 매장도 엄청 넓고, 포장해도 좋아용👍','2026-10-12T00:00:00.000Z'),
('nr-38529','naver-1219615644','naver','신선하고 답니다 ㅎㅎ 너무 맛나용~ 포장 굿굿👍 이모 친절해용','2026-10-12T00:00:00.000Z'),
('nr-38530','naver-1642042192','naver','향라선찬찬향에서 육단가지랑 뚝배기 삼선가지 먹었는데 둘 다 맛있었어요ㅎㅎ 육단가지는 겉은 바삭하고 속은 촉촉해서 계속 손이 갔고, 달달한 소스랑 잘 어울렸어요. 삼선가지는 뚝배기에 뜨겁게 나와서 끝까지 따뜻하게 먹기 좋았고 해산물도 들어 있어 든든했어요. 메뉴가 다양해서 여럿이 와서 나눠 먹기 좋은 낙성대 중식 맛집이에요:)','2026-10-12T00:00:00.000Z'),
('nr-38531','naver-1642042192','naver','낙성대역 4번 출구로 조금걷다가 길건너 대로변에 있어 찾아가기 편해요! 간판에는 ''중국 본토 요리''라고 적혀있는데 여기가 향라선촨촨향 맞아요 ㅎㅎ ✨ 매장이 정말 넓고 쾌적한데, 6인석은 칸막이가 잘 되어 있어서 회식이나 소모임 하기에 분위기가 딱 좋습니다. 👍 태블릿으로 사진 보며 주문할 수 있어서 편해요. 꿔바로우는 겉바속촉에 상큼한 유자소스라 계속 손이 가고, 양고기덮밥은 부드러운 고기에 양꼬치 풍미가 느껴져서 맛있어요. 🍖🥢🍋 마파두부는 양이 진짜 어마무시하게 많아서 2인 이상 밥에 비벼 먹기 최고입니다! 🥘🍚🔥 남은 음식도 엄청 깔끔하게 포장해 주셔서 감동이었어요. 🙏✨ 메뉴도 다채롭고 공간이 넓어 낙성대 모임 장소로 강력 추천합니다! 🙌','2026-10-12T00:00:00.000Z'),
('nr-38532','naver-1642042192','naver','다양한 중국요리가 있음. 양꼬치와 훈툰 먹었고 향신료가 맞는 사람에겐 맛있는 음식들 같음. 개인적으론 맛있게 먹었지만 가격대가 좀 있는 편.','2026-10-12T00:00:00.000Z'),
('nr-38533','naver-1642042192','naver','중국맛~~~ 생각나는 맛^^ 추천요.','2026-10-12T00:00:00.000Z'),
('nr-38534','naver-1642042192','naver','진짜 맛있어요!!! 💓💓💓 중식 원탑임 ㅎㅎㅎ 자주올거같네용 사장님 친절하시구 음식도 맛있고 엄청 양 많아요 ㅋㅋㅋ 마라탕이랑 양꼬치 덮밥 추천합니다👍🏻','2026-10-12T00:00:00.000Z'),
('nr-38535','naver-1642042192','naver','서울대 근처에 중국본토음식 잘하는데가 있다길래 와봤는데 전부 다 맛있습니다 정말로요,, 개인적으로 뚝배기마파두부가 완내스!!!! 진짜 맛있어요 마음같아선 곱배기 없나 더 먹고싶더라구요 ㅠㅠ 라즈지는 완전 짭짤하니 맥주안주고요 다음에 또 올거에요!','2026-10-12T00:00:00.000Z'),
('nr-38536','naver-1642042192','naver','이집 오면 그냥 여기가 중국인지 한국인지 분간이 안됩니닼ㅋㅋ진짜 찐 현지맛 느끼고 싶으면 고민말고 오세요👍','2026-10-12T00:00:00.000Z'),
('nr-38537','naver-1642042192','naver','아는맛이지만 건더기가 실해요','2026-10-12T00:00:00.000Z'),
('nr-38538','naver-1642042192','naver','감자채볶음은 완전 중국식은 아닌거같아요 아삭아삭하고 살짝 시큼한 맛이 중요한데 많이 익은편이고 시큼한 맛도 없네요 양볶음은 서비스로 주셨는데 양을 못 먹어서ㅜ 친절하세요 다른 음식들은 좋아요','2026-10-12T00:00:00.000Z'),
('nr-38539','naver-1642042192','naver','요즘 멀어도 자주 가게되는 맛집. 훌륭합니다. 가성비도 최고!! 자세한 리뷰는 네이버 블로그 청담동유상무 글 참고하세요.','2026-10-12T00:00:00.000Z'),
('nr-38540','naver-2021969916','naver','기본 스테이크 주문했는데 고기도 부드럽고 맛있었어요! 가격도 부담스럽지 않고 든든하게 한 끼 먹기 좋았습니다. 직원분들도 친절하고 매장도 깔끔해서 편하게 식사했어요. 서울대입구에서 가볍게 스테이크 먹고 싶을 때 또 방문할 것 같아요!','2026-10-12T00:00:00.000Z'),
('nr-38541','naver-2021969916','naver','헤비스테이크에 왔습니다. 가성비 갑입니다. 스테이크 두개 세트에 스프 콜라까지 라면 느끼하지않게 먹는데 정말 든든하게 먹었습니다. 스테이크 가볍게 즐기려면 강추입니다. 서울대입구점 맛있어요.','2026-10-12T00:00:00.000Z'),
('nr-38542','naver-2021969916','naver','스테이크 먹고 싶어서 방문했는데 고기가 두툼하고 육즙도 살아 있어서 맛있었어요! 뜨거운 철판에 나와서 마지막까지 따뜻하게 먹을 수 있는 것도 좋았습니다ㅎㅎ 같이 나온 사이드랑 곁들여 먹으니 든든하고 한 끼 제대로 먹은 느낌이에요. 혼자 방문해서 먹기에도 부담 없어서 스테이크 생각날 때 또 올 것 같아요 :)','2026-10-12T00:00:00.000Z'),
('nr-38543','naver-2021969916','naver','헤비스테이크 매번 퇴근길에 지나가면서 봤는데요! 드디어 오늘 시간이 가능해서 방문해보았습니다 ㅋㅋ 스테이크를 가성비있게 접할 수 있어서 너무 좋았구요, 가게도 아담하지만 아늑한 분위기에 식사를 할 수 있어서 마음에 들었습니다~~ 특히 바 테이블 형식이 좋았어요! 밥 먹는 것에 집중할 수 있고 그만큼 회전률도 빠른 거 같아서 빠른 식사가 가능했어요😁 비프스테이크랑 치킨마요덮밥 둘다 맛도 좋았구요 ㅋㅋㅋ 가끔 퇴근하면서 고기 땡기는 날 있으면 또 들릴 예정입니다! 🫢🫢🫢','2026-10-12T00:00:00.000Z'),
('nr-38544','naver-2021969916','naver','돼지갈비스테이크랑 헤비매니아 스테이크 주문해서 먹고 왔어요! 가성비 진짜 최고고 고기 퀄리티가 생각보다 너무 좋네요. 돼지갈비스테이크는 양념이 잘 베어있어서 짭조름하니 밥도둑이고, 헤비매니아 스테이크는 육즙 팡팡 터져서 소스랑 와사비 곁들여 먹으니 순삭이었습니다. 서울대입구 근처에서 부담 없이 든든하게 고기 먹고 싶을 때 자주 올 것 같아요. 주차/혼밥 편해서 만족스러운 한 끼였습니다!','2026-10-12T00:00:00.000Z'),
('nr-38545','naver-2021969916','naver','서울대입구에서 간단하게 점심 먹으려고 들렀는데 메가치킨마요 괜찮네요! 오믈렛이랑 밥에 갈비소스, 마요네즈가 같이 들어가서 전체적으로 달달하고 고소한 맛이고 크리스피어니언까지 있어서 식감도 좋았어요. 가격 부담 없이 한 끼 든든하게 먹기 좋고 서울대입구역에서도 가까워서 혼밥이나 점심 먹으러 오기 괜찮은 것 같아요. 다음에는 스테이크 메뉴도 먹어보려고요 :)','2026-10-12T00:00:00.000Z'),
('nr-38546','naver-2021969916','naver','바 테이블 구조라 혼밥하기에도 좋고 둘이 나란히 앉아 식사하기에도 편안한 분위기였습니다. 비프 스테이크는 잡내 없이 부드럽고 불향이 잘 살아있어서 맛있었습입스니다. 양파랑 옥수수 콘을 곁들여 취향껏 소스와 와사비를 얹어 먹으니 물리지 않고 끝까지 맛있게 먹었네요. 치킨 덮밥도 닭고기가 촉촉해서 밥이랑 조합이 만족스러워서 재방문 의사 있습니다.','2026-10-12T00:00:00.000Z'),
('nr-38547','naver-2021969916','naver','메가치즈스테이크랑 메가치킨마요풀세트 먹었어요 소시지 파인애플 토핑 추가했는데 넘 든든합니다 👏 특히 스테이크 굽기가 넘 좋았어요 치즈랑 각종 소스랑 먹으니까 최고 🩷','2026-10-12T00:00:00.000Z'),
('nr-38548','naver-2021969916','naver','배달로도 자주 시켜먹다가 처음 방문했는데 여전히 고기가 맛도 있고 최고네요 ! 치킨 오므라이스는 처음 먹어봤는데 추천이요!😃😃','2026-10-12T00:00:00.000Z'),
('nr-38549','naver-2021969916','naver','궁금해서 가봤는데 넘 맛있고 매장도 청결해요ㅎㅎ 다른 메뉴들도 먹어보고싶습니다 가성비 맛집인거 인정합니다😊😊 번창하세요! 감사합니다!!!','2026-10-12T00:00:00.000Z'),
('nr-38550','naver-2004276007','naver','주변에서 이야기는 많이 들었는데 직접 먹어본건 처음이에요 스테이크가 가격대비 해서 괜찮은거같아요ㅎㅎ 맛있어요 혼자서나 둘이서 먹으러 오기 좋을것같고, 컵라면도 같이 나와서 너무 불어버릴까 걱정했는데 꼬들하게 주셔서 같이 먹기좋아요','2026-10-12T00:00:00.000Z'),
('nr-38551','naver-2004276007','naver','맛과 퀄리티 대비 합리적인 가격 같아요. 아직 두세번 정도로 많이 방문해보진 않았지만 굽기도 딱 좋게 미디움 웰정도로 좋고 잡내도 없었습니다. 약간 추성훈 마초스테이크같은 그런 감성의 철판스테이크? 밥 추가해서 밥이랑 같이 먹어도 좋을것 같아요. 철판이 뜨겁다보니 처음 굽기보단 더 구워질 수 있으니 기호 껏 철판에서 덜어내는거 추천','2026-10-12T00:00:00.000Z'),
('nr-38552','naver-2004276007','naver','신림 혼밥 성지 발견!!! 가성비도 좋고 혼밥하기도 좋아서 혼자 방문하는 분들이 많더라구요!!! 저는 둘이 방문해서 비프스테이크랑 메가치킨마요덮밥 먹었는데!! 다 맛있었어요👍 개인적으로 치킨마요덮밥은 이색적이라 꼭 드셔보세용 강추🤤','2026-10-12T00:00:00.000Z'),
('nr-38553','naver-2004276007','naver','헤비스테이크에 딸과 함께 왔습니다. 신림역에서 1분거리에 가까운 위치에 있으며 메가치즈 2인세트를 주문했는데 스프와 스테이크에 사발면까지 알차네요. 으깬감자에 고소한 치즈가 얹어 풍미가 좋고 사발면이 느끼할 수 있는데 잡아줍니다. 혼밥하기도 좋고 둘이 와도 너무 좋아요.','2026-10-12T00:00:00.000Z'),
('nr-38554','naver-2004276007','naver','아무래도 신림역에서 바로 갈 수 있는 게 나이스하죠😋 꼭 와보고 싶었는데 오늘 드디어! 6시 전에는 조금 여유로워요~! 혼밥하기도 너무 좋고 육식 먹고싶을 때 가성비로 오기 좋습니당','2026-10-12T00:00:00.000Z'),
('nr-38555','naver-2004276007','naver','연기펄펄나는 스테이크를 이렇게 먹을 수 있다니.. 맛 좋고 저려미 메뉴도 있는데 스테이크가 원탑이긴 합니다!! 양배추 샐러드도 딱 괜찮고 여기 다이어트 할 때 오기 너무 좋어요 자취생들 스테이크 먹기 어려운데 저렴하게 먹으러 오세요','2026-10-12T00:00:00.000Z'),
('nr-38556','naver-2004276007','naver','스테이크 생각날 때 부담 없이 먹기 좋은 곳이에요! 고기도 부드럽고 소스랑 같이 먹으니 맛있었어요. 양도 생각보다 든든해서 한 끼 식사로 괜찮았고, 가격 대비 만족도가 높은 편입니다. 신림에서 스테이크 먹고 싶을 때 종종 들를 것 같아요 👍','2026-10-12T00:00:00.000Z'),
('nr-38557','naver-2004276007','naver','눈여겨 보고 있다가 지나가는데 있길래 웨이팅 없이 들어왔어요! 직원분들 되게 바빠보이셨는데도 불구하고 잘 대응해주셔서 기분좋은 한끼 보냅니다👍고기 굽기도 너무 좋았어요!!! 완전 맛있었음 ㅎㅎ 다른 메뉴 먹으러 또 와보고 싶었어요~~🤭','2026-10-12T00:00:00.000Z'),
('nr-38558','naver-2004276007','naver','신림에서 가성비 좋은 스테이크 찾다가 방문했는데 기대 이상이었어요! 고기 양도 푸짐하고 스테이크 소스랑 버터 조합이 진짜 맛있네요. 스프까지 같이 나와서 든든하게 한 끼 먹기 좋았고, 음식도 빨리 나와서 좋았습니다. 매장도 깔끔하고 직원분들도 친절해서 기분 좋게 식사했어요. 다음에는 다른 메뉴도 먹으러 재방문할게요! 😊','2026-10-12T00:00:00.000Z'),
('nr-38559','naver-2004276007','naver','컵라면을 저렇게 내주는 식당 보셨나요? 음식 사진도 함 보세요!! 맛이는 것들 천지라 먹지 않아도 배가 부르고 실제 먹어보니 정말 맛나네유~~ 드실때 같이 섞어서 드셔야 다같이 따뜻해지니 참고해주세요!','2026-10-12T00:00:00.000Z'),
('nr-38560','naver-2086230494','naver','집 근처에 새로 생기길래 오픈하면 다녀와보자 하고 큰 기대없이 다녀왔는데 너무 맛있게 먹고왔어요! 2인세트 짬짜세트 곱빼기로 시켰는데 양도 많고 맛있었습니다 :) 짜장면은 옛날 짜장면 맛에 야채 큼직한 거 안 좋아하는 저는 숟가락으로 떠먹기 좋게 잘려 있어서 좋았고, 짬뽕 맛있는 곳 찾기 힘든데 짬뽕.. 제 스타일이었습니다 🫠🩷 탕수육도 맛있게 먹어서 다음엔 옛날볶음탕수육 먹어보러 다시 오기로 했어요! 맛있게 잘 먹었습니다😆🙌🏻','2026-10-12T00:00:00.000Z'),
('nr-38561','naver-2086230494','naver','출근할 때 지나가면서 보고 오픈하면 꼭 와봐야지 했는데, 퇴근하고 가족모임으로 저녁 8시 반쯤 갔는데 늦은 시간인데도 편하게 먹을 수 있어서 좋았어요! 음식도 생각보다 빨리 나오고 양도 푸짐해서 가족들이랑 배부르게 먹었네요😋 무엇보다 음식이 너무 맛있어서 만족스러웠어요ㅎㅎ 매장도 깔끔하고 직원분들도 정말 친절하셔서 기분 좋게 식사하고 왔습니다! 처음 방문했는데 가족들도 다 맛있다고 해서 다음에 또 방문하려고요😊','2026-10-12T00:00:00.000Z'),
('nr-38562','naver-2086230494','naver','짜장면과 짬뽕 먹으러 방문했는데 전체적으로 맛있게 잘 먹었습니다! 😊 짜장면은 소스가 진하고 감칠맛이 좋아서 면과 잘 어울렸고, 짬뽕은 국물이 얼큰하면서도 개운해서 만족스러웠어요. 두 메뉴 모두 양도 괜찮고 음식도 깔끔하게 나와서 든든하게 한 끼 먹기 좋았습니다. 다음에 중식이 생각날 때 다시 방문하고 싶은 곳이에요. 맛있게 잘 먹었습니다! 👍','2026-10-12T00:00:00.000Z'),
('nr-38563','naver-2086230494','naver','우연히 지나가다가 보고 내부가 너무 청결하고 깨끗해서 오게 됐는데, 고추짬뽕 먹고싶은데 매운걸 잘 못먹어서 맵기 조절도 해주시고, 해산물이 너무 많아서 놀랬어요! 멘보샤도 바삭바삭하고 탕수육도 둘이와서 소자 먹어도 충분해요! 바삭한게 신의한수! 일단 직원분들이 너무 친절하고 내부가 너무 청결해서 맘에들어요. 다음에는 크림짬뽕 먹어봐야겠어요 너무 궁금하네용!','2026-10-12T00:00:00.000Z'),
('nr-38564','naver-2086230494','naver','맛있어요. 자극적이지 않고 딱 중식 기본레 충실한 맛입니다. 유니짜장 양념 아까워서 밥 비벼먹었어요. 밥 엄청 많이 주셔서 남겼네요. 배부르고 맛있게 먹을 수있어서 좋았어요. 짬뽕도 해물 많고 얼큰하니 딱 좋습니다. 많이 맵지 않아서 끝까지 잘 먹었어요. 담번엔 탕수육 먹으러 갈려구요. 강추합니다!! 그리고 여자 직원분 엄청 친절합니다!','2026-10-12T00:00:00.000Z'),
('nr-38565','naver-2086230494','naver','새로오픈해서 와봐야지하다 바로 오게됐는데 유니짜장 건더기 소스 낭낭하고 맛 조화로움! 짬뽕은 오랜만에 짬뽕답다?느낀거같은데 요즘 프차 중식집은 되게 찐하고불향만 내는데 정말맘에듬','2026-10-12T00:00:00.000Z'),
('nr-38566','naver-2086230494','naver','중식 먹고 싶었는데 마침 오픈해서 방문했아요ㅎㅎ 음식도 금방 나오고 시킨 음식들 다 맛있었어요😆 특히 짬뽕 불맛도 제대로 나서 좋았어요👍👍 사장님 매니저님 넘 친절하셔서 더 좋았어요~~! 자주올게요! 번창하세용🥹','2026-10-12T00:00:00.000Z'),
('nr-38567','naver-2086230494','naver','깔끔하고 분위기도 요즘 감성 중국집 느낌! 벽에 적힌 ‘불향 가득한 중식의 새로운 기준, 호룡각’ 문구부터 기대감 뿜뿜✨ 신림역 새로 오픈한 호룡각 🍜 짜장 짬뽕 먹으러 왔는데 면발이 탱글탱글! 어릴 적 먹던 그때 그 맛이 생각나서 괜히 추억 돋았던 날☺️ 깔끔한 분위기에 맛도 굿👍','2026-10-12T00:00:00.000Z'),
('nr-38568','naver-2086230494','naver','점심시간에 방문했는데 전체적으로 음식도 깔끔하고 맛있게 잘 먹었어요😊 매장도 깨끗하고 음식도 정성스럽게 나와서 만족스러웠습니다. 신림 쪽에서 깔끔하게 점심 먹을 곳 찾으신다면 한 번 방문해보셔도 좋을 것 같아요👍🏻','2026-10-12T00:00:00.000Z'),
('nr-38569','naver-2086230494','naver','신림역 근처에서 새로 생겨서 먹어보러 왔습니다. 짬뽕 기막혀요. 해장이 싸악 됨 매장도 넓어서 편하게 있기 좋아요. 근데 주방에서는 주문누락이 계속 나오는 것 같고 바쁜시간대에 매장에서는 홀보시는 분이 하나뿐이라 그런가 감당을 못하는게 보여요. 오픈 초기라 그런 것 같은데 이런거만 정리되면 롱런하실듯. 음식들은 진짜 맛있긴해요.. 리뷰이벤트로 받은 만두조차 기막힘.','2026-10-12T00:00:00.000Z'),
('nr-38570','naver-2003716571','naver','예전 명륜진사있던 자리에 호르몬치치가생겼네요~와규큐브스테이크가 육즙 팡팡 넘 맛있구요 애들도 함께 즐길수있게 다양한 사이드메뉴들이 있네요~가족모임하기 쾌적하고 좋은거같아요~ 일본에서 먹던맛이에요!','2026-10-12T00:00:00.000Z'),
('nr-38571','naver-2003716571','naver','고기가 엄청 다양하고 맛있네요~ 고기 질이 좋은 편이에요. 부페음식도 곁들여져 있고, 디저트도 좋네요.^^ 우연히 지나가다가 사전 오픈하는 날 들렀는데 괜찮은 식당이 생겼네요. 고기 종류별로 다 맛보고 싶었는데 배불러서 다 못 먹겠어요.~ 다음에 또 올게요♡','2026-10-12T00:00:00.000Z'),
('nr-38572','naver-2003716571','naver','큰기대안하고 왔는데 맛있음..😮😮 종류도 많고 심지어 주류가 1인 9900원에 무제한.. 이미 뽕 뽑았습니다ㅎㅎ 라면이 생긴거와 다르게 진짜 존맛탱...양도 딱 적당해요 6살 아이가 있는데 놀이터에서 나오질 않습니다..ㅎㅎㅎ그덕에 자유입니다👍👍','2026-10-12T00:00:00.000Z'),
('nr-38573','naver-2003716571','naver','호르몬치치 진짜 너무 맛있어요ㅎㅎ 친구 가족들이랑 다 같이 왔는데 너무 즐겁게 잘 먹고 갔어요! 아이들이랑 같이 오면 아무래도 식사할 때 정신없을 때가 많은데 여기는 놀이방이 있어서 정말 좋더라고요. 아이들은 신나게 놀고 어른들은 조금 여유롭게 먹을 수 있어서 좋았어요ㅎㅎ 아이들도 재밌어하고 어른들도 편하게 이야기할 수 있어서 만족! 음식도 기대했던 것보다 더 맛있어서 다들 맛있다고 했어요. 친구 가족들이랑 같이 오기에도 분위기가 편하고 좋았어요. 아이 있는 가족끼리 모임 장소 찾는다면 괜찮은 것 같아요. 다음에도 아이들이랑 또 오고 싶어요 :)','2026-10-12T00:00:00.000Z'),
('nr-38574','naver-2003716571','naver','고기 종류도 다양하고 시키면 친절하게 가져다 줍니다 제한시간은 있지만 술을 부어라 마시지 않는다면 넉넉해요 생기지 얼마 안되어서 식기류도 새거입니다 다만 엄청 높은 퀄리티를 생각한다면 당연히 단품 파시는 곳 가야하고 가성비는 좋았습니다 이전 고깃집에 어린이 놀이터를 그대로 보존해놓아서 애기 있는 집도 좋아하실거 같아요','2026-10-12T00:00:00.000Z'),
('nr-38575','naver-2003716571','naver','저희는 커플이서 왔는데 고기만 총 30그릇 먹었습니다.. 아무리 많이 먹는 커플이라도 여긴 배불러도 계속 시키느라 30그릇 먹은줄은 몰랐네요.. 진짜 너무 맛있습니다.. 특히 갈릭마요 소스에 옥수수 발라서 구워먹으니 진짜 존맛.. 꼭 해보시길.. 우설도 맛있고.. 닭목살도 오독오독해서 너무 맛있었네요!! 먹다보니 먹는 사진은 어디가고 다 먹은거 뿐.. 다들 한번씩 꼭 방문해보세요!!','2026-10-12T00:00:00.000Z'),
('nr-38576','naver-2003716571','naver','고기도 너무 맛있는데 무한리필 사이드 바 메뉴들도 새롭고 좋았어요! 아무래도 고기 무한리필집은 많은데 야끼니꾸라 그런지 좀 색다르고 좋았습니다 ㅎㅎ 또 올게요','2026-10-12T00:00:00.000Z'),
('nr-38577','naver-2003716571','naver','집근처에 호르몬치치 매장이 생겨서 와봤습니다 주휴 무한리필 가능하고 다양한 재료의 야키니쿠를 맛볼수있어 가성비가 좋습니다! 맥주 한잔 하기 너무 좋네요!!!','2026-10-12T00:00:00.000Z'),
('nr-38578','naver-2003716571','naver','와규가 부드럽고 흔치 않은 우설이 있어서 좋아요. 리필도 빠르게 나오고 사이드가 적당히 느끼함을 없애줘서 좋습니다. 평일 6시까지는 매장 앞 도로 주차가 가능해서 편리합니다','2026-10-12T00:00:00.000Z'),
('nr-38579','naver-2003716571','naver','호르몬치치가 집앞에 생겨서 바아아로 와봤어요!!! 고기 다 너무너무 맛있고 음료무한리필로 배터지게 먹고갑니당😍 디저트도 야무져용 짱짱👍❤️','2026-10-12T00:00:00.000Z'),
('nr-38580','naver-1090363671','naver','구운고기도 먹고싶고 샤브샤브도 먹고싶어서 고민하다가 두가지를 다 먹을 수 있다고 해서 방문했습니다 식당이 아주 넓고 쾌적했어요 고기도 부위마다 다양하게 나오는데 질까지 좋으니까 처음부터 끝까지 맛있게 먹을 수 있었습니다 편백찜크기는 무척커서 놀라고 양도 많고 담백했습니다 다 먹고 마무리로 샤브샤브까지 야채듬뿍 넣어서 먹으니 배가 터질 것 같아요 정말 잘먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-38581','naver-1090363671','naver','무한리필이었지만 한돈구이부터 샤브샤브, 편백찜까지 퀄리티가 정말 수준급이었어요! 셀프바도 깨끗하게 관리되면서 반찬이나 월남쌈 등등 구성도 괜찮았고 사장님도 엄청 친절하시면서 매장도 굉장히 쾌적하고 깔끔해서 좋았습니다! 가족 외식이나 모임 장소로 추천드리고 싶네요 :)','2026-10-12T00:00:00.000Z'),
('nr-38582','naver-1090363671','naver','서울 신림역 7번출구 인근. 민물장어,샤브샤브 맛집 ''혼고념,편백상회'' 리뷰입니다. 입구 들어서자마자 반겨주시는 사장님의 친절에 고민없이 입장. 친절한 설명과 응대. 하지만 무엇보다 맛과 원물의 품질이 중요한데, 일단 민물장어 상태가 너무 좋았고, 돼지고기는 몇몇 질긴부위가 있고 퍽퍽했으나 무한리필을 감안했을 때 삼겹살,목살은 굉장히 나쁘지않았습니다. 특히 샤브 육수가 정말 맛있어서 놀랐고, 자포니카 민물장어를 이 가격에 무한리필로 즐길 수 있다는건 정말 큰 메리트가있다고 생각합니다. 돈이 아깝지않은 굉장히 만족스러운 식사를 했답니다. 재방문 의사 150% 입니다. 번창하세요 사장님!','2026-10-12T00:00:00.000Z'),
('nr-38583','naver-1090363671','naver','무한리필인데도 메뉴 하나하나 맛있음 사장님께서 간장소스나 샤브육수나 직접 만드시고 많이 고민하신게 느껴짐 편백찜도 간장소스에먹으면 너무맛잇고 특히 한돈 고기 질 왜케 좋아요 뽈살이랑 항정살 꼬들살 존맛탱!! 샤브에 죽까지 먹으니 배 부여잡고나갑니다......','2026-10-12T00:00:00.000Z'),
('nr-38584','naver-1090363671','naver','숯도 좋고 편백도 맛있고 고기 질은 뭐 사르르 정도? 사장님너무 친절 하시죠 아 진짜 놓치는거 화장실 개깨끗해요 !!! 이게 가계다 진짜 사진 못찍는거 인정하는데 저기에 보정 100배 들어가야 실물나옴','2026-10-12T00:00:00.000Z'),
('nr-38585','naver-1090363671','naver','고기가 질이 엄청 좋고 숯불에서 구워서 캠핑와서 먹는 고기맛이었어요! 편백찜도 샤브샤브도 양이 엄청 많고 샤브는 무한이라 진짜 배터지고 갑니다~! 이 가격에 이 퀄리티면 진짜 대추천추천합니당💯💯💯','2026-10-12T00:00:00.000Z'),
('nr-38586','naver-1090363671','naver','신림에서 오랜만에 지인들과 모이기 위해 선택한 고깃집! 무엇보다 점심부터 운영해주시는게 너무 좋았고 고기가 부드럽고 맛있었어요 >///< 강추드립니다!! 장어도 팔던데 다음에는 장어도 먹어보고 싶어요~','2026-10-12T00:00:00.000Z'),
('nr-38587','naver-1090363671','naver','고기 상태도 너무 좋고 고기 비싼거 아니에요 ㅠㅠㅠ!!! 무려 한돈인데 정말 맛있었고 리필도,편백찜도 최고🩵🩵 서울대입구역에 사는데 먹으러 또 와야겠어요!!! 사장님도 엄청 친절하시고 최곱니다👍🏻👍🏻👍🏻👍🏻👍🏻👍🏻 고기상태 최고!!!!','2026-10-12T00:00:00.000Z'),
('nr-38588','naver-1090363671','naver','구이랑 샤브샤브 둘다 먹고싶을때! 그럴때 가면 좋아요, 한자리에서 편하게 그것도 무한리필이라 너무 만족스러웠습니다 한돈이라 확실히 맛이 좋네요 월남쌈으로 싸먹으면 더 맛있어요 자주 방문할것같아요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-38589','naver-1090363671','naver','무한리필인데 고기 퀄리티가 미쳤어요!! 기본으로 주시는 구이랑 편백찜 양도 많고 너무 맛있어요~ 주변에 가시는 분들 모두 드셔보셨으면 좋겠네요👍🏻 완전 반했어요!! 혼고념🤭','2026-10-12T00:00:00.000Z'),
