('nr-41495','naver-1802587243','naver','21,900원 훠궈 무한리필 맛집! - 훠궈용: 각종 야채, 면, 두부, 완자 고기, 중국냉동만두, 해산물, 소스바 - 사이드: 꿔바로우, 볶음밥, 튀긴만두, 중국식계란 등 - 음료: 콜라/사이다 등 탄산 무제한 - 디저트: 내려 먹는 아이스크림 이 모든게 인당 21900원이면 요즘 물가에 완전 땡큐고, 심지어 맛도 좋아요!! 홍탕, 백탕 반반 먹었는데 중국 본토맛 나요 (하이디라오만큼 진한 육수는 아님) 마한 맛이나 마라의 매운맛 필요하면 소스바에서 재료 가져와서 넣으면 딱이에요','2026-10-12T00:00:00.000Z'),
('nr-41496','naver-1802587243','naver','＜평일 점심 : 18,900원＞ ＜1인 입장 : +5,000원＞ TV 및 유튜브에 정말 많니 출연한 건대양꼬치거리 훠궈 무한리필 대장으로 불리는 중경식객 육수 종류는 5가지, 이들 중에서 "홍탕 & 스키야키" 맵고 감칠나는 식재료 조합으로 제대로 된 맛을 즐깁니다 샤브샤브는 역시 진하고 깊은 맛을 느끼기 좋아야 마땅하며, 여기가 진짜 중국식 샤브샤브 무한리필(뷔페)입니다 기본 메뉴들(꿔바로우, 마파두부, 양념계란•메추리알, 계란볶음밥 등)의 맛이 전반적으로 진하고 퀄리티가 좋아서 돈이 아깝지 않을 것입니다 별 5개 드립니다','2026-10-12T00:00:00.000Z'),
('nr-41497','naver-1802587243','naver','건대 훠궈 무한리필 맛집으로 추천드려용 볶음밥이랑 꿔바로우도 맛있고 고기랑 채소도 신선하고 맛있었어요 !','2026-10-12T00:00:00.000Z'),
('nr-41498','naver-1802587243','naver','가성비 좋게 잘 먹었습니다. 1층 만석이라 지하로 안내받았어요. 다음에는 기다리더라도 1층에서 먹어야겠습니다. 꿔바로우, 고기튀김, 만두, 리필탄산음로 등의 사이드가 1층에만 있고 지하에는 없네요. 올르락내리락 번거로웠어요. 그리고 1층이 훠궈재료가 좀 더 다양합니다. 지하의 장점은 훠궈재료담는 접시가 더 커요. ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41499','naver-1802587243','naver','혼자 가서 마라훠궈 무한리필 시켰는데 냄비 비우기 무섭게 채워주셔서 리필 버튼 연타하는 게임하는 기분이었어요🎮 매장 인테리어도 세련돼서 혼밥러도 눈치 안 보이고, 건대 근처라 접근성도 최고였네요.','2026-10-12T00:00:00.000Z'),
('nr-41500','naver-1802587243','naver','요즘 핫플로 뜨는 곳이라길래 여름특선 훠궈 무한리필 먹으러 왔어요! 국물 색깔이 넘 예뻐서 사진 찍느라 바빴는데 맛있는 건 기본이더라고요🍲 동일로 쪽인데 리필도 계속 채워주셔서 배불리 먹고 왔어요📸','2026-10-12T00:00:00.000Z')
INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-41501','naver-1802587243','naver','냄비 뽀글뽀글 끓는 소리 들으면서 남자친구랑 마라훠궈 무한리필에 젓가락 부딪혀가며 먹었어요😆 매콤한 국물이 은근 중독성 있어서 계속 리필했네요. 옆자리 아이 유아 메뉴도 순해 보이더라고요. 건대 근처 데이트 코스로 강추예요!','2026-10-12T00:00:00.000Z'),
('nr-41502','naver-1802587243','naver','남자친구랑 데이트 코스로 골랐는데 마라훠궈 무한리필이라 국물 리필하다 보니 시간 가는 줄 몰랐어요🔥 얼큰한 맛에 계속 젓가락질하게 되고, 매장 분위기도 힙해서 데이트하기 딱이었어요. 광진구 동일로 쪽이라 위치도 찾기 쉬웠고 다음엔 더 배고픈 상태로 재도전하고 싶네요.','2026-10-12T00:00:00.000Z'),
('nr-41503','naver-1802587243','naver','냄비 하나에 마라훠궈 무한리필 국물 색깔이 너무 예뻐서 인생샷 찍느라 정작 먹는 속도는 느렸어요🍲 옆에 조카 유아 메뉴는 순삭하는데 저는 사진 찍느라 바빴네요😂 건대입구역 근처라 찾기도 쉽고 다음엔 폰 내려놓고 먹기에만 집중해볼게요!','2026-10-12T00:00:00.000Z'),
('nr-41504','naver-1802587243','naver','혼자서도 마라훠궈 무한리필 도전해봤는데 국물 색깔이 너무 예뻐서 사진부터 남겼어요📷 매콤하고 맛있는 국물에 혼밥인데도 만족도 최고였고, 건대입구역 근처라 접근성도 좋아서 또 올 것 같아요🌶️','2026-10-12T00:00:00.000Z'),
('nr-41505','naver-2037150210','naver','오늘 이사와서 고생했단 의미로 파티를 해야해서 첫 디너를 참으로 고심했습니다.. 많은 음식점중에 예랑이가 그린와사비를 골랐는데요 진짜 여기는 무조건 한 번 더가 아닌 10번은 더 와야하는 집이라 생각 들었어요.. 물론 일요일이라 사람이 적어서 더 쾌적했지만 다른 날은 리뷰에 사람이 많다고도 봐서 눈치게임을 잘 해야하겠지만.. 야키토리를 먼저 먹고 너무 맛있어서 모듬회가 별로면 어떡하지 걱정했던 제가 미울정도로 모듬회도 너무 맛있더라고요..! 야키토리 중에는 개인적으로 삼겹 팽이말이가 고트였구요 예랑이는 닭다리대파가 젤 맛났대요 ㅎㅎ 군자에서의 척 저녁을 너무 행복하게 보내게 해주셔서 감사합니다 :)','2026-10-12T00:00:00.000Z'),
('nr-41506','naver-2037150210','naver','먹다가 더 좋아져서 머물게 되는 집~~ 사시미 꼬치 먹다가 타이까지 먹게되는 신기한 집~~ 너무좋아요~^^','2026-10-12T00:00:00.000Z'),
('nr-41507','naver-2037150210','naver','리뷰가 너무 좋아서 왔는데 좋은 이유가 있었네요 너무 맛있어요! 동네분들 많이 오는 공간이 되면 좋겠어요 😋','2026-10-12T00:00:00.000Z'),
('nr-41508','naver-2037150210','naver','자주 이용하는 가게 입니다. 꾸준한 맛과 퀄리티, 잘생긴 사장님과 함께여서 더 즐거운자리였습니다.','2026-10-12T00:00:00.000Z'),
('nr-41509','naver-2037150210','naver','아늑한 분위기에 혼자서 혼술하기 너무 좋아요!! 사장님께서도 친절하시고 차분한 분위기 속에서 혼자 은은히 취하기 딱 좋은 곳이에요!! 혼술할 땐 무조건 여기로 올거에요!!!','2026-10-12T00:00:00.000Z'),
('nr-41510','naver-2037150210','naver','꼬치랑 사시미 시켜서 먹었는데 너무 맛있었어용! 꼬치는 배가 너무고파서 바로 먹느라 사진은 못찍었지만ㅠㅠ불맛 제대로 나고 염통꼬치는 통통해서 입안에서 터집니당ㅠㅠ😍안주 퀄리티에 비해 가격이 너무 착해서 놀랬습니당!! 아마 동네터줏대감 맛집인것 같아요! 예전부터 오고 싶었는데 오늘 근처에 마침 볼일있어서 방문했어용! 첫방문이지만 재방문 무조건 할려고용!!!😍사장님 너무 친절하시고 음식도 너무 맛있어서 기분좋은 휴일 보냈습니당!','2026-10-12T00:00:00.000Z'),
('nr-41511','naver-2037150210','naver','항상 맛있게 먹고있어요!!! 최고최고입니다. ㅎㅎ 메뉴 다 맛있어요 >.<','2026-10-12T00:00:00.000Z'),
('nr-41512','naver-2037150210','naver','전에는 문을 안여셔서 못왔었고 그 전에는 만석이였어서 못왔었는데 드디어 왔습니당 !!! 동네라서 가끔 애용할거같애요 ㅎㅎ 다른메뉴도 다 먹어보고싶어여 또 올게용~>>','2026-10-12T00:00:00.000Z'),
('nr-41513','naver-2037150210','naver','한달에 두세번 오면서 힐링하는 곳이에요 조용하고 음식 맛있고 분위기도 사장님도 너무 좋아요 솔직히 혼자 알고싶어서 후기 쓰기 싫은데 사장님이 잘되어야 가게도 유지되는거니까....','2026-10-12T00:00:00.000Z'),
('nr-41514','naver-2037150210','naver','오픈하고 얼마 안됐을때 방문했다가 엄청 오랜만에 왔는데 역시 너무 맛있어요👍🏻😚 그때보다 손님도 많아지고 분위기 너무좋아요 그리구 방문한지 오래됐는데 저희 커플 기억해주시는 사장님의 눈썰미가 최고..👍🏻👍🏻👏👏','2026-10-12T00:00:00.000Z'),
('nr-41515','naver-1993969313','naver','음식도 맛있고 사장님도 친절합니다!!','2026-10-12T00:00:00.000Z'),
('nr-41516','naver-1993969313','naver','매콤하면서 기름기 없는 닭날개랑 우육면 모두 맘에 들었습니다','2026-10-12T00:00:00.000Z'),
('nr-41517','naver-1993969313','naver','최악... 온면은 다 뿔어터지구 신경도 안쓰는 역대급 음식점 다시 방문의사없음 제발 안갔음하는 맘','2026-10-12T00:00:00.000Z'),
('nr-41518','naver-1993969313','naver','새벽에 이만한 윙집은 없지... 싶네요 다양한 맛의 윙 골라먹는 맛 ㅋㅋ','2026-10-12T00:00:00.000Z'),
('nr-41519','naver-1993969313','naver','닭날개 실하고 맛있어요 ! 가리지 구이도 별미고 2-3차쯤 간단한 안주가ㅡ많아서 좋아요','2026-10-12T00:00:00.000Z'),
('nr-41520','naver-1993969313','naver','딱히….','2026-10-12T00:00:00.000Z'),
('nr-41521','naver-1993969313','naver','간단하게먹기좋아여 닭날개맵기2단계여도 엽떡오리지날3배매움 참고하세여ㅠ','2026-10-12T00:00:00.000Z'),
('nr-41522','naver-1993969313','naver','김밥천국 중국버전 가성비 좋은 중국요리들을 먹을 수 있어요 중국 현지맛에 가까운 음식들도 있고 향신료맛 1도 없는 메뉴들도 있어서 선택지가 많습니다 무조건 닭날개는 주문하는데요 매운맛 매니아가 인정한 변태매움맛,, 이건 매운맛 찾아다니시는 분들 도전해볼만 합니다 콜라맛은 달달하니 누구나 좋아할 것 같아요 고슬고슬하게 잘 볶아낸 볶음밥, 짭쪼롬하게 양념한 가리비구이, 속 풀리는 온면 등 다양한 중식 메뉴들에 술 한잔 제대로 뿌시고 왔습니다 24시간 영업하니 건대가면 항상 막차로 들리는 것 같아요~~','2026-10-12T00:00:00.000Z'),
('nr-41523','naver-1993969313','naver','마시쏘예와 함께 떠나는 자양동 나들이 퐁퐁퐁 맵기로 소문난 중화닭날개구이 맵기로 소문난 변태매운맛주문 와.. 그동안 다닌 매운집들은 소문만 무성한 매운집이었나 이름답게 진짜 변태스럽게 맵다 살면서 먹은 중 제일 매움 혀를 잘라버릴것 같은 고통 나중엔 배가 찢어질것 같은 고통 나름 100키로 가까운 돼지가 윙 한개를 다 못먹었다 건대 양꼬치 골목 안에 있는데 나름 위생도 깨끗하고 나름 친절도 친절하고 다른메뉴들도 꽤나 맛있음 배달이 주구장창 나가는 이유가 있음 1차로 다시 한번 방문해보고 싶은 집','2026-10-12T00:00:00.000Z'),
('nr-41524','naver-1993969313','naver','맛집이라 추천 받아 갔는데 메뉴가 다양하고 가성비 좋아요! 2차 하기 딱 좋은 곳☺️ 음식이 조금 짜요ㅠㅠ','2026-10-12T00:00:00.000Z'),
('nr-41525','naver-752309342','naver','오랜만에 방문한 질서정연은 너무 감사하고 좋았어요 ㅠㅠ 메뉴는 더 맛있어졌고 와인 테이스팅존까지 있어서 더 좋더라구요… 여기 라자냐는 진짜 보물이니까 꼭 드시고 콥샐러드도 사장님이 정말 정성스럽게 썰어 준 야채랑 과일에다가 소스 진짜 넘사벽이니까 꼭 드세요. 또 오겠습니다!! 사장님 건강하세요❤️','2026-10-12T00:00:00.000Z'),
('nr-41526','naver-752309342','naver','음식 퀄리티가 너무 좋아요 맛있어요 해물크림누룽지그라탕은 꼭꼭 시켜보세요 누룽지+그라탕..? 처음엔 신기했는데 이렇게 조합이 괜찮은지 몰랐네요 맛있어요 통삼겹스테이크도 든든하고 맛있어요 직원분들도 다들 친절하시고 가게 분위기도 편안하게 맛있게 식사하구왔어요 강추가게~~~','2026-10-12T00:00:00.000Z'),
('nr-41527','naver-752309342','naver','혼자 산책하다 매장 분위기가 좋아 잠시 들러 와인 한 잔 마시고 가는데 만족도가 너무 높아 리뷰 남김니다 ㅎㅎ 다양한 와인을 편안한 분위기에서 테이스팅할 수 있어 흥미로웠고, 사장님도 너무 친절하셔서 또 방문하고싶은 매장입니다! 음식과 주류가 다양하게 준비되어있어 누구와도 방문하기 좋은 매장인듯해요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41528','naver-752309342','naver','남편이랑 데이트 하러왔는데 메뉴선정 탁월했어요 스테이크는 겉바촉촉인데 굽기도 너무 잘구워주셔서 너무 맛있었어요!! 누룽지들어간 그라탕도 잘 어울리고 미니피자 서비스도 나와요~! 데이트완전강추😆','2026-10-12T00:00:00.000Z'),
('nr-41529','naver-752309342','naver','#건대맛집 #건대술집 질서정연 남자친구 생일 겸 데이트 왔습니다 분위기도 좋고 와인 테이스팅 존에서 무료로 시음도 해보고 고를 수 있어서 너무 좋았어요!! 시그니처 메뉴인 삼겹 스테이크랑 해물 크림 누룽지 그라탕 주문했는데 진짜 다 맛있었어요💕','2026-10-12T00:00:00.000Z'),
('nr-41530','naver-752309342','naver','친구가 좋아하는 가게라고 소개해 줘서 가게 되었어요. 와인 무료 테이스팅존이 있어서 와인 시음 후에 마음에 드는 잔와인으로 주문할 수 있는 점이 너무 좋았어요. 음식도 하나하나 전부 맛있었는데, 특히 돼지김치탕! 이거 밥도둑이라서 한 입 먹고 공기밥 시켜서 먹었습니다ㅋ 분의기 좋고, 친절하고, 가성비도 좋아서, 친구들 소모임으로 데이트로 방문하기 좋은 곳이에요.','2026-10-12T00:00:00.000Z'),
('nr-41531','naver-752309342','naver','정말 좋은 가게입니다. 음식의 맛이 중요하지만 사장님의 친절에 정말 기분 좋은 식사를 했습니다. 기분이 좋아서 음식이 더 맛있게 느껴졌네요. 만약 기분 좋은 식사를 하고 싶다면 강력 추천 드릴 수 있을 거 같아요. 그리고 안쪽 자리가 소리 울림이 있어서, 친목으로 친구들과 함께 가면 더욱 좋을 거 같아요! 연인이랑 데이트로 와인 한 잔 하고 싶을 때나 가볍게 반주 하고 싶을 때 오기 좋은 집입니다! 음식 가성비 좋습니다.','2026-10-12T00:00:00.000Z'),
('nr-41532','naver-752309342','naver','기념일로 왔습니다 이번에 테스팅 와인 이벤트도해서 다양하게 맛보고 마실 와인 고를 수 있어서 좋았어요 역시 그라탕은 맛있었습니다','2026-10-12T00:00:00.000Z'),
('nr-41533','naver-752309342','naver','여자친구랑 기념일에 데이트로 왔습니다. 와인 무료테이스팅존에서 여러가지 와인 시음해보고 좋았어요! 돼지김치탕 한입먹자마자 공기밥도 시켰습니다. 건대맛집이에요! 통삼겹 스테이크 불닭소스랑 너무 잘어울려요👍👍','2026-10-12T00:00:00.000Z'),
('nr-41534','naver-752309342','naver','분위기도 좋고 너무 친절하십니다 ♥ 와인은 테스팅 후에 고를 수도 있어서 너무 좋습니다 ! 음식도 맛있어서 다음에 꼭 재방문 하겠습니다~','2026-10-12T00:00:00.000Z'),
('nr-41535','naver-2066278994','naver','짚불향 가득한 초벌 삼겹살이 정말 매력적인 뚝섬고기집 폴딩도어를 열어두어 시원한 테라스 감성 속에서 식사할 수 있어 분위기부터 최고였는데요. 두툼한 초벌 삼겹살과 목살은 잡내 없이 육즙이 가득해 씹을 때마다 감탄이 절로 나옴 특히 고기와 곁들여 먹을 수 있는 소스가 무려 6가지나 되어 다양한 조합으로 즐기는 재미가 쏠쏠했어요! 노릇하게 구워 먹는 새우젓과 멜젓, 파절이 조합은 절대 실패 없는 맛이예요.🥹 현재 오픈 기념으로 소주와 맥주를 1,900원에 즐길 수 있는 파격 이벤트까지 진행 중이라 가성비까지 완벽쓰!','2026-10-12T00:00:00.000Z'),
('nr-41536','naver-2066278994','naver','짚불고기 한판 시켰는데 너무너무 맛있어요! 정말 고기질도 좋고 삼겹살, 목살 다 맛있었어요~!! 된장찌개 추가로 시켜서 먹어봤는데 너무 맛있어서 깜놀했어요! 자양동 한강가는 입구에 새로 생겨서 소주 맥주 할인행사도 하는데 번창해서 잘되셨으묜 좋겠습니다~~~','2026-10-12T00:00:00.000Z'),
('nr-41537','naver-2066278994','naver','새로 오픈해서 가봤는데 편하게 먹기 좋은 분위기였어요ㅎㅎ 직원분들도 친절해서 기분 좋게 식사함!! 고기는 짚불이랑 숯불 향이 솔솔 나는 게 진짜 특이한데, 초벌 돼서 나와가지고 구워 먹기도 넘 편하더라구요 ㅎㅎ 반찬도 다채롭게 잘 나오는데 명이와사비랑 함초소금, 황태보풀이 소스 찍어 먹는 조합이 완전 별미예요 ㅎㅎ 고기 다 먹고 계란프라이 올라간 볶음밥까지 싹 비우고 나왔습니다!! 맛있게 먹어서 조만간 또 방문할 것 같아요 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41538','naver-2066278994','naver','고기 질 좋고, 상차림도 깔끔합니다! 사이드 음식도 맛있어요!👍','2026-10-12T00:00:00.000Z'),
('nr-41539','naver-2066278994','naver','회식 장소로 방문했는데 고기 메뉴라 그런지 분위기도 활기차고 좋았어요ㅎㅎ 고기 굽는 향이 입맛을 확 살려주고 여러 명이 같이 먹기에도 양이 괜찮았어요 다 같이 맛있게 먹고 이야기하기 좋은 시간이었네요','2026-10-12T00:00:00.000Z'),
('nr-41540','naver-2066278994','naver','사진 보고 맛있어 보여서 방문했는데 실제로 먹어보니 더 괜찮았어요! 고기 색깔도 좋고 구워진 상태도 적당해서 먹기 좋았고 짚불 특유의 향이 은은하게 느껴졌어요 다음에는 다른 친구들도 데리고 오려고요','2026-10-12T00:00:00.000Z'),
('nr-41541','naver-2066278994','naver','2번 초벌한다는 말에 반신반의했는데, 먹어보니 잡내가 정말 없더라고요! 고기 자체 맛이 살아있어서 더 맛있게 느껴지는 것 같아요. 곁들여 나오는 반찬들도 다양해서 골라 먹는 재미가 있고, 파김치랑 같이 구워 먹으면 조합이 진짜 예술이에요. 꼭 한번 드셔보세요!','2026-10-12T00:00:00.000Z'),
('nr-41542','naver-2066278994','naver','여행 갔다가 맛있는 고기집 찾다가 방문했는데 좋은 선택이었어요ㅎㅎ 짚불로 구워서 그런지 고기에서 은은한 향이 나고 잡내 없이 깔끔했어요 맛있는 고기 먹으면서 여행 마무리하니 기분도 좋고 다음에 근처 오면 다시 들르고 싶어요','2026-10-12T00:00:00.000Z'),
('nr-41543','naver-2066278994','naver','고기 먹고 싶다는 친구 따라서 갔다가 저까지 완전 만족하고 왔어요ㅋㅋ 짚불 향 때문에 고기가 더 맛있게 느껴지고 육즙도 적당히 살아있어서 부드러웠어요 쌈채소에 이것저것 올려 먹으니까 조합이 좋아서 계속 먹게 되더라고요','2026-10-12T00:00:00.000Z'),
('nr-41544','naver-2066278994','naver','저녁 시간에 방문했는데 손님들이 꽤 있어서 기대하고 들어갔어요! 음식도 깔끔하게 나오고 직원분들이 필요한 것도 바로 챙겨주셔서 편했어요 짚불 고기는 향이 좋고 고소해서 맛있게 먹었고 전체적으로 만족스러운 식사였어요','2026-10-12T00:00:00.000Z'),
('nr-41545','naver-2098066870','naver','건대에서 저녁 어디서 먹지 하다가 닭발이 땡겨서 왔어요! 신당에 본점이 있는 걸로 아는데 건대에도 생겨서 대기도 있길래 얼마나 맛있나하구 들어왔습니다. 직원분들도 친절하시고 대창꾸덕닭발도 너무 맛있어요! 감자전도 최고. 매장 분위기도 좋아요','2026-10-12T00:00:00.000Z'),
('nr-41546','naver-2098066870','naver','불향 제대로 입혀진 닭발이라 첫입부터 너무 맛있었어요🔥 쫄깃한 식감에 매콤한 양념까지 조합이 완벽하고, 불향이 은은하게 올라와서 계속 손이 가네요. 술안주로도 딱이고 같이 주문한 메뉴들도 전체적으로 만족스러웠어요! 건대에서 닭발 생각날 때 재방문할 것 같습니다 :)','2026-10-12T00:00:00.000Z'),
('nr-41547','naver-2098066870','naver','닭발 진짜 맛있게 먹고 왔어요! 🔥 양념이 너무 맵기만 한 게 아니라 맛있게 매콤해서 계속 손이 가네요. 닭발도 쫄깃하고 잡내 없이 깔끔해서 너무 좋았습니다! 같이 먹는 메뉴들이랑 조합도 최고였고 사장님도 친절하셔서 기분 좋게 먹고 왔어요 😊 다음에 닭발 생각나면 또 방문할 것 같아요. 강추합니다!!','2026-10-12T00:00:00.000Z'),
('nr-41548','naver-2098066870','naver','무뼈 닭발 불향이 나고 미쳤어요ㅠㅠ 당면 치즈떡 떡도 있고 닭발도 야들야들해요. 원조맛 시켰는데 딱 좋은 맵기에요. 신라면과 불닭 사이고 끓이는 거라서 계속 따뜻하게 먹을수 있어요. 매콤한 거 먹고 싶었는데 좋아요!','2026-10-12T00:00:00.000Z'),
('nr-41549','naver-2098066870','naver','매장도 깔끔하고 닭발 너무 맛있게 매워서 좋아요 진짜 과장 안하고 서울에서 먹은 닭발 중에 제일 맛있어서 또 올 것 같아요😭😭😭','2026-10-12T00:00:00.000Z'),
('nr-41550','naver-2098066870','naver','서울 놀러왔다가 매운거 먹고싶어서 찾던 중에 여기 짚뿔닭발 유명하길래 본점 가려고 했는데 멀어서 건대점으로 왔어요 ! 친절하시고 메뉴도 다양하고 가성비도 괜찮은 것 같아요 ! 감자전 맛있고 대창 닭발도 존맛이에요 🤍','2026-10-12T00:00:00.000Z'),
('nr-41551','naver-2098066870','naver','건대에서 닭발이 먹고싶어서 찾던 와중에 맛있다는 리뷰도 많고 맛있어 보여서 방문하였습니다. 닭발도 맛있고 같이 나온 감자전도 너무 맛있었습니다. 또 올게요~!','2026-10-12T00:00:00.000Z'),
('nr-41552','naver-2098066870','naver','요즘 핫한 주꾸미닭발 먹으러 건대점 방문🐙🔥 인테리어도 청결도 서비스도 만족합니당~!! 쭈꾸미닭발과 하이볼 강추❤️','2026-10-12T00:00:00.000Z'),
('nr-41553','naver-2098066870','naver','신당 본점이 워낙 유명해서 가보고 싶었는데 건대점이 새로 오픈했다는 소식 듣고 바로 다녀왔어요 ~~ 짚불에 구워서 그런지 닭발에서 불향이 진하고 맵기만 한 게 아니라 감칠맛이 있어서 미쳤어요 닭발 식감도 쫄깃해서 맛있게 먹었습니다 ! 매장도 오픈한 지 얼마 안 돼서 깔끔했고 직원분들도 친절해서 기분 좋게 식사했습니당 대창꾸덕닭발 꼭 드세용 👍🏻','2026-10-12T00:00:00.000Z'),
('nr-41554','naver-2098066870','naver','요즘 알고리즘에 쭈꾸미닭발이 떠서 먹으러 왔어요!! 기대만큼 너무너무 맛있었어요.. 불향을 진짜 좋아하는데 불향도 많이 나고 다음에 또 생각나서 방문 할 것 같아요!!','2026-10-12T00:00:00.000Z'),
('nr-41555','naver-1218040958','naver','지나갈 때 항상 보던 사람많던 짬뽕가온에 드디어 왔어요! 2명이서 야무지게 세트시켰습니다. 차돌숙주짬뽕이랑 짜장, 숙주 탕수육 주문했네요. 토요일 점심인데 대기없이 바로 입장해서 우선 좋았고, 파김치나 매실차같은 사이드가 센스있게 느껴졌어요. 아차산 더미 숙주 탕수육은 숙주더미에 특제 겨자소스 곁들여 나오는데..(이거 비주얼 보고 온 것임) 탕수육 러버로서 쫀득하고 부드러워서 넘 맛있어요.. 숙주랑도 잘 어울리구요!! 짬뽕은 살짝 매콤한데 차돌이랑 숙주랑 먹으니 딱 좋아요. 짜장은 달달소스인데 입에 착 감기는 감칠맛이 있어요. 2명이서 배부르게 먹고 갑니다.','2026-10-12T00:00:00.000Z'),
('nr-41556','naver-1218040958','naver','아삭한 숙주와 바삭한 탕수육의 조화👍 불맛 입힌 차돌짬뽕도 너무 밋있어요 ㅎ 중식이 땡길땐 무조건 짬뽕가온이에요. 짜장면과 다양한 요리도 맛있고 합리적인 세트 구성도 좋습니다. 저녁에 빼갈 한잔에 양장피도 최고에요 👍','2026-10-12T00:00:00.000Z'),
('nr-41557','naver-1218040958','naver','벌써 세번째 이용합니다.^^ 아이가 숙주탕수육을 좋아해서 가끔왔네요~ 여기만 있는 특별한 메뉴라서 좋아요. 탕수육소스대신 겨자소스 뿌려먹는것도 궁합이 잘맞네요~ #구의역맛집 #짬뽕가온 #탕수육맛집 #아차산더니숙주탕수육','2026-10-12T00:00:00.000Z'),
('nr-41558','naver-1218040958','naver','처음 방문이데 매장 안은 깨끗하고 짬뽕이 괜히 맛있게 느껴지네요. 음식 나오기 전에 매장을 둘러보는데, 기분 좋게하는 여러 아이템들이 있네요. 기본 짜장과 짬봉, 곱배기 짬봉도 양도 가득하네요. 휴일이라 가족과 연인들 방문들도 많아요. 음식도 맛있네요.','2026-10-12T00:00:00.000Z'),
('nr-41559','naver-1218040958','naver','짬뽕은 깔꼼하고 불맛이 끝내줍니다. 탕슉은 겨자소스에 숙주랑 찍어먹는데 코가 찡하니 자극적이고 홍고추 청고추가 간간히 매콤하니 씹히고 고기는 촉촉하고 잡내 없고 튀김옷은 얇고 주방은 조리모습이 훤히 보이고 5시 넘으니 차리 꽉참. 재방문 의사 있음. 리뷰쓰고 크림새우 두개 얻어먹음 ㅎㅎ 군인,경찰,소방관,국가유공자는 5프로 할인받아서 좋음. 동서울역 근처라 군인 추천 ㅎㅎ 근처에 음식점이랑 카페 많음 버스시간 기다리며 저녁 먹기 좋음','2026-10-12T00:00:00.000Z'),
('nr-41560','naver-1218040958','naver','짬뽕국물 진국에 불맛이 장난 아니네요 탕수육도 숙주가 철철 넘쳐요~ 테이블이 넓직하고 아주 깔끔해요 나도 모르게 조심스럽게 먹게될정도로 깔끔ㅎ 간만에 쾌적하게 맛난 음식 먹었습니다. 구의동 맛집으로 추천합니다ㅎㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41561','naver-1218040958','naver','구의역 근처에 볼일있어서 왔다가 짬뽕맛집이 있다고 해서 왔습니다! 일단 비쥬얼부터 깡패! 숙주 탕수육은 겨자소스가 기본이지만 본래 탕수육소스도 무료로 제공해준대용 탕수육도 맛있고, 차돌짬뽕도 맛있어여!!!','2026-10-12T00:00:00.000Z'),
('nr-41562','naver-1218040958','naver','찐 구의역 맛집이에요 ㅎ 이사오고나서 중국집 정착 못했는데 오늘 가족외식와서 넘 맛있어서 후기 남깁니다..오픈주방이라 잠깐 봤는데 화력이 어마어마 ㅎ 불맛내는 이유가 있네요!!!밑반찬이 내스톼일 ♡♡ 아이가 좋아해서 자주오려구요!','2026-10-12T00:00:00.000Z'),
('nr-41563','naver-1218040958','naver','딸과 둘이 저녁 데이트하러 왔어요! 우선 매장이 깔끔해서 너무 좋구요! 음식양도 많고 맛도 좋아서 너무 만족했습니다! 다른것도 맛나지만 특히 탕수육이 취향저격이었어요 #구의역맛집#탕수육맛집','2026-10-12T00:00:00.000Z'),
('nr-41564','naver-1218040958','naver','직장이 근처여서 짬뽕 맛있다는 동료 추천듣고 와봤는데 진짜 구의역 맛집이네요! 게다가 탕수육도 진짜 부드럽고 달콤한 소스에 찍어 먹으니 너무 맛있네요~ 다음달에는 크림짬뽕 먹으러 와야겠어요~','2026-10-12T00:00:00.000Z'),
('nr-41565','naver-1685699877','naver','이렇게 늦게까지 하는 맛집 보셨어요!? 탕슉도 맛있고 짬뽕지존 이름답게 짬뽕 맛잇고 불맛...으... 식사도 좋고 술안주로도 너무 좋아요!!!🍟🍟🍟🍟🍟🍜 만두도 바샄바샄하고 진짜 맛있습니다!! 근처사시는분들 꼭 와보세요🍟🍟🌼🎀🍔☀🍋🎵🍒🌻','2026-10-12T00:00:00.000Z'),
('nr-41566','naver-1685699877','naver','진짜 명품 짜장면맛 짬뽕도 국물 진하고 너무 맛있구요 찹쌀탕수육은 오늘 여기서 첨먹었는데 엄천 부드럽고 너무 맛있어요 튀김옷 얇고 고기도 부드럽고 너무 맛나요 매장도 깨끗해서 아이랑 이용하기 너무 좋네요','2026-10-12T00:00:00.000Z'),
('nr-41567','naver-1685699877','naver','추석 연휴에 부모님, 할아버지랑 같이 방문래 했습니다. 어른들도 오랜만에 짬뽕 맛있게 드셨다고 좋아하셨고, 탕수육도 맛있었어요. 밥도 추가로 셀프로 가져다 먹을 수 있는 점을 어른들이 좋아하셨어요.','2026-10-12T00:00:00.000Z'),
('nr-41568','naver-1685699877','naver','넓고 쾌적하면서 주차가능한 매장.짬뽕과 짜장의 매콤함 단계별 선택이 더욱 좋네요 면이 쫄깃,조개나 고기가 짬뽕의 진한 국물맛을 냅니다 찹쌀 탕수육도 맛있어요^^','2026-10-12T00:00:00.000Z'),
('nr-41569','naver-1685699877','naver','골고루 다 먹어봤는데 다 맛있어요. 셀프반찬코너 있고 짜샤이도 있고 물도 깔끔히 생수고 카스 이벤트도 해요. 아이도 짜장면 맛있다고 다 먹었어요.','2026-10-12T00:00:00.000Z'),
('nr-41570','naver-1685699877','naver','짬뽕지존은 체인점이라🙋‍♀️ 종종 가는데 아차산점은 또 처음이네요🙏음식 빨리 나오고 맛있어요 다른지점보다 매운맛이 약한느낌? 꽤 바쁜매장이지만 직원분들 정말 친절하시네요👍','2026-10-12T00:00:00.000Z'),
('nr-41571','naver-1685699877','naver','믿고먹는 짬뽕지존! 포장도 배달도 먹어봤지만 아차산점 가게에서 먹는게 제맛!! 너무맛있어요ㅋ 불맛나는 짬뽕에 쫄깃쫄깃 탕수육!! 강추합니다❤️','2026-10-12T00:00:00.000Z'),
('nr-41572','naver-1685699877','naver','특별하다 진짜 맛있다. 진심ㅋㅋㅋ와~다이어트하다 먹어서그런가? 너무맛있다.짬뽕 그냥 맵기만한게아니라, 특별하게 맛있고매움.ㅋㅋㅋ 단무지에서 플라스틱 이물질나옴 근데 너무맛있어서 커버됨','2026-10-12T00:00:00.000Z'),
('nr-41573','naver-1685699877','naver','아차산 대로변에 있는 아차산 대표 짬뽕집! 셀프코너에 밥도 있고 반찬들도 다양해서 더 자주 오게 되는 집이에요~ 지금 맥주 2,000원 이벤트도 하네요^^ 칼칼한 맥주와 짬뽕조합으로 완전 추천입니다','2026-10-12T00:00:00.000Z'),
('nr-41574','naver-1685699877','naver','점심 조금 지나 들리니 여유있고 좋네요! 요즘 짬뽕 맛있는 곳 찾기 힘든데 이 곳 짬뽕 알게되어 너무 좋아요>_< 근처 지나갈때마다 꼭 들리는 거 같아요!','2026-10-12T00:00:00.000Z'),
('nr-41575','naver-2012729602','naver','아이들과 함께 짱 육해공 돌짜장에 다녀왔어요 😊 어른들은 매콤한 매운해물돌짜장을 주문했는데 해물이 푸짐하게 들어있고 매콤하면서도 감칠맛이 좋아서 정말 맛있게 먹었어요! 돌판에 나와서 끝까지 따뜻하게 먹을 수 있는 것도 좋았어요. 아이들은 짜장면을 시켜줬는데 아이들도 맛있다며 잘 먹어서 만족스러웠고, 사이드로 주문한 군만두도 바삭바삭해서 함께 먹기 좋았어요. 어른 2명, 아이 2명이 방문해서 메뉴 구성도 딱 좋았고 가족끼리 외식하기 좋은 곳인 것 같아요. 다음에는 다른 메뉴도 먹어보고 싶네요 👍','2026-10-12T00:00:00.000Z'),
('nr-41576','naver-2012729602','naver','자양동에서 돌짜장 생각나서 방문했어요! 해물돌짜장 2인에 짬뽕 하나 추가했는데 둘이 먹기에 양이 정말 넉넉합니다. 돌짜장은 뜨거운 돌판에 지글지글 끓으면서 나와서 마지막 한 젓가락까지 따뜻하게 먹을 수 있는 게 제일 좋았어요. 위에 아삭한 숙주가 듬뿍 올라가 있어서 짜장 소스랑 비벼 먹으면 느끼함 없이 식감이 살아있고, 해물이랑 야채도 큼직큼직하게 들어 있어요. 면에 소스가 잘 배어 있어서 불맛 나는 볶음짜장 좋아하시는 분들께 추천! 짬뽕은 국물이 얼큰하고 시원해서 짜장이랑 번갈아 먹기 딱 좋았고, 탕수육은 찹쌀 튀김옷이라 겉은 바삭, 속은 쫀득했어요. 소스가 과하게 달지 않아서 계속 손이 가더라고요. 매장도 깔끔하고 음식도 빨리 나와서 만족스러운 식사였습니다. 다음엔 다른 메뉴도 먹어보러 또 올게요👍','2026-10-12T00:00:00.000Z'),
('nr-41577','naver-2012729602','naver','처음 먹어 본 “매운돌짜장” 감칠맛 폭발, 푸짐한 채소와 해산물의 조화 완면 전까지 뜨거움이 계속 유지 되지만 면은 불지 않아 좋았어요👍🏻 셀프바에 파김치 있으니 꼭 곁들이기! 그리고 셀프로 전 부쳐 먹는 것도 필수!! 양이 꽤 많아 배부르게 잘 먹었습니다😋','2026-10-12T00:00:00.000Z'),
('nr-41578','naver-2012729602','naver','돌판에 짜장이라니 지글지글 양도 푸짐하고 맛나요. 매운 돌짜장 신라면 정도의 맵기라 느끼하지 않고 딱 좋습니다. 중국집에 파김치도 맛나고, 음식 나오기 전 셀프로 전 부쳐먹을 수 있어서 그것도 별미예요..','2026-10-12T00:00:00.000Z'),
('nr-41579','naver-2012729602','naver','오늘 탕수육, 짬뽕, 콩국수 주문해서 먹었는데 전체적으로 만족스러웠어요! 특히 탕수육은 튀김이 바삭하면서도 고기가 부드럽고 잡내 없이 깔끔해서 맛있었습니다. 소스랑도 잘 어울려서 계속 손이 가더라구요👍🏻 짬뽕은 국물이 칼칼하고 진해서 좋았고, 콩국수도 고소하면서 시원해서 여름에 먹기 딱 좋았어요. 그리고 셀프전을 직접 만들어 먹을 수 있는 게 재미도 있고 별미였습니다ㅎㅎ 기본으로 나오는 파김치도 맛있어서 면이랑 같이 먹으니 궁합이 좋았어요! 전반적으로 편하게 식사하기 좋았습니다. 메뉴 종류도 다양해서 다음에는 다른 메뉴도 먹어보고 싶네요☺️ 맛있게 잘 먹고 갑니다!','2026-10-12T00:00:00.000Z'),
('nr-41580','naver-2012729602','naver','돌짜장 궁금해서 와봤는데 해물이많고 담백하게 맛있네요! 갓튀긴 탕수육도 깔끔하고 군만두도 속이 실해 맛있습니다!','2026-10-12T00:00:00.000Z'),
('nr-41581','naver-2012729602','naver','동네에 돌짜장 집이 있어서 지나가다가 들렸어요. 일반과 매운맛 있어요. 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-41582','naver-2012729602','naver','일요일 오후 방문했는데 사장님이 나와서 주차도 도와주시고 부침개도 구워 주시고 너무 친절해요. 탕수육+돌짜장+만두 주문해서 먹었는데 너무 맛있고 신선해요. 다음에 또 오려고요^^','2026-10-12T00:00:00.000Z'),
('nr-41583','naver-2012729602','naver','자양동 짜장면 맛집 검색하다가 홍콩에서 유명하다는 돌짜장 전문점이 있다고 해서 방문했어요! 저희는 해물돌짜장과 왕군만두 주문했는데 만두는 진짜 크고 겉은 바삭하면서 속은 육즙 가득이라 필수로 드셔야해요! 해물돌짜장은 철판에 나오는데 해물 한가득과 숙주로 비주얼부터 맛까지 완벽해요 어릴적 먹던 간짜장과 맛이 비슷해서 추억도 생각나게 하는 곳이였어요 양도 푸짐하고 셀프바에는 전도 직접 부쳐먹을수도 있으니 완전 가성비 자양동 맛집이였어요! 짜장면 맛집 고민하지 말고 짱육해공으로 가서 돌짜장 꼭 드셔보세요🔥','2026-10-12T00:00:00.000Z'),
('nr-41584','naver-2012729602','naver','고추짬뽕, 짜장면 먹었습니다 맛있게 잘 먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-41585','naver-1533308837','naver','오랫만에 찾아온 찌마기 조개찜. 워낙에 해물을 좋아하기도 하지만 이곳은 유독 재료가 신성하고 맛있다. 손님이 많으니 재료가 더 신선한 것 같고, 무엇보다 맛이있다! 지원분들 너무 친절하고 가격이 괜찮다. 조개집 술집이기도 하지만 아이랑 가족단위로 오기도 좋고 구의 이스트폴 옆이라 교통도 좋다. 샤워한 달걀 등 아이디어도좋고 서비스도 굿! 사실 여름엔 안 오는데 가을부터 봄전까지는 매달 올 것이다','2026-10-12T00:00:00.000Z'),
('nr-41586','naver-1533308837','naver','항상 맛있는 찌마기 !!!🤍 동네 맛집인데 이사가도 생각날거같이 너무 맛있고 소주를 부릅니다....🤍✨️✨️ 생새우회 비린맛 1도 없이 달달하고 새우머리 튀겨주시는게 치킨보다 맛있게 튀겨주셔서 감사해요😆','2026-10-12T00:00:00.000Z'),
('nr-41587','naver-1533308837','naver','바다의 깊은 풍미를 가득 머금은 요리가 테이블 위에서 정갈하게 피어오릅니다. 신선함이 살아있는 재료들은 저마다의 본연의 맛을 품고 있어 입안 가득 즐거움을 선사합니다. 정성스럽게 준비된 한 그릇은 소중한 사람들과 함께하는 시간을 더욱 특별하게 만들어 줍니다. 자극적이지 않으면서도 깊고 깔끔한 맛은 먹는 내내 기분 좋은 여운을 남깁니다. 자연이 주는 건강한 선물을 음미하며 평온하고 따뜻한 식사 시간을 보내시길 바랍니다.','2026-10-12T00:00:00.000Z'),
('nr-41588','naver-1533308837','naver','여름이 가기전에 물회 먹으러 왔습니다.😄살아있는 낙지보고 애기가 한번 먹어보고 싶더고해서 산낙지도 먹어봤네요👍🏻 시원하고 새콤달콤한 물회 왜 안드시는건지ㅎㅎ 초등학생은 조개찜 홀릭이었네요. 멋있게 잘 먹고 왔습니다. 직원분들이 정말 친절하셨어요🙏🏻','2026-10-12T00:00:00.000Z'),
('nr-41589','naver-1533308837','naver','구의역 근처에서 조개찜이 먹고 싶어서 방문한 찌마기 구의점🦪 메뉴는 조개찜 모듬으로 주문했는데, 생각보다 양이 푸짐하게 나와서 보는 순간부터 만족스러웠어요. 여러 종류의 조개가 골고루 들어 있어서 하나씩 골라 먹는 재미도 있고, 조개 자체도 신선해서 비린 맛이나 모래 씹히는 느낌 없이 맛있게 먹었습니다. 특히 조개에서 우러난 국물이 시원하고 칼칼해서 술안주로 정말 잘 어울렸어요. 조개만 먹어도 꽤 배가 차는 편이고, 마지막에 칼국수나 라면 사리를 추가해서 국물까지 즐기면 더 든든하게 먹을 수 있을 것 같아요.','2026-10-12T00:00:00.000Z'),
('nr-41590','naver-1533308837','naver','조개 신선하고 넘 맛있고 칼국수 사리1개만 추가해도 좋지만 맛있어서 2개 추가하니 엄청 많은 양으로 드실 수 있어요. 직원분들도 넘 친절하신 찐 맛집으로 왜 사람들이 줄서서 먹는지 알겠습니다.👍🏻','2026-10-12T00:00:00.000Z'),
('nr-41591','naver-1533308837','naver','구의동 최고 맛집 구의동 유일한 맛집은 찌마기뿐. 항상 포장만 해서 먹다가 홀에서는 처음 먹어보는데 직접 먹으니까 진짜 맛있네요. 무엇보다 직원분들이 넘나 친절!','2026-10-12T00:00:00.000Z'),
('nr-41592','naver-1533308837','naver','10년넘게 방문중입니다!! 생새우회가 6마리에 1.2만원으로 조개찜이 익는 시간동안 가볍게 한잔 안주하기 좋아요. 머리는 요청하면 튀겨주십니다! 조개찜이야 말해 뭐해요. 홍합조차 깨끗이 손질된거보면 너무 청결하게 관리하신듯 해요.','2026-10-12T00:00:00.000Z'),
('nr-41593','naver-1533308837','naver','우와! 생새우 왜 안드세요? 머리튀김 왜 안먹어요?ㅋㅋ 진짜 쫀득하고 맛있어요! 머리튀김은 바삭바삭! 소고기샤브랑 칼국수는 꼭 추가해서 드세용♡찌마기는 항상 사랑스럽네요. 맛있게 잘 먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-41594','naver-1533308837','naver','너무 맛있어요ㅜㅠㅠ 오랜만에 방문했는데 변함없이 진짜 맛닜어요 조개 싱싱하고 쫄깃하고 국물 진짜 미쳤습니다','2026-10-12T00:00:00.000Z'),
('nr-41595','naver-2075486904','naver','참치 구성도 좋고 부위도 다양해요 새우도 달달하니 맛있어요 우니도 꼬숩해요 기본찬으로 소라무침도 새콤해요 초대리밥도 있어서 먹다가 참치랑 같이 싸먹어도 맛있어요 리뷰이벤트로 음료나 소주도 하나줘요','2026-10-12T00:00:00.000Z'),
('nr-41596','naver-2075486904','naver','11주년 결혼기념일 맞이해서 방문했어요~ 처음 오픈했을때부터 오고 싶었는데 사람이 너무 많더라구요 ㅎㅎ 나름 참치 꽤 많이 먹어봤는데 퀄리티 진짜진짜 좋습니다. 연어 매니아인 아이도 참치 잘 먹네요! 가족끼리 방문하기 분위기도 너무 좋아요. 사장님도 친절하시구요! 덕분에 좋은 기념일이 됐습니다~ 집 근처라 종종 들를게요~!^^','2026-10-12T00:00:00.000Z'),
('nr-41597','naver-2075486904','naver','회식으로 방문했는데, 지인이랑 또 오고싶은 맛집 하나 저장! 얼큰스지전골은 진짜 얼큰 그자체.. 참치 먹고 튀김 먹은다음에 얼큰스지전골로 입깔끔하게 마무리하고 다시 시작할 수 있는 맛집입니다!! ❤️ 사장님 부부도 넘넘 친절하십니다아〰️ 예약방문 추천드로용','2026-10-12T00:00:00.000Z'),
('nr-41598','naver-2075486904','naver','참치부터 시이드 요리 메뉴까지 모두 너무 맛있어요 참치는 그냥 당연히 참치집이름값하는데 다른 메뉴들이 있어서 가족모임 단체모임 모두 좋을거같아요~ 친절하고 인성좋은 훈남 사장님도 넘 좋네요~~ 자주 올거같아요','2026-10-12T00:00:00.000Z'),
('nr-41599','naver-2075486904','naver','로얄(3-4인) 참치 부위도 다양하고 딱새우, 달마새우는 완전 달달하고 신선해요 입에서 살살 녹고 우니랑 연어까지 다양하게 즐길수 있어서 좋았어요 초대리밥 시켜서(공기밥 마냥 밥그릇에 나옴) 초밥처럼 먹었는데도 맛있었어요 먹다보니 좀 매콤한게 땡겨서 얼큰진사골라면 시켰어요 면도 일반 라면면이 아니라 약간 라멘면 같아서 쫄깃하고 맛있어요 위에 고기도 듬뿍 야채도 푸짐해요 매콤칼칼을 원했는데 더 매웠으면 좋겠어요 신라면 보다 안매워요 :; 진순이같음','2026-10-12T00:00:00.000Z'),
('nr-41600','naver-2075486904','naver','지나가다가 사람이 많아서 맛집인 것 같아서 부모님 모시고 다녀왔어요~ 오픈 한지 2개월 정도 되셨다고! 내부 넓고 깔끔하고 깨끗해요 전화해보니 주차 가능하다고 하셔서 가게 앞 편하게 주차! 로얄 주문해서 셋이서 맛나게 먹었어요. 진짜 싱싱했고 부모님도 대 만족! 사진을 너무 못 찍었지만 진짜 맛있었어요! 적당히 기분좋게 배부른 정도 였는데 옆테이블 라면이 너무 맛나보여서 추가 주문ㅎㅎ 라면도 만족! 점심때라 그런지 점심메뉴 시키는 테이블도 많았어요 서비스로 주신 연어머리구이도 너무 맛나서 싹싹 긁어먹고 나왔습니다!! 재방문 할게요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41601','naver-2075486904','naver','아이가 참치회를 먹어보고 싶다고 해서 방문했어요. 저희 가족이 날 것을 잘 못먹는데 어른들은 참치를 조금씩은 먹을수 있어서 함께 방문했는데.. 어마어마한 양이 나와서 살짝 긴장했습니다. 혹시 많이 남길까봐서요. 그런데 아이가 생각보다 너무 잘 먹었습니다. 싱싱해서 저희 부부도 많이 먹어서 다 먹고 왔네요. 아직 회가 익숙치 않은 작은 아이는 진사골라면과 튀김을 먹었는데 이것 또한 너무 맛있어서 다 먹어 치우고 왔습니다. 4명이 가서 얼마나 먹은건지... 사장님과 직원분들도 너무 친절하셔요. 친절하게 어떻게 먹어야하는지도 설명해주셔서 아이가 첫 참치회를 아주 만족스러게 먹었습니다. 매장도 너무너무 깨끗해요! 회 입문자 메뉴로 너무 좋은것 같습니다!!! 강력 추천!','2026-10-12T00:00:00.000Z'),
('nr-41602','naver-2075486904','naver','언제가도 신선하고 맛있는 참치가 있는 곳이에요 사이드메뉴도 하나하나 맛있어요 단체모임하기에도 좋은 곳이에요 강추드립니다^^','2026-10-12T00:00:00.000Z'),
('nr-41603','naver-2075486904','naver','벌써 3번째 방문이네요 한번 먹어보고 계속 생각이 나서 또 방문했는데 역시 만족스러웠어요 참치회가 너무 다양하고 예쁘게 나와서 기분이 좋았고, 신선하고 부드러운 맛도 늘 한결같아서 대만족했습니다. 곁들임 음식도 깔끔하고 맛있어서 계속 손이가고, 분위기에 취해 술이 술술들어갑니다~^^ 세번째 방문도 행복했습니다. 맛있는 음식 먹고 싶으면 자연스럽게 생각나는 저의 단골집입니다!','2026-10-12T00:00:00.000Z'),
('nr-41604','naver-2075486904','naver','광진구에 새로 오픈한 ‘참찌’에 다녀왔어요. 모둠회가 나오자마자 비주얼부터 정말 푸짐해서 눈길을 확 끌더라고요. 😍 참치부터 새우, 우니까지 다양한 종류가 한 접시에 알차게 구성되어 있어서 하나씩 맛보는 재미가 있었어요. 특히 회가 두툼하게 썰려 있어서 식감도 좋고, 전체적으로 플레이팅도 예쁘게 나와서 사진 찍기에도 좋았습니다. 같이 나온 곁들임 메뉴들도 깔끔했고, 가족이나 지인들과 함께 와서 편하게 회 먹기 좋은 분위기였어요. 새로 생긴 곳이라 매장도 깔끔하고 음식도 정성스럽게 준비된 느낌! 광진구에서 회나 참치 생각날 때 한 번 방문해볼 만한 곳으로 추천합니다. 앞으로 광진구 회 맛집으로 자리 잡았으면 좋겠네요.','2026-10-12T00:00:00.000Z'),
('nr-41605','naver-2082336199','naver','제육볶음이 정말 맛있어서 기분 좋게 식사하고 왔어요. 고기도 부드럽고 양념이 너무 자극적이지 않으면서 감칠맛이 있어서 밥이랑 먹기 딱 좋았습니다. 양념이 고기에 잘 배어 있어서 한입 먹을 때마다 맛있더라고요. 특히 곤드레밥에 제육볶음을 올려 먹으니 정말 잘 어울렸어요. 곤드레밥의 은은한 향과 담백한 맛이 제육볶음의 매콤달콤한 양념과 잘 맞아서 계속 손이 갔습니다. 여기에 계란후라이까지 곁들여 먹으니 훨씬 부드럽고 고소해서 더 맛있었어요. 찌개도 국물이 진하고 간이 잘 맞아서 제육볶음과 함께 먹기에 좋았어요. 밥, 제육볶음, 계란후라이, 찌개 조합이 정말 든든하고 맛있는 한 끼였습니다.','2026-10-12T00:00:00.000Z'),
('nr-41606','naver-2082336199','naver','여긴 걍 미쳤음. 일단 보리차 줌. 따뜻한 보리차 차가운 보리차 다 있음. 1메뉴당 계란후라이1개씩 포함. 쌈채소 무제한 셀프. 밥은 현미밥 곤드레밥 흰밥 중에 선택인데 추가금없음. 수저 깨끗하게 세팅됨. 김 기본 제공. 테이블 간격 매우 넓음. 다 먹고 요구르트 후식.','2026-10-12T00:00:00.000Z'),
('nr-41607','naver-2082336199','naver','제육 먹고 싶어서 방문했는데 전체적으로 매장이 깔끔하고 분위기도 편안해서 좋았어요. 테이블 간격도 여유 있는 편이라 식사하는 동안 답답하지 않았고, 창가 쪽은 햇살도 들어와 분위기가 괜찮더라고요. 무엇보다 고기를 깔끔하게 즐길 수 있는 점이 마음에 들었어요. 국내산 한돈과 직접 담근 김치, 현미밥·흰쌀밥·곤드레밥 등 메뉴 선택지도 다양해서 취향에 맞게 골라 먹기 좋았습니다. 고기와 김치 조합도 잘 어울려서 밥이랑 같이 먹으니 든든했어요. 주문도 테이블에 있는 키오스크로 간편하게 할 수 있어서 편리했고, 필요한 반찬이나 추가 메뉴를 눈치 보지 않고 주문할 수 있는 점도 좋았습니다.','2026-10-12T00:00:00.000Z'),
('nr-41608','naver-2082336199','naver','한식이 너무 땡겨서 정식으로 먹을수있는곳 찾다가 들어왔는데 매장내부도 깔끔하고 직원분들도 친절하십니다~ 음식들도 맛있어요!! 리뷰이벤트로 동그랑땡도 주시는데 맛있습니다!! 매콤하니 너무 제취향이에요!','2026-10-12T00:00:00.000Z'),
('nr-41609','naver-2082336199','naver','군자역 직장인 점심 성지 인정합니다! 🍚🔥 12시 딱 맞춰 가면 무조건 줄 서는 찐 웨이팅 맛집이에요 🏃‍♂️💨 대기 줄 보고 살짝 긴장했는데, 회전율이 빨라서 생각보다 금방 들어갔어요 ⏱️✨ 고기 불향이 제대로 배어 있어서 밥 한 공기 순식간에 뚝딱 비웠습니다 🥩🤤 쌈채소랑 반찬도 정갈하고 푸짐해서 가성비 최고예요 🥬👍 양도 든든해서 오후 근무 버틸 에너지 제대로 충전 완료 ⚡ 직장 동료들이랑 점심 메뉴 고민될 때마다 1순위로 달려올 것 같아요 🤝 군자역 직장인분들 든든한 한 끼 찾으시면 무조건 추천드립니다! 재방문 의사 200% ❤️‍🔥','2026-10-12T00:00:00.000Z'),
('nr-41610','naver-2082336199','naver','계란후라이가 이렇게 이뻐도 되나요~ 밥이랑 계란이랑 쌈채소가 무한리필인곳~ 사촌언니 강력추천으로 왔는데 너무 맛있고 든든하네요~~ 굴림만두도 두툼 동그랑땡도 너무 맛납니다~~ 늦은 점심이었는데도 브레이크타임없이 들어가서 밥먹을수있어서 좋았어요~~~ 맛난음식 계속 부탁드려요❤️❤️','2026-10-12T00:00:00.000Z'),
('nr-41611','naver-2082336199','naver','음식이 깔끔하고 사장님 직원분들 친절하세요~ 늘 배부르게 맛있게 식사할수 있어서 자주 방문 하고 있습니다👍👍👍 음식도 깔끔하고 한상대접받는 기분이 든답니다 군자동 방문때 꼭 식시강추입니다^^','2026-10-12T00:00:00.000Z'),
('nr-41612','naver-2082336199','naver','전체적으로 든든하게 한 끼 먹기 좋았어요. 특히 셀프쌈이 준비되어 있어서 제육볶음과 함께 쌈을 넉넉하게 먹을 수 있었던 점이 좋았습니다. 차돌된장찌개는 얼큰하고 진한 맛이라 밥과 함께 먹으니 정말 맛있었고, 제육볶음과도 잘 어울렸어요. 군자역 근처에서 든든한 한식 메뉴가 생각날 때 방문하기 좋은 곳이었습니다.','2026-10-12T00:00:00.000Z'),
('nr-41613','naver-2082336199','naver','매장도 깨끗하고 직원분도 친절하세요 :) 김치찌개랑 제육볶음 너무 맛있게 먹었어요. 밥이랑 계란후라이도 무료이고 쌈야채도 셀프로 편하게 이용 할 수 있어서 좋아요. 맛있게 잘 먹었습니다👍','2026-10-12T00:00:00.000Z'),
('nr-41614','naver-2082336199','naver','쌈채소 무한이라 좋아요. 반찬도 테이블에 비치되어 있어 편하게 먹을수 있었어요. 궁채, 마늘고추장아찌, 마늘김치를 몇번이나 먹었는지 몰라요. 계란후라이도 달라고 하니 주시네요. 현미밥, 곤드레밥, 쌀밥 고를 수 있는것도 너무 좋아요. 깔끔하고 온식구 만족할 식당입니다. 제육이랑 오겹먹었는데 둘 다 맛있었어요. 된장국도 시골 된장맛이라 굿^^','2026-10-12T00:00:00.000Z'),
('nr-41615','naver-12035278','naver','어린이 대공원 오면 늘 오는 집이에요. 맛있어서 세번째 방문이에요.아이랑 오기 좋고 룸도 있어서 단체 손님도 많은거 같아요👍','2026-10-12T00:00:00.000Z'),
('nr-41616','naver-12035278','naver','천미향 다녀왔어요 😊 매장 분위기도 깔끔하고 편안해서 가족끼리 식사하기 좋았고, 음식도 전체적으로 정갈하게 나와 만족스러웠어요. 메뉴 하나하나 재료도 신선한 느낌이고 간도 부담스럽지 않아 맛있게 먹었어요. 양도 넉넉해서 든든하게 한 끼 하기 좋았답니다 👍 직원분들도 친절하시고 매장 관리도 잘 되어 있어서 기분 좋게 식사했어요. 부모님 모시고 방문하거나 가족 외식 장소 찾는 분들에게도 괜찮을 것 같아요. 다음에 근처 갈 일 있으면 또 방문하고 싶은 천미향이에요 :) 맛있는 한 끼 잘 먹고 왔습니다 💛','2026-10-12T00:00:00.000Z'),
('nr-41617','naver-12035278','naver','갑오징어 짬뽕이랑 짬뽕밥 주문했는데 국물이 진하고 얼큰해서 맛있게 먹었어요!! 짬뽕 특유의 불향도 은은하게 나고 해산물 맛이 국물에 잘 우러나서 국물이 계속 당기는 맛이었어요. 너무 자극적으로 맵기만 한 게 아니라 감칠맛이 있어서 좋았습니다. 갑오징어는 쫄깃하면서도 질기지 않고 씹을수록 고소한 맛이 나서 짬뽕이랑 잘 어울렸고, 야채도 아삭하게 살아 있어서 식감이 좋았어요. 짬뽕밥은 밥이 국물에 잘 어우러져서 국물 한 숟갈에 밥 같이 먹으니까 더 든든하고 맛있더라고요. 국물까지 거의 다 먹을 정도로 만족스러웠어요! ❤️❤️','2026-10-12T00:00:00.000Z'),
('nr-41618','naver-12035278','naver','처음 방문해서 과감하게 코스요리 도전했는데 요리들이 하나같이 맛있고 짜지않고 조미료맛도 안나고 아주 맛있게 먹었습니다! 애들도 잘먹었어요 고추잡채까지! 별점 5점입니다 ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-41619','naver-12035278','naver','아이와 어린이대공원 갔다가 점심 먹으러왔어요. 대공원 갔다가 짜장면은 국룰이죠 ㅎ 아이는 간짜장, 저는 잡채밥 먹었는데 잡채밥이 맵지않아서 아이도 줘봤는데 짜장면 나오기전에 잡채밥 엄청 먹네요~이거 무슨 밥이냐고 물어보고 담에도 먹고 싶다고 하네요!덕분에 잘 먹는 메뉴하나 추가요~👍','2026-10-12T00:00:00.000Z'),
('nr-41620','naver-12035278','naver','처음 와봤는데 맛있어요! 유니짜장, 마파두부, 탕수육 다 맛있었는데 특히 탕수육 겉이 포슬포슬하면서 안에는 고기가 꽉 차있어서 특별했습니다.👍🔥🔥추천','2026-10-12T00:00:00.000Z'),
('nr-41621','naver-12035278','naver','어린이대공원 바로 앞이라 도보 5분만에 도착한 중식당! 아이가 무조건 좋아하는 탕수육 볶음밥 짜장면 너무너무 잘 먹으니 체험이 훨씬 수월합니다 ㅎㅎ 즐거운 가족 나들이에 탁월한 메뉴 선택이었어요 찹쌀탕수육 너무 바삭하고 맛납니당','2026-10-12T00:00:00.000Z'),
('nr-41622','naver-12035278','naver','천미향에서 단체 모임 식사 했어요~ 숙주탕수육은 처음 보는 메뉴였는데 탕수육 숙주 소스 조합이 넘 좋아요 다음에 또 주문하려구요! 짬뽕밥도 국물 깔끔하고 맛있었습니당','2026-10-12T00:00:00.000Z'),
('nr-41623','naver-12035278','naver','지난번 갔을때 아이들이 유린기를 맛보고 또 먹고 싶다고해서 방문했어요 유린기 나오자마자 아이들이 달려들어 먹다가 사진을 찍었네요 튀김이 바삭하고 소스에 적셔 야채랑 같이 곁들여먹으니 너무 맛있어요~ 짜장면과 짬뽕은 무조건 주문해요 입짧은 아들도 많이 먹어 만족입니다','2026-10-12T00:00:00.000Z'),
