('nr-45497','naver-258166501','naver','굿~~','2026-10-12T00:00:00.000Z'),
('nr-45498','naver-1664295471','naver','가성비 좋은 카이센동이었고,맛있었습니다. 뭔가 일식 전문집 느낌은 아닌데, 정성스러운 맛이고 가격이 착해서 마음에 쏙 들었습니다. 안쪽 테이블은 한쪽만 트인공간에 여러개의 테이블을 두어서인지 목소리 큰 손님이 합류해서인지, 대화 내용이 이어폰을 뚫고 들어와서, 식사 하다가 자리를 옮겼습니다. BAR 와 함께 하는 곳이어서. 외부쪽은 실내 테라스 느낌이라 또 다른 느낌이에요. 저녁에 혼밥하기 좋은','2026-10-12T00:00:00.000Z'),
('nr-45499','naver-1664295471','naver','내돈내산) 타임딜 챤스로 큰 기대없이 갔는데 기대이상!! 분위기..맛...good!!^^ 양고기, 연어회, 육회, 고등어회, 맛탕도 맛있고... 쌀국수도 굿, 잔치국수는 굿굿... 아..회랑 먹을 묵은지 곁들이니 완전 최고였다는건 비밀!!^^ 세척 묵은지가 신의 한수!! 사이드로 계속 갖다 먹었다는...ㅋ 피자, 특히 도우가 예술...스프에 찍어...^^ 과일도 신선하고..아이스크림, 커피도 굿... 입장시 브리핑(?)도.. 여리한 여성분이 매번 인사도 잘 하고 빈 그릇도 빨리빨리 치워주시고.. 섬세한 친절함에 기분 좋은 식사시간이었다는... 비오는 날이라 보이차, 국화차도 좋았지만... 피자랑 먹을 탄산음료가 extra charge인게 좀... 그래도 전반적으로 굿!! 재방문의사 300%!!^^','2026-10-12T00:00:00.000Z'),
('nr-45500','naver-1664295471','naver','너무 맛 있는 행사같아요. 종류도 많고 맛도 있고 나무랄 때없는 최고의 뷔페입니다. 가족끼리 와서 더 즐겁게 좋은 시간 가질 수 있는 곳입니다. 특히 구로에는 뷔페같은 뷔페가 없는데 최고네오ㅡ.','2026-10-12T00:00:00.000Z')
INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-45501','naver-1664295471','naver','가족모임으로 갔는데 랍스터도 자리로 가져다 주시고, 음식도 전체적으로 깔끔했어요. 다란 뷔페들에 비해서 메뉴 종류가 많지는 않은데 그래도 음식들은 괜찮은편 같아요.','2026-10-12T00:00:00.000Z'),
('nr-45502','naver-1664295471','naver','구로에서 기념일 식사할 곳을 찾다가 방문했는데, 기대 이상 깔끔하고 구성도 다양하고 음식 맛도 좋았습니다. 가족도 만족해했구요~ 랍스터구이도 제공되고 대게도 맛이 괜찮네요. 다음에 또 방문하고 싶은 뷔페입니다.','2026-10-12T00:00:00.000Z'),
('nr-45503','naver-1664295471','naver','랍스타도 테이블별로 나오고 부채살 진짜 맛잇어요~~~~~ 직원분들도 너무 친절하시고 좋습니다 즐거운 저녁 식사였어요💚','2026-10-12T00:00:00.000Z'),
('nr-45504','naver-1664295471','naver','매장 내부가 깔끔하고 쾌적하게 관리되고 있어서 식사하는 내내 기분이 좋았고, 음식도 종류가 다양하면서 맛과 퀄리티가 전반적으로 좋았습니다. 특히 가장 인상 깊었던 부분은 직원분들의 친절한 응대였습니다. 바쁜 시간에도 하나하나 세심하게 챙겨주시고 밝은 표정으로 응대해주셔서 더욱 편안하고 즐거운 시간을 보낼 수 있었습니다. 음식뿐만 아니라 서비스까지 만족스러웠던 곳이라 다음에도 가족들과 다시 방문하고 싶습니다. 오랜만에 기분 좋게 식사하고 온 곳이라 주변에도 추천하고 싶네요!','2026-10-12T00:00:00.000Z'),
('nr-45505','naver-1664295471','naver','생일기념으로 식사하러 방문했는데 음식 퀄리티가 좋네요 주중디너,$주말이용 고객에게는 랍스터 시즈닝 플래터가 제공되어 더욱 알차고 좋습니다^^ 종류가 많지는 않지만 전체적으로 품질이 좋아 만족하고 알찬 식사가 되었습니다 또 다시 방문할 생각입니다','2026-10-12T00:00:00.000Z'),
('nr-45506','naver-1664295471','naver','집에서 멀지않은곳이라 방문하기 편해요 종종 가는편인데 쉐라톤호텔계열이라 음식도 정갈하고 괜찮은편이에요 굳이 5성급까지 가지 않아도 이정도면 만족이에요','2026-10-12T00:00:00.000Z'),
('nr-45507','naver-1664295471','naver','명절 연휴에 다녀왔습니다^.^ 연휴라 그런지 사람이 많았네요. 해산물 좋아하는 남편 말로는 가성비가 매우 훌륭하다고 합니다. 개인적으론 콘스프 좋아하는데 달달하니 맛있었어요 두그릇 먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-45508','naver-2058055802','naver','빵이 다른버거 브랜드와 달리 부드럽고 촉촉해요. 패티는 고기맛이 진하게 나고 고급스런맛이라 정말 만족스러워요. 9월부터는 새벽1시 까지 영업이라 야식 당길때 찾아갈 수 있어 좋네요. 버거 종류가 다양하고 재료가 진짜 신선하고 맛이 느끼하지않고 깔끔해서 자주 먹고 있어요. 거리공원 옆이라서 먹은 뒤 산책하기도 좋아요. 만원 이상 구매하면 무료주차 가능해서 더 편하고 좋아요','2026-10-12T00:00:00.000Z'),
('nr-45509','naver-2058055802','naver','6회째 방문. 매주 주말에 오는 것 같다. 인근 버거킹은 이제 안가게됨. 꽤 여러 수제버거를 먹어봤다. 그 중 예전 브루클린버거(지금은 없어짐)라는 체인점 버거맛과 비슷하고, 왠만큼 유명하다는 국내 수제버거 가게의 다수를 먹어봤다. 맛만 놓고 봤을 때, 개인적으로 반포 무슨 마을에 있는 버거조인트, 쉑쉑보다 만족도가 높다. 단, 빅패티를 선택하더라도 두께가 살짝 얇은 느낌. 하지만, 가격을 고려하면 이 또한 훌륭하다.','2026-10-12T00:00:00.000Z'),
('nr-45510','naver-2058055802','naver','오픈때부터 햄버거 먹고싶을땐 항상 프레디버거를 먹습니다 신선하고 고기패티도 완전 맛있어요 그리고 감튀도 바삭고소짭잘 ,,, 완벽🖤','2026-10-12T00:00:00.000Z'),
('nr-45511','naver-2058055802','naver','집 근처에 새로 오픈한 수제버거집이 있길래 와봤는데 양도 엄청 많고 가성비 좋아요! 도서관 옆이라 주말에 공부하고 혼밥하기에도 좋을 거 같아용 자주 오게될 거 같은 느낌!','2026-10-12T00:00:00.000Z'),
('nr-45512','naver-2058055802','naver','새로 생긴 수제버거집인데 버거 맛있어요 수제버거집 몇번 다녀보니까 패티나 재료같은건 다 비슷하고 소스가 좀 가르는 것 같은데 여기 소스 괜찮음 그리고 벽이 빨간색이라 사진 찍기 좋아하시는 분들도 벽 근처 자리 앉으면 사진 쨍하니 잘 나올 것 같아요','2026-10-12T00:00:00.000Z'),
('nr-45513','naver-2058055802','naver','오픈한지 얼마 안됐는데 남편이 좋아해서 여러번 방문했어요. 늘 포장해가다가 매장에서는 처음 먹는데 리뷰이벤트가 있어서 참여합니다. 말만 수제버거가 아닌 진짜 수제버거의 맛! 추천합니다^^','2026-10-12T00:00:00.000Z'),
('nr-45514','naver-2058055802','naver','집이랑 가까워서 자주 방문 하는 매장이에요! 다른 지점에서도 맛나게 먹어서 집근처에 생겨서 너무 좋습니다! 넘 맛나용!!','2026-10-12T00:00:00.000Z'),
('nr-45515','naver-2058055802','naver','매장이 깨끗하고 메뉴가 다양해요. 만원 이상 구매하면 주차가 무료에요. 공원옆이라 산책 후 들려서 먹고가기 좋아요. 패티두께를 고를 수 있어서 좋고 맛이 고급지네요. 사장님이 친절하셔서 더 좋았어요.','2026-10-12T00:00:00.000Z'),
('nr-45516','naver-2058055802','naver','남편이랑 둘이 자주 먹는데 맛있어요 ! 이거먹으면 프랜차이즈 버거집 못먹는 ㅋ 근데 가격도 착하고 가성비 좋고 맛있어서 자주 시켜요. 단골입니다 ㅋ 고기패티가 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-45517','naver-2058055802','naver','새로 생긴 버거집 수제버거라는 호기심에 왔는데 깨끗하고 인테리어가 귀엽네요 빵은 부드럽고 맛있네요 감튀도 맛있고 가까이에 있어 자주 올것 같네요','2026-10-12T00:00:00.000Z'),
('nr-45518','naver-2051772552','naver','동양미래대학 먹자골목에 있는 프렌치쪽갈비 디려왔어요. 참숯불향을 품고 초벌되어 나오는 쪽갈비는 목장갑끼고 뜯어야 제 맛. 소금쪽갈비를 먹었는데요. 잡내없고요. 잘익어나와 살도 잘 뜯어져요. 찍어먹는 카레가루와 고추장이 정말 맛났어요. 고추장이 집고추장인가? 싶게 맛났답니다ㅡ. 돼지껍데기도 신선해서 식감이 참 좋았어요. 순두부찌개와 콘치즈는 기본이라는 점~^^ 먹고 걸으며 후식도 사먹고 안양천산책도 할수있어요. 고척돔 야구장 방문하시는 분들 한번 들러보세요^^ #협찬','2026-10-12T00:00:00.000Z'),
('nr-45519','naver-2051772552','naver','학교앞 술 땡길때 가야하는곳🇦🇲 쪽갈비의 살이 풍성하다🏅땀이 줄줄흘러서 먹는데 집중하게된다🏏 사이드인 라면도 엄청 푸짐하고 숯에 구워먹을수있어 더욱 맛있다🥏 기본반찬으로 순두부찌개, 껍데기, 두부김치, 옥수수콘치즈 등이 제공되어서 메리트가 있다.','2026-10-12T00:00:00.000Z'),
('nr-45520','naver-2051772552','naver','쪽갈비는 프렌치, 프렌치는 쪽갈비~! #동양공전 맛집 #고척동 맛집 #고척동쪽갈비 #고척동갈비 #고척동술집 #구로술집 항상 너무 맛있고 기분좋게 먹고 가는 프렌치 쪽갈비입니다👍👍👍👍👍👍👍 더욱 더 번창하시길 바랍니다👏👏👏👏👏','2026-10-12T00:00:00.000Z'),
('nr-45521','naver-2051772552','naver','야구장데이트 왔다 들른 쪽갈비~ 기본찬 좋구 쪽갈비는 초벌 되서 나와서 살짝만 구워먹으면 되니 넘나 좋아욤~~ 직원분이 칼집내서 올려주시는데 이러면 숯불향이 더 잘들어가서 맛있데욤~ 소금구이 깔끔하고 잡내없고~칼집 때문인지 더 잘 뜯기는데 뜯는 맛도 좋아요~ 매운갈비도 딱 기분좋게 맵네요~마시썽~ 제 픽은 매운갈비~ 넘나 잘 묵었어욤~~^^','2026-10-12T00:00:00.000Z'),
('nr-45522','naver-2051772552','naver','쪽갈비는 처음 먹어봤는데 너무 맛있어서 놀랐어요! 소금구이로 시켰는데 곁들여먹는 소스를 주셔서 질리지 않고 맛있게 먹을 수 있었어요~ 돼지껍데기도 두툼해서 씹는 맛이 있었구요 기본으로 주시는 순두부찌게랑 두부김치, 콘치즈도 완전 술안주로 최고였답니당👍 쪽갈비 생각나면 여기로 또 먹으러 올 생각이에요❤️','2026-10-12T00:00:00.000Z'),
('nr-45523','naver-2051772552','naver','근처 축제가 있어서 가던길에 발견한 쪽갈비집 사람들도 많고 해서 들어갔는데 여기가 맛집이었습니다 가격도 좋고 구성이 너무 알찼어요 제일중요한 맛은 정말 입맛에 딱 맞아서 맛있게 먹었습니다 재방문 할거 같아요!!','2026-10-12T00:00:00.000Z'),
('nr-45524','naver-2051772552','naver','🍖 소금 쪽갈비 - 간이 짭조름하게 딱 알맞았고 미리 초벌 되어 나와서 좋았어요 - 고기가 쫄깃하고 맛있었어요 - 순두부찌개, 콘치즈, 두부김치, 돼지껍데기도 같이 나와서 든든하게 먹을 수 있었어요 - 돼지 껍데기는 너무 느끼하거나 기름지지 않았고, 살짝 달콤하고 식감이 좋았어요 ✔ 전체적인 후기 - 매장이 잘 꾸며져 있었고 깔끔했어요 - 직원분들이 친절하셨어요','2026-10-12T00:00:00.000Z'),
('nr-45525','naver-2051772552','naver','쫄깃쫄깃 고기가 맛있어요!! 밑반찬에 순두부찌개랑 두부김치, 콘치즈까지!! 그리고 껍데기랑 떡까지 하나같이 맛있어요!!! 또 올거예요!!','2026-10-12T00:00:00.000Z'),
('nr-45526','naver-2051772552','naver','에피타이저로 반찬이 너무 훌륭해요~순두부찌개, 콘치즈, 두부김치가 나오는데 너무 맛있어서 먹다보니 고기를 못먹을거 같아서 멈추고 고기를 즐겼습니다. 초벌해서 나와서 많이 굽지 않고 먹기 편하고 가위로 먹기 편하게 손질을 해주셔서 좋아요. 자리는 안쪽까지 있어서 꽤 많은 편이구요~ 동네 매일 지나가면서 한번 가봐야지 했는데 오늘 왔네요 ㅎㅎ 또올집입니다.','2026-10-12T00:00:00.000Z'),
('nr-45527','naver-2051772552','naver','고기 진짜 맛있어요! 숯불에 구워서 불향도 좋고 고기도 부드럽고 육즙이 살아있어요👍 매운양념도 맛있어요~~서비스로 나오는 순두부 찌개도 너무 맛나요~^^동네에 쪽갈비가 없었는데 생각날 때 또 방문할 것 같아요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-45528','naver-1063781950','naver','새우와 버섯이 듬뿍 들어간 오일 파스타 먹었는데 정말 맛있었어요! 새우도 통통하고 재료가 전체적으로 푸짐해서 만족스러웠습니다. 오일 베이스라 느끼하지 않고 마늘과 허브 향이 잘 어우러져서 계속 먹게 되는 맛이었어요. 다음에 또 올게요! #플레어비 #고척아이파크브런치 #고척아이파크파스타 #고척브런치 #고척파스타','2026-10-12T00:00:00.000Z'),
('nr-45529','naver-1063781950','naver','매장이 넖고 테이블이 다양해서 이용하기 좋아요. 팥빙수에 견과류가 듬뿍~ 우유얼음에 떡과 팥, 미숫가루가 어우러져 기분좋고 건강한 맛이예요^^ 한가한 시간 혼자도 지인들과 브런치도 가족들과 차한잔도 모두 좋습니다^^ 가까운곳에 플레어비가 있어 좋네요ㅎㅎ','2026-10-12T00:00:00.000Z'),
('nr-45530','naver-1063781950','naver','제니스에서 모닝 스크린치고 브런치하러 왔어요. 주차도 좋고, 음식맛도 무난해서 수다떨기 딱 좋은 집이에요,. 세트B와 C 로 주문했는데 여자 다섯명이서도 넉넉하게 브런치 즐겼네요. 커피맛이 좀 슴슴하고 환기가 살짝 아쉬웠지만 가성비 훌륭했던 집입니다. 재방문의사 있습니다. 골프존 제니스에서 새벽 스크린 치고 방문하기 딱 좋은 곳이네요.','2026-10-12T00:00:00.000Z'),
('nr-45531','naver-1063781950','naver','주말 점심에 브런치집 찾다 방문했는데 너무맛있게 잘먹고 갑니다 재방문할께요','2026-10-12T00:00:00.000Z'),
('nr-45532','naver-1063781950','naver','#플레어비 #고척아이파크 브런치 #고척브런치 #고척파스타 #고척아이파크파스타 지인이 놀러와서 어디갈까하다가 고척아이파크 맛집인 플레어비 추천받아 왔습니다 세트C인데 여자 둘이서 배부르고 맛나게 먹었습니다 파스타 맛집이네요👍🏻👍🏻','2026-10-12T00:00:00.000Z'),
('nr-45533','naver-1063781950','naver','동네에 있는 브런치카페 추천이요❤️ 세트메뉴도 구성이 잘되어있어요!','2026-10-12T00:00:00.000Z'),
