INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-46501','naver-34357869','naver','3명이가서 인당 깔국수, 만두 한판씩 잘 먹고 갑니다','2026-10-12T00:00:00.000Z'),
('nr-46502','naver-34357869','naver','굿','2026-10-12T00:00:00.000Z'),
('nr-46503','naver-34357869','naver','수수해서 더 특별한 만두와 쫄면','2026-10-12T00:00:00.000Z'),
('nr-46504','naver-1913254076','naver','노릇하게 잘 구워진 고기 한 점을 입에 넣자마자 감탄사가 절로 나왔어요. 겉은 바삭하고 속은 육즙이 가득해서 씹을 때마다 정말 행복했답니다. 함께 나온 밑반찬들과 곁들여 먹으니 느끼함도 전혀 없이 끝까지 맛있게 즐겼네요. 왜 다들 이곳을 추천하는지 한입 먹어보자마자 바로 이해가 가더라고요. 다음에도 고기가 생각날 땐 고민 없이 이곳으로 달려와야겠어요.','2026-10-12T00:00:00.000Z'),
('nr-46505','naver-1913254076','naver','고기 너무 맛있어요😊😊 추석이랑 엄마 아빠 밥 먹고 싶어 먹으러 왔는데 너무 맛있게 잘 먹었습니다 ♥ 아이들도 잘 뽑 부모님도 너무 좋게 하셔서 식사 시간이었어요 😊','2026-10-12T00:00:00.000Z'),
('nr-46506','naver-1913254076','naver','두껍삼 가산디지털단지역점 정말 너무 최고예요 🤩 매장이 엄청 넓고 깔끔해서 쾌적하게 식사할 수 있었어요 ✨ 무엇보다 고기를 전문 그릴러 직원분이 다 구워주셔서 너무 편했답니다 👍 환풍구가 불판 아래쪽에 있어서 연기도 안 나고 옷에 고기 냄새가 하나도 안 배었어요 🌬️ 진짜 신세계 경험하고 왔어요 👏 두툼한 삼겹살은 육즙 팡팡 터지고 미나리랑 백김치 조합이 끝내줍니다 🌿 주차 지원도 넉넉하게 해주셔서 주차 스트레스도 없었어요 🚗 직원분들도 친절하셔서 다음에는 가족 다 같이 오려고요 👨‍👩‍👦 점심 식사나 저녁 모임 장소로 강력 추천합니다 💖','2026-10-12T00:00:00.000Z'),
('nr-46507','naver-1913254076','naver','삼겹살+백김치+미나리 백미삼 2인분 먹었는데 조합이 정말 좋았어요⭐️⭐️ 고기도 직원분이 맛있게 구워주셔서 편하게 먹을 수 있었고, 미나리랑 백김치를 곁들이니 느끼하지 않고 계속 들어가더라고요ㅎㅎ 🐷🐷 무엇보다 고기 연기 빨아들이는게 불판쪽에 있어서 냄새 안나요!!!‼️‼️👍 된장찌개도 ㄹㅇ 구수하고 비빔냉면은 고기랑 같이 먹기 딱 좋았음ㅠㅠ 못참고 맥주까지 곁들이니 완벽한 저녁❤️💜💙💛🧡 다음에도 삼겹살 먹으러 재방문하고 싶어요 😆🤩','2026-10-12T00:00:00.000Z'),
('nr-46508','naver-1913254076','naver','제일 좋아하는 고기집 중 한곳이에요. 매장이 넓고 쾌적하고 프라이빗하게 식사하기 좋아요. 고기는 전문적으로 구워주셔서 편하게 먹을 수 있어요. 상차림 구성 좋고, 삼겹살은 정말 감칠맛이 있어요. 미나리, 백김치와 함께 먹어도 별미에요.','2026-10-12T00:00:00.000Z'),
('nr-46509','naver-1913254076','naver','고기가 신선하고 정말 맛있어요! 직원분들도 친절하시고 매장도 깔끔해서 기분 좋게 식사했습니다. 전체적으로 만족스러워서 다음에도 또 방문하고 싶어요 😊','2026-10-12T00:00:00.000Z'),
('nr-46510','naver-1913254076','naver','주차하기가 편해서 차로 가기 좋습니다. 주차하실 때 우림라이온스 A동 쪽으로 대시면 됩니다. 매장도 크고 넓어서 좋아요 고기를 처음부터 끝까지 다 구워주셔서 편하게 먹기만 하면 되고 특히 연기가 아래로 빠지게 설계된 듯한데 매장 안이 매우 쾌적했습니다. 고기도 너무 맛있고 편한 데다 사장님도 친절하셔서 기분 좋게 먹고 왔습니다.','2026-10-12T00:00:00.000Z'),
('nr-46511','naver-1913254076','naver','불판 위에 노릇노릇하게 구워지는 삼겹살 비주얼부터 합격인 곳입니다. 고기 두께도 적당해서 씹을 때마다 고소한 육즙이 터지고, 겉은 바삭하고 속은 촉촉하게 잘 구워져서 정말 맛있게 먹었습니다.','2026-10-12T00:00:00.000Z'),
('nr-46512','naver-1913254076','naver','처음 방문인데 친절하게 안내해 주셔서 감사합니다! 다음에도 또 방문할 것 같아요! 음식 맛있어요!','2026-10-12T00:00:00.000Z'),
('nr-46513','naver-1913254076','naver','직원분께서 다 구워주셔서 편하게 먹고 왔어요. 고기가 확실히 질이 좋았어요. 하지만 여기서 3인분 먹으면 배고프더라고요. 다른 데보다 양은 좀 적지만 확실히 보기실도 좋고 구워주시는 서비스도 초코직원분께서 다 구워주셔서 편하게 먹고 왔어요. 고기가 확실히 질이 좋았어요. 하지만 여기서 3인분 먹으면 배고프더라고요. 다른 데보다 양은 좀 적지만 확실히 보기실도 좋고 구워주시는 서비스도좋고 반찬도 하나같이 맛있었어요. 그래서 여러 번 재방문하게 되는 곳이에요. 회식으로 가면 더 좋을 것 같아요 그래서 그런지 재방문하게 되는 곳이에요. 회식으로 가면 더 좋을 것 같아요','2026-10-12T00:00:00.000Z'),
