INSERT INTO retrip_review (id,place_id,source,content,created_at) VALUES
('nr-111001','naver-33913378','naver','팥빙수 6100원 저렴해서 맛보려고 사왔는데 넘달아요~~~;;','2026-10-12T00:00:00.000Z'),
('nr-111002','naver-33913378','naver','롯데리아 신상메뉴 넘 맛있어용','2026-10-12T00:00:00.000Z'),
('nr-111003','naver-33913378','naver','동네','2026-10-12T00:00:00.000Z'),
('nr-111004','naver-32335539','naver','예악후 가족들과 방문했어요 이전에도 자주 왔던곳인데 이전한 매장의 분위기는 너무 좋네요 모두 룸으로 이루어져있어서 조용하게 모임하기 좋은것 같아요 직원분들 친절하시고 요청사항도 바로 들어주시고 음식까지 맛있으니 최고네요👍 코스메뉴가 알차게 구성되어있어 참치회까지 먹으니 배가 터질뻔 했습니다~ 조만간 또 방문 예정입니다!','2026-10-12T00:00:00.000Z'),
('nr-111005','naver-32335539','naver','가족 모임으로 미리 예약하고 이용 했어요. 룸으로 되어 있어 너무 좋네요. 아이들은 새우 튀김, 돈까스, 우동 추가로 시켜서 먹였더니 잘 먹었어요. 참치도 신선하고 맛있어요. 가족 모임으로 추천드립니다.','2026-10-12T00:00:00.000Z'),
('nr-111006','naver-32335539','naver','‘로’코스로 먹었는데 황새치,눈다랑어,참다랑어 다 신선하고 맛있습니다. 기념일에 오기 너무 좋습니다💗 주차는 건물뒤에 하면 됩니다. 직원분들 친절하시고, 가족들과 또 오고싶은 곳이네요.','2026-10-12T00:00:00.000Z'),
('nr-111007','naver-32335539','naver','다양항 부위의 퀄리티 좋은 고급 참치는 물론 프라이빗한 룸에서 코스요리까지 함께 즐길 수 있는 가족 외식이나 회식, 모임 장소로 찾기 좋은 상봉역 맛집, 상봉 참치 맛집 마구로진❗️ 3가지 마구로 코스 정식 메뉴는 1인 가격으로 참치 무한리필 서비스가 제공돼요👏🏻 리필 참치도 처음과 같은 퀄리티와 좋은 부위 구성에 퀄리티 좋은 참치회뿐 아니라 초밥과 전복장, 생선요리, 튀김, 식사까지 코스로 나와 든든하게 즐길 수 있는 상봉 참지집입니당👍🏻','2026-10-12T00:00:00.000Z'),
('nr-111008','naver-32335539','naver','참치가 정말 신선하고 맛있었어요! 2명이 방문해서 로얄 메뉴로 먹었는데 참치뿐만 아니라 죽, 샐러드, 구이, 조림, 초밥 등 코스 구성이 알차서 하나하나 맛있게 잘 먹었습니다. 참치 부위별로 다양하게 주시고 전체적으로 음식이 깔끔하고 정갈해서 만족스러웠어요. 직원분들도 친절하시고 편안한 분위기에서 식사할 수 있어서 가족이나 모임으로 오기에도 좋을 것 같아요. 참치 제대로 먹고 싶을 때 다시 방문하고 싶은 곳이에요. 😊 맛있게 잘 먹었습니다!','2026-10-12T00:00:00.000Z'),
('nr-111009','naver-32335539','naver','참치가 정말 맛있어요!!👍🏻 반찬도 하나같이 다 정갈하고 맛나용😄 사장님도 친절하고~ 매장도 넘 깨끗하고 좋으네요~ 데이트하기 딱 좋아용💕','2026-10-12T00:00:00.000Z'),
('nr-111010','naver-32335539','naver','너무너무 친절하시고, 맛있어요. 중랑구에 이런 곳이 있다니!! 감사합니다💙💙💙','2026-10-12T00:00:00.000Z'),
('nr-111011','naver-32335539','naver','상봉 마구로진에서 구세트 먹고 왔는데 정말 대만족입니다! 참치 전문점답게 해동 상태나 신선도가 완벽해서 입에서 살살 녹더라고요. 구세트 구성이 알차서 다양한 부위를 질리지 않고 끝까지 맛있게 즐길 수 있었습니다. 양도 부족함 없이 넉넉해서 진심으로 배부르게 먹었어요. 매장 분위기도 깔끔한데… 다만 들어오고 나가도 사장님이나 직원의 인사는 없는 곳이에요','2026-10-12T00:00:00.000Z'),
('nr-111012','naver-32335539','naver','정말 배불리 먹었습니다. 이만큼 가성비 있는 참치코스요리집 없을 것 같네요. 다 나왔나? 할 때마다 계속해서 나와서 리필 되는 것도 딱 1번 하고 나왔습니다ㅋㅋㅋ 다음에 또 중요한 모임있으면 방문할 계획입니다. 잘 먹고갑니다!','2026-10-12T00:00:00.000Z'),
('nr-111013','naver-32335539','naver','중랑구에 맛있는 참치집이 있다고 해서 방문했어요~~ 기대하고 왔는데 정말 맛있네요 👍','2026-10-12T00:00:00.000Z'),
('nr-111014','naver-1961443685','naver','이번주도 참지 못하고 와버렸네요 정말 매주 먹는 곳 .. 사장님 조금만 덜 맛있게 만들어주세요 너무 맛있어서 맨날 생각나잖아요ㅠㅠ😆 저는 항상 3단계+마라맛세게 요청드립니다 최고','2026-10-12T00:00:00.000Z'),
('nr-111015','naver-1961443685','naver','일주일에 한번은 무조건 먹는 곳입니다 요즘 마라탕집들 위생문제가 많은데 이 곳은 항상 재료도 매장도 식기들도 너무 깔끔합니다 사장님께서 워낙 관리를 잘하셔요 진한 사골맛으로 맨날 생각나요 너무 맛있습니다 장사 오래오래 해주셨으면 좋겠습니다 감사히 잘먹었습니다','2026-10-12T00:00:00.000Z'),
('nr-111016','naver-1961443685','naver','국물이 깔끔하네요 첨와봤어요. 초4 아이도 맛있다고 합니다 재방문 할께요','2026-10-12T00:00:00.000Z'),
('nr-111017','naver-1961443685','naver','마라순코우가 여기밖에 없어서 슬픕니다.. 마라탕은 마라순코우가 맛있는데.. 청량리까지도 배달 해주시면 안되나요...','2026-10-12T00:00:00.000Z'),
('nr-111018','naver-1961443685','naver','가끔 마라탕 땡길때 가는곳인데 매장도 청결하고 사장님 두분 모두 친절하시고 좋아요~~!','2026-10-12T00:00:00.000Z'),
('nr-111019','naver-1961443685','naver','다니던 대학교 근처에 마라순코우가 있어서 거의 매일같이 먹었었는데 본가쪽에도 있다는게 너무 행운같네요 .. 그맛 그대로라서 정말 행복해요 ㅠ 재료도 많고 신선한데 호박 분모자 여기서 처음 먹어봐요 너무 맛있습니다 추천추천 !!!🩷🩷','2026-10-12T00:00:00.000Z'),
('nr-111020','naver-1961443685','naver','3일만에 또 먹으러 왔습니다 역시나 매장 깔끔, 재료 깔금, 사장님도 친절하세요 맨날 먹어도 너무 맛있어요 새우도 작은 칵테일 새우 아니고 큰 새우에요 오늘도 맛있게 잘 먹고 갑니다','2026-10-12T00:00:00.000Z'),
('nr-111021','naver-1961443685','naver','마라탕 맛집 ^^','2026-10-12T00:00:00.000Z'),
('nr-111022','naver-1961443685','naver','마라순코우 첨 생기고부터 두번의 사장님 바뀐 지금까지 다니고 있어요. 마라탕 중에 저는 마라순코우 마라탕이 제일 맛나요~ 특히 재료들 상태가 좋아요. 소세지도 새우도 싸구려 말고 좀 큰 사이즈로 통통해요. 야채들도 늘 신선하구요. 청결 상태도 좋아요~ 사장님들도 넘 친절하세요 늘 잘 먹고있습니다☺️','2026-10-12T00:00:00.000Z'),
('nr-111023','naver-1961443685','naver','사장님이 바뀌사듯요 ^^ 국물맛은 좀 변한듯 합니다만 맛있어요 ~~ 딸아이 최애 마라탕입니다. 전병 같이 드셔보세요. 맛있어요','2026-10-12T00:00:00.000Z'),
('nr-111024','naver-1427773394','naver','양꼬치 고기 질이 정말 좋아서 잡내 하나 없이 고소하고 육즙이 터집니다! 함께 시킨 요리 메뉴도 간이 딱 맞고 입에 착착 감겨서 안주가 맛있으니 술이 술술 넘어가네요. 🍻 매장도 넓고 쾌적해서 모임이나 회식하기에도 최고예요. 양꼬치 좋아하시는 분들은 꼭 방문해 보세요! 재방문의사 200%입니다.','2026-10-12T00:00:00.000Z'),
('nr-111025','naver-1427773394','naver','원래 가려던 곳이 휴무라 왔는데, 이렇게 알게된게 너무너무 다행일정도로 맛있고 깔끔하고 좋았습니다! 고기 잡내 전혀없이 깔끔한 맛에 서비스로 주신 오이무침이 느끼함을 싹 잡아줘서 가지튀김이랑 양꼬치랑 맥주랑 합이 너무 좋았어요🥹 정말 맛있게 먹고와서 다음에도 마라양꼬치로 갈 예정이예요!! 중랑구 양꼬치 맛집입니다!!','2026-10-12T00:00:00.000Z'),
('nr-111026','naver-1427773394','naver','매번 먹지만 다른집 보다 양꼬치가 고기질이 좋와요 냄새도 안나고 중랑구 양꼬치 맛집이예요 . 요리는 더더욱 맛잇구요 !!!','2026-10-12T00:00:00.000Z'),
('nr-111027','naver-1427773394','naver','여기저기 아무리 양꼬치 맛있다는 곳 다 다녀봐도 여기만한곳을 찾을수가 없어요~ 먹어보면 알아요!!!!! 시간낭비하며 다른곳에 줄서지 마시고 진짜 마라양꼬치가 최고입니다! 사람들 많이 알게되어 줄설까 겁나지만~ 사장님부부 너무 친절하시고 정말 너무너무 맛있어서 추천해요!!!!','2026-10-12T00:00:00.000Z'),
('nr-111028','naver-1427773394','naver','처음가본 가게인데. 일단 청결함. 양고기에 누린내 없이 신선하고 맛있어요. 곁드림 밑반찬도 맛있고 친절합니다. 추천합니다.','2026-10-12T00:00:00.000Z'),
